INSERT INTO courses (id, slug, title, status, subject, description, position, requires) VALUES ('aab40d79-a597-4e18-a656-b6cc3a29ad47', 'qa-lesson-engine-smoketest', '{"en-US": "Lesson Engine QA — Smoke Test", "es-MX": "Motor de Lecciones — Prueba de Humo", "pt-BR": "Motor de Lições — Teste de Fumaça"}', 'published', 'mixed', '{"en-US": "Internal QA content — one isolated exercise per Lesson Engine type, used to validate the full generation pipeline (text, gates, judge, localization, images, audio, endpoints) before a real course run. Not for learners.", "es-MX": "Contenido interno de QA — un ejercicio aislado por cada tipo del Motor de Lecciones, para validar el pipeline completo de generación (texto, gates, juez, localización, imágenes, audio, endpoints) antes de una corrida real. No es para alumnos.", "pt-BR": "Conteúdo interno de QA — um exercício isolado por tipo do Motor de Lições, para validar todo o pipeline de geração (texto, gates, juiz, localização, imagens, áudio, endpoints) antes de uma execução real. Não é para alunos."}', '0', '[]') ON CONFLICT (id) DO NOTHING;
INSERT INTO adventures (id, course_id, position, slug, title, description, narrative_arc, theme, age_tier, status) VALUES ('2c90f904-3896-409b-aab8-7c0ecc7ab2bf', 'aab40d79-a597-4e18-a656-b6cc3a29ad47', '1', 'estacion-de-pruebas', '{"en-US": "Liruf''s Lemonade Stand", "es-MX": "El Puesto de Limonada de Liruf", "pt-BR": "A Barraca de Limonada do Liruf"}', '{"en-US": "Liruf opens his first lemonade stand and learns to count money, set prices, save, and sell — one small skill at a time.", "es-MX": "Liruf abre su primer puesto de limonada y aprende a contar dinero, poner precios, ahorrar y vender — una habilidad pequeña a la vez.", "pt-BR": "Liruf abre sua primeira barraca de limonada e aprende a contar dinheiro, definir preços, poupar e vender — uma habilidade de cada vez."}', 'Liruf quiere una guitarra que cuesta 80 pesos. Con ayuda de Dina, Rho y Zara decide ganarse el dinero con un puesto de limonada: primero imagina la idea, luego cuenta sus monedas, arma el puesto, fija un precio justo de 5 pesos por vaso, atiende a sus primeros clientes, aprende de sus errores de cuentas y, día a día, ahorra sus ganancias hasta acercarse a su meta.', 'city', 'tier2', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO sagas (id, adventure_id, position, slug, title, description, icon, status) VALUES ('9ffbe461-9967-4037-93cf-9f30b50790c7', '2c90f904-3896-409b-aab8-7c0ecc7ab2bf', '2', 'secuencias-y-repaso', '{"en-US": "Sale Days & Review", "es-MX": "Días de Venta y Repaso", "pt-BR": "Dias de Venda e Revisão"}', '{"en-US": "Full sale days that mix skills, and quick reviews to make them stick.", "es-MX": "Días de venta completos que mezclan habilidades, y repasos veloces para que se queden.", "pt-BR": "Dias de venda completos que misturam habilidades, e revisões rápidas para fixá-las."}', 'repeat', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO sagas (id, adventure_id, position, slug, title, description, icon, status) VALUES ('3467f69b-7248-4910-aec2-720d49b2db00', '2c90f904-3896-409b-aab8-7c0ecc7ab2bf', '1', 'camara-de-tipos', '{"en-US": "Opening the Stand", "es-MX": "Abrir el Puesto", "pt-BR": "Abrindo a Barraca"}', '{"en-US": "From the first idea to the first sale: money basics, one skill per lesson.", "es-MX": "De la primera idea a la primera venta: fundamentos del dinero, una habilidad por lección.", "pt-BR": "Da primeira ideia à primeira venda: fundamentos do dinheiro, uma habilidade por lição."}', 'storefront', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('c0517497-736c-4d14-b8d4-86e2777d7554', '3467f69b-7248-4910-aec2-720d49b2db00', '3', 'tipos-input', '{"en-US": "The Stand''s Accounts", "es-MX": "Las Cuentas del Puesto", "pt-BR": "As Contas da Barraca"}', 'Escribir y calcular números reales del puesto: cuántos limones hay, cuánto se ganó, cuánto falta para la meta.', '{"en-US": "Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20).", "es-MX": "Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20).", "pt-BR": "Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20)."}', '["suma", "total", "contar"]', 'El precio de 5 pesos por vaso y la meta de 80.', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('46ef76be-b497-4863-b868-2baa537fd2c2', '3467f69b-7248-4910-aec2-720d49b2db00', '1', 'tipos-story', '{"en-US": "The Big Idea", "es-MX": "La Gran Idea", "pt-BR": "A Grande Ideia"}', 'Ganar dinero empieza con una idea: Liruf quiere una guitarra de 80 pesos y decide vender limonada al vecindario en lugar de solo esperar.', '{"en-US": "Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar.", "es-MX": "Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar.", "pt-BR": "Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar."}', '["meta", "ganar", "vender"]', 'Ninguno — es el inicio del curso.', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('61a15ceb-4618-4d2b-bf72-aebf238c98ce', '9ffbe461-9967-4037-93cf-9f30b50790c7', '2', 'repaso-veloz', '{"en-US": "Quick Review", "es-MX": "Repaso Veloz", "pt-BR": "Revisão Rápida"}', 'Volver a tocar lo aprendido días después hace que se quede: precio justo, ahorro y cambio, en versión rápida.', '{"en-US": "Responder de memoria, sin ayuda, las ideas centrales del puesto: el precio justo del vaso y cómo crece el ahorro.", "es-MX": "Responder de memoria, sin ayuda, las ideas centrales del puesto: el precio justo del vaso y cómo crece el ahorro.", "pt-BR": "Responder de memoria, sin ayuda, las ideas centrales del puesto: el precio justo del vaso y cómo crece el ahorro."}', '["repaso", "memoria"]', 'El curso completo del puesto.', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('b2f8b049-5c84-4bf4-ab53-e30a7ab4563e', '3467f69b-7248-4910-aec2-720d49b2db00', '2', 'tipos-choice', '{"en-US": "Seller Decisions", "es-MX": "Decisiones de Vendedor", "pt-BR": "Decisões do Vendedor"}', 'Un vendedor toma decisiones todo el día: qué precio poner, dónde guardar el dinero, a qué cliente atender primero y qué gastos valen la pena.', '{"en-US": "Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo.", "es-MX": "Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo.", "pt-BR": "Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo."}', '["precio", "decisión", "seguro"]', 'La meta de 80 pesos y el precio de 5 pesos por vaso.', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('37c8107a-682c-424b-a8ec-d6a3a45a9594', '3467f69b-7248-4910-aec2-720d49b2db00', '7', 'tipos-storyplay', '{"en-US": "Decision Stories", "es-MX": "Historias con Decisiones", "pt-BR": "Histórias com Decisões"}', 'Vivir el puesto en historias jugables: cada decisión (precio, trato al cliente, gasto) cambia cómo termina el día.', '{"en-US": "Tomar decisiones dentro de historias del puesto y ver sus consecuencias inmediatas en las ventas y el ahorro.", "es-MX": "Tomar decisiones dentro de historias del puesto y ver sus consecuencias inmediatas en las ventas y el ahorro.", "pt-BR": "Tomar decisiones dentro de historias del puesto y ver sus consecuencias inmediatas en las ventas y el ahorro."}', '["decisión", "consecuencia", "cliente"]', 'Todo lo aprendido del puesto hasta aquí.', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('e4b09cd0-6133-41dd-ba93-43d34dda8dff', '3467f69b-7248-4910-aec2-720d49b2db00', '5', 'tipos-money', '{"en-US": "The Money Box", "es-MX": "La Caja del Dinero", "pt-BR": "A Caixa do Dinheiro"}', 'Manejar dinero de verdad: contar monedas mexicanas, dar cambio exacto, repartir la ganancia y avanzar hacia la meta de 80 pesos.', '{"en-US": "Contar dinero con monedas de 1, 2, 5 y 10, calcular cambio de un billete de 20, y planear cuántas semanas faltan para la meta.", "es-MX": "Contar dinero con monedas de 1, 2, 5 y 10, calcular cambio de un billete de 20, y planear cuántas semanas faltan para la meta.", "pt-BR": "Contar dinero con monedas de 1, 2, 5 y 10, calcular cambio de un billete de 20, y planear cuántas semanas faltan para la meta."}', '["cambio", "alcancía", "meta"]', 'Sumas hasta 80; monedas y billetes de México.', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('bef8210e-a360-46ed-a134-94bdf745a1a3', '9ffbe461-9967-4037-93cf-9f30b50790c7', '1', 'combinaciones', '{"en-US": "A Full Day of Sales", "es-MX": "Un Día Completo de Ventas", "pt-BR": "Um Dia Inteiro de Vendas"}', 'Un día real del puesto mezcla todo a la vez: historia, decisiones, cuentas y cambio — como en la vida.', '{"en-US": "Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar.", "es-MX": "Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar.", "pt-BR": "Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar."}', '["venta", "cambio", "jornada"]', 'Todas las habilidades de la saga anterior.', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status) VALUES ('08a1006e-d9fe-4a0c-865a-7c147399dfe9', '3467f69b-7248-4910-aec2-720d49b2db00', '8', 'tipos-maker', '{"en-US": "Stall Builders", "es-MX": "Constructores del Puesto", "pt-BR": "Construtores da Barraca"}', 'Construir y calibrar las herramientas del puesto: la ruta del repartidor, la balanza de trueques, la jarra medidora y la máquina registradora.', '{"en-US": "Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades.", "es-MX": "Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades.", "pt-BR": "Resolver retos de construcción y medición aplicados al puesto: ordenar instrucciones, leer medidas y balancear cantidades."}', '["medir", "construir", "balanza"]', 'Conteos y sumas del puesto.', 'published') ON CONFLICT (id) DO NOTHING;
