INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "fact-opinion", "title": "Hechos y opiniones en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar hechos de opiniones en frases del puesto de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["Un hecho se puede medir o contar, como el precio o la cantidad.", "Una opinión es lo que alguien siente o prefiere, no se puede comprobar."], "title": "¿Qué es un hecho?", "payload": {"statements": [{"id": "a", "text_md": "El vaso cuesta 5 pesos."}, {"id": "b", "text_md": "Mi limonada es la más rica del mundo."}, {"id": "c", "text_md": "Hoy vendí 20 vasos."}, {"id": "d", "text_md": "Esta limonada sabe mejor que la de la competencia."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/d9f92922e88a1227916c0df5728a74da222c315c07f9f127496275e16c90e2f2.png", "prompt_md": "Rho leyó frases del puesto. Toca las que se pueden comprobar (hechos).", "difficulty": 1, "explanation_md": "El precio del vaso (5 pesos) y los vasos vendidos (20) son hechos porque se pueden contar. ''La más rica'' es un gusto, no un hecho.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["a", "c"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6b40c0b2fba2cb98fe9cf74c4b502fc69e09cea6679177100679e5f4ac869af1.mp3", "hash": "c36e37a5c728b4bdc3e72405c2948a0fdc968218f0497c595fe1425db7214d73", "bytes": 33408, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/6b40c0b2fba2cb98fe9cf74c4b502fc69e09cea6679177100679e5f4ac869af1.mp3", "duration_ms": 5520}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2859df72b3cb377a719c04eeaee659e4915f7f0d33370ca9758e59775996c01d.mp3", "hash": "eb043f4613d3ba4f61d3d93ced29887d6a56ac23ea9934f2b1b719398d947c3e", "bytes": 29088, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2859df72b3cb377a719c04eeaee659e4915f7f0d33370ca9758e59775996c01d.mp3", "duration_ms": 4800}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/7684c7fb2261962f5f5d1e67636a6301fa06bffe4d6d86a21dc4a3d439cb2d29.mp3", "hash": "0f91958b4a90e9cca29914eb4916241e299594fbe4ccd336b9afb2f888d81441", "bytes": 32544, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7684c7fb2261962f5f5d1e67636a6301fa06bffe4d6d86a21dc4a3d439cb2d29.mp3", "duration_ms": 5360}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/455af13e5b4852337988b9fd4aefce0a161d0f48a1a5a3d6dd8e8d876e36882a.mp3", "hash": "2087415def4f4a43cf86f37457e32f60e7554d3ee26c6f958307418182403608", "bytes": 65664, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/455af13e5b4852337988b9fd4aefce0a161d0f48a1a5a3d6dd8e8d876e36882a.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "measure-read", "title": "Liruf''s measuring jug", "locale": "en-US", "subject": "mixed", "objectives": ["Read measurements on a graduated jug to serve even 5-dollar cups."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Look at the marks on the jug: 200, 250, 300 ml.", "The liquid reached exactly the middle line."], "title": "The measuring jug", "payload": {"max": 300, "min": 200, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "encouraging", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/882bf9d1a94d5a0a6dc54d63583060f2b167500e804822aa747d14c4ad2a9aad.png", "prompt_md": "Rho filled the jug to the line. How many milliliters does it have?", "difficulty": 1, "explanation_md": "The liquid reached the 250 ml line, right between 200 and 300. That way all the 5-dollar cups are equal.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 250, "tolerance": 0}}', '{"units": {"s1-measure-read.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6b1b808b210f262f2549a5a57b9b4452e4423e69c68484981449c65cc0b92a72.mp3", "hash": "db8eb84cc3e647ffb0e01f5ec9913a6935530c54ee9ba6852792a5c6e48fea39", "bytes": 35856, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6b1b808b210f262f2549a5a57b9b4452e4423e69c68484981449c65cc0b92a72.mp3", "duration_ms": 5920}, "s1-measure-read.hint.1": {"url": "http://localhost:4006/files/lesson-audio/252a6146687646df4de483984577d16d82c587e1a21cf65bf2a89e121d1c6396.mp3", "hash": "5dd49039b41369f53d2acc456fe9467dce22f4e7d0f2131eec9ec9070e1a4665", "bytes": 16128, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/252a6146687646df4de483984577d16d82c587e1a21cf65bf2a89e121d1c6396.mp3", "duration_ms": 2640}, "s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/b913a9058c88c385b71eaa311d265feafc37c83006099e396d509de1a42dfa6b.mp3", "hash": "15e3d0b14af603b1186ee547163281532c8c81313d7a9a15aa72aab2f716bf4f", "bytes": 30528, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b913a9058c88c385b71eaa311d265feafc37c83006099e396d509de1a42dfa6b.mp3", "duration_ms": 5040}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/c7ce0b2393a3e516efa1db13bedd12712cb1699469a030ddabd5d6275542d510.mp3", "hash": "ea7d3d8daac3a5dd90f3e628a47a8afed94a41a2fdf9c4a749402b72eba54c5d", "bytes": 58896, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c7ce0b2393a3e516efa1db13bedd12712cb1699469a030ddabd5d6275542d510.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "measure-read", "title": "O copo medidor de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler medidas em um copo graduado para servir copos iguais de 5 reais."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Observe as marcas do copo: 200, 250, 300 ml.", "O líquido chegou exatamente na linha do meio."], "title": "O copo medidor", "payload": {"max": 300, "min": 200, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "encouraging", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/15261948bd0646e17ea85d094c5a21b3cc35ca9f50db522a2316b331d11d3ca4.png", "prompt_md": "Rho encheu o copo até a linha. Quantos mililitros tem?", "difficulty": 1, "explanation_md": "O líquido chegou na linha de 250 ml, bem entre 200 e 300. Assim todos os copos de 5 reais ficam iguais.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 250, "tolerance": 0}}', '{"units": {"s1-measure-read.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9849b13ff5841f6b9136bb200143babbf7ec885181b19af02b3dc139bec2733d.mp3", "hash": "c4bd91bf601d8b86657468698e88774d14b3638f48053716d92ca0872c55ea3c", "bytes": 41184, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9849b13ff5841f6b9136bb200143babbf7ec885181b19af02b3dc139bec2733d.mp3", "duration_ms": 6800}, "s1-measure-read.hint.1": {"url": "http://localhost:4006/files/lesson-audio/443f4e586e2da97c8ee355592de64b52b8f623e9df74d3a01dce697aec98d336.mp3", "hash": "12536cfcdbeb847ef3fd918ca12051a97664eb2bc1bc07f423d5bad539c6f6f5", "bytes": 21024, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/443f4e586e2da97c8ee355592de64b52b8f623e9df74d3a01dce697aec98d336.mp3", "duration_ms": 3440}, "s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/bb73d7dd3989f4eb9890bcd4c0ddacc618e94cbb1ee876d99937464ae94a1448.mp3", "hash": "b136e5a7ca61c4df70101fdf5685afba3febd3e2675742723817926a155542dd", "bytes": 26784, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/bb73d7dd3989f4eb9890bcd4c0ddacc618e94cbb1ee876d99937464ae94a1448.mp3", "duration_ms": 4400}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/5bd9d5efc446f5389b128b58053ab6d04d8443603dbc91e804b8b3896a65c93d.mp3", "hash": "9efb52aa12230bd2666436fc4ba0e46827293064f4334eee65494ee9275d9c8c", "bytes": 59904, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/5bd9d5efc446f5389b128b58053ab6d04d8443603dbc91e804b8b3896a65c93d.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "quiz-mcq", "title": "Elige el precio justo", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el precio justo para un vaso de limonada (5 pesos) entre opciones exageradas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Si el precio es muy alto, nadie comprará. Si es muy bajo, Liruf no gana nada.", "Piensa en cuánto cuesta hacer un vaso de limonada: limones, agua, azúcar."], "title": "¿A cuánto el vaso?", "payload": {"options": [{"id": "a", "text_md": "1 peso", "rationale_md": "1 peso es muy poco: no alcanza ni para comprar los limones. Liruf perdería dinero."}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "50 pesos", "rationale_md": "50 pesos es demasiado caro para un vaso de limonada. Casi nadie lo compraría."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf pone el precio al vaso de limonada. ¿Cuál es justo para todos?", "difficulty": 1, "explanation_md": "El precio justo es 5 pesos. Así los clientes compran y Liruf gana un poco por su trabajo.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "b"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/db12224c9836b0e6bab1c7dc72798b3d0b5ed184756155aa01979bba948b6658.mp3", "hash": "efd82a443532e431a12b6e3a98c41cb3070061fd7eaa7a83a4cf634db46bd2e3", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/db12224c9836b0e6bab1c7dc72798b3d0b5ed184756155aa01979bba948b6658.mp3", "duration_ms": 6400}, "s1-precio-justo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4658bc1e86f6349c7732ef94bae957105e3f9c0129484935e81f05fd9f1775c5.mp3", "hash": "1b752938a928558f7743d3b636e7459e1a42b56479db277cf7a34c9786c88bdb", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4658bc1e86f6349c7732ef94bae957105e3f9c0129484935e81f05fd9f1775c5.mp3", "duration_ms": 5520}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/878ec70b2c37c4afa7d97839a4ae85bc5759bdc6de8de36c9057902b3c863bac.mp3", "hash": "3eb6eeca31c64dbe0ba828b3d10fda2f4d936ecd6997dfc149db9cfacf502f24", "bytes": 31536, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/878ec70b2c37c4afa7d97839a4ae85bc5759bdc6de8de36c9057902b3c863bac.mp3", "duration_ms": 5200}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/49f7c3026044ba7e790d83d0dfd4e095702f07f4903be7cbdff758746ff7b2e5.mp3", "hash": "4c2221f4d893590203ce7a98405b929419c468664e1f75cbeba6a78982d0a68f", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/49f7c3026044ba7e790d83d0dfd4e095702f07f4903be7cbdff758746ff7b2e5.mp3", "duration_ms": 3920}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/5cd8c2d8e17e36c56da3f92fa4037d0ef488fcee3f3484669ba42d2999170a57.mp3", "hash": "b5d7cb03fa6385cfe33b53a1ddf2ba395b93d4bff8222ed6c487ca2fe7c8dca0", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5cd8c2d8e17e36c56da3f92fa4037d0ef488fcee3f3484669ba42d2999170a57.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'es-MX', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "¿Cierto o Falso? El ahorro que crece", "locale": "es-MX", "subject": "mixed", "objectives": ["Decidir si es cierto o falso: ''Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Piensa: el lunes guardó 5, el martes guardó otros 5, el miércoles otros 5. ¿El total es más que al principio?"], "title": "¿Cierto o falso?", "payload": {"statement_md": "Zara guardó 5 pesos cada día por 3 días. Su ahorro creció.", "justifications": [{"id": "j-crece", "text_md": "Cada día sumó 5 pesos nuevos, así que el total aumentó."}, {"id": "j-no-crece", "text_md": "Cada día gastó los 5 pesos que guardó, así que el total no cambió."}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara vendió limonada 3 días seguidos y guardó 5 pesos cada día. ¿Su ahorro creció?", "difficulty": 1, "explanation_md": "Sí, su ahorro creció. Cada día sumó 5 pesos nuevos: el lunes tenía 5, el martes 10, el miércoles 15. Guardar de cada venta hace que el ahorro aumente.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j-crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b30a7c66009e33de2259eb81698f314809ee6a5a974baa15980479b021c75cd7.mp3", "hash": "050642a8f0f804432cfc29b3423ba63e613da28cb1492cda896de14ea052e3e4", "bytes": 49248, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b30a7c66009e33de2259eb81698f314809ee6a5a974baa15980479b021c75cd7.mp3", "duration_ms": 8160}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/f0f85972cbf686e5f8296c15d78b0363ba3aabf7225225c3307995d69d79a31b.mp3", "hash": "7dc392cc599602b527c8b5885ceb0b9c44cb908e147d7891941562ba832874cd", "bytes": 36864, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/f0f85972cbf686e5f8296c15d78b0363ba3aabf7225225c3307995d69d79a31b.mp3", "duration_ms": 6080}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/95bc13bf55e35a42e090d43a19bd34e8b18e01b3a50f19cfa2f589b465ac28ac.mp3", "hash": "e8fd77f29bb57d8e52fc665bfb7277079c8dc0471a67d7e6cfe6968d6c2d7e5c", "bytes": 65088, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/95bc13bf55e35a42e090d43a19bd34e8b18e01b3a50f19cfa2f589b465ac28ac.mp3", "duration_ms": 10800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparar proveedores de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer una tabla de dos proveedores de limones (precio y cantidad) y elegir el que da más por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 10, "type": "compare_table", "hints": ["Mira cuántos limones da cada uno por el mismo dinero."], "title": "Elige el mejor proveedor", "payload": {"cols": [{"id": "precio", "label": "Precio"}, {"id": "limones", "label": "Limones"}], "rows": [{"id": "proveedor-a", "label": "Puesto A"}, {"id": "proveedor-b", "label": "Puesto B"}], "tokens": [{"id": "a-precio", "text_md": "20 pesos"}, {"id": "a-limones", "text_md": "10 limones"}, {"id": "b-precio", "text_md": "20 pesos"}, {"id": "b-limones", "text_md": "6 limones"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/69e58f683dee884b914afd5e4b64460657ff68543d402ebb2a190c9a81aaad83.png", "prompt_md": "Dina tiene 20 pesos. ¿Con cuál proveedor puede comprar más limones?", "difficulty": 1, "explanation_md": "Con 20 pesos, en el puesto A obtienes 10 limones. En el puesto B, 20 pesos solo alcanzan para 6 limones (porque 24 pesos dan 8, entonces 20 pesos dan menos). El puesto A te da más limones por tu dinero.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "20 pesos", "proveedor-b:precio": "20 pesos", "proveedor-a:limones": "10 limones", "proveedor-b:limones": "6 limones"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/64e10bd8364f1c19dd2f5e64611090e0d2f036b8a409600f40d7b714371c20aa.mp3", "hash": "f4dcff2415e161190e36b3519d4502b222068481c80c1068d22d5f17d80bce1f", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/64e10bd8364f1c19dd2f5e64611090e0d2f036b8a409600f40d7b714371c20aa.mp3", "duration_ms": 4000}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/35e36b8479d5217271cfe82734308ead53ecc09efb59a9b5bf2ddeff834f42bf.mp3", "hash": "665302fd97306a692400ae90e598abc233f7549bc09d85b3be5cfd679acba13c", "bytes": 31968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/35e36b8479d5217271cfe82734308ead53ecc09efb59a9b5bf2ddeff834f42bf.mp3", "duration_ms": 5280}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/17fd3f75ba220cee70f6aa146b5347c4d51f53842914a0246a8b03b43c73dc86.mp3", "hash": "56394cba4752d78079571f82e17f818b69a0f39acdac7593b3aafd05b374c1f9", "bytes": 96768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/17fd3f75ba220cee70f6aa146b5347c4d51f53842914a0246a8b03b43c73dc86.mp3", "duration_ms": 16080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Comparar fornecedores de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler uma tabela de dois fornecedores de limões (preço e quantidade) e escolher o que dá mais por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 10, "type": "compare_table", "hints": ["Veja quantos limões cada um dá pelo mesmo dinheiro."], "title": "Escolha o melhor fornecedor", "payload": {"cols": [{"id": "precio", "label": "Preço"}, {"id": "limones", "label": "Limões"}], "rows": [{"id": "proveedor-a", "label": "Barraca A"}, {"id": "proveedor-b", "label": "Barraca B"}], "tokens": [{"id": "a-precio", "text_md": "20 reais"}, {"id": "a-limones", "text_md": "10 limões"}, {"id": "b-precio", "text_md": "20 reais"}, {"id": "b-limones", "text_md": "6 limões"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/b878dca771e0c75498548386d7002ae4f6da82264036974cc4de9eb284f8d9e5.png", "prompt_md": "Dina tem 20 reais. Com qual fornecedor ela pode comprar mais limões?", "difficulty": 1, "explanation_md": "Com 20 reais, na barraca A você obtém 10 limões. Na barraca B, 20 reais só dão para 6 limões (porque 24 reais dão 8, então 20 reais dão menos). A barraca A te dá mais limões pelo seu dinheiro.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "20 pesos", "proveedor-b:precio": "20 pesos", "proveedor-a:limones": "10 limones", "proveedor-b:limones": "6 limones"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9bee6054a13dfd70d45825fd8311959c125fbbb7f5c4c200a5d0613417fdbea2.mp3", "hash": "0641246e45f304c5a8a3bad4211b6166822c106498cfb9d7ee363534c485d4bf", "bytes": 25776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9bee6054a13dfd70d45825fd8311959c125fbbb7f5c4c200a5d0613417fdbea2.mp3", "duration_ms": 4240}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/d50ef5f4b8e1f6f7f6016acbb54771b0f7486996a82d9e6f5ee6c67c87911770.mp3", "hash": "14081115b8cd567948e269a11dc68fed4d93b3760682f379c915e8d3e6f29c88", "bytes": 36288, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d50ef5f4b8e1f6f7f6016acbb54771b0f7486996a82d9e6f5ee6c67c87911770.mp3", "duration_ms": 6000}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/6d0e519f7f01fc7ad3f95dcc743e841512c34ddde3125fcaa03e1b0aaa3dc4b8.mp3", "hash": "a46625acffb636233231a14a69bed6a80293de1452851f2b71a7ee979476e8c0", "bytes": 96768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6d0e519f7f01fc7ad3f95dcc743e841512c34ddde3125fcaa03e1b0aaa3dc4b8.mp3", "duration_ms": 16080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "La pista del recibo", "locale": "es-MX", "subject": "mixed", "objectives": ["Buscar en el recibo del mercado la evidencia exacta de cuánto costaron los limones."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Busca en el recibo la línea que dice ''limones''.", "Fíjate en el número junto a ''limones''."], "title": "El recibo arrugado", "payload": {"claim_md": "Liruf afirma: ''Gasté 20 pesos en limones.''", "sentences": [{"id": "s1", "text_md": "Limones: 15 pesos"}, {"id": "s2", "text_md": "Azúcar: 5 pesos"}, {"id": "s3", "text_md": "Vasos: 10 pesos"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/941c18fb8df60eebaaebf2e6e83583804d9dc735ae81b1d5f717aa297c7e81ad.png", "prompt_md": "Liruf dice: ''Gasté 20 pesos en limones.'' El recibo dice otra cosa. ¿Qué evidencia muestra el recibo?", "difficulty": 1, "explanation_md": "El recibo muestra que los limones costaron 15 pesos, no 20. Liruf se equivocó al sumar.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d1e94f5ca4dc9ca770a6869ed595de8f2fa3f5d28a0177d2e7c5f0da60c82a58.mp3", "hash": "6c8bba7ccd6403011c2b49c55c0067de0d734b6025a26e6ef5466de394acac24", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d1e94f5ca4dc9ca770a6869ed595de8f2fa3f5d28a0177d2e7c5f0da60c82a58.mp3", "duration_ms": 4000}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5ee5094a931df6720a0451c72e79c6283432aaf7f3b39ef3fd48e41ddfc28398.mp3", "hash": "f02ca3068489a89b4a79ecae7406327d5d6f0e23ff062c7fb2b32d3950cf24f0", "bytes": 16128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5ee5094a931df6720a0451c72e79c6283432aaf7f3b39ef3fd48e41ddfc28398.mp3", "duration_ms": 2640}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/7d7d8978a6ee83fa383592750bd9e644ad6d003d5c9380fa733929b5be5e0488.mp3", "hash": "4b21cf6a2ff98b1ad5dad2c9fb2b63b7a61332954b18270e1d61584198386065", "bytes": 48816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7d7d8978a6ee83fa383592750bd9e644ad6d003d5c9380fa733929b5be5e0488.mp3", "duration_ms": 8080}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/1775c423ebf334cbcb33e26777f8d47851729d15e4fb051f3d41e0f5c1ab8574.mp3", "hash": "12a9b026d9abac5313a365fc96ea84c5a3657c27b0e618b53f223051d9f957de", "bytes": 43488, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1775c423ebf334cbcb33e26777f8d47851729d15e4fb051f3d41e0f5c1ab8574.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Write and calculate real numbers from the stand", "locale": "en-US", "subject": "money", "objectives": ["Write exact numeric and text answers about the day''s sales (sums up to 80, counts up to 20).", "Write the word that names the money you save for later: ''savings''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["If he saves 5 dollars on day 1, he already has 5. How much does he need?", "On day 2 he saves another 5. Add 5 + 5."], "title": "How many days for the guitar?", "payload": {"max_chars": 2, "placeholder": "Write the number"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho saves 5 dollars each day. The guitar costs 10 dollars. How many days must he save to buy it?", "difficulty": 1, "explanation_md": "That''s right! 5 dollars the first day and 5 the second add up to 10. Rho needs 2 days of saving for the guitar.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["2", "dos"], "keywords": ["2", "dos"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/51e0acd7ffd9c969b86d2a6790a93e56fa5d4f37bed1306d185dec51bda0994d.mp3", "hash": "711288317bf139868fe780d8b505b3ef77609f1a09608d90556bbcd7d86b83bc", "bytes": 38736, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/51e0acd7ffd9c969b86d2a6790a93e56fa5d4f37bed1306d185dec51bda0994d.mp3", "duration_ms": 6400}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7ae3b81aac9816a8a920e2ce29dbd0d5ee501a823d56cdc34e058ade586ac3ff.mp3", "hash": "3a4c6ad7e5598409318569e042be1743924ea181de8810bdc6e1e0cbffeccc6e", "bytes": 31104, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/7ae3b81aac9816a8a920e2ce29dbd0d5ee501a823d56cdc34e058ade586ac3ff.mp3", "duration_ms": 5120}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/cb773e1ec0f9f6f92e7dd4d8db7e2bcc9440b5fd6a6b55bc8246a61e342c72da.mp3", "hash": "6a211929a084b196a40de7dc5e4bd21c51c62cd95ba8f6c3526547215e389ff5", "bytes": 46368, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/cb773e1ec0f9f6f92e7dd4d8db7e2bcc9440b5fd6a6b55bc8246a61e342c72da.mp3", "duration_ms": 7680}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/07be481ab146e6364e7b8d729476f9710300866a44ef2c75cca579c42afe36c0.mp3", "hash": "def68dd1a9aa89f3a6a3a73526729f8e3b672cf62f89e003ee371ad37c2e70ce", "bytes": 52704, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/07be481ab146e6364e7b8d729476f9710300866a44ef2c75cca579c42afe36c0.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escrever e calcular números reais do posto", "locale": "pt-BR", "subject": "money", "objectives": ["Escrever respostas numéricas e de texto exatas sobre as vendas do dia (somas até 80, contagens até 20).", "Escrever a palavra que nomeia o dinheiro que você guarda para depois: ''poupança''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Se ele poupa 5 reais no dia 1, já tem 5. Quanto falta?", "No dia 2 ele poupa outros 5. Some 5 + 5."], "title": "Quantos dias para o violão?", "payload": {"max_chars": 2, "placeholder": "Escreva o número"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho poupa 5 reais cada dia. O violão custa 10 reais. Quantos dias ele deve poupar para comprá-lo?", "difficulty": 1, "explanation_md": "Isso mesmo! 5 reais no primeiro dia e 5 no segundo somam 10. Rho precisa de 2 dias de poupança para o violão.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["2", "dos"], "keywords": ["2", "dos"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d3c1d4a16c99a6db7de0cb8a94e0aae84c28e53899c4ca464049e2e7d2d0c2ac.mp3", "hash": "46893d864b22f05c146e3327d696a9e9456f3bc704da4c938996d997b8d673fa", "bytes": 31104, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d3c1d4a16c99a6db7de0cb8a94e0aae84c28e53899c4ca464049e2e7d2d0c2ac.mp3", "duration_ms": 5120}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/270ff1616e6370eab9b18d3cf290bcb0f478db56d462b41257a56f66f806d04c.mp3", "hash": "2800855abbe2053887d4d37ce332afdbe9accc14d5eb2be19d46e883fcfe0063", "bytes": 30528, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/270ff1616e6370eab9b18d3cf290bcb0f478db56d462b41257a56f66f806d04c.mp3", "duration_ms": 5040}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/d47896849bcbb9550f3424d7ffb029794cc76554ac01904f662f68d9fc1fe53c.mp3", "hash": "b0d3992be96e02ddf70f113c375e2c09e32ef03f2f771aa4ba436dbafdbbd4f6", "bytes": 54576, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d47896849bcbb9550f3424d7ffb029794cc76554ac01904f662f68d9fc1fe53c.mp3", "duration_ms": 9040}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/83fdc79fcd3d0d21891c129d66d4d6396305de06c0f1652c5780fd6152668268.mp3", "hash": "29bffe8745860171b477ee17e54f542eda8c6d3a3241d7e35ad46f7184dac127", "bytes": 57024, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/83fdc79fcd3d0d21891c129d66d4d6396305de06c0f1652c5780fd6152668268.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "count-objects", "title": "Conte as moedas do Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de uma olhada para saber quanto Liruf vendeu hoje."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta-monedas", "xp": 10, "type": "count_objects", "hints": ["Conte apenas as moedas, não os biscoitos nem o copo.", "Você pode tocá-las uma por uma para não se perder."], "title": "Moedas na mesa", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 6}, {"icon": "cookie", "tint": "accent", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Quantas moedas você vê?", "difficulty": 1, "explanation_md": "Há 6 moedas. Cada moeda é um copo de 5 reais que Liruf vendeu hoje. Isso soma 30 reais para o violão de 80.", "audio_segment_id": "s1-cuenta-monedas.prompt"}], "schema_version": 1}', '{"s1-cuenta-monedas": {"value": 6}}', '{"units": {"s1-cuenta-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2b06e6b6bc8b5dfcc9a7872555412c38aa6e875d304d6be88fab1ffce4f51f2e.mp3", "hash": "6f64ae3c7832d089b4f35595a826a4c5642e98bf6a48e89e41fd1da412b5538c", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2b06e6b6bc8b5dfcc9a7872555412c38aa6e875d304d6be88fab1ffce4f51f2e.mp3", "duration_ms": 4000}, "s1-cuenta-monedas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ba29558342de4ef3b2f116ca5a72ef11275e29b0eb0e9ef013d744c8b5b29877.mp3", "hash": "e3a8f72d1d0c2826fcdb4fd0181ffbe5d3f9568ce52b9d11ae534b5f9af08d94", "bytes": 22464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ba29558342de4ef3b2f116ca5a72ef11275e29b0eb0e9ef013d744c8b5b29877.mp3", "duration_ms": 3680}, "s1-cuenta-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/ce0763c29812bda77d23452a4d75bfa927e6d5b7c7392730e72de597795dca67.mp3", "hash": "275edfc5716a51997ea7030c504b05c29733a874e82830113e65ae9932b61435", "bytes": 10944, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ce0763c29812bda77d23452a4d75bfa927e6d5b7c7392730e72de597795dca67.mp3", "duration_ms": 1760}, "s1-cuenta-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/437d2443f31ceb539f58e089ffdcf859c56a5a30156032a08c70760a342f1cd1.mp3", "hash": "d95b55f452c31d30725a6f9faca17eb2ea1bf6412e54c620e4a46513a6ccbc70", "bytes": 57456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/437d2443f31ceb539f58e089ffdcf859c56a5a30156032a08c70760a342f1cd1.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "dialogue-choice", "title": "Choosing what to say to a customer asking for a discount", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing a kind response that doesn''t give away profit when a customer asks for a discount"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cliente-rebaja", "xp": 15, "type": "dialogue_choice", "hints": ["Think: if you lower it too much, do you gain anything?", "You can be kind without losing your profit."], "title": "Do you lower the price?", "payload": {"turns": [{"id": "t1", "npc_md": "Customer: ''Can you give it to me for 3?''", "replies": [{"id": "r1", "text_md": "Sure, for you, I''ll give it to you for 3."}, {"id": "r2", "text_md": "Sorry, the price is 5 dollars. It''s nice and cold!"}, {"id": "r3", "text_md": "No, I can''t. If you don''t like it, leave."}]}, {"id": "t2", "npc_md": "Customer: ''Okay, thanks. Then I''ll take one.''", "replies": [{"id": "r4", "text_md": "Thank you! Enjoy it."}, {"id": "r5", "text_md": "Are you sure? I could give you two for 8 dollars."}, {"id": "r6", "text_md": "Okay, but hurry up."}]}], "persona": {"name": "Liruf", "role_md": "lemonade stand owner", "character": "liruf"}, "opening_md": "A customer approaches and says: ''Hey, can you give it to me for 3 dollars? I only have that!''"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/907bcc3a5be51a71989eb7ca266de808a0e0821a7d6e88997d1ac6f761d55f2a.png", "prompt_md": "A customer wants a glass of lemonade but asks for a discount. What do you say?", "difficulty": 2, "explanation_md": "Liruf earns 5 dollars per glass. If he lowers it to 3, he only earns 2 dollars. Better to offer the same price with kindness.", "audio_segment_id": "s1-cliente-rebaja.prompt"}], "schema_version": 1}', '{"s1-cliente-rebaja": {"turns": [{"turn_id": "t1", "qualities": {"r1": 20, "r2": 100, "r3": 10}, "reactions": {"r1": "El cliente paga 3, pero Liruf gana solo 2 pesos. No alcanza para la guitarra.", "r2": "El cliente sonríe y paga 5. ¡Liruf gana su ganancia completa!", "r3": "El cliente se va enojado. Liruf no vende nada."}}, {"turn_id": "t2", "qualities": {"r4": 100, "r5": 80, "r6": 30}, "reactions": {"r4": "El cliente se va contento. ¡Venta exitosa!", "r5": "El cliente duda, pero acepta. Liruf vende 2 vasos, gana 10 pesos.", "r6": "El cliente se siente apurado y se va sin comprar."}}]}}', '{"units": {"s1-cliente-rebaja.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3ff73c0ea120c32e528b62fe4abdec4e6861450eac17fc66cf77e66d18a7cdb6.mp3", "hash": "220bf46b53e85f151fc371d75cb3a7d9c00005f8aaa11873e9f623d90784968c", "bytes": 19584, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/3ff73c0ea120c32e528b62fe4abdec4e6861450eac17fc66cf77e66d18a7cdb6.mp3", "duration_ms": 3200}, "s1-cliente-rebaja.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e2709413e1345dbabf221d6f3057b3060937e8341f731b5d2c0401ee4bc0e3e7.mp3", "hash": "64de2cc425fcf668a6cc29d88a2f26e1a6984a1390522c1c0a480eb2521bc1e7", "bytes": 15696, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e2709413e1345dbabf221d6f3057b3060937e8341f731b5d2c0401ee4bc0e3e7.mp3", "duration_ms": 2560}, "s1-cliente-rebaja.prompt": {"url": "http://localhost:4006/files/lesson-audio/28ea8c07b98ef5c602ca4689ba510b628a8ab694423ce39d377c9b2dd793cecc.mp3", "hash": "64ccf6a4b06f5a6a6fc769ad54875c41ca4fe7d29f66da109155cd461ca5b931", "bytes": 28656, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/28ea8c07b98ef5c602ca4689ba510b628a8ab694423ce39d377c9b2dd793cecc.mp3", "duration_ms": 4720}, "s1-cliente-rebaja.explanation": {"url": "http://localhost:4006/files/lesson-audio/6c51e82c23ba55fa857fe3da9c96872e66dbeace3b5873cebefb4c82b3973a8c.mp3", "hash": "e8cdf2d7d23a097033f4e7b825cb1e067b327f7b98a334fcc7f70368bcaa1dec", "bytes": 54144, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6c51e82c23ba55fa857fe3da9c96872e66dbeace3b5873cebefb4c82b3973a8c.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Señales de alerta en un trato", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar las señales de alerta en la oferta de un desconocido: promesas demasiado buenas no son de fiar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Piensa: ¿es normal ganar tanto dinero en un día sin trabajar?", "¿Conoces a esa persona? ¿Por qué te ofrecería tanto?"], "title": "El negocio mágico", "payload": {"flags": [{"id": "f1", "text_md": "La persona es un desconocido"}, {"id": "f2", "text_md": "Promete mucho dinero sin explicación"}, {"id": "f3", "text_md": "Pide dinero hoy a cambio de una promesa"}, {"id": "f4", "text_md": "Dice que es ''mágico'' o ''seguro''"}], "artifact_md": "Un señor desconocido se acerca al puesto de Liruf y le dice: ''Oye, niño, dame tus 20 pesos hoy. Mañana te devuelvo 100. Es un negocio mágico, no pierdes nada.''", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/a55bb6dc0e2d9830ba6d28e482363dd26e346272adbfb490a72a7ffbc838f1dd.png", "prompt_md": "Liruf está en su puesto. Un señor se acerca y le dice: ''Dame tus 20 pesos hoy y mañana te doy 100''. ¿Qué señales de alerta ves?", "difficulty": 1, "explanation_md": "Las promesas de ganar mucho dinero rápido sin esfuerzo suelen ser falsas. Si suena demasiado bueno para ser verdad, probablemente no es cierto.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["f1", "f2", "f3", "f4"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1796f1fcf1d3fd717f16332a7a7398aed6d30f0b0d2b2437be1eae1ec3d7ca71.mp3", "hash": "0cd0ea8b4aea2b97695f53dd498687b93915091e17a8d1b2ca249798947075be", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1796f1fcf1d3fd717f16332a7a7398aed6d30f0b0d2b2437be1eae1ec3d7ca71.mp3", "duration_ms": 4400}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c6298f38f7933ae8ba120a378d9f28b6ec8a99c2bd43244d8590042533a30472.mp3", "hash": "2ef466c377fcd8db83580a7fddd20140efe6b1c935cc9bdbc76296973c39c539", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c6298f38f7933ae8ba120a378d9f28b6ec8a99c2bd43244d8590042533a30472.mp3", "duration_ms": 3920}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/ad2f861e2ff44a8716b5e1c9c70d739fa416d55da18e4181704163e39580e82d.mp3", "hash": "7e1379d0792d0f344095255ce3d40da5e46ffb4d69986d93fe45c0c811d7c759", "bytes": 56448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ad2f861e2ff44a8716b5e1c9c70d739fa416d55da18e4181704163e39580e82d.mp3", "duration_ms": 9360}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/4b26c702fe144f2b43e71467f7000659ba2ae80a1b584ca2dacc190911ce1ef0.mp3", "hash": "0215a0f021a6a2c14331ade4fa1ef0bfbe0f1d8f4f934dafb065135f931190bc", "bytes": 56448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4b26c702fe144f2b43e71467f7000659ba2ae80a1b584ca2dacc190911ce1ef0.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "rank-choices", "title": "Priorities at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Order from most to least urgent what to spend today''s profit on: restock lemons first, then cups, and finally decorations."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 10, "type": "rank_choices", "hints": ["Without lemons you can''t make lemonade.", "Decorations are nice, but not urgent."], "title": "What to buy first?", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/ece9633fe96f5d045707a81fce31cc8e162d1218fb688c4267f35a3823968ce9.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/cee7eb92d17fec9d4e97c0798b301ba4a3c11c0e97c9ad608b50e17ac9ae9747.png"}, {"id": "adornos", "text_md": "Decorations", "image_url": "http://localhost:4006/files/lesson-images/134238407570169c23bd4f0db5d32f7fd140a19affac5ab965dee17e7ae2aeb9.png"}], "criterion_md": "Urgency for the stand: what you need most today goes first."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Order the purchases from most urgent to least urgent for Liruf''s stand.", "difficulty": 1, "explanation_md": "Lemons are the most urgent because without them there is no lemonade. Cups are necessary for serving. Decorations can wait.", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank-choices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/49ba0dd4373c585815f6c9bebb79a198f9cbd09706f643bd77443535cbd446ea.mp3", "hash": "e34a29ee46bb4134fb5691856494d3197e09130ad737bded77bda2e6206dad77", "bytes": 16704, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/49ba0dd4373c585815f6c9bebb79a198f9cbd09706f643bd77443535cbd446ea.mp3", "duration_ms": 2720}, "s1-rank-choices.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d9768c9014c70b80712bd3549d1b275227cf7356c313dde1bfc05b3707ea4ed7.mp3", "hash": "b50d375662ed63221ecc665f60babeedd9127feedb7dc5911bb74211d8fcd3ca", "bytes": 17568, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d9768c9014c70b80712bd3549d1b275227cf7356c313dde1bfc05b3707ea4ed7.mp3", "duration_ms": 2880}, "s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/1b4fec3d5f38611921f166be3138aca8ad2e70b24f40b34d504ea8358337179e.mp3", "hash": "3eb0e0b1e45acc943d61e05d42995185d3aeea87e5a4e16020ffc46d129ad1b3", "bytes": 30096, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1b4fec3d5f38611921f166be3138aca8ad2e70b24f40b34d504ea8358337179e.mp3", "duration_ms": 4960}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/a15473b087edac4f5d495d3cd74bc6e7d45abd4430ae3060a278c849ea7170ba.mp3", "hash": "e6a322329dbbc0de9a245153de14b24700eae658697de845c41744183a7e9ba8", "bytes": 57456, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a15473b087edac4f5d495d3cd74bc6e7d45abd4430ae3060a278c849ea7170ba.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "fact-opinion", "title": "Facts and opinions at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Separate facts from opinions in lemonade stand sentences"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["A fact can be measured or counted, like price or quantity.", "An opinion is what someone feels or prefers; it cannot be proven."], "title": "What is a fact?", "payload": {"statements": [{"id": "a", "text_md": "The cup costs $5."}, {"id": "b", "text_md": "My lemonade is the tastiest in the world."}, {"id": "c", "text_md": "Today I sold 20 cups."}, {"id": "d", "text_md": "This lemonade tastes better than the competition''s."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/60b617ec84c99f6a662ed8a84ebda9836100fb5c3332cab036c4e4cfbf649e91.png", "prompt_md": "Rho read stand sentences. Tap the ones that can be proven (facts).", "difficulty": 1, "explanation_md": "The price of a cup ($5) and cups sold (20) are facts because they can be counted. ''The tastiest'' is a preference, not a fact.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["a", "c"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/608b83af461ae64c3210db8b8b841c97a535f36827bfbfb0d6ab269821627aa8.mp3", "hash": "dc6fd128e74660b352ce88982e312dcc21df5b439b2fd4706f8f7a0450953d9f", "bytes": 25344, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/608b83af461ae64c3210db8b8b841c97a535f36827bfbfb0d6ab269821627aa8.mp3", "duration_ms": 4160}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/400fcd22767c55b1b08da3cb2e4e1fd69d63344964ac00cd5eea9682e3dcc88f.mp3", "hash": "2f7ab49ea9a259a4a45e1fee3969b0043ca04f80e3165906c15c0c8427b7776a", "bytes": 27648, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/400fcd22767c55b1b08da3cb2e4e1fd69d63344964ac00cd5eea9682e3dcc88f.mp3", "duration_ms": 4560}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/6e66090719036a0a9df046cdd2542c83bfe7212bebd9cb04ac65afd77b710b47.mp3", "hash": "9fce15a60a0879d353ae42e5e381f8467bdf9589b93a002e2106fc5f2f8d7194", "bytes": 30528, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6e66090719036a0a9df046cdd2542c83bfe7212bebd9cb04ac65afd77b710b47.mp3", "duration_ms": 5040}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/71804209a53c68070a9d46d1da857fc917cd4befa36499f5e920948aab58e587.mp3", "hash": "c1e3ec19dd615653ade515117ecdff28fa112ae240d43898d81cf408ff1674d1", "bytes": 57024, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/71804209a53c68070a9d46d1da857fc917cd4befa36499f5e920948aab58e587.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "El mercado de Liruf", "locale": "es-MX", "subject": "money", "objectives": ["Contar dinero con monedas de 1, 2, 5 y 10", "Calcular cambio de un billete de 20", "Planear cuántas semanas faltan para la meta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["Suma el precio de los limones y el azúcar: 8 + 6 = 14. Luego resta 14 de 20 para saber cuánto le queda."], "title": "Resurtir el puesto", "payload": {"items": [{"id": "limones", "icon": "nutrition", "need": true, "label": "Limones", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/27766a3f46a1fda722d64a7b573d05e6279ba2e8360049e0a0afd516f15ea190.png"}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Azúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/4d538964712016457bc978b933eab53e14e206b5348e1ba867df133f35c5f532.png"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Hielo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/32fbe582d09e98a014853f52b2be5934a9376afe242f0be86b058a58b5caa970.png"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Popotes", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/611fd0c4a73c6df94f91d908c48e393c975ae2cefa0e9f973f83bfbac2f9fae1.png"}, {"id": "jarra", "icon": "local_bar", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/ebc7b8fae9af175a35b561460bb579cbdb91f35e707f9d74dd2bcf303655aa9d.png"}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf tiene un billete de $20. Debe comprar limones ($8) y azúcar ($6). ¿Qué más cabe sin pasarse de $20?", "difficulty": 2, "explanation_md": "Liruf necesita limones y azúcar para la limonada. Si gasta 8 + 6 = 14, le quedan 6 pesos. El hielo cuesta 5, los popotes 3, y la jarra 8. Solo el hielo (5) cabe en los 6 que le quedan. Si compra la jarra (8), se pasa y el marchante le quita algo; si compra popotes (3), aún le sobra, pero el hielo es mejor para la limonada.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9ca30195375fc3926a02e265ae6cb54bb2fed1ff94c4ad7907b0e9242d505742.mp3", "hash": "81e630e7bb8f10e7e65c24ea6e6c3a8d36c9468d3b3576a20918f9db4643e7fd", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9ca30195375fc3926a02e265ae6cb54bb2fed1ff94c4ad7907b0e9242d505742.mp3", "duration_ms": 9280}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/658ed6cf7abc15bbe36e2e86e5d9e28b502169b8ab56f81a8906188a5999c648.mp3", "hash": "c1cdc1ad5ee06e9aab952d0d90e2fe2e0ed526efdc16324a4542005c7c38b68f", "bytes": 62208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/658ed6cf7abc15bbe36e2e86e5d9e28b502169b8ab56f81a8906188a5999c648.mp3", "duration_ms": 10320}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/b9435fd810fee75cd98c1066f376cb65283bd32059948117398b62b43265f1ee.mp3", "hash": "a4ec6cd0eb3811fcf64034d002ad594aaa6d1f2435b68d0f223bb89631e9fcaf", "bytes": 145296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b9435fd810fee75cd98c1066f376cb65283bd32059948117398b62b43265f1ee.mp3", "duration_ms": 24160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Caça o erro na promoção", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encontrar o erro em um cartaz de promoção e corrigi-lo"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-promo", "xp": 15, "type": "debug_hunt", "hints": ["Pense quanto custa um copo avulso.", "Compare o preço de 2 copos avulsos com os 8 reais da promoção."], "title": "A promoção que não fecha", "payload": {"blocks": [{"id": "block1", "text_md": "2 copos por 8 reais"}, {"id": "block2", "text_md": "1 copo custa 5 reais"}, {"id": "block3", "text_md": "Economize 2 reais!"}], "intro_md": "Liruf colocou um cartaz: ''2 copos por 8 reais''. Mas os clientes riem: sai mais caro do que comprá-los avulsos!"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Qual é o erro no cartaz da Liruf?", "difficulty": 2, "explanation_md": "Dois copos avulsos custam 10 reais (5+5), mas a promoção os vende por 8. É mais barato, não mais caro!", "audio_segment_id": "s1-debug-promo.prompt"}], "schema_version": 1}', '{"s1-debug-promo": {"fix_md": "¡Ahorra 2 pesos! → ¡Ahorra 2 pesos! (en realidad es más caro, no ahorras)", "bug_ids": ["block3"]}}', '{"units": {"s1-debug-promo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fbcac3c948579c5b5f3d5718266d9b6a5ae13fddde673ec5926fb0f3f92fe380.mp3", "hash": "ce4f29575781e818561c8929a1a2c9dd1c3ce693a7e7673f1fca82ca84ed942f", "bytes": 16704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fbcac3c948579c5b5f3d5718266d9b6a5ae13fddde673ec5926fb0f3f92fe380.mp3", "duration_ms": 2720}, "s1-debug-promo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/896ce09fc6443991a965a5d83116655e7d867f5877b765cd196c6717762fd3c2.mp3", "hash": "83bc4a9bfafeeece32b0ed3575c6e460789cc97a3cb125112730982db795723a", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/896ce09fc6443991a965a5d83116655e7d867f5877b765cd196c6717762fd3c2.mp3", "duration_ms": 4400}, "s1-debug-promo.prompt": {"url": "http://localhost:4006/files/lesson-audio/296b9861d29cdc0182820b7a6cee61f6237f99df0050a70236453264a49103f3.mp3", "hash": "3d3a6724ebd71f58b7890a4989fe6c5562c7c8fd4985a8feb53030d83728cb3c", "bytes": 14688, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/296b9861d29cdc0182820b7a6cee61f6237f99df0050a70236453264a49103f3.mp3", "duration_ms": 2400}, "s1-debug-promo.explanation": {"url": "http://localhost:4006/files/lesson-audio/e6ceeccb2407feb951ca199465ac89d57cd26cc3d4613069d343861fcd3d2788.mp3", "hash": "adb5babb1bc78f022ff1acbaf40ee18cf3fed0897e6758ad3b0e01885a29e43f", "bytes": 53568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e6ceeccb2407feb951ca199465ac89d57cd26cc3d4613069d343861fcd3d2788.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "fact-opinion", "title": "Fatos e opiniões na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar fatos de opiniões em frases da barraca de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["Um fato pode ser medido ou contado, como o preço ou a quantidade.", "Uma opinião é o que alguém sente ou prefere, não pode ser comprovada."], "title": "O que é um fato?", "payload": {"statements": [{"id": "a", "text_md": "O copo custa 5 reais."}, {"id": "b", "text_md": "Minha limonada é a mais gostosa do mundo."}, {"id": "c", "text_md": "Hoje vendi 20 copos."}, {"id": "d", "text_md": "Esta limonada tem um sabor melhor que a da concorrência."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/e06373b713e3b14a54a424d574bdb240e5819a9e0e27b4826b449ae16f49c8d1.png", "prompt_md": "Rho leu frases da barraca. Toque nas que podem ser comprovadas (fatos).", "difficulty": 1, "explanation_md": "O preço do copo (5 reais) e os copos vendidos (20) são fatos porque podem ser contados. ''A mais gostosa'' é um gosto, não um fato.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["a", "c"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/76834aca413bd20f01e6f4f21f096b187e02ceb9b2733a58df11aebf8b4b204f.mp3", "hash": "42777136d7dfb8fea9078a5c9f348d3a00c2a10f9c449e778af451457396bf15", "bytes": 29088, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/76834aca413bd20f01e6f4f21f096b187e02ceb9b2733a58df11aebf8b4b204f.mp3", "duration_ms": 4800}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a36869dfc4e8b5c274d6a52bc43e266b34d8122a51862ede9d1ce6a955a804a1.mp3", "hash": "16719bee46c2dc29a421cce018a993ac6692b0c1fa63a5acba2ab707fcc0661b", "bytes": 33408, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a36869dfc4e8b5c274d6a52bc43e266b34d8122a51862ede9d1ce6a955a804a1.mp3", "duration_ms": 5520}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/64b52cb003aa76fd1fdd7f95d36575f88baf8e0ed944346bb432681127e24784.mp3", "hash": "3438ef299ee9f1cb2732d0a779fa82c2026b510100f074ca555434031391f72c", "bytes": 35856, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/64b52cb003aa76fd1fdd7f95d36575f88baf8e0ed944346bb432681127e24784.mp3", "duration_ms": 5920}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/5bbad7d82a59626147fa0556b46b3186051f41c3bcd811e891068a74310ee237.mp3", "hash": "f2d84d577c7d09d865174ac8ae27ad6f218d6152460f5b587a16c4b39e8be8e7", "bytes": 68544, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/5bbad7d82a59626147fa0556b46b3186051f41c3bcd811e891068a74310ee237.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "A real day at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Chain several skills in one lesson: listen to the situation, decide, calculate, and charge."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "title": "Sunny Saturday", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/5ace29dc3dbe344dbd2849585ea23f502edbfd1489964b8ea261218a7f8b9e0e.png"}, "action": "idle", "body_md": "It''s Saturday morning. The sun is shining and Liruf has prepared a big pitcher of lemonade. There are already three customers waiting. It''s time to decide today''s price!", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Liruf opens his lemonade stand. There''s already a line of customers!", "difficulty": 1, "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-precio-del-dia", "xp": 15, "type": "quiz_mcq", "hints": ["Think of a price that is fair for customers and gives Liruf a profit.", "Remember that making lemonade costs money: lemons, sugar, cups."], "title": "Price of the day", "payload": {"options": [{"id": "a", "text_md": "2 dollars", "rationale_md": "2 dollars is too little. Liruf wouldn''t earn enough to buy more lemons."}, {"id": "b", "text_md": "5 dollars"}, {"id": "c", "text_md": "10 dollars", "rationale_md": "10 dollars is too expensive. Customers might go to another stand."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "How much will Liruf charge for each cup of lemonade today?", "difficulty": 2, "explanation_md": "Liruf decides to charge 5 dollars per cup, the same price as always. That way customers know what to expect and Liruf covers his costs.", "audio_segment_id": "s2-precio-del-dia.prompt"}], "schema_version": 1}', '{"s2-precio-del-dia": {"correct_option_id": "b"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/0463f5ee9abd3da11980aa157bbe36ea1e32cb478cf48a8cff1ea338fde126ae.mp3", "hash": "c1b1b075b9425c152bdc9de78a2361e87e3758648c8c3d651f641b9cbe9158ed", "bytes": 58464, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/0463f5ee9abd3da11980aa157bbe36ea1e32cb478cf48a8cff1ea338fde126ae.mp3", "duration_ms": 9680}, "s2-precio-del-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/594535cc2193f82555fb514e6f260e2812050a444074daa4c3a5d032222bf923.mp3", "hash": "bd543c49301474478a5e8fab0645c65b9c521e3bfb06c098414d20d39b420c73", "bytes": 26208, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/594535cc2193f82555fb514e6f260e2812050a444074daa4c3a5d032222bf923.mp3", "duration_ms": 4320}, "s2-precio-del-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/410a0ea3d3741690408c3f7bf7d41c6f675b5c727698ac915be4fb5f894eca65.mp3", "hash": "6ce19b1b7fbb217390a90d186a3f8d892567108c90654dad855772e470ec9a23", "bytes": 26784, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/410a0ea3d3741690408c3f7bf7d41c6f675b5c727698ac915be4fb5f894eca65.mp3", "duration_ms": 4400}, "s2-precio-del-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/efb3eb8166169d0ac74b4e85f679d24c6ace5860e19ec2aa3dabcd18a5560db7.mp3", "hash": "113db496df9bfc1a84d57273bae6b74ce9555084828ea8269f206717a73a3c1d", "bytes": 21456, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/efb3eb8166169d0ac74b4e85f679d24c6ace5860e19ec2aa3dabcd18a5560db7.mp3", "duration_ms": 3520}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/4c9184a32b0612eaa7be5ecee9c3f9cf7d2cf509abefaef8f6fa3a2d774e9321.mp3", "hash": "3143bc241380d98bffd165debb96cf51c178974c8269207fbbe63a26c4b71904", "bytes": 25344, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/4c9184a32b0612eaa7be5ecee9c3f9cf7d2cf509abefaef8f6fa3a2d774e9321.mp3", "duration_ms": 4160}, "s2-precio-del-dia.choices": {"url": "http://localhost:4006/files/lesson-audio/58eed3c58ee1b90f6b713ede66fa76777f2e0e7739ef39ea3b33de6a04a2f8ba.mp3", "hash": "3c6929f8b497be455ccd397cce433cac5f04d1c10211e7a40bf02753bc35df36", "bytes": 17136, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/58eed3c58ee1b90f6b713ede66fa76777f2e0e7739ef39ea3b33de6a04a2f8ba.mp3", "duration_ms": 2800}, "s2-precio-del-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/ee3b2939360cff97cc539f376ab43bfd745964f3d64dc0643a85388a05856032.mp3", "hash": "99dc6a3b4bdd664380648e573bbd113eb654bd72d1e003230695ea7b36e44b10", "bytes": 53568, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/ee3b2939360cff97cc539f376ab43bfd745964f3d64dc0643a85388a05856032.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa e efeito no estande", "locale": "pt-BR", "subject": "mixed", "objectives": ["Conectar causas e efeitos do estande: dia ensolarado → mais sede → mais copos vendidos; subir o preço ao dobro → menos clientes."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 10, "type": "cause_effect", "hints": ["Pense: o que aconteceu primeiro?", "O sol faz com que as pessoas tenham mais sede."], "title": "O que aconteceu?", "payload": {"slots": 5, "events": [{"id": "e1", "text_md": "Dia ensolarado e quente"}, {"id": "e2", "text_md": "As pessoas têm mais sede"}, {"id": "e3", "text_md": "Liruf vende 12 copos de limonada"}, {"id": "e4", "text_md": "Rho aumenta o preço para R$10 por copo"}, {"id": "e5", "text_md": "Menos clientes compram limonada"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toque nos eventos em ordem: causa → efeito.", "difficulty": 1, "explanation_md": "O dia ensolarado fez com que as pessoas tivessem sede, por isso compraram mais limonada. Liruf vendeu 12 copos!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/22ed8d4e2db7b291d61fec187615a4fcb6dc82768e8585ca15b9193f544ad378.mp3", "hash": "635341b82ab6adcbaf218977d0154a23cc5a6eda59b782b2694a117b94dadac4", "bytes": 13824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/22ed8d4e2db7b291d61fec187615a4fcb6dc82768e8585ca15b9193f544ad378.mp3", "duration_ms": 2240}, "s1-cause-effect.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8d705db8029d8491f491dbd39a78ea9f3c60f0cd66ee9c4a5df6151f8a5dce7d.mp3", "hash": "d2c5d850f84c512f2d6f9292c26eefc548b8e7002bc46c57e22eb7d98078fd1d", "bytes": 18576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8d705db8029d8491f491dbd39a78ea9f3c60f0cd66ee9c4a5df6151f8a5dce7d.mp3", "duration_ms": 3040}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/db0c62b3aec188ec33e42f2b45d7cdb4479dc05c76b37770346ebdaa556b151e.mp3", "hash": "566e3621f0327b91e757ca6f0180c791465f975c4117b068470949a43906594f", "bytes": 21456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/db0c62b3aec188ec33e42f2b45d7cdb4479dc05c76b37770346ebdaa556b151e.mp3", "duration_ms": 3520}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/b7ae5d40d76ae9db3745b2fe9d09e457c17b4658febe030be58e91bd45a1250f.mp3", "hash": "f1de990187d6fc9d960b8aa49e0d17667d4d6f5549ccb04637df96841796545c", "bytes": 53568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b7ae5d40d76ae9db3745b2fe9d09e457c17b4658febe030be58e91bd45a1250f.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Group the money from the cash box", "locale": "en-US", "subject": "mixed", "objectives": ["Order steps, match products with prices, and sort purchases between needs for the stand and wants that can wait.", "Group the money from the cash box: coins with coins and bills with bills, to count it more easily."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 10, "type": "group_sets", "hints": ["Coins are round and made of metal, bills are made of paper.", "Look for the group that says ''Coins'' and the one that says ''Bills''."], "title": "Group the money", "payload": {"items": [{"id": "item1", "text_md": "$1 coin", "image_url": "http://localhost:4006/files/lesson-images/76ceaee679e765f04c9387c1cd55e5b39d532516838beb3935635d6855fff4d3.png"}, {"id": "item2", "text_md": "$5 coin", "image_url": "http://localhost:4006/files/lesson-images/8d595ec6218353c5d1ca05b8a935a43d1d2d165262b4ffd43eff8ce5334e5783.png"}, {"id": "item3", "text_md": "$10 coin", "image_url": "http://localhost:4006/files/lesson-images/e760f8cca26829552c070d5ad023921047f0e154b34f4219feda9ed7ce820456.png"}, {"id": "item4", "text_md": "$20 bill"}, {"id": "item5", "text_md": "$50 bill"}, {"id": "item6", "text_md": "$100 bill"}], "set_a": "Coins", "set_b": "Bills"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Tap each coin or bill and put it in the correct group.", "difficulty": 1, "explanation_md": "Coins go with coins and bills go with bills, that way it''s easier to count how much money you have.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b", "item6": "b"}}}', '{"units": {"s1-group-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/175a532263d9c96936cd3c92a31ae27828a14f6606cfcdd5da4453809d1c754c.mp3", "hash": "e716d6d6f4218a7ad7352776f3904d86c447e93d4a44867618ea6a992840053d", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/175a532263d9c96936cd3c92a31ae27828a14f6606cfcdd5da4453809d1c754c.mp3", "duration_ms": 3440}, "s1-group-money.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6ef4257f98bedad33c7b276669651038ea9732fe46881c20891d9ec29a1bcf45.mp3", "hash": "4dd5fcd9e4d00d2d2ed1c207d7cae725dd5b73044bdbc95450cb406aad10fdf4", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6ef4257f98bedad33c7b276669651038ea9732fe46881c20891d9ec29a1bcf45.mp3", "duration_ms": 3120}, "s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/b449da57c602743951c13b3e6000fe8a5a8456df547686a7b5a5fe72073dd69a.mp3", "hash": "d34b5a0c8f67a8b1a08bfde820b24ea45f51972083de4b57ca4d03bbe62c4ec8", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b449da57c602743951c13b3e6000fe8a5a8456df547686a7b5a5fe72073dd69a.mp3", "duration_ms": 3040}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/947722b304dcb94c8ba6ea05532b6744480a7c021186bd65202009fc9f374d9e.mp3", "hash": "75ccef0970c901a7fd44e994e3dac5b991d69f5433d061dfdc9d4baa6a49c2fa", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/947722b304dcb94c8ba6ea05532b6744480a7c021186bd65202009fc9f374d9e.mp3", "duration_ms": 5280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "Quanto o Liruf ganhou?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular e escrever quanto o Liruf ganhou no total se vendeu 4 copos a 5 reais cada um."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "number_input", "hints": ["Cada copo dá 5 reais. Quanto é 4 vezes 5?", "Você pode somar: 5 + 5 + 5 + 5."], "payload": {"unit": "reais", "decimals_hint": 0}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/1e0be30642331ccf7ca54fe1268fac83cb13cdee275c05c1e99de24cdd969725.png", "prompt_md": "Liruf vendeu 4 copos de limonada a 5 reais cada um. Quanto ele ganhou no total?", "difficulty": 1, "explanation_md": "Liruf ganhou 20 reais porque 4 copos × 5 reais cada um = 20 reais.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"value": 20, "tolerance": 0}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ad140ffdaaf2ce777ec315425f1ad611743d9c04d7bd298796618a9349b5449c.mp3", "hash": "a44acd3a92c358f83ea757f6e2097f4001fb5e38abf65ad60f2c0efca654860d", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ad140ffdaaf2ce777ec315425f1ad611743d9c04d7bd298796618a9349b5449c.mp3", "duration_ms": 4800}, "s1-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/60d267e64eb67198b069e1d616f6502b8a21a93dba1f7694c8dea674d9768136.mp3", "hash": "4a83704eb2d66c194fb1594273ca5cd95ca767b62e2df853d876edbe791365de", "bytes": 25776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/60d267e64eb67198b069e1d616f6502b8a21a93dba1f7694c8dea674d9768136.mp3", "duration_ms": 4240}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/42b3e22c76b1ecdc1069ca0a2fd4c828705b6785befc14f77157d67cb51761d1.mp3", "hash": "87aab5979a719b0e188a7a9f02be7b66c699aecc9d8b0934d0e4959e763d38b0", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/42b3e22c76b1ecdc1069ca0a2fd4c828705b6785befc14f77157d67cb51761d1.mp3", "duration_ms": 7280}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/db227f87d787ad13e077f01c0b7b24967478797ad6d25563880bbf58b7cb5f5f.mp3", "hash": "3f23ad40ff9d6fa13e3db8b7a8f7ff149968641ce87ca21eb786e42fd92ff1b5", "bytes": 41616, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/db227f87d787ad13e077f01c0b7b24967478797ad6d25563880bbf58b7cb5f5f.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Lightning round at peak hour", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the correct change for customers who order 1-3 glasses of lemonade at 5 dollars and pay with 10 or 20 dollars.", "Apply the strategy: first add the total cost, then subtract from the payment."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning-round", "xp": 15, "type": "lightning_round", "hints": ["First add how much the glasses cost: 2 glasses × 5 dollars each.", "Then subtract that total from the 20-dollar payment."], "title": "Lightning round", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 dollars"}, {"id": "b", "text_md": "5 dollars"}, {"id": "c", "text_md": "15 dollars"}, {"id": "d", "text_md": "20 dollars"}], "prompt_md": "Doña Rosa: 2 glasses, pays with 20. How much change do you give her?"}, {"id": "q2", "options": [{"id": "a", "text_md": "5 dollars"}, {"id": "b", "text_md": "10 dollars"}, {"id": "c", "text_md": "15 dollars"}, {"id": "d", "text_md": "0 dollars"}], "prompt_md": "Don José: 3 glasses, pays with 20. How much change do you give him?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 dollars"}, {"id": "b", "text_md": "10 dollars"}, {"id": "c", "text_md": "0 dollars"}, {"id": "d", "text_md": "4 dollars"}], "prompt_md": "Mamá Lila: 1 glass, pays with 10. How much change do you give her?"}, {"id": "q4", "options": [{"id": "a", "text_md": "0 dollars"}, {"id": "b", "text_md": "5 dollars"}, {"id": "c", "text_md": "10 dollars"}, {"id": "d", "text_md": "2 dollars"}], "prompt_md": "Tío Toño: 2 glasses, pays with 10. How much change do you give him?"}, {"id": "q5", "options": [{"id": "a", "text_md": "5 dollars"}, {"id": "b", "text_md": "10 dollars"}, {"id": "c", "text_md": "15 dollars"}, {"id": "d", "text_md": "20 dollars"}], "prompt_md": "Abuela Nena: 3 glasses, pays with 20. How much change do you give her?"}, {"id": "q6", "options": [{"id": "a", "text_md": "15 dollars"}, {"id": "b", "text_md": "10 dollars"}, {"id": "c", "text_md": "5 dollars"}, {"id": "d", "text_md": "20 dollars"}], "prompt_md": "Don Chuy: 1 glass, pays with 20. How much change do you give him?"}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Doña Rosa: 2 glasses, pays with 20. How much change do you give her?", "difficulty": 2, "explanation_md": "2 glasses cost 10 dollars (2×5). 20 minus 10 is 10 dollars in change.", "audio_segment_id": "s1-lightning-round.prompt"}], "schema_version": 1}', '{"s1-lightning-round": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a", "q5": "a", "q6": "a"}}}', '{"units": {"s1-lightning-round.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8ef90533a9156aa27364ab933a7361e527673bb32d2c01edf474b70835b75d93.mp3", "hash": "a942a624545ce99a393093acaff1045654e279e356c343d5a756a5ab1e590349", "bytes": 25776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8ef90533a9156aa27364ab933a7361e527673bb32d2c01edf474b70835b75d93.mp3", "duration_ms": 4240}, "s1-lightning-round.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f1700c51511bedc5f1fe10d987b85768501f4cb263676679e5ff0769c338383f.mp3", "hash": "f79a95a87734cae6482c84b9537786ebc06dc892065cee081d0ad48453129e79", "bytes": 17136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f1700c51511bedc5f1fe10d987b85768501f4cb263676679e5ff0769c338383f.mp3", "duration_ms": 2800}, "s1-lightning-round.prompt": {"url": "http://localhost:4006/files/lesson-audio/1d7ae96e14e7fd8f1335beb4a69e12f312aa3e893bfb27ffb75d88de85ecaa63.mp3", "hash": "36c08401c6113373ce9887d857b055949dd28198e03fc4076d94a71529239919", "bytes": 26784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1d7ae96e14e7fd8f1335beb4a69e12f312aa3e893bfb27ffb75d88de85ecaa63.mp3", "duration_ms": 4400}, "s1-lightning-round.explanation": {"url": "http://localhost:4006/files/lesson-audio/49fc66d0a6aec42b2c4416a8a95d6245261a1ab5437b68b731f73466ac389084.mp3", "hash": "46728e364e6d82de8bfc5c3d0ce161fc1ecc26dfab1f8693d9f7280765d4277d", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/49fc66d0a6aec42b2c4416a8a95d6245261a1ab5437b68b731f73466ac389084.mp3", "duration_ms": 5920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "picture-choice", "title": "Elige el lugar más seguro", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar el lugar más seguro para guardar dinero comparando opciones visuales."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Piensa: ¿dónde no se puede caer ni perder el dinero?", "Busca un lugar que se cierre con llave."], "title": "¿Dónde guardas tu dinero?", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Alcancía con llave", "image_url": "http://localhost:4006/files/lesson-images/8327eba19a18088c2789d9e8efe1b941a8221c8adaa979e059121d8f8e3e1fdd.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolsillo roto", "image_url": "http://localhost:4006/files/lesson-images/9a9cd66339fcfddbb645400ccdfe97b3f71db7fcf3e4142515e7d2251c9bbe91.png", "rationale_md": "El bolsillo roto tiene un agujero: las monedas se caen y se pierden."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa del puesto", "image_url": "http://localhost:4006/files/lesson-images/fec20665ba590574cdc059adac4ab77a41028513e4af0abf9790e33f356b7c2f.png", "rationale_md": "La mesa del puesto está al aire libre: cualquiera puede tomar el dinero."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf cerró su puesto. Toca el lugar más seguro para guardar sus ganancias.", "difficulty": 1, "explanation_md": "La alcancía con llave es segura porque solo tú puedes abrirla. El bolsillo roto deja caer las monedas, y la mesa del puesto está a la vista de todos.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/da13d01941f90d0ef4c5abf8c5dd664bf0fd8d8955e512f10c3555f1da22d5b6.mp3", "hash": "a300413174c7f3f320882b0021c19ba7890c8960cf72ef8ce66ce4f60569c4b5", "bytes": 23328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/da13d01941f90d0ef4c5abf8c5dd664bf0fd8d8955e512f10c3555f1da22d5b6.mp3", "duration_ms": 3840}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5bdc86e3e05600827400667bbb69350fb298fa511f2399c5e137f9ce6f952b84.mp3", "hash": "ce7ac99c9975a51b4d11588e68b0d901a48710d4e6824ff5da95d095adc745ce", "bytes": 15264, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/5bdc86e3e05600827400667bbb69350fb298fa511f2399c5e137f9ce6f952b84.mp3", "duration_ms": 2480}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/2ce2dace217fcc396fa734ca24306a3a4cb00593062ccf3b60adf388e10eba09.mp3", "hash": "3a120c7dd250f30adc94c517853425f8aa310fd444fc211468016791dac47288", "bytes": 31104, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2ce2dace217fcc396fa734ca24306a3a4cb00593062ccf3b60adf388e10eba09.mp3", "duration_ms": 5120}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/b2c389fde51c777e6ead37def98bb1e5a3a385cd115de8f311dc6ae4969ab756.mp3", "hash": "ae9efcc8b3b806657c089dd124203e91622ce26eedf0698e44cfbb0bfdb2701e", "bytes": 27648, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b2c389fde51c777e6ead37def98bb1e5a3a385cd115de8f311dc6ae4969ab756.mp3", "duration_ms": 4560}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/1e984eb1717b5228245a83af468bcc526f01b8ac8dd6360be645c4af2f3effb5.mp3", "hash": "dbe664ea11efb4ad351cee87fe1f1b379df386ab96450d45a2e46885c4b80f8c", "bytes": 67104, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/1e984eb1717b5228245a83af468bcc526f01b8ac8dd6360be645c4af2f3effb5.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "A rota do entregador", "locale": "pt-BR", "subject": "mixed", "objectives": ["Guiar o carrinho entregador pela grade do bairro até a casa do cliente gastando a menor quantidade de passos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["O carrinho avança para frente. Gire com esquerda ou direita."], "title": "Rota mais curta", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "commands": ["forward", "forward"], "max_commands": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Zara espera seu suco na casa 2. Dê ao carrinho a rota mais curta.", "difficulty": 2, "explanation_md": "O carrinho gira à direita, avança dois quarteirões e chega à casa 2. Zara recebe seu suco!", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/10e41dcf3928abd676d3d351150d2d9a088ee5a7f2ef1ae4508bac073416de33.mp3", "hash": "ed5f39a27d882e8bb6e96637665ad15b05cecaad42307e4e2ab0c4366eb3fc6c", "bytes": 30096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/10e41dcf3928abd676d3d351150d2d9a088ee5a7f2ef1ae4508bac073416de33.mp3", "duration_ms": 4960}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/f1f411c178f42d51ac81bcc82e6f938f91e43f15dd1dc1168b77800e69082aa3.mp3", "hash": "321b8c13923735c992bc1a9cc7c8ef2b0a8f71c6518cf52d7a838c28f04d0ccc", "bytes": 38304, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f1f411c178f42d51ac81bcc82e6f938f91e43f15dd1dc1168b77800e69082aa3.mp3", "duration_ms": 6320}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/a78c541bcc1c25a1532b5bf2227e2bfbd4b4cba946b59a53bbe7de79414c2258.mp3", "hash": "8d3497c213edf323815ea79886043798342049314c2aca673fcb4f7a9cf8bf81", "bytes": 47808, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a78c541bcc1c25a1532b5bf2227e2bfbd4b4cba946b59a53bbe7de79414c2258.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'es-MX', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "order-steps", "title": "Ordena las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar compras por prioridad de venta: primero lo que genera ingresos hoy, luego lo que mejora la venta, al final el lujo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "order_steps", "hints": ["Piensa: ¿sin qué no puedes vender ni un vaso de limonada?", "Lo que da ganancias hoy va primero; lo que es un lujo va al final."], "title": "Ordena las compras del puesto", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/ca53f1869ff314b1aa5b58d96db9369c1a206a911c7271161abb7dff9f05e0f7.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/27212681ec02b264fccc57b7c1331d15ef516d700236c53c76e9626ab91098b6.png"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/43b37cbd8ec60415ef32e3dc1b0b5207452a20768f1a4502ea64317c6ab03dd5.png"}, {"id": "calcomanias", "text_md": "Calcomanías", "image_url": "http://localhost:4006/files/lesson-images/86d0eaaa130d32ba3b855a691cd15c5b27eeece570ce9ae8bd06d34d03b39ba0.png"}], "slots": 4}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Liruf tiene 20 pesos. Ordena las compras de la más necesaria para vender hoy a la que puede esperar.", "difficulty": 2, "explanation_md": "Los limones son lo más urgente porque sin ellos no hay limonada que vender. Los vasos van después, porque sin ellos no puedes servir. El azúcar mejora el sabor, pero puedes vender sin ella. Las calcomanías son un gusto que puede esperar.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/50c0f877a34e77683fc185548298cbe8f9e4babf006940ef949f7519b6dd8efc.mp3", "hash": "5d0355b74814af63e7b6dd4d580bced445833045c5e70221fcd70572a37e7850", "bytes": 22464, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/50c0f877a34e77683fc185548298cbe8f9e4babf006940ef949f7519b6dd8efc.mp3", "duration_ms": 3680}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f8cf38c3ccf2d7a9a6e5aea6fd497116c1011fbe281b64836476b2be6fe5fa3c.mp3", "hash": "5d576a228568d63f4f7687bc9afaa87dc5ab4b85b1894362f42fe4cc1e7c0e01", "bytes": 26208, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/f8cf38c3ccf2d7a9a6e5aea6fd497116c1011fbe281b64836476b2be6fe5fa3c.mp3", "duration_ms": 4320}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/9294f876b16b3096e13d2e7a727b1dd4dd46ca9b6af192ca6a4ea8dea572d8ee.mp3", "hash": "319b6b1f9de41a6a5dd7811658a4fd15abe527cf2e16ca4c552e6e5b6d9f8101", "bytes": 36288, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/9294f876b16b3096e13d2e7a727b1dd4dd46ca9b6af192ca6a4ea8dea572d8ee.mp3", "duration_ms": 6000}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/4563798e7dfd23e9657938627355687fed837d143fd0cc3b3a661e5902cc0574.mp3", "hash": "20a5a7c59d611adb7a9030873c960aea895e0ec22ec4d11af36c1a0d989113eb", "bytes": 85824, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/4563798e7dfd23e9657938627355687fed837d143fd0cc3b3a661e5902cc0574.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "How much did Liruf earn?", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate and write how much Liruf earned in total if she sold 4 cups for 5 dollars each."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "number_input", "hints": ["Each cup gives 5 dollars. What is 4 times 5?", "You can add: 5 + 5 + 5 + 5."], "payload": {"unit": "dollars", "decimals_hint": 0}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/5fc975d223af4624d09d40c3001ffb94c26a1bfad160bda0edfdf95a05e622be.png", "prompt_md": "Liruf sold 4 cups of lemonade for 5 dollars each. How much did she earn in total?", "difficulty": 1, "explanation_md": "Liruf earned 20 dollars because 4 cups × 5 dollars each = 20 dollars.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"value": 20, "tolerance": 0}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4276c74dbb98d330ec435fee5d7138e51f097e2426e0f2dd7cb4cfe86c34c479.mp3", "hash": "cf3d5165371d13cad20547ce3d72061b76c8ba078e8b0058fc38ed1e6be21f91", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4276c74dbb98d330ec435fee5d7138e51f097e2426e0f2dd7cb4cfe86c34c479.mp3", "duration_ms": 3120}, "s1-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/491e29d0a68c0c775020ede587f9a2bc1b383bab8ccd0f286a9cb8cb9ee9ea77.mp3", "hash": "eec3736b1146fa1963c524cef876bebb4633f0415c5394b75a67edd8a7dfeaad", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/491e29d0a68c0c775020ede587f9a2bc1b383bab8ccd0f286a9cb8cb9ee9ea77.mp3", "duration_ms": 3760}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/4d850d2039b0f21bc66240ae9ba7bf9a24903a52126f340063c062a42619c87e.mp3", "hash": "3caebf7b90609a458b130d283c7db7e4cf03a7293ffab5180bd3e93f9ca80cff", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4d850d2039b0f21bc66240ae9ba7bf9a24903a52126f340063c062a42619c87e.mp3", "duration_ms": 4960}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/270014bc62c88a1c5079d83c7131904138177dab318431a22c84ac8a58a35f90.mp3", "hash": "a4574f6fa9eb1b436ae2d82ed316461b0f8f161a1d257de8793485d6ddf896cd", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/270014bc62c88a1c5079d83c7131904138177dab318431a22c84ac8a58a35f90.mp3", "duration_ms": 4880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Caza el error en la promoción", "locale": "es-MX", "subject": "mixed", "objectives": ["Encontrar el error en un cartel de promoción y corregirlo"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-promo", "xp": 15, "type": "debug_hunt", "hints": ["Piensa cuánto cuesta un vaso suelto.", "Compara el precio de 2 vasos sueltos con los 8 pesos de la promo."], "title": "La promo que no cuadra", "payload": {"blocks": [{"id": "block1", "text_md": "2 vasos por 8 pesos"}, {"id": "block2", "text_md": "1 vaso cuesta 5 pesos"}, {"id": "block3", "text_md": "¡Ahorra 2 pesos!"}], "intro_md": "Liruf puso un cartel: ''2 vasos por 8 pesos''. Pero los clientes se ríen: ¡sale más caro que comprarlos sueltos!"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "¿Cuál es el error en el cartel de Liruf?", "difficulty": 2, "explanation_md": "Dos vasos sueltos cuestan 10 pesos (5+5), pero la promo los vende a 8. ¡Es más barato, no más caro!", "audio_segment_id": "s1-debug-promo.prompt"}], "schema_version": 1}', '{"s1-debug-promo": {"fix_md": "¡Ahorra 2 pesos! → ¡Ahorra 2 pesos! (en realidad es más caro, no ahorras)", "bug_ids": ["block3"]}}', '{"units": {"s1-debug-promo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/48aa031b20fe73ead099c72adc9c65d744db6814efdb60614b34600b7c119cfd.mp3", "hash": "2b12e4413f8561a8da2c8bcbab3ef8c53a4cdae95a23df8f1e3da30b38456b67", "bytes": 15696, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/48aa031b20fe73ead099c72adc9c65d744db6814efdb60614b34600b7c119cfd.mp3", "duration_ms": 2560}, "s1-debug-promo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d327b393bf23235c492b3869bdfdf8abdf89a14c53769376de5c00a6da9c4491.mp3", "hash": "3f6f20a60ff922c8a054124a7ec0be55ad010ba0c3fb7938ff802181ca2f8030", "bytes": 23328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d327b393bf23235c492b3869bdfdf8abdf89a14c53769376de5c00a6da9c4491.mp3", "duration_ms": 3840}, "s1-debug-promo.prompt": {"url": "http://localhost:4006/files/lesson-audio/00065227775ec69f05e71af29ec77662e6b7441c0600a276b60611e548128059.mp3", "hash": "c2a06bd6df9ca2c3bfe480053d841f53855cc190820925d67eb416b82fab62ab", "bytes": 15264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/00065227775ec69f05e71af29ec77662e6b7441c0600a276b60611e548128059.mp3", "duration_ms": 2480}, "s1-debug-promo.explanation": {"url": "http://localhost:4006/files/lesson-audio/a952f156c7e9e01eddb32efa65d2d364dfe847ba1497c107ac751cc6f126c553.mp3", "hash": "565e014fe383467dc04941f70a0fdc2f383372ba6bbe5080b8501343f94f076f", "bytes": 48384, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a952f156c7e9e01eddb32efa65d2d364dfe847ba1497c107ac751cc6f126c553.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "machine-io", "title": "La máquina de propinas", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir que la máquina duplica lo que entra", "Predecir la salida de la máquina con un nuevo número"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 15, "type": "machine_io", "hints": ["Observa: 1 → 2, 3 → 6. ¿Qué operación hace la máquina?", "Cada moneda que entra se convierte en el doble."], "title": "Descubre la regla", "payload": {"options": [{"id": "opt-7", "text_md": "7"}, {"id": "opt-8", "text_md": "8"}, {"id": "opt-10", "text_md": "10"}, {"id": "opt-15", "text_md": "15"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "La abuela mete 1 moneda y salen 2. Mete 3 y salen 6. ¿Cuántas salen si mete 5?", "difficulty": 2, "explanation_md": "La máquina duplica: 1 se vuelve 2, 3 se vuelve 6, así que 5 se vuelve 10.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt-10"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a10bf0f2e5eef0f1db1329368f2fa20107efa1e8092f1d8b226b72f7e1051319.mp3", "hash": "6db153f053c4099de940e1c2e6e84fc65a475eb83deb123b8f55e142cd094f54", "bytes": 32544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a10bf0f2e5eef0f1db1329368f2fa20107efa1e8092f1d8b226b72f7e1051319.mp3", "duration_ms": 5360}, "s1-machine-io.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5d8e8075cd355efeee0fc37ae0649fc7531dffb419d5a824e8f52b0aefa26fe9.mp3", "hash": "2ad1d871c84825aab1f57650444d05b1b9740930c0a3519f67517628ca8fd1f7", "bytes": 18144, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5d8e8075cd355efeee0fc37ae0649fc7531dffb419d5a824e8f52b0aefa26fe9.mp3", "duration_ms": 2960}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/b268ad431f854d52c99e89942f1d02c9bc1126a86ab0245f7cf9b2f0d4d3374c.mp3", "hash": "5bb4c31c0f3ad762b68cdf75f80ffbee3720fdc26cd30a4b669eb1e7fb8a3003", "bytes": 48384, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b268ad431f854d52c99e89942f1d02c9bc1126a86ab0245f7cf9b2f0d4d3374c.mp3", "duration_ms": 8000}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/f0a20ae96d42a3e29416931bd4c2a740bbab4ed773e3a1943168cfbe963f160c.mp3", "hash": "5765670eb441c5bd02329fbd5ad234d9fc232c70f693808afb4c274b64b17f17", "bytes": 37296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f0a20ae96d42a3e29416931bd4c2a740bbab4ed773e3a1943168cfbe963f160c.mp3", "duration_ms": 6160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "equation-builder", "title": "Monte a conta da tarde", "locale": "pt-BR", "subject": "mixed", "objectives": ["Montar com fichas a soma da tarde: 5 + 5 + 5 = 15 reais (três copos vendidos)"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-cuenta", "xp": 10, "type": "equation_builder", "hints": ["Cada copo custa 5 reais. Quanto é 5 + 5?", "Depois some o terceiro 5 ao resultado."], "title": "Monte a soma da tarde", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Rho vendeu 3 copos de limonada esta tarde. Monte a soma com as fichas.", "difficulty": 1, "explanation_md": "Três copos de 5 reais cada um somam 5 + 5 + 5 = 15 reais. Assim se monta a conta da tarde!", "audio_segment_id": "s1-arma-cuenta.prompt"}], "schema_version": 1}', '{"s1-arma-cuenta": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-arma-cuenta.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4872406b45e9a1fdae55aad44dc38a35260bda3a9e52cb442ea94eb2d40a3046.mp3", "hash": "246413ded3b45eadcffd441e7ff74f88bd167e5b43b17a525d92c8f3d830db76", "bytes": 30528, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/4872406b45e9a1fdae55aad44dc38a35260bda3a9e52cb442ea94eb2d40a3046.mp3", "duration_ms": 5040}, "s1-arma-cuenta.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d9331d6a784fbc70eb9d3950f43f2e5c3c1f164c7f00f22050291973553599f3.mp3", "hash": "b6d72ae341accf3e11be4d5741ca1ddd76b86e0e3b76bec9cbfbfe863f44c828", "bytes": 21456, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d9331d6a784fbc70eb9d3950f43f2e5c3c1f164c7f00f22050291973553599f3.mp3", "duration_ms": 3520}, "s1-arma-cuenta.prompt": {"url": "http://localhost:4006/files/lesson-audio/fcae2219b3444be71acffc9358c701f8d3d67238158ce38624eaa826f137bf34.mp3", "hash": "531476628ae8f25f01bfdf2a894c847a544ff1a0c28f841a3ad4a3bc33f9646e", "bytes": 34848, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/fcae2219b3444be71acffc9358c701f8d3d67238158ce38624eaa826f137bf34.mp3", "duration_ms": 5760}, "s1-arma-cuenta.explanation": {"url": "http://localhost:4006/files/lesson-audio/e157003206e9cfa2c480007771615bbd4e7645d146061dd36903417d01797ba9.mp3", "hash": "a198f52b90fd6148edd8d0525f7d9b4b582d6a85bfd2be59ed0b91448ce4ab52", "bytes": 62784, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e157003206e9cfa2c480007771615bbd4e7645d146061dd36903417d01797ba9.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classifique as compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Classifique as compras do dia em dois baldes: NECESSIDADE da barraca (limões, copos) ou GOSTO que pode esperar (adesivos, balões)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Pense: sem isso, a barraca não pode vender limonada?", "Os limões e os copos acabam rápido. Os adesivos e balões são para decorar."], "title": "Necessidade ou gosto", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/65b0d4e506c4502d186b21cf1338f4fe70edc03b3e5c6d8ba2ba71841cd922b8.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/375c96b839708d8b4d434ce4de08fd4701b480f811d74c9cb37f8aa8ac028a28.png"}, {"id": "stickers", "text_md": "Adesivos", "image_url": "http://localhost:4006/files/lesson-images/0c5c5b4114ea04b158d2d052a822a5705192ca0eed621a682c02cc9ad225d56b.png"}, {"id": "globos", "text_md": "Balões", "image_url": "http://localhost:4006/files/lesson-images/f38b52af525dff6fa08243fbb8c3f0899dc8a1d9bac953a406ce6f81b5cd760a.png"}], "buckets": [{"id": "necesidad", "label": "NECESSIDADE da barraca"}, {"id": "gusto", "label": "GOSTO que pode esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toque em cada coisa e coloque no balde correto: o que a barraca PRECISA hoje, ou um GOSTO que pode esperar.", "difficulty": 1, "explanation_md": "A barraca precisa de limões e copos para vender limonada. Os adesivos e balões são gostos que podem esperar outro dia.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4d917e22601d6c3ab8e2975ec9fce89dc221b22fd8c623189f7e03536f99b818.mp3", "hash": "a00ad9e0b458f953cf7c23fb2d3c81d1ac33daf3a10f1dc84ccde0d64f3107a1", "bytes": 26208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4d917e22601d6c3ab8e2975ec9fce89dc221b22fd8c623189f7e03536f99b818.mp3", "duration_ms": 4320}, "s1-sort-buckets.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3693f61634e403e49f42d798d41c8549035dfe4e713de372512d7b6eef32ac91.mp3", "hash": "947246a17f5c00bc5005ec648dacff12ad2e2489e8a29d60b033b3087f340200", "bytes": 38736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3693f61634e403e49f42d798d41c8549035dfe4e713de372512d7b6eef32ac91.mp3", "duration_ms": 6400}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/b158aa109e4daa0bdb6e6c76e45a97917f18d9d13ecf2bc4a8f41af4be447f8b.mp3", "hash": "a399a29fd14dfdeaab6319dbaa65d10931b81ab50f546e309259d10357ccd5ba", "bytes": 46368, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b158aa109e4daa0bdb6e6c76e45a97917f18d9d13ecf2bc4a8f41af4be447f8b.mp3", "duration_ms": 7680}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/20e04c4884c3c8082f459a7af698bdc3de88f3f32d11d50d8cbe6e8e194b720e.mp3", "hash": "ab1e83adcf0d63e968ed1c1b145cdf6534574e7623c0c6f16e57ce0d30ec06fc", "bytes": 53568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/20e04c4884c3c8082f459a7af698bdc3de88f3f32d11d50d8cbe6e8e194b720e.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "would-you-rather", "title": "What would you do? Stand dilemmas", "locale": "en-US", "subject": "mixed", "objectives": ["Choose between two seller paths and defend it: earn 10 dollars today or 20 next week?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-wyr", "xp": 15, "type": "would_you_rather", "hints": ["Think: does Liruf need the money today or can he wait a week?", "There''s no wrong answer, only different consequences."], "title": "Earn today or wait?", "payload": {"a": {"icon": "payments", "text_md": "**Earn 10 dollars today** by selling 2 glasses of lemonade right now.", "image_url": "http://localhost:4006/files/lesson-images/50f03a4763633d3542a89f14c2684c8c1ae13267de11aeb4d6284513a5eac931.png"}, "b": {"icon": "trending_up", "text_md": "**Earn 20 dollars next week** if you prepare more lemonade and sell twice as much.", "image_url": "http://localhost:4006/files/lesson-images/3f8363782b1c405b1d703664c2e9d95decf22bac80bc5221c4e0e27d42dcb712.png"}, "followup_md": "Why did you choose that option? Tell Dina your reason."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina gives you a dilemma: what do you choose for Liruf?", "difficulty": 2, "explanation_md": "Dina smiles: ''Both options have their reason. The important thing is that you think before you decide.''", "audio_segment_id": "s1-wyr.prompt"}], "schema_version": 1}', '{"s1-wyr": {"qualities": {"a": 50, "b": 50}, "reveal_md": "Dina asiente: ''Ambos caminos tienen sentido. Lo importante es que sepas por qué eliges.''"}}', '{"units": {"s1-wyr.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3eff0fed44d0e832e9827ba0944aebf9dfa42358598c97691b8b8b7cf30b8c0a.mp3", "hash": "d65b12a7b5e9120968732757a9776151c842ae210209790f384df1e0b968e825", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3eff0fed44d0e832e9827ba0944aebf9dfa42358598c97691b8b8b7cf30b8c0a.mp3", "duration_ms": 3040}, "s1-wyr.hint.1": {"url": "http://localhost:4006/files/lesson-audio/bf87e898c0eee5f35bfb290a8f83ae212df95fcd99e59930073bb8a3e852f030.mp3", "hash": "2a82e8c5bc4e2fb2e9bd4a9cf583e5e7229f4fa87d1cbe8c182f678233caba3b", "bytes": 20448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bf87e898c0eee5f35bfb290a8f83ae212df95fcd99e59930073bb8a3e852f030.mp3", "duration_ms": 3360}, "s1-wyr.prompt": {"url": "http://localhost:4006/files/lesson-audio/6b7e9b6f76f06b482a5ba0d3c9d693ffe28f706bf9a6894841523ada13281a45.mp3", "hash": "69da1d2676ee44ea4c6496be39a9e233dd986ba278c1daa0305deb2c8a01f396", "bytes": 18144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6b7e9b6f76f06b482a5ba0d3c9d693ffe28f706bf9a6894841523ada13281a45.mp3", "duration_ms": 2960}, "s1-wyr.choices": {"url": "http://localhost:4006/files/lesson-audio/dbfa95fc51c97cef896155f328dbc2a2e514f93d60f66df8dd114e864595004d.mp3", "hash": "253f4ca8fac18e8af5db398036fa76cfcbfe188f72e85bc6300b916ab29478a2", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dbfa95fc51c97cef896155f328dbc2a2e514f93d60f66df8dd114e864595004d.mp3", "duration_ms": 8080}, "s1-wyr.explanation": {"url": "http://localhost:4006/files/lesson-audio/9c0664a773ec6a1923b1ef7f7e0d34dbe10f8f4e1c172b296f911558605bb1c4.mp3", "hash": "f1fc1fde66759fa968bc3d295673f467b3254bf9c107a6cdd9fb7944f58c4fad", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9c0664a773ec6a1923b1ef7f7e0d34dbe10f8f4e1c172b296f911558605bb1c4.mp3", "duration_ms": 5440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'en-US', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "order-steps", "title": "Rank the purchases for the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Rank purchases by sales priority: first what generates income today, then what improves sales, luxury last."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "order_steps", "hints": ["Think: without what can you not sell even one glass of lemonade?", "What gives profit today goes first; what is a luxury goes last."], "title": "Rank the purchases for the stand", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/3b45b8ab9c3b5c8d6e44f886bd164818e3b497679c53445b5df3855abbaad0bc.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/ed34989698b749c872c29902b62a797d1481b8a39c26ab0431d39c22c0611fbb.png"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/ccc2e7b0962fd804c6387a52329cc96aa2fd7acf38e77435131602cc4803ca28.png"}, {"id": "calcomanias", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/b9b72fede3039a3d7ec7ad4e86696081ca600b04eb0f1067d3f3d265c21b09c6.png"}], "slots": 4}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Liruf has 20 dollars. Rank the purchases from most needed to sell today to what can wait.", "difficulty": 2, "explanation_md": "Lemons are the most urgent because without them there is no lemonade to sell. Cups come next, because without them you can''t serve. Sugar improves the taste, but you can sell without it. Stickers are a treat that can wait.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dfd0ff31a1881a02ac76c97c69f86884d00b1a2d6b8efc9ff1f05cb18803027f.mp3", "hash": "89f9219a471c4a8b1c38a6ae6c5ef27fd66aa1ab29e75418746124422a9de587", "bytes": 33984, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/dfd0ff31a1881a02ac76c97c69f86884d00b1a2d6b8efc9ff1f05cb18803027f.mp3", "duration_ms": 5600}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e9a845a742be0e01b09eb0174bc9cfd0abbae55c411c06d1ae0830d3d3872f18.mp3", "hash": "f0b4b3b0ea9542ce1ee1c69d74271559e2a41437f3fca0220f1715300aff20b7", "bytes": 27216, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/e9a845a742be0e01b09eb0174bc9cfd0abbae55c411c06d1ae0830d3d3872f18.mp3", "duration_ms": 4480}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/f85b2de58441fe0aa0d5d3593504a71bf5ac68f7947da0f0c15b0a3f2cf2b967.mp3", "hash": "6d36cc1116fd5f4fd0c1f6076470a5dd8d8521d79f06b4d42f1e80715546a331", "bytes": 38736, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/f85b2de58441fe0aa0d5d3593504a71bf5ac68f7947da0f0c15b0a3f2cf2b967.mp3", "duration_ms": 6400}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/7a9ecc4d3bc1c96486af53f5882986eb10d487366031c5fe2a60cbc047962777.mp3", "hash": "acba15583c5f283dbb2aa9fb19a349bfa7d70e9224e2d82b153ca7566210e1bf", "bytes": 80496, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7a9ecc4d3bc1c96486af53f5882986eb10d487366031c5fe2a60cbc047962777.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Counting coins for the goal", "locale": "en-US", "subject": "mixed", "objectives": ["Counting 1, 2, and 5 dollar coins to pay for a glass of lemonade"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Count the coins one by one. How much do they add up to?"], "title": "Count the coins", "payload": {"target": 5, "currency": "USD", "denominations": [1, 2, 2]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/f7443243a232ee7a1e948a7e617448d20d7fec3276cfc0f5d5f4b31dfcaaa28d.png", "prompt_md": "Liruf sold a glass of lemonade. The customer pays with these coins. Is it exactly 5 dollars?", "difficulty": 1, "explanation_md": "The coins add up to 5 dollars: 2 + 2 + 1 = 5. Exactly what the glass costs!", "audio_segment_id": "s1-contar-monedas.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7af5c8d10224cea55229694fb2242c9da75b73e3fb8e407c9eb835bcbde122df.mp3", "hash": "63e4de90bf5562d6fb30b268378c6ea5d75624605440824c5a272889d5560668", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7af5c8d10224cea55229694fb2242c9da75b73e3fb8e407c9eb835bcbde122df.mp3", "duration_ms": 3120}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/68891144127035adcc6e947baf0336ebee49a486d6afbe421786316b7317f181.mp3", "hash": "e61be08b3a1afe1cc9318f18861c2e5b07242fe49330822769e2b8d27f04258d", "bytes": 34416, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/68891144127035adcc6e947baf0336ebee49a486d6afbe421786316b7317f181.mp3", "duration_ms": 5680}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/8bdf09b4dd8f0245f65a27ed3c5bb22689f24152a0fb669e397f800befeae38d.mp3", "hash": "1e8cb9e25d6c2bc1637767b1679d5bd9c3c95a9b4869253a7c2da07bc1d9766f", "bytes": 41184, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8bdf09b4dd8f0245f65a27ed3c5bb22689f24152a0fb669e397f800befeae38d.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'en-US', '1', E'{"meta": {"cast": ["liruf", "zara", "dina"], "slug": "build-sentence", "title": "The combo sign", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the price of 2 glasses of lemonade at 5 dollars each and put up the correct sign."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-letrero", "xp": 15, "type": "build_sentence", "hints": ["Each glass costs 5 dollars. How much do two cost?", "Think: 5 plus 5 is..."], "title": "The combo sign", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "glasses"}, {"id": "t3", "text_md": "for"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "10"}, {"id": "t6", "text_md": "15"}, {"id": "t7", "text_md": "20"}, {"id": "t8", "text_md": "dollars"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf wants a sign that says: \\"2 glasses for ___ dollars\\". Tap the tiles in order to build it.", "difficulty": 2, "explanation_md": "The sign should say \\"2 glasses for 10 dollars\\" because each glass costs 5 and two cost 5+5=10. If you put 5, it would only be enough for one glass. 15 is what Dina spent on something else, and 20 is the bill they pay with.", "audio_segment_id": "s1-combo-letrero.prompt"}], "schema_version": 1}', '{"s1-combo-letrero": {"order": ["t1", "t2", "t3", "t5", "t8"]}}', '{"units": {"s1-combo-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0a12697942c34d2d7c4145e27df4495884671acf9c7eb9bd72ccf091fa876135.mp3", "hash": "51ca575e7f94554c062191bc947877e6ac58bee0bf3381c2df51b631db0395ff", "bytes": 23904, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/0a12697942c34d2d7c4145e27df4495884671acf9c7eb9bd72ccf091fa876135.mp3", "duration_ms": 3920}, "s1-combo-letrero.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8614a11b4496b1f0c61817e3acaa40b41c445dd86cd9723fbfcc98dab6c4f6ac.mp3", "hash": "faca1fdafee4eeeccb9d42235cb19d8057a207989f6b5e3f7581c5b0ae3dcdc6", "bytes": 13824, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/8614a11b4496b1f0c61817e3acaa40b41c445dd86cd9723fbfcc98dab6c4f6ac.mp3", "duration_ms": 2240}, "s1-combo-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/fc3aa240849044b56ee209b998f2b424ad270ecf4d33130c7d9c9524e43d6dd0.mp3", "hash": "e37779d622571c52aed061d6a92ae4ea408fe3b965ea688fe3def2f245545dd7", "bytes": 33408, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/fc3aa240849044b56ee209b998f2b424ad270ecf4d33130c7d9c9524e43d6dd0.mp3", "duration_ms": 5520}, "s1-combo-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/7920bebf014d2341516aca534b814a0022b17b224229225f1ce8c32bb7883930.mp3", "hash": "6a7e92aad76b7eee7f50351e42ba10287c68e4e623ae9a93453a3744be0beab2", "bytes": 89136, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/7920bebf014d2341516aca534b814a0022b17b224229225f1ce8c32bb7883930.mp3", "duration_ms": 14800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Sinais de alerta em um negócio", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar os sinais de alerta na oferta de um desconhecido: promessas boas demais não são confiáveis."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Pense: é normal ganhar tanto dinheiro em um dia sem trabalhar?", "Você conhece essa pessoa? Por que ela te ofereceria tanto?"], "title": "O negócio mágico", "payload": {"flags": [{"id": "f1", "text_md": "A pessoa é um desconhecido"}, {"id": "f2", "text_md": "Promete muito dinheiro sem explicação"}, {"id": "f3", "text_md": "Pede dinheiro hoje em troca de uma promessa"}, {"id": "f4", "text_md": "Diz que é ''mágico'' ou ''seguro''"}], "artifact_md": "Um senhor desconhecido se aproxima da barraca de Liruf e diz: ''Ei, menino, me dê seus 20 reais hoje. Amanhã te devolvo 100. É um negócio mágico, você não perde nada.''", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/05812e4a7860390b1ec83cf4e24317260ba7d12e611b0d27a20f88540fdc6ab4.png", "prompt_md": "Liruf está em sua barraca. Um senhor se aproxima e diz: ''Me dê seus 20 reais hoje e amanhã te dou 100''. Que sinais de alerta você vê?", "difficulty": 1, "explanation_md": "Promessas de ganhar muito dinheiro rápido sem esforço geralmente são falsas. Se parece bom demais para ser verdade, provavelmente não é.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["f1", "f2", "f3", "f4"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3352abd30d2701b1304494f6dce1e0caf4e809c97d5581075b2e2f7f2c30dda1.mp3", "hash": "b837be3c7fc3daf7448e80097c8f460f0822d3a5e7859d0532ce1099625ee54b", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3352abd30d2701b1304494f6dce1e0caf4e809c97d5581075b2e2f7f2c30dda1.mp3", "duration_ms": 4080}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/899a61d41507ef648c9f3fd795a39ce28da25ea2d5fa9937a6700a651791ada5.mp3", "hash": "6ed3c00317ef772c37e5aedcc294f65b456ea95ed8411a600d7d26b4f52ad997", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/899a61d41507ef648c9f3fd795a39ce28da25ea2d5fa9937a6700a651791ada5.mp3", "duration_ms": 4160}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/420e473b52d39236c8e0729dd0d179d8cded7bdddaf99366241f2595387aecc3.mp3", "hash": "10e61e65f7163f04c3050cccc5cc305d9a12be954f3889cbdde62a494cf741a1", "bytes": 58464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/420e473b52d39236c8e0729dd0d179d8cded7bdddaf99366241f2595387aecc3.mp3", "duration_ms": 9680}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/c7371872263a1dd7078b66bf441e8b78881df8c294104de0a9eff5cb9a286063.mp3", "hash": "452e20677c88a094fbc0596746853fb82f12f5e84b08ef1129e74860177fe58e", "bytes": 56448, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c7371872263a1dd7078b66bf441e8b78881df8c294104de0a9eff5cb9a286063.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "Um dia real da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encadear várias habilidades em uma mesma lição: ouvir a situação, decidir, calcular e cobrar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "title": "Sábado ensolarado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/13af8e1a957c39b18e1e70167a60d2398015ae0f56b5f47737b4c7485027c648.png"}, "action": "idle", "body_md": "É sábado de manhã. O sol brilha e Liruf preparou uma jarra grande de limonada. Já tem três clientes esperando. É hora de decidir o preço de hoje!", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Liruf abre sua barraca de limonada. Já tem fila de clientes!", "difficulty": 1, "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-precio-del-dia", "xp": 15, "type": "quiz_mcq", "hints": ["Pense em um preço que seja justo para os clientes e que dê lucro para Liruf.", "Lembre-se que fazer limonada custa dinheiro: limões, açúcar, copos."], "title": "Preço do dia", "payload": {"options": [{"id": "a", "text_md": "2 reais", "rationale_md": "2 reais é muito pouco. Liruf não ganharia o suficiente para comprar mais limões."}, {"id": "b", "text_md": "5 reais"}, {"id": "c", "text_md": "10 reais", "rationale_md": "10 reais é muito caro. Os clientes poderiam ir para outra barraca."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Quanto Liruf vai cobrar por cada copo de limonada hoje?", "difficulty": 2, "explanation_md": "Liruf decide cobrar 5 reais por copo, o mesmo preço de sempre. Assim os clientes sabem o que esperar e Liruf cobre seus custos.", "audio_segment_id": "s2-precio-del-dia.prompt"}], "schema_version": 1}', '{"s2-precio-del-dia": {"correct_option_id": "b"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/3c40a539b646c517a4b2388d893673e7e5085718a15725f84ae9fac60a1e121c.mp3", "hash": "fb8748823a4df646fb1bfc9c0d9d7518932e7283045971d339dfb9a07598e0cd", "bytes": 60336, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3c40a539b646c517a4b2388d893673e7e5085718a15725f84ae9fac60a1e121c.mp3", "duration_ms": 10000}, "s2-precio-del-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/24c49c82270eae0f6ff72a7f35ee18696ad7c7d5ce41148c76b5e2e2c97216ca.mp3", "hash": "36e2cc0bf245927eeca88202643aaff01e6493a530190b15f0b462dce7d25256", "bytes": 29664, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/24c49c82270eae0f6ff72a7f35ee18696ad7c7d5ce41148c76b5e2e2c97216ca.mp3", "duration_ms": 4880}, "s2-precio-del-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8309db3583b2695abccdd5d879bb64e71c744a56fd7d6902dd711c5008c317a0.mp3", "hash": "e56177a7812212d66b85b234992ad8f1bc2001a87a2baa028d38ce5c01af7ecb", "bytes": 33408, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8309db3583b2695abccdd5d879bb64e71c744a56fd7d6902dd711c5008c317a0.mp3", "duration_ms": 5520}, "s2-precio-del-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/5027cf29ab6165bc9759291e147d35ce0e834bc6bda0b5bc4dd76823724a9454.mp3", "hash": "46b175086aab1d36973af7f7ca1308640e68299484b116ace1731225c91650fa", "bytes": 23328, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5027cf29ab6165bc9759291e147d35ce0e834bc6bda0b5bc4dd76823724a9454.mp3", "duration_ms": 3840}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/5e9c10cb8ccbeb6b60336c6b830bcb273654e3c2117f9d5faba3e93aa622b87b.mp3", "hash": "5e6985bf4c57b6686004658aac09758cbee4455ce2869c03fca0cb6cad544513", "bytes": 31104, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5e9c10cb8ccbeb6b60336c6b830bcb273654e3c2117f9d5faba3e93aa622b87b.mp3", "duration_ms": 5120}, "s2-precio-del-dia.choices": {"url": "http://localhost:4006/files/lesson-audio/feb8245b1604f8938d0ac208a8ca0b018301f5b2d3c6637e009d4acb336e4627.mp3", "hash": "e0fd061f4d615043be254375cea10be60d0d9ba26d2a817d87868bba18608125", "bytes": 24768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/feb8245b1604f8938d0ac208a8ca0b018301f5b2d3c6637e009d4acb336e4627.mp3", "duration_ms": 4080}, "s2-precio-del-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/82c56d45ccc8cde18dc9b78cb1cde5141df7fce071a899958e5bea5133fd7413.mp3", "hash": "218d3da7b6e1ece8d4ca85605f2f815b4ad5c1bd5ef8ea4fbd1a86c932f4424b", "bytes": 57888, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/82c56d45ccc8cde18dc9b78cb1cde5141df7fce071a899958e5bea5133fd7413.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Repaso rápido: ganancia por vaso", "locale": "es-MX", "subject": "money", "objectives": ["Calcular la ganancia por vaso de limonada (precio - costo de ingredientes)"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-por-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["La ganancia es lo que sobra después de pagar los ingredientes.", "Resta el costo de los ingredientes al precio del vaso."], "title": "Ganancia por vaso", "payload": {"options": [{"id": "a", "text_md": "2 pesos", "rationale_md": "Ese es el costo de los ingredientes, no la ganancia."}, {"id": "b", "text_md": "3 pesos"}, {"id": "c", "text_md": "5 pesos", "rationale_md": "Ese es el precio del vaso, pero hay que restar lo que cuesta hacerlo."}, {"id": "d", "text_md": "7 pesos", "rationale_md": "Sumaste el precio y el costo, pero la ganancia es la resta."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina te reta: sin ver el cuaderno, ¿cuánto gana Liruf por cada vaso que vende? El vaso cuesta 5 pesos y los ingredientes cuestan 2 pesos.", "difficulty": 1, "explanation_md": "Liruf gana 3 pesos por vaso: 5 pesos del precio menos 2 pesos de ingredientes. ¡Esa es la ganancia!", "audio_segment_id": "s1-ganancia-por-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-por-vaso": {"correct_option_id": "b"}}', '{"units": {"s1-ganancia-por-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0b5d7b570d8c53d18aea1dc0d53735b3bb02c693afd84aff82c38628008bf71b.mp3", "hash": "af8dba66e16fcd5db718c1dc637b7d9ff9c9be3f3a35a3c2713a7d703827a0df", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0b5d7b570d8c53d18aea1dc0d53735b3bb02c693afd84aff82c38628008bf71b.mp3", "duration_ms": 3680}, "s1-ganancia-por-vaso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a85f014cd80bca323abcc04f90761ef1dcab42fb4771e7ed0927bbbea76a5f96.mp3", "hash": "309c19b5d2de0210a757b4856052e0eacd470bfa4beaf36544cf38b754f23868", "bytes": 19584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a85f014cd80bca323abcc04f90761ef1dcab42fb4771e7ed0927bbbea76a5f96.mp3", "duration_ms": 3200}, "s1-ganancia-por-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d89d018deaaf004c5fb65af885c21affe378b69d01a7be6ad70d8bdf2e8f992.mp3", "hash": "e7bf9202e5fa7abe407c22b92b13233f0531df8cd98e5f7ed41ac81378709d9f", "bytes": 59328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3d89d018deaaf004c5fb65af885c21affe378b69d01a7be6ad70d8bdf2e8f992.mp3", "duration_ms": 9840}, "s1-ganancia-por-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/dc88c525294bb3ad8e0e68a34bd897d3969c1ee38b37d34bff3c26628e9197fa.mp3", "hash": "0f84a053d2d9c9d99ac06753195fa06d88cc158c55672b5cdbc7f6a5ae62f273", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dc88c525294bb3ad8e0e68a34bd897d3969c1ee38b37d34bff3c26628e9197fa.mp3", "duration_ms": 4560}, "s1-ganancia-por-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/58a7c18adf420f96cdcdfb15066ca2ddbb87bf184f7c804636571ad8808444ae.mp3", "hash": "7a1d2179b4acdad0efbd882375d2f7ed26a1956b00ee3f28a21f315f41d78720", "bytes": 46944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/58a7c18adf420f96cdcdfb15066ca2ddbb87bf184f7c804636571ad8808444ae.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "A reta da poupança", "locale": "pt-BR", "subject": "mixed", "objectives": ["Localizar quantidades em uma reta numérica de 0 a 100", "Identificar quanto falta para alcançar uma meta de poupança"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 10, "type": "number_line", "hints": ["A poupança de Liruf está mais perto do 0 do que do 100.", "Conte de 10 em 10 a partir do 0: 10, 20..."], "title": "Onde está Liruf?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": true}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Mova o marcador para o lugar onde está a poupança de Liruf: 20 reais.", "difficulty": 1, "explanation_md": "Liruf tem 20 reais poupados. Na reta, o 20 está dois saltos de 10 a partir do 0.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dfa76a007a6de1e71fe8381f2b1860dfe26f048dae981ba1fe4119a1ae66c3f0.mp3", "hash": "e025756b06f3fbc682f0e32bf515e8a9172069833676bbe56457e1c3349dc3e2", "bytes": 26208, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/dfa76a007a6de1e71fe8381f2b1860dfe26f048dae981ba1fe4119a1ae66c3f0.mp3", "duration_ms": 4320}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a3d956193fad3d6f6c92bbe58a68f732de31875531dcf2e408999fbafd60a404.mp3", "hash": "0d93a55ec94d26510fbccd12a6ac79d584c0a4058f06c8971f6f1b5a18053a1c", "bytes": 28224, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a3d956193fad3d6f6c92bbe58a68f732de31875531dcf2e408999fbafd60a404.mp3", "duration_ms": 4640}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/2fdfcdf7e395e0a81bd86eb364b400fca3beee1ea898a006f683d65a1434e605.mp3", "hash": "fca1d421d2e9f96d9b8e29e1b1942580a94d87f6db517b03afccf4cd193fccbe", "bytes": 32544, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2fdfcdf7e395e0a81bd86eb364b400fca3beee1ea898a006f683d65a1434e605.mp3", "duration_ms": 5360}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/b7a057594b9127f282002e05a28a91f93ef70cd669a6b9a157fb365756ff4039.mp3", "hash": "ba94d5a838aed974bfbf091231801999fc985e69d18c25337f565c05137bed21", "bytes": 45936, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/b7a057594b9127f282002e05a28a91f93ef70cd669a6b9a157fb365756ff4039.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "A melhor decisão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher a melhor decisão quando um cliente paga com nota de 20 por um copo de 5: contar o troco com calma."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cambio-correcto", "xp": 10, "type": "best_decision", "hints": ["O copo custa 5 reais. Se pagam com 20, quanto ele precisa devolver?", "Conte o troco devagar para não errar."], "title": "O troco de Liruf", "payload": {"options": [{"id": "contar-cambio", "text_md": "Contar o troco com calma: dar 15 reais", "rationale_md": "É a melhor decisão porque assim Liruf entrega o troco exato e a cliente confia nele."}, {"id": "adivinar-cambio", "text_md": "Adivinhar o troco rápido e dar 10 reais", "rationale_md": "Adivinhar pode fazer com que você dê troco a menos e a cliente fique brava."}, {"id": "quedarse-dinero", "text_md": "Ficar com toda a nota e não dar troco", "rationale_md": "Ficar com a nota inteira é desonesto e a cliente perderia seu dinheiro."}], "scenario_md": "Liruf está nervoso porque a primeira cliente paga com uma nota de R$20 por um copo de R$5. Qual é a melhor decisão?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/45effb76fc6f8662f63688a902529a1c1611d31ccd8c8aac814ceff586457157.png", "prompt_md": "Uma cliente paga com uma nota de R$20 por um copo de R$5. O que Liruf deve fazer?", "difficulty": 1, "explanation_md": "Liruf deve contar o troco com calma: 20 menos 5 são 15 reais. Assim ele não erra e a cliente fica contente.", "audio_segment_id": "s1-cambio-correcto.prompt"}], "schema_version": 1}', '{"s1-cambio-correcto": {"qualities": {"contar-cambio": 100, "adivinar-cambio": 30, "quedarse-dinero": 0}}}', '{"units": {"s1-cambio-correcto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2176f6cae43b3a494e526a5ea88174fc8cbb596fe2aed68f95b8446f0a2b571f.mp3", "hash": "cc59c4db0f52536a9a8c454509b574796453cca94fec90b065efe3f2658f2e5c", "bytes": 34848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2176f6cae43b3a494e526a5ea88174fc8cbb596fe2aed68f95b8446f0a2b571f.mp3", "duration_ms": 5760}, "s1-cambio-correcto.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fb358d078587827dbb50b1e1396e0cb2b74cb5cd2a7e4d089a086b915504d11f.mp3", "hash": "16d27ec9033dd4cad44fca355f531056e48034cc10a4a312fb27c73a66a12bb7", "bytes": 14688, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fb358d078587827dbb50b1e1396e0cb2b74cb5cd2a7e4d089a086b915504d11f.mp3", "duration_ms": 2400}, "s1-cambio-correcto.prompt": {"url": "http://localhost:4006/files/lesson-audio/ae94958a6553e993d31875c0776ca33c044eae4f3d54ccebc00367ad3b583e88.mp3", "hash": "7050bc8e1f96ad38fb8b6b7114136f99c9ebfa6da5143481fdd2f44046366cc9", "bytes": 46368, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ae94958a6553e993d31875c0776ca33c044eae4f3d54ccebc00367ad3b583e88.mp3", "duration_ms": 7680}, "s1-cambio-correcto.choices": {"url": "http://localhost:4006/files/lesson-audio/4553a5498466b743ec633f2e84f46881c3240b8cdc8e6584f038b78fdd5c4f2b.mp3", "hash": "dd44547677620f844b5691e7c3bcb4beac8d5d7e30372ce8953683ac7d1d8d41", "bytes": 57456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4553a5498466b743ec633f2e84f46881c3240b8cdc8e6584f038b78fdd5c4f2b.mp3", "duration_ms": 9520}, "s1-cambio-correcto.explanation": {"url": "http://localhost:4006/files/lesson-audio/7e86a212aa37454e354128acc2423483b3b802dde046ba9ab593c926145e937b.mp3", "hash": "0ac7de7cfc569ad88f80360c4f3087dc0649981eecd7beb961d1f07498079e7b", "bytes": 55584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7e86a212aa37454e354128acc2423483b3b802dde046ba9ab593c926145e937b.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "A real day at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Listen to two customers talk about the lemonade and answer two questions in a row: one true/false and one with images."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-clientes", "xp": 0, "type": "story_dialogue", "title": "Neighbors share their thoughts", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Hey, Liruf''s lemonade is really tasty. And it only costs 5 dollars a cup.", "character": "rho"}, {"action": "idle", "emotion": "surprised", "text_md": "5 dollars? That''s cheap! At the corner store it costs 8.", "character": "zara"}, {"action": "idle", "emotion": "happy", "text_md": "Yeah, and Liruf always puts a lot of ice. I''m going to buy two cups.", "character": "rho"}, {"action": "idle", "emotion": "thinking", "text_md": "Me too. With 10 dollars I can afford two.", "character": "zara"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/584c479e963f068a857d952d74a40324f3f71f1232bbe0548698c14c9e574310.png", "prompt_md": "Listen to what the neighbors say about the lemonade stand.", "difficulty": 1, "audio_segment_id": "s1-dialogo-clientes.prompt"}, {"id": "s2-precio-verdadero", "xp": 10, "type": "true_false", "title": "True or false?", "payload": {"statement_md": "Liruf''s lemonade costs 5 dollars a cup.", "justifications": [{"id": "j1", "text_md": "Rho said it costs 5 dollars and Zara said it''s cheap."}, {"id": "j2", "text_md": "Zara said it costs 8 dollars at the store."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "According to the conversation, does the lemonade cost 5 dollars?", "difficulty": 1, "explanation_md": "Rho said ''it only costs 5 dollars a cup'', so it''s true. Zara compared it to another price of 8 dollars, but that''s not the stand''s price.", "audio_segment_id": "s2-precio-verdadero.prompt"}, {"id": "s3-cuantos-vasos", "xp": 10, "type": "picture_choice", "title": "How many cups?", "payload": {"options": [{"id": "opt1", "icon": "local_cafe", "label": "1 cup", "image_url": "http://localhost:4006/files/lesson-images/46af6d772b221291dd17d00534ad529312329e6f3b728983bf69cc21cfbbc59e.png", "rationale_md": "With 10 dollars you can buy more than one cup if each costs 5."}, {"id": "opt2", "icon": "local_cafe", "label": "2 cups", "image_url": "http://localhost:4006/files/lesson-images/b8e5fb42eda0d4386c70f5b92af914dbf372391b78e1429e39eac054b1800e45.png"}, {"id": "opt3", "icon": "local_cafe", "label": "3 cups", "image_url": "http://localhost:4006/files/lesson-images/b9545f1c5a103a448519b501774aa653b64fcb71113bda1c8a87e8b7e8fa2efd.png", "rationale_md": "With 10 dollars you can''t afford 3 cups because 3×5=15, and you only have 10."}]}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Zara has 10 dollars. How many cups of lemonade can she buy if each one costs 5 dollars?", "difficulty": 1, "explanation_md": "Each cup costs 5 dollars. With 10 dollars you can buy 2 cups because 5+5=10.", "audio_segment_id": "s3-cuantos-vasos.prompt"}], "schema_version": 1}', '{"s3-cuantos-vasos": {"correct_option_id": "opt2"}, "s2-precio-verdadero": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s3-cuantos-vasos.prompt": {"url": "http://localhost:4006/files/lesson-audio/8efefffa16f7ebf3c0a008fd424dbfcaef0ff028cbc3a58e4bfdfb67e3717cb7.mp3", "hash": "9fbde1ba86736a940ebb36a1f1e3a7a8c7b1f7aebee9c8723c7bb2f408effac1", "bytes": 35856, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/8efefffa16f7ebf3c0a008fd424dbfcaef0ff028cbc3a58e4bfdfb67e3717cb7.mp3", "duration_ms": 5920}, "s3-cuantos-vasos.choices": {"url": "http://localhost:4006/files/lesson-audio/5034092e8513c12ead7ed427a5550a592ddb3db1a01c7abaa7bf24961afcd0de.mp3", "hash": "716acfe6ef4855b4f814cd3d2469f9d0e7a2e9054f59903ee83af08380b1a8b1", "bytes": 16128, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/5034092e8513c12ead7ed427a5550a592ddb3db1a01c7abaa7bf24961afcd0de.mp3", "duration_ms": 2640}, "s1-dialogo-clientes.line.0": {"url": "http://localhost:4006/files/lesson-audio/f479187e29fe6860d67cfb239aafc4da94439dbed65937bf556211d107d0e6a3.mp3", "hash": "95d3db599150c23c2814ec82075088d0b02138b314dd91dac78575ca1aab7159", "bytes": 35424, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/f479187e29fe6860d67cfb239aafc4da94439dbed65937bf556211d107d0e6a3.mp3", "duration_ms": 5840}, "s1-dialogo-clientes.line.1": {"url": "http://localhost:4006/files/lesson-audio/c91b8274bf45dc30fc85d9f6d9dadecfc1beb51243dddf47d6208c40dc5d263f.mp3", "hash": "b4338ebb1567195d95136e1e73c28d49c58a48b9a8fe36a509322ee3ce54c4e7", "bytes": 27216, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c91b8274bf45dc30fc85d9f6d9dadecfc1beb51243dddf47d6208c40dc5d263f.mp3", "duration_ms": 4480}, "s1-dialogo-clientes.line.2": {"url": "http://localhost:4006/files/lesson-audio/45b43b50e95c36800141dcacd795cb2429aaa096e8a1ad12ab8bab0fd309d76f.mp3", "hash": "0f803fe019af4dd0783436fc66afbe14c24c86663afb82027d6cbeeebbe3fea2", "bytes": 29664, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/45b43b50e95c36800141dcacd795cb2429aaa096e8a1ad12ab8bab0fd309d76f.mp3", "duration_ms": 4880}, "s1-dialogo-clientes.line.3": {"url": "http://localhost:4006/files/lesson-audio/7120a7952745ccabc1ff363ad411e0fc1274adf25bcb1fe4da8b5934d500fc57.mp3", "hash": "5dc233cea5be54c6855b7fa8be57868d5c66500e230aef74f7e911f5bae741a8", "bytes": 21024, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7120a7952745ccabc1ff363ad411e0fc1274adf25bcb1fe4da8b5934d500fc57.mp3", "duration_ms": 3440}, "s1-dialogo-clientes.prompt": {"url": "http://localhost:4006/files/lesson-audio/912e805a5f7395343ffd4c3471253334a97df75e704f65e980abfd44a490ce3a.mp3", "hash": "58f471e66b273b6affbdebd0dfb32e5c73d39894dd70b1914d15502ecd8e1670", "bytes": 19584, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/912e805a5f7395343ffd4c3471253334a97df75e704f65e980abfd44a490ce3a.mp3", "duration_ms": 3200}, "s2-precio-verdadero.prompt": {"url": "http://localhost:4006/files/lesson-audio/4a46d630b1d22d0b5cf583cc810c79602fbdd2dde1f1ba31992d5073ba424de7.mp3", "hash": "2359b5fbe61eb137f7f03e11e2215d53b5766943c71ef3d0dee98932475317b3", "bytes": 23904, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/4a46d630b1d22d0b5cf583cc810c79602fbdd2dde1f1ba31992d5073ba424de7.mp3", "duration_ms": 3920}, "s3-cuantos-vasos.explanation": {"url": "http://localhost:4006/files/lesson-audio/5ebf5273b39703e3002fb1b3288b8721b67d3981e73661c460c7a3d1d9be07d5.mp3", "hash": "b773460a31572a5f194cb3f35fe66df0a654e8c5712a851ada1384620c1b65e8", "bytes": 40608, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/5ebf5273b39703e3002fb1b3288b8721b67d3981e73661c460c7a3d1d9be07d5.mp3", "duration_ms": 6720}, "s2-precio-verdadero.explanation": {"url": "http://localhost:4006/files/lesson-audio/f9bf2ed68dcd346e2d33b540d8ee631f5ab2b8fc99ac8811ec88022cf99b2fc7.mp3", "hash": "86be71ac281247aa9b650422293eeb56b84125527d40670391de372dd61c616a", "bytes": 51264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f9bf2ed68dcd346e2d33b540d8ee631f5ab2b8fc99ac8811ec88022cf99b2fc7.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Order Liruf''s Day", "locale": "en-US", "subject": "mixed", "objectives": ["Order the steps of the sales day in chronological order"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 15, "type": "timeline_order", "hints": ["What do you do first when you arrive at the stand?", "Think: before selling, you have to prepare."], "title": "Liruf''s Day", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Buy lemons and sugar", "image_url": "http://localhost:4006/files/lesson-images/9a1fd1d1b180c741233fb94b2381175937cdd0f3d11eabd629df048b2a30ab2b.png"}, {"id": "preparar", "icon": "local_drink", "text_md": "Prepare the lemonade", "image_url": "http://localhost:4006/files/lesson-images/39a510fb02ce3c4dd48cafc09a4e4a3ae32050a32974efc946236da00cbcf1b3.png"}, {"id": "vender", "icon": "storefront", "text_md": "Sell cups at noon", "image_url": "http://localhost:4006/files/lesson-images/fc96f7e1051a982f87cf9218d9fc69082075ee90deca429cffbc660a26331cdb.png"}, {"id": "contar", "icon": "payments", "text_md": "Count money and put away", "image_url": "http://localhost:4006/files/lesson-images/f6a4e19bba704ca48543f8d44cfbb628ac45c76e6ecac795ae55963e3cf5f6c1.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Tap the events in order, from morning to closing.", "difficulty": 2, "explanation_md": "Liruf buys ingredients early, then prepares lemonade, sells at noon, and finally counts the money and puts it away.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a36f48a698ced60f2efa3cc620db1254121ec67437e49873e340cc212b7896ae.mp3", "hash": "7a75aaf0f33183e908d991cff041b6be5b635d7a49131961478ea2c8a26d505e", "bytes": 17136, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/a36f48a698ced60f2efa3cc620db1254121ec67437e49873e340cc212b7896ae.mp3", "duration_ms": 2800}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3e8728e47f9951b9735905e0ceab610ccef047722c9c7108e236516082711fe8.mp3", "hash": "fc81d7eeae32b9740512b3dde015a7191d0820c8059735aafe642fcb2dc826a4", "bytes": 16128, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/3e8728e47f9951b9735905e0ceab610ccef047722c9c7108e236516082711fe8.mp3", "duration_ms": 2640}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/8474275456aa849f78f9c9fb333b8179c78560b11503560e60cfb727301f37d0.mp3", "hash": "b737e397da59c1944219d918b74860c59c9cf9796decf5ec2af79eea08ee349b", "bytes": 18576, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/8474275456aa849f78f9c9fb333b8179c78560b11503560e60cfb727301f37d0.mp3", "duration_ms": 3040}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/91b7a0f407a3dfa1da52320cac14fc96a20f2740c3f41321921687b3233b285e.mp3", "hash": "32f2f48be0053200e877bc810391e281dff659824d6e778d3e3532282233ec00", "bytes": 43488, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/91b7a0f407a3dfa1da52320cac14fc96a20f2740c3f41321921687b3233b285e.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Quick review: profit per cup", "locale": "en-US", "subject": "money", "objectives": ["Calculate the profit per cup of lemonade (price - cost of ingredients)"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-por-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["Profit is what''s left after paying for the ingredients.", "Subtract the cost of the ingredients from the price of the cup."], "title": "Profit per cup", "payload": {"options": [{"id": "a", "text_md": "2 dollars", "rationale_md": "That''s the cost of the ingredients, not the profit."}, {"id": "b", "text_md": "3 dollars"}, {"id": "c", "text_md": "5 dollars", "rationale_md": "That''s the price of the cup, but you have to subtract what it costs to make it."}, {"id": "d", "text_md": "7 dollars", "rationale_md": "You added the price and the cost, but profit is the subtraction."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina challenges you: without looking at the notebook, how much does Liruf earn for each cup he sells? The cup costs 5 dollars and the ingredients cost 2 dollars.", "difficulty": 1, "explanation_md": "Liruf earns 3 dollars per cup: 5 dollars for the price minus 2 dollars for the ingredients. That''s the profit!", "audio_segment_id": "s1-ganancia-por-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-por-vaso": {"correct_option_id": "b"}}', '{"units": {"s1-ganancia-por-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4a55a1a674ba2c9486fe6b0fe8ceb48bede41d586e8887796846131d9b072f19.mp3", "hash": "941c269532bc88262226fea41cc48d82f754e4fb391e171f3824add13912337f", "bytes": 15696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4a55a1a674ba2c9486fe6b0fe8ceb48bede41d586e8887796846131d9b072f19.mp3", "duration_ms": 2560}, "s1-ganancia-por-vaso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4d523a31086fab138dd559d4a5369ffdbca6a34288e6936e505024ada0635f20.mp3", "hash": "772fdfadaa800d34de765dc1908328661a1f7cb9a353813329fc66e52808d23e", "bytes": 18144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4d523a31086fab138dd559d4a5369ffdbca6a34288e6936e505024ada0635f20.mp3", "duration_ms": 2960}, "s1-ganancia-por-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/134b16eb9410ba0ef09cfa067574e6a62f0fcdf054a8767a0bbedb04a84f49d5.mp3", "hash": "0d9fdb380e5ea8578ac9a61f14eb1c964f477a539c0ddd6621059db4c91be2e6", "bytes": 53568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/134b16eb9410ba0ef09cfa067574e6a62f0fcdf054a8767a0bbedb04a84f49d5.mp3", "duration_ms": 8880}, "s1-ganancia-por-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/fd0a058ee6aafd232f85f8c29a7e474932fd1fa8aac2f39b87787e02070bf8fd.mp3", "hash": "5d6c9a481afb094c32644acedbf1ddb5e4343b731b0a50519fb34d438ca895f4", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fd0a058ee6aafd232f85f8c29a7e474932fd1fa8aac2f39b87787e02070bf8fd.mp3", "duration_ms": 3760}, "s1-ganancia-por-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/e9f019d0a69568c07496a3da583077817a17c7bf44df7dea7075892a15f930a4.mp3", "hash": "4314cf965e926409a5ddc7d53cd3ac27f0d70d57c609206f8e71920fa91aa631", "bytes": 42624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e9f019d0a69568c07496a3da583077817a17c7bf44df7dea7075892a15f930a4.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar monedas para la meta", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de 1, 2 y 5 pesos para pagar un vaso de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Cuenta las moneditas una por una. ¿Cuánto suman?"], "title": "Cuenta las monedas", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2, 2]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/b5c68803f5c284713947656179b3d733c44e3f37dc0949f6d8370dfa570af459.png", "prompt_md": "Liruf vendió un vaso de limonada. El cliente paga con estas monedas. ¿Son exactamente 5 pesos?", "difficulty": 1, "explanation_md": "Las monedas suman 5 pesos: 2 + 2 + 1 = 5. ¡Justo lo que cuesta el vaso!", "audio_segment_id": "s1-contar-monedas.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6dba61aa2bc2f09fae460636a69b4f9644c4f44eb13073f5d4760ba24a730f03.mp3", "hash": "379c5aa5e9bdb217d3d23ad42bef8ffdbee543ff338e9f522d43fd334b6d5709", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6dba61aa2bc2f09fae460636a69b4f9644c4f44eb13073f5d4760ba24a730f03.mp3", "duration_ms": 3600}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/61456eea4e4a1acd365e897432933104c6dc31a8b56b351089a6963c69542552.mp3", "hash": "229e75138269a7997da6ee5811e9a332c20e14494dea0b951499f0a42d232235", "bytes": 44928, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/61456eea4e4a1acd365e897432933104c6dc31a8b56b351089a6963c69542552.mp3", "duration_ms": 7440}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/7d5bc216e4f66466eea967331d793b1bfe6089b743f2be992cd2e6627a2ac263.mp3", "hash": "3f216d1c2e7c5bbb6c2cea106c1ebfa8863fc584970db6a395b7c7bdd127a274", "bytes": 45504, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7d5bc216e4f66466eea967331d793b1bfe6089b743f2be992cd2e6627a2ac263.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Un día real del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Escuchar a dos clientes conversar sobre la limonada y responder dos preguntas seguidas: una de cierto/falso y una con imágenes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-clientes", "xp": 0, "type": "story_dialogue", "title": "Vecinos opinan", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Oye, la limonada de Liruf está bien rica. Y solo cuesta 5 pesos el vaso.", "character": "rho"}, {"action": "idle", "emotion": "surprised", "text_md": "¿5 pesos? ¡Qué barato! En la tienda de la esquina cuesta 8.", "character": "zara"}, {"action": "idle", "emotion": "happy", "text_md": "Sí, y Liruf siempre pone mucho hielo. Voy a comprar dos vasos.", "character": "rho"}, {"action": "idle", "emotion": "thinking", "text_md": "Yo también. Con 10 pesos me alcanza para dos.", "character": "zara"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/bf567928612b1c5a4f77cd796a681de5a62acbbbf2e42a98c266b0fb62a3e1c5.png", "prompt_md": "Escucha lo que dicen los vecinos sobre el puesto de limonada.", "difficulty": 1, "audio_segment_id": "s1-dialogo-clientes.prompt"}, {"id": "s2-precio-verdadero", "xp": 10, "type": "true_false", "title": "¿Cierto o falso?", "payload": {"statement_md": "La limonada de Liruf cuesta 5 pesos el vaso.", "justifications": [{"id": "j1", "text_md": "Rho dijo que cuesta 5 pesos y Zara dijo que es barato."}, {"id": "j2", "text_md": "Zara dijo que cuesta 8 pesos en la tienda."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Según la conversación, ¿la limonada cuesta 5 pesos?", "difficulty": 1, "explanation_md": "Rho dijo ''solo cuesta 5 pesos el vaso'', así que es cierto. Zara comparó con otro precio de 8 pesos, pero ese no es el del puesto.", "audio_segment_id": "s2-precio-verdadero.prompt"}, {"id": "s3-cuantos-vasos", "xp": 10, "type": "picture_choice", "title": "¿Cuántos vasos?", "payload": {"options": [{"id": "opt1", "icon": "local_cafe", "label": "1 vaso", "image_url": "http://localhost:4006/files/lesson-images/46af6d772b221291dd17d00534ad529312329e6f3b728983bf69cc21cfbbc59e.png", "rationale_md": "Con 10 pesos puedes comprar más de un vaso si cada uno cuesta 5."}, {"id": "opt2", "icon": "local_cafe", "label": "2 vasos", "image_url": "http://localhost:4006/files/lesson-images/b8e5fb42eda0d4386c70f5b92af914dbf372391b78e1429e39eac054b1800e45.png"}, {"id": "opt3", "icon": "local_cafe", "label": "3 vasos", "image_url": "http://localhost:4006/files/lesson-images/b9545f1c5a103a448519b501774aa653b64fcb71113bda1c8a87e8b7e8fa2efd.png", "rationale_md": "Con 10 pesos no alcanza para 3 vasos porque 3×5=15, y solo tienes 10."}]}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Zara tiene 10 pesos. ¿Cuántos vasos de limonada puede comprar si cada uno cuesta 5 pesos?", "difficulty": 1, "explanation_md": "Cada vaso cuesta 5 pesos. Con 10 pesos puedes comprar 2 vasos porque 5+5=10.", "audio_segment_id": "s3-cuantos-vasos.prompt"}], "schema_version": 1}', '{"s3-cuantos-vasos": {"correct_option_id": "opt2"}, "s2-precio-verdadero": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s3-cuantos-vasos.prompt": {"url": "http://localhost:4006/files/lesson-audio/2a4798824553fea36dc128e572c8a80e940e63721bff5b855e8c71545b087caf.mp3", "hash": "56eddeabba62a31a9eb0a9c3bd901dd21770b0c06d43956ce99d1878b955649a", "bytes": 42624, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2a4798824553fea36dc128e572c8a80e940e63721bff5b855e8c71545b087caf.mp3", "duration_ms": 7040}, "s3-cuantos-vasos.choices": {"url": "http://localhost:4006/files/lesson-audio/b73b7531866e415cc11cff8d9c78faae2fdb585ace3697212d618e4600fed198.mp3", "hash": "6dcba3bcf862b84c5f3e4e60e584fa04f10c30ae143ebee93f0fff76a138d0c7", "bytes": 23328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b73b7531866e415cc11cff8d9c78faae2fdb585ace3697212d618e4600fed198.mp3", "duration_ms": 3840}, "s1-dialogo-clientes.line.0": {"url": "http://localhost:4006/files/lesson-audio/2025cc2da5ca2c3398a61d68e3b4a1cbd012e4bd08094ee25a8a048398cd501e.mp3", "hash": "798322dfc134406f4c0f5ee661a9b1f8b345fe116eac85524bb7b962066d2bb7", "bytes": 38736, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2025cc2da5ca2c3398a61d68e3b4a1cbd012e4bd08094ee25a8a048398cd501e.mp3", "duration_ms": 6400}, "s1-dialogo-clientes.line.1": {"url": "http://localhost:4006/files/lesson-audio/e723c0489342e60349160be7c33a947bd526adf1e5fc462cbabe09a51b7dbe5b.mp3", "hash": "38e61292796174bf524b467d6653ef64d0f4848458578225636db2731c558b06", "bytes": 27648, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/e723c0489342e60349160be7c33a947bd526adf1e5fc462cbabe09a51b7dbe5b.mp3", "duration_ms": 4560}, "s1-dialogo-clientes.line.2": {"url": "http://localhost:4006/files/lesson-audio/5a825e0fd1dccb04bf39e5e90a34e9d65fbcd2c48a149d8fb2cc657ddf6d98b1.mp3", "hash": "812b5d337e15f510c6e4990089442973a6a95b9d6bd2625d01cadee9bdfb119f", "bytes": 30528, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5a825e0fd1dccb04bf39e5e90a34e9d65fbcd2c48a149d8fb2cc657ddf6d98b1.mp3", "duration_ms": 5040}, "s1-dialogo-clientes.line.3": {"url": "http://localhost:4006/files/lesson-audio/832db44f681a1a72c64fe03fdea9bcc022aaebfffb202fa74f2c6d2c56fbdae1.mp3", "hash": "5b7c8e2c9126b3ca7f8f2baa6cea29eb3bb279b5cef64f8e88527f34d1321b23", "bytes": 21456, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/832db44f681a1a72c64fe03fdea9bcc022aaebfffb202fa74f2c6d2c56fbdae1.mp3", "duration_ms": 3520}, "s1-dialogo-clientes.prompt": {"url": "http://localhost:4006/files/lesson-audio/fb74fe09cafc2d2ab99a2d6e499fffd387511dd0e0cd91b84bd618e08d076ef7.mp3", "hash": "b5de275f6bb00326e6929ce64aa904b317aa3b75d11c530718f7b4d216f5825a", "bytes": 21888, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fb74fe09cafc2d2ab99a2d6e499fffd387511dd0e0cd91b84bd618e08d076ef7.mp3", "duration_ms": 3600}, "s2-precio-verdadero.prompt": {"url": "http://localhost:4006/files/lesson-audio/d0c01912d45328dcc268e4801c9159ff135cfe162250ea2319559d571fc4fa60.mp3", "hash": "5e38344a5940d232e565296a64b2e0652401111f17f5b5d3e37fecd3a9b0a209", "bytes": 26208, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/d0c01912d45328dcc268e4801c9159ff135cfe162250ea2319559d571fc4fa60.mp3", "duration_ms": 4320}, "s3-cuantos-vasos.explanation": {"url": "http://localhost:4006/files/lesson-audio/6cab9798bfa3c9eb164ef6a617c78e49bbe85b4666ce99c27e37fece8b3a16b5.mp3", "hash": "fdac51394042f67d92c8cd80d02205951b6b836727d40b4aade65fdbae73f4b5", "bytes": 47808, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6cab9798bfa3c9eb164ef6a617c78e49bbe85b4666ce99c27e37fece8b3a16b5.mp3", "duration_ms": 7920}, "s2-precio-verdadero.explanation": {"url": "http://localhost:4006/files/lesson-audio/2e16c5e3345bd5785e53c86699aed40828d1a56fd38eefc08e260c4c729a504a.mp3", "hash": "15e504fcdc6968ea28e7006992ec40406d2efe8bcc1bfacfdde6f4b14e25fedf", "bytes": 62784, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2e16c5e3345bd5785e53c86699aed40828d1a56fd38eefc08e260c4c729a504a.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Empareja los precios del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar productos con sus precios exactos usando monedas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 10, "type": "memory_flip", "hints": ["Recuerda: la galleta cuesta 3 monedas, el vaso chico 5, y la jarra grande 20."], "title": "Memoria de precios", "payload": {"pairs": [{"a_md": "Galleta", "b_md": "3 monedas (1+2)", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/2ac15f9b207c4be166502b1979c9e3a45edc259af5e60111ef5cfb52a8c57fd8.png", "b_image_url": "http://localhost:4006/files/lesson-images/5b03a040e5c1b67fe6414ed9ae88886601840d6a4249dc78adfa55a8a45f24fc.png"}, {"a_md": "Vaso chico", "b_md": "5 monedas", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/e6a4e9a95c1ff3666c647a1d4dc49d68dbe6409a8c541aa262f5be269b82bf0e.png", "b_image_url": "http://localhost:4006/files/lesson-images/54522151bc48a76c0dc4d258aa9f0b475cdd286affe496556b6a82500df8742c.png"}, {"a_md": "Jarra grande", "b_md": "20 monedas (10+10)", "a_icon": "local_bar", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/a6d12279f5517ba82361dbd32d6eac734aa351529ca9c96c5da0d81a7db27e69.png", "b_image_url": "http://localhost:4006/files/lesson-images/fdcbac21b05e8107452923230b198536dedae4c9bc9f04f5a3339ca51bb877b2.png"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Toca las cartas para emparejar cada producto con su pago exacto. Galleta = 3, vaso chico = 5, jarra grande = 20.", "difficulty": 1, "explanation_md": "Cada producto tiene un precio fijo: galleta 3, vaso chico 5, jarra grande 20. ¡Así Liruf puede cobrar rápido!", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/275ce4955ae8e4c20deb7ca743e303d71469589ed73723b7ab6c3231e3a3d56a.mp3", "hash": "eefc62c4b02bdb7163419228d9d54cd30e97fffd5c71ad3a41b55873da1a110b", "bytes": 36288, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/275ce4955ae8e4c20deb7ca743e303d71469589ed73723b7ab6c3231e3a3d56a.mp3", "duration_ms": 6000}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/c6ea43e139642c36562a65fcbf5be91de57917555a2b9cbe56f9b4f0dbe5c257.mp3", "hash": "ec5299eb036df8f613d0b3d3666f209e09fd60b29530dad8a2eee9e423987a51", "bytes": 54576, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/c6ea43e139642c36562a65fcbf5be91de57917555a2b9cbe56f9b4f0dbe5c257.mp3", "duration_ms": 9040}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/278511fec94fb9be487b12910e4e9433787c2f0689151a19894b8a8d68edd4e6.mp3", "hash": "93f0c54b60d14cd52fdc6acf826a44a019dd82a5759ad6b27adca0dd1a293974", "bytes": 49824, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/278511fec94fb9be487b12910e4e9433787c2f0689151a19894b8a8d68edd4e6.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "equation-builder", "title": "Build the afternoon total", "locale": "en-US", "subject": "mixed", "objectives": ["Build the afternoon sum with tokens: 5 + 5 + 5 = 15 dollars (three cups sold)"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-cuenta", "xp": 10, "type": "equation_builder", "hints": ["Each cup costs 5 dollars. What is 5 + 5?", "Then add the third 5 to the result."], "title": "Build the afternoon sum", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Rho sold 3 cups of lemonade this afternoon. Build the sum with the tokens.", "difficulty": 1, "explanation_md": "Three cups of 5 dollars each add up to 5 + 5 + 5 = 15 dollars. That''s how you build the afternoon total!", "audio_segment_id": "s1-arma-cuenta.prompt"}], "schema_version": 1}', '{"s1-arma-cuenta": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-arma-cuenta.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7ace595f516d191356ef5a2e3265d45f30a406bec5a9d71358e72fc437748f44.mp3", "hash": "3dbcfcc5e9e59c0dc303498225ee0e0be24b1820daf21cfaf648ab394b2e5b88", "bytes": 27648, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/7ace595f516d191356ef5a2e3265d45f30a406bec5a9d71358e72fc437748f44.mp3", "duration_ms": 4560}, "s1-arma-cuenta.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3f892dc62f448d1fe9dc322e43dc5385031a5c0b13af4c0ea71e8eb82c221be6.mp3", "hash": "12625a94e21d47ca033db5e509441e124965cd591bc9c3044e6f4834c4ff51d0", "bytes": 16704, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3f892dc62f448d1fe9dc322e43dc5385031a5c0b13af4c0ea71e8eb82c221be6.mp3", "duration_ms": 2720}, "s1-arma-cuenta.prompt": {"url": "http://localhost:4006/files/lesson-audio/e7e3964c33e898929202928f7fedccb2268108d2fa5e9dfe479e9dc4c550a146.mp3", "hash": "4c9d39a828796a74ab201d50538c9a4d8a28c8334477a4e929c6114f9e68aac3", "bytes": 37296, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/e7e3964c33e898929202928f7fedccb2268108d2fa5e9dfe479e9dc4c550a146.mp3", "duration_ms": 6160}, "s1-arma-cuenta.explanation": {"url": "http://localhost:4006/files/lesson-audio/0980af2d4738ace8717e611bc21e789fede01b30f2ce3eda2b80e245d899f09f.mp3", "hash": "d43ace866ca21a61e35998134d2f17d6b22a447e40ee3a53b1e0b9e812a57b25", "bytes": 65088, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0980af2d4738ace8717e611bc21e789fede01b30f2ce3eda2b80e245d899f09f.mp3", "duration_ms": 10800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "balance-scale", "title": "Equilibra la balanza del trueque", "locale": "es-MX", "subject": "mixed", "objectives": ["Equilibrar una balanza colocando pesos equivalentes para lograr un trueque justo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-trueque", "xp": 15, "type": "balance_scale", "hints": ["Cada vaso vale 5 pesos. ¿Cuánto valen los 3 vasos juntos?", "Cada galleta vale 3 pesos. Busca cuántas galletas suman lo mismo que los 3 vasos."], "title": "Trueque justo", "payload": {"weights": [{"id": "galleta1", "label": "Galleta", "value": 3}, {"id": "galleta2", "label": "Galleta", "value": 3}, {"id": "galleta3", "label": "Galleta", "value": 3}, {"id": "galleta4", "label": "Galleta", "value": 3}, {"id": "galleta5", "label": "Galleta", "value": 3}], "left_fixed": [{"label": "Vaso de limonada", "value": 5}, {"label": "Vaso de limonada", "value": 5}, {"label": "Vaso de limonada", "value": 5}], "unknown_label": "Galleta"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf pone 3 vasos de limonada (5 pesos cada uno). El galletero pone galletas de 3 pesos. Coloca galletas hasta que la balanza se equilibre.", "difficulty": 2, "explanation_md": "3 vasos de 5 pesos suman 15 pesos. 5 galletas de 3 pesos también suman 15 pesos. ¡La balanza se equilibra!", "audio_segment_id": "s1-balance-trueque.prompt"}], "schema_version": 1}', '{"s1-balance-trueque": {}}', '{"units": {"s1-balance-trueque.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bc81a0bbcf9331e8e24d9e6f897b7855f4495809467de4af354a91ccb77fd57c.mp3", "hash": "205bc6042211de56d779081cec963e4df4fc1af285e8d516268338f7fc342e57", "bytes": 30528, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/bc81a0bbcf9331e8e24d9e6f897b7855f4495809467de4af354a91ccb77fd57c.mp3", "duration_ms": 5040}, "s1-balance-trueque.hint.1": {"url": "http://localhost:4006/files/lesson-audio/43b53dcf1d11dbea8e4ce970c15cd62dab695d3856e949c44023761f70fb9acd.mp3", "hash": "2918f0ebefce32e664ea6fb5f24e3b0430668f348086eb8705308bf88fe39921", "bytes": 40608, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/43b53dcf1d11dbea8e4ce970c15cd62dab695d3856e949c44023761f70fb9acd.mp3", "duration_ms": 6720}, "s1-balance-trueque.prompt": {"url": "http://localhost:4006/files/lesson-audio/3a4ef82cb4b66494ef273558ebd6f83b7dc65798116e6ac5d974433ef77113b2.mp3", "hash": "11b3284b09e8aeb746036fc7b256467230bfe5b283d09527f99d293566d583e8", "bytes": 65088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/3a4ef82cb4b66494ef273558ebd6f83b7dc65798116e6ac5d974433ef77113b2.mp3", "duration_ms": 10800}, "s1-balance-trueque.explanation": {"url": "http://localhost:4006/files/lesson-audio/f63bc93594373c82c1d299303c2bbb9ba49a7b4d1f115f1231c6addf74f91cd1.mp3", "hash": "fe3702f5acdb55ac2abed37a88fdef72516273fdb1c8e13365e41f7dc5b97984", "bytes": 59328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f63bc93594373c82c1d299303c2bbb9ba49a7b4d1f115f1231c6addf74f91cd1.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "¿Cuánto ganó Liruf?", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular y escribir cuánto ganó Liruf en total si vendió 4 vasos a 5 pesos cada uno."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "number_input", "hints": ["Cada vaso da 5 pesos. ¿Cuánto es 4 veces 5?", "Puedes sumar: 5 + 5 + 5 + 5."], "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8b7f65a1005c8ba3bba389951904346f8edeabd93aa8984d6c3cd6e443e4900d.png", "prompt_md": "Liruf vendió 4 vasos de limonada a 5 pesos cada uno. ¿Cuánto ganó en total?", "difficulty": 1, "explanation_md": "Liruf ganó 20 pesos porque 4 vasos × 5 pesos cada uno = 20 pesos.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"value": 20, "tolerance": 0}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7e150623c565aea9c8f772829024dc355d53752da56fb22d286b665c84e95e98.mp3", "hash": "e786b7724a6fa351898c2971ba38e4f2df88403c60ba44d821cec0955327c6a3", "bytes": 24768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7e150623c565aea9c8f772829024dc355d53752da56fb22d286b665c84e95e98.mp3", "duration_ms": 4080}, "s1-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b11f14657e08693f950c8a17a62b9149c2fb35e546ee7cf5b357e0c3a7c1cdd6.mp3", "hash": "16a91efeddaf9c0b994814b062ba8e1da3c171ff5f20bc5bfe8fc8965835571e", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b11f14657e08693f950c8a17a62b9149c2fb35e546ee7cf5b357e0c3a7c1cdd6.mp3", "duration_ms": 4000}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/0e915d6f0864a006bda1fed96e178882999e792fac4d3c45f441fe8fe290eb1e.mp3", "hash": "e1ab4b1af02456c791308db07555f338fd91e4e7374bca574f7d62265a671223", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0e915d6f0864a006bda1fed96e178882999e792fac4d3c45f441fe8fe290eb1e.mp3", "duration_ms": 6720}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/ed1ed448ce8d9dfe7507f692da18d136a0fe63e7ab3f3c33c8d030a7211c10d1.mp3", "hash": "19d347a7f7a4c049359e87f1bf516b9e12eb66e1655a4d273758b09a2ab21b9c", "bytes": 41184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ed1ed448ce8d9dfe7507f692da18d136a0fe63e7ab3f3c33c8d030a7211c10d1.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "Vivir el puesto en historias jugables", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el precio de la limonada considerando el costo y la ganancia", "Observar cómo cada decisión afecta el avance hacia la meta de ahorro"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-limonada", "xp": 20, "type": "story_branch", "hints": ["Piensa: si cobras muy caro, quizá no compren. Si cobras muy barato, ganas poco por vaso.", "Recuerda que tu meta es juntar 80 pesos para la guitarra."], "title": "Elige el precio de hoy", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 pesos (el precio de siempre)"}, {"id": "precio3", "next": "final3", "text_md": "3 pesos (más barato)"}, {"id": "precio10", "next": "final10", "text_md": "10 pesos (el doble)"}], "emotion": "thinking", "text_md": "¡Es mediodía y hace un calorón! Seis vecinos hacen fila en tu puesto de limonada. Tú decides el precio de cada vaso. Cada vaso te cuesta 2 pesos hacerlo. ¿Cuánto cobras?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "Fin"}], "emotion": "happy", "text_md": "¡Los 6 vecinos compran! Cada vaso te deja 3 pesos de ganancia (5 - 2 = 3). En total ganaste 18 pesos. ¡Buen avance hacia la guitarra de 80 pesos!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "Fin"}], "emotion": "thinking", "text_md": "¡Se venden volando! Pero cada vaso solo te deja 1 peso de ganancia (3 - 2 = 1). En total ganaste solo 6 pesos. Casi no avanzas hacia la guitarra…", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "Fin"}], "emotion": "surprised", "text_md": "Los vecinos hacen mueca y se van a la nieve. No vendiste ni un vaso. Ganaste 0 pesos y te quedas con la jarra llena. La guitarra se ve muy lejos…", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/1b44fb451f3164f86933d033b2dded1da7b91f6d0e8396852fa67c8eb5412f4b.png", "prompt_md": "Hace calor y 6 vecinos esperan limonada. Cada vaso te cuesta 2 pesos hacerlo. ¿A qué precio vendes cada vaso?", "difficulty": 2, "explanation_md": "Liruf eligió un precio y vio cuánto avanzó hacia la guitarra de 80 pesos.", "audio_segment_id": "s1-precio-limonada.prompt"}], "schema_version": 1}', '{"s1-precio-limonada": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-limonada.hint.0": {"url": "http://localhost:4006/files/lesson-audio/241d5f19bb212621f595636fb5e7cc501abe6e1593b740b7b0cea3a4e8529ff3.mp3", "hash": "98952c0266ca3699ba07f08645bc151901cae6efc18684bc706cb584a8df7b50", "bytes": 42048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/241d5f19bb212621f595636fb5e7cc501abe6e1593b740b7b0cea3a4e8529ff3.mp3", "duration_ms": 6960}, "s1-precio-limonada.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b901bb996cfcdf3093202a15ac3af3f07530408cf4edb0c5f78dc647fa035939.mp3", "hash": "7c1dd6dfafa96a14c4d1a6980e142e652d89a994927c889f99edf27870c1a7b5", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b901bb996cfcdf3093202a15ac3af3f07530408cf4edb0c5f78dc647fa035939.mp3", "duration_ms": 3760}, "s1-precio-limonada.prompt": {"url": "http://localhost:4006/files/lesson-audio/758373ffbbb5632901d5ba7fb11a09293eab3b3d926c4497cc353695db165cdc.mp3", "hash": "9e83f056f411f80acb0454692bba341a6d3c79ab2e7062c5d2119f6bd43ccf7b", "bytes": 53136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/758373ffbbb5632901d5ba7fb11a09293eab3b3d926c4497cc353695db165cdc.mp3", "duration_ms": 8800}, "s1-precio-limonada.explanation": {"url": "http://localhost:4006/files/lesson-audio/a4639099bfca18b2db472eb61863805cdd31a31e71e898805de42a5a4bdb39ff.mp3", "hash": "b56c6a268c28b46c596112036b214f08db82ad19689d8acd8d7bfb4534b3a9c5", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a4639099bfca18b2db472eb61863805cdd31a31e71e898805de42a5a4bdb39ff.mp3", "duration_ms": 5600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "O mercado de Liruf", "locale": "pt-BR", "subject": "money", "objectives": ["Contar dinheiro com moedas de 1, 2, 5 e 10", "Calcular troco de uma nota de 20", "Planejar quantas semanas faltam para a meta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["Some o preço dos limões e do açúcar: 8 + 6 = 14. Depois subtraia 14 de 20 para saber quanto sobra."], "title": "Reabastecer a barraca", "payload": {"items": [{"id": "limones", "icon": "nutrition", "need": true, "label": "Limões", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/51663ea0a5c9c39f9dca310f92e00ee2d26e650857be7a91cc97e9732827cd88.png"}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Açúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/44acc4b1bcfc5e7f18da46a28d2f880f626946aeeefe2fe64e2f79318f037798.png"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Gelo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/8589cd04b2adf6e56e110426235fa171e453ac0450cd81b21f940ec69f317927.png"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Canudos", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/4cf348a4e191566c4267cd483f42051b152e877db7fc6273b208087c8b1c1882.png"}, {"id": "jarra", "icon": "local_bar", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/d17638f24f4c89796061397d012038f9545bb223885afcac69ea332f778264b0.png"}], "budget": 20, "currency": "BRL", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf tem uma nota de R$20. Precisa comprar limões (R$8) e açúcar (R$6). O que mais cabe sem passar de R$20?", "difficulty": 2, "explanation_md": "Liruf precisa de limões e açúcar para a limonada. Se gastar 8 + 6 = 14, sobram 6 reais. O gelo custa 5, os canudos 3, e a jarra 8. Só o gelo (5) cabe nos 6 que sobraram. Se comprar a jarra (8), passa do limite e o feirante tira algo; se comprar canudos (3), ainda sobra, mas o gelo é melhor para a limonada.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/00b1338c461357adedecd0d14e066b6dc41704c7c37a70fff252eafc0d5151df.mp3", "hash": "ee18aa222266789b79aa54c2704b20e49f89ba906bc6a50f09d45f1440cda0d0", "bytes": 57024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/00b1338c461357adedecd0d14e066b6dc41704c7c37a70fff252eafc0d5151df.mp3", "duration_ms": 9440}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/a2b6c54397ec258e310001e27399b0a1ca01c15350b56ec537973b9c019aec1c.mp3", "hash": "f6e64e89c3a1d1afa23e9daf89fdd7a9980791fff16532a452fd21b57aa1b1b5", "bytes": 66096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a2b6c54397ec258e310001e27399b0a1ca01c15350b56ec537973b9c019aec1c.mp3", "duration_ms": 10960}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/06882ed4a1a14d15f05cf8cc2d69bc09a36e17f967c73604f455bb01fd2a5790.mp3", "hash": "c78baf612c79fc4a03bf3c6d6180a21ec07a29576848dee28801356186b74b12", "bytes": 152064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/06882ed4a1a14d15f05cf8cc2d69bc09a36e17f967c73604f455bb01fd2a5790.mp3", "duration_ms": 25280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "repaso-true-false", "title": "Revisão: Verdadeiro ou Falso?", "locale": "pt-BR", "subject": "money", "objectives": ["Distinguir entre receita total e lucro em uma barraca de limonada", "Lembrar que cada copo custa 2 reais de insumos, então o lucro por copo é 3 reais"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Lembre-se: cada copo custa 2 reais de limão e açúcar. Quanto sobra de verdade por copo?", "Se você vende 10 copos a 5 reais, entram 50 reais. Mas disso é preciso subtrair o custo para fazê-los."], "title": "Verdadeiro ou Falso?", "payload": {"statement_md": "Liruf vendeu 10 copos a 5 reais cada, então ganhou 50 reais.", "justifications": [{"id": "j-verdadero", "text_md": "Verdadeiro: 10 copos × 5 reais = 50 reais, esse é o lucro."}, {"id": "j-falso", "text_md": "Falso: 10 copos × 5 reais = 50 reais de receita, mas cada copo custou 2 reais para fazer, então o lucro é 30 reais."}]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Rho diz: ''Você vendeu 10 copos a 5 reais cada, então ganhou 50 reais!'' É verdade ou é uma pegadinha?", "difficulty": 1, "explanation_md": "É **falso**. Entraram 50 reais, mas cada copo custou 2 reais para fazer (limão e açúcar). O lucro por copo é 5 - 2 = 3 reais. Para 10 copos, o lucro real é 10 × 3 = 30 reais, não 50. O que entra não é o que você ganha!", "audio_segment_id": "s1-verdadero-falso.prompt"}], "schema_version": 1}', '{"s1-verdadero-falso": {"is_true": false, "correct_justification_id": "j-falso"}}', '{"units": {"s1-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2548eee72463e5690d15b6d822b285473c5893830b96ccc2193b4799001e53d9.mp3", "hash": "a6e4a755e69ef0b35bd26a4e9540c0d960d79b3e79fdddae2a90974bdee6de09", "bytes": 43488, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2548eee72463e5690d15b6d822b285473c5893830b96ccc2193b4799001e53d9.mp3", "duration_ms": 7200}, "s1-verdadero-falso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/55f28b6e9ccfeb8ab1be1a2d587ab6fe77a454a3aafc901396b7d0cea8244794.mp3", "hash": "4aa0e1b23408b40fc36f8f7358eeaa8ff7e1a1abae9931b110f222e743e01b6b", "bytes": 52128, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/55f28b6e9ccfeb8ab1be1a2d587ab6fe77a454a3aafc901396b7d0cea8244794.mp3", "duration_ms": 8640}, "s1-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/626cb13d5fda2a573ef467c6f42e952fc84277509caf3fdb66dae4896ebc5c21.mp3", "hash": "843f3d418def69729c7f9c0adf596a3f8731bdadaaf542af1efd58c27f64cdbb", "bytes": 56448, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/626cb13d5fda2a573ef467c6f42e952fc84277509caf3fdb66dae4896ebc5c21.mp3", "duration_ms": 9360}, "s1-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/120fa9223e7ce4a98f87128dd5b2b304e9a502273bd05cfe9e77444fbbe6f8a2.mp3", "hash": "18e4c35ab83f38143615886c31095bf504500337f1642b1c29781c1ba4a801f9", "bytes": 121248, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/120fa9223e7ce4a98f87128dd5b2b304e9a502273bd05cfe9e77444fbbe6f8a2.mp3", "duration_ms": 20160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "The cardboard cash register", "locale": "en-US", "subject": "mixed", "objectives": ["Order the instructions for the homemade cash register: receive payment → verify amount → give change → record the sale."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-registradora", "xp": 15, "type": "code_order", "hints": ["First, receive the customer''s payment.", "After giving change, record the sale."], "title": "Order the steps", "payload": {"blocks": [{"id": "recibir", "text_md": "Receive payment"}, {"id": "verificar", "text_md": "Verify amount"}, {"id": "dar_cambio", "text_md": "Give change"}, {"id": "anotar", "text_md": "Record the sale"}], "language_hint": "Step by step"}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Rho sells lemonade for 5 dollars. A customer pays with 10. What does Rho do first?", "difficulty": 2, "explanation_md": "Rho receives the 10 dollars, sees it''s more than 5, gives 5 in change, and records the sale. That''s how the cash register works!", "audio_segment_id": "s1-ordenar-registradora.prompt"}], "schema_version": 1}', '{"s1-ordenar-registradora": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"s1-ordenar-registradora.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2291dc88d99f70f05298af46613995e15e2ce7108039ae0f5aae635766fcfed8.mp3", "hash": "b7f413c700e7e29d1592acf498d37204ea4888de6b1d4bfc026484ed05a69acd", "bytes": 17568, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2291dc88d99f70f05298af46613995e15e2ce7108039ae0f5aae635766fcfed8.mp3", "duration_ms": 2880}, "s1-ordenar-registradora.hint.1": {"url": "http://localhost:4006/files/lesson-audio/955486babde14af3879e4341994cf8149500def4b9b66eb88692a10666de7a35.mp3", "hash": "285e2a390a0923e4f399a832b4e8978644b3ffd0558f3f21a3b6868f0f9cc8bd", "bytes": 15696, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/955486babde14af3879e4341994cf8149500def4b9b66eb88692a10666de7a35.mp3", "duration_ms": 2560}, "s1-ordenar-registradora.prompt": {"url": "http://localhost:4006/files/lesson-audio/ce6ada4640db2a467b8ec595f7c0ee89b4cb94bd420e1b8bd30d50175baa5ee5.mp3", "hash": "c46e7ff528867b3fcbbcfe1b63e9980e39aae7d61e5abc3b210197d548b2ba31", "bytes": 40608, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/ce6ada4640db2a467b8ec595f7c0ee89b4cb94bd420e1b8bd30d50175baa5ee5.mp3", "duration_ms": 6720}, "s1-ordenar-registradora.explanation": {"url": "http://localhost:4006/files/lesson-audio/add0e5ee3dfb65bafb20c88edde980b1a42b1e7d9c11f07b5b1f1b2c5a3eb806.mp3", "hash": "7636657ac43ecf8f3142fa4dc36aa7f447aa05863cd30550757ee0ec028fb55f", "bytes": 61776, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/add0e5ee3dfb65bafb20c88edde980b1a42b1e7d9c11f07b5b1f1b2c5a3eb806.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "dialogue-choice", "title": "Elegir qué decirle al cliente que pide rebaja", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir una respuesta amable que no regale la ganancia cuando un cliente pide rebaja"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cliente-rebaja", "xp": 15, "type": "dialogue_choice", "hints": ["Piensa: si le bajas mucho, ¿ganas algo?", "Puedes ser amable sin perder tu ganancia."], "title": "¿Le bajas el precio?", "payload": {"turns": [{"id": "t1", "npc_md": "Cliente: ''¿Me lo dejas en 3?''", "replies": [{"id": "r1", "text_md": "Claro, por ser tú, te lo dejo en 3."}, {"id": "r2", "text_md": "Lo siento, el precio es 5 pesos. ¡Está bien fresca!"}, {"id": "r3", "text_md": "No, no puedo. Si no te gusta, vete."}]}, {"id": "t2", "npc_md": "Cliente: ''Vale, gracias. Entonces me llevo una.''", "replies": [{"id": "r4", "text_md": "¡Gracias a ti! Disfrútala."}, {"id": "r5", "text_md": "¿Seguro? Podría darte dos por 8 pesos."}, {"id": "r6", "text_md": "Bueno, pero apúrate."}]}], "persona": {"name": "Liruf", "role_md": "dueño del puesto de limonada", "character": "liruf"}, "opening_md": "Un cliente se acerca y dice: ''Oye, ¿me lo dejas en 3 pesos? ¡Solo traigo eso!''"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/c35b7173ba58a6e909a7fa199010fdc9bb636a9070f90ff827b2ff0a7d32ddba.png", "prompt_md": "Un cliente quiere un vaso de limonada pero pide rebaja. ¿Qué le dices?", "difficulty": 2, "explanation_md": "Liruf gana 5 pesos por vaso. Si lo deja en 3, gana solo 2 pesos. Mejor ofrecer el mismo precio con amabilidad.", "audio_segment_id": "s1-cliente-rebaja.prompt"}], "schema_version": 1}', '{"s1-cliente-rebaja": {"turns": [{"turn_id": "t1", "qualities": {"r1": 20, "r2": 100, "r3": 10}, "reactions": {"r1": "El cliente paga 3, pero Liruf gana solo 2 pesos. No alcanza para la guitarra.", "r2": "El cliente sonríe y paga 5. ¡Liruf gana su ganancia completa!", "r3": "El cliente se va enojado. Liruf no vende nada."}}, {"turn_id": "t2", "qualities": {"r4": 100, "r5": 80, "r6": 30}, "reactions": {"r4": "El cliente se va contento. ¡Venta exitosa!", "r5": "El cliente duda, pero acepta. Liruf vende 2 vasos, gana 10 pesos.", "r6": "El cliente se siente apurado y se va sin comprar."}}]}}', '{"units": {"s1-cliente-rebaja.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b1e2dadb50e8f7a73e5b939f612a5040bfd73dcd7a92a17eb31061b41f97296e.mp3", "hash": "3646fde020a3dbc404da34eddb335d359e9aae5d3ac71a012daa9db8c1bfaaab", "bytes": 25776, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b1e2dadb50e8f7a73e5b939f612a5040bfd73dcd7a92a17eb31061b41f97296e.mp3", "duration_ms": 4240}, "s1-cliente-rebaja.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8581d3e79956a1eed4d1ce78bfff4727d8f5af986cfe35628bf3022d1fac29a5.mp3", "hash": "e10385aadfa42a6b9cc50149dcf2f5c354ab3ea36148ef241df96c14f66c2ceb", "bytes": 14688, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/8581d3e79956a1eed4d1ce78bfff4727d8f5af986cfe35628bf3022d1fac29a5.mp3", "duration_ms": 2400}, "s1-cliente-rebaja.prompt": {"url": "http://localhost:4006/files/lesson-audio/b4f2ad99a69d14e6196818cd7779e59097055353cbc17cee72d5491fcc8f4bc2.mp3", "hash": "4ee0b51bc29ee771ae8898d10823abd3625c6796efd33cc6d79a5315300d000e", "bytes": 32544, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b4f2ad99a69d14e6196818cd7779e59097055353cbc17cee72d5491fcc8f4bc2.mp3", "duration_ms": 5360}, "s1-cliente-rebaja.explanation": {"url": "http://localhost:4006/files/lesson-audio/bea37532713d442294a8f957b71918afaf04d84c1d0f01990e5afa6e78ef6c82.mp3", "hash": "b09a9542fa34a10ee786425a03e17ee4cbfa0465a77cc22bd717ab22faf1c492", "bytes": 56448, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/bea37532713d442294a8f957b71918afaf04d84c1d0f01990e5afa6e78ef6c82.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "La alcancía que agradece la paciencia", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si dejar dinero en una alcancía que da moneditas extra cada semana conviene más que gastarlo ya.", "Predecir el total después de esperar, entendiendo que crece un poco pero no se duplica."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana la alcancía da 2 monedas de 1 peso. ¿Cuántas monedas extra da en 2 semanas?", "Empieza con 20. Suma las moneditas extra."], "title": "¿Dejar los 20 o sacarlos ya?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Se queda en 20"}, {"id": "opt2", "text_md": "24 pesos"}, {"id": "opt3", "text_md": "Casi 40 pesos"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tiene 20 pesos ahorrados para una guitarra que cuesta 80. Rho le dice: ''Si guardas tu dinero en esta alcancía especial, cada semana te da 2 monedas de 1 peso extra por dejarlo ahí.'' Liruf mete sus 20 pesos. Piensa: ''Si espero 2 semanas, ¿tendré más o menos que si gasto todo ahora?'' ¿Cuánto tendrá Liruf después de 2 semanas?", "difficulty": 1, "explanation_md": "La alcancía da 2 monedas de 1 peso cada semana, así que en 2 semanas da 4 pesos extra. 20 + 4 = 24. ¡El dinero crece poquito a poquito hacia la guitarra! Si hubiera gastado todo ahora, no tendría esos 4 pesos extra.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "hash": "3dc18383d9a32c406d7fbe70048d4c251d4877228f2348bcfeef02d3057b0217", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "duration_ms": 6720}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "hash": "ac7225036bac770feb6907a8d2cdac588fcdfe82d73be88200379222db2cac7f", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "hash": "bb23ce2312a94c7ed78d3215c8a47b3b4ddc843eb4ca2970f9243cfe474e18df", "bytes": 131328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "duration_ms": 21840}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "hash": "e4009c6e87dc657fc8d8b2b77b6ceafab722fa548a5d58601a4ec344defe357a", "bytes": 100224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Llena los números del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar dinero para comprar una limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "fill_blank", "hints": ["Cuenta las monedas que le sobran después de pagar."], "title": "Ganancia del día", "payload": {"bank": [{"id": "b1", "text_md": "2"}, {"id": "b2", "text_md": "5"}, {"id": "b3", "text_md": "8"}], "mode": "typed", "text_md": "A Liruf le quedan {{1}} monedas de $1."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tiene 5 monedas de $1. La limonada cuesta $3. ¿Cuántas monedas le quedan?", "difficulty": 1, "explanation_md": "Liruf pagó $3 y le quedaron 2 monedas de $1. ¡Todavía tiene dinero para otro gusto!", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["2"], "bank_id": "b1"}]}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/193c04fde61b57455080913817473e5c47c92203444e9cc3ba6149c51156e906.mp3", "hash": "9d402d254c14fe3ab304d16bc8c7161cf75fafa77672dddd3317af86bc634fe3", "bytes": 19008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/193c04fde61b57455080913817473e5c47c92203444e9cc3ba6149c51156e906.mp3", "duration_ms": 3120}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/1bf3ab9bd06fe816d09c93dc75da766a26503ce1c110f06b02e675997de92bec.mp3", "hash": "4f3780eb28bf297248fb7e93265aca58300a9ced2fc3d28320fe316c0e2c1ee9", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1bf3ab9bd06fe816d09c93dc75da766a26503ce1c110f06b02e675997de92bec.mp3", "duration_ms": 6720}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/6514e9219e882e4c9797489508cf006f667f04b7475d7f6d8bc6f400a03a6708.mp3", "hash": "926a71c75f78e0f88655338fe090e39a03dde5404b69802be8f3e75a98f83dea", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6514e9219e882e4c9797489508cf006f667f04b7475d7f6d8bc6f400a03a6708.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "Liruf''s guitar", "locale": "en-US", "subject": "mixed", "objectives": ["Divide 80 by different weekly amounts to calculate weeks needed", "Compare results with a 4-week deadline", "Choose the plan that reaches the goal on time"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guitar-plan", "xp": 15, "type": "savings_goal", "hints": ["Think: if you save $10 each week, in 4 weeks you''d have $40, not enough.", "With $20 each week, in 4 weeks you save $80 exactly."], "title": "Choose your plan", "payload": {"goal": 80, "currency": "USD", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf wants a guitar for $80. The contest is in 4 weeks. Which plan saves enough in time?", "difficulty": 1, "explanation_md": "With $20 each week, in 4 weeks you save exactly $80. Liruf can buy the guitar on time!", "audio_segment_id": "s1-guitar-plan.prompt"}], "schema_version": 1}', '{"s1-guitar-plan": {}}', '{"units": {"s1-guitar-plan.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9eba4ffd2d18bf63b6c01760102afe0916f9e4b889d21e7de3b4efb0b32de861.mp3", "hash": "fbf77e13f36c053478e8f5e163a4ee3eba94284864b4efa9757ff6903a5406b4", "bytes": 41184, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9eba4ffd2d18bf63b6c01760102afe0916f9e4b889d21e7de3b4efb0b32de861.mp3", "duration_ms": 6800}, "s1-guitar-plan.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d6d16a966311e601e3be1e6b15069ea42bc78dd7a0e0258a50462d7e06d5116a.mp3", "hash": "064265473b55f7c5e839f6a5a8895ff1c7614b5166907435419938759041e996", "bytes": 31104, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d6d16a966311e601e3be1e6b15069ea42bc78dd7a0e0258a50462d7e06d5116a.mp3", "duration_ms": 5120}, "s1-guitar-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/1e179786114435a21d4983a7d5831b6a87a2fb19233192115743a1381eadc5f0.mp3", "hash": "4fe167e6f9a3554238630b4a24a376d8bac1c0b1d79312269fc1155ab528a820", "bytes": 48384, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1e179786114435a21d4983a7d5831b6a87a2fb19233192115743a1381eadc5f0.mp3", "duration_ms": 8000}, "s1-guitar-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/3e670adbcdc3c4184749185931be3b2dca8cb482a378f1e217d09881b31c6d08.mp3", "hash": "7a5f477857e19df715bc185c4c3292b52818e828dfd557d2c79b189b81640132", "bytes": 50256, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3e670adbcdc3c4184749185931be3b2dca8cb482a378f1e217d09881b31c6d08.mp3", "duration_ms": 8320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Custo e lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que outros querem, e que uma meta clara (o violão de 80 reais) ajuda a começar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["Pense no que Liruf gasta para fazer a limonada (limões, açúcar). Isso é o custo.", "O que sobra depois de vender e pagar o custo é o lucro."], "title": "Custo e lucro", "payload": {"cards": [{"icon": "payments", "back_md": "O que você gasta em limões e açúcar", "front_md": "Custo", "image_url": "http://localhost:4006/files/lesson-images/586777bf0bbc7df17ea58a75433d8819756b4a9b6d49188af41827e8ca6f83e7.png"}, {"icon": "monetization_on", "back_md": "O que sobra depois de pagar o custo", "front_md": "Lucro", "image_url": "http://localhost:4006/files/lesson-images/971e629bf4c69e6762736791739f8a6a564f9d59c354e892b2ea41b2775e90c7.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toque nos cartões para descobrir o que significam ''custo'' e ''lucro''.", "difficulty": 1, "explanation_md": "O custo são os 5 reais que Liruf gasta em limões e açúcar por cada copo. O lucro é o que sobra depois de subtrair o custo.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9cce29d57b04302ed85fe5657d3063e79ce453b929160a1a9ece912f292f099b.mp3", "hash": "29e62e9877cbb9c01685bc77cba71fcc5dc45e4f4e37eb35d025411c051cc1a5", "bytes": 38736, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/9cce29d57b04302ed85fe5657d3063e79ce453b929160a1a9ece912f292f099b.mp3", "duration_ms": 6400}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3b343db8912185c4a87455ef8ab68beb3d637cb09850675c4980540bc218d293.mp3", "hash": "e5de20c820eb0912d32c1434a9435d2647a0c8ab435c8b4770318211f222003a", "bytes": 24336, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/3b343db8912185c4a87455ef8ab68beb3d637cb09850675c4980540bc218d293.mp3", "duration_ms": 4000}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/ba2e395e9eb40bc36a3046378516ca7a10a3dbb0e60262ed228bd69a52f6a7ce.mp3", "hash": "35bcee98816153f0aa8a8d4d8a38ca4f35cdaf2a3c2060c47fed7ca58e052adb", "bytes": 24336, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/ba2e395e9eb40bc36a3046378516ca7a10a3dbb0e60262ed228bd69a52f6a7ce.mp3", "duration_ms": 4000}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/d20e35d7c960d32864fa58cc21b8d5a6825ba5a738395b4871754c46c7ce690e.mp3", "hash": "776ceca44db2dc2c7b8f17a9e3bbaa6debf45aa95f901713b78378e83e95f87c", "bytes": 16704, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/d20e35d7c960d32864fa58cc21b8d5a6825ba5a738395b4871754c46c7ce690e.mp3", "duration_ms": 2720}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/d44b3c65263942d2c21f4f6c75ef8f618b42b8f92287ccfbf6c0862357d8d384.mp3", "hash": "09eeaa346378ea4ee755187d016fbd5145e9e0f6751ec3fd4459334b873557bf", "bytes": 14688, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/d44b3c65263942d2c21f4f6c75ef8f618b42b8f92287ccfbf6c0862357d8d384.mp3", "duration_ms": 2400}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/b45c150e4ea12801d2a2919a1a814a09c729c7c346d356ca51a325f7decf3146.mp3", "hash": "13ef26d74461f3fab2d87ac77850a14cdb02fd488c9fa9e88e676f86e87525a9", "bytes": 52704, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b45c150e4ea12801d2a2919a1a814a09c729c7c346d356ca51a325f7decf3146.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Emparelhar produtos e preços", "locale": "pt-BR", "subject": "mixed", "objectives": ["Emparelhar cada produto da barraca com seu preço correto (copo pequeno–5, jarra–20, biscoito–3)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["O copo pequeno custa o mesmo que uma moeda de 5 reais.", "A jarra custa 20 reais, como 4 moedas de 5."], "title": "Etiquetas embaralhadas", "payload": {"left": [{"id": "vaso", "text_md": "Copo pequeno", "image_url": "http://localhost:4006/files/lesson-images/9134b1d0911872f7c6b5559ae64fff23df8e540c3a7ac125a6f02463b553c683.png"}, {"id": "jarra", "text_md": "Jarra", "image_url": "http://localhost:4006/files/lesson-images/f98e59e6fa57afa517fcff45b4a9c6b5010a8a031f12346687496ebbcae941be.png"}, {"id": "galleta", "text_md": "Biscoito", "image_url": "http://localhost:4006/files/lesson-images/17f20c989d6b52855bbaa37ae24d42822fdce8c87eafdcd2a153d0de8379f769.png"}], "right": [{"id": "precio5", "text_md": "5 reais"}, {"id": "precio20", "text_md": "20 reais"}, {"id": "precio3", "text_md": "3 reais"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toque em cada produto e depois em seu preço para emparelhá-los.", "difficulty": 1, "explanation_md": "O copo pequeno custa 5 reais, a jarra custa 20 e o biscoito custa 3. Assim a barraca fica organizada!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "precio5"], ["jarra", "precio20"], ["galleta", "precio3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/02bc536c6e862682b97dfd4af80eec4ac88dc5bce2b9d5ad3f15fda35d1d614e.mp3", "hash": "72e95086f837a7d33f52b32c402ec72ba5002c657214a32854e8cade8abe2553", "bytes": 27216, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/02bc536c6e862682b97dfd4af80eec4ac88dc5bce2b9d5ad3f15fda35d1d614e.mp3", "duration_ms": 4480}, "s1-match-prices.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a98adbc7285f712875a4c4fe9b5ded190b7c6917ee45864dba80d03cde389d5d.mp3", "hash": "35aa91f2fcb3af133cb0ae7965eea95a0790e864cb45f3918c4804b01954b341", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a98adbc7285f712875a4c4fe9b5ded190b7c6917ee45864dba80d03cde389d5d.mp3", "duration_ms": 4080}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/f3918b1b2bc02bf7acb6161006c7cb0bb6b02848f72f9debc1045554c31e3905.mp3", "hash": "be5c1af111400d3dfcfac97b217a91c8a9e01b7d49431dba7947076d3577e551", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f3918b1b2bc02bf7acb6161006c7cb0bb6b02848f72f9debc1045554c31e3905.mp3", "duration_ms": 4400}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/cd276e466a61cc2262556b327da3ad37c45c24d8b8556b3f9c2d66d6e5e77151.mp3", "hash": "88dd253e8b1feb4637f867b8db07d08c38e58608973be5beed932c40fac14320", "bytes": 47808, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cd276e466a61cc2262556b327da3ad37c45c24d8b8556b3f9c2d66d6e5e77151.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "make-change", "title": "Dar cambio exacto", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular cambio de un billete de 20 tras comprar dos productos", "Armar el cambio con monedas de 1, 2, 5 y 10"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Suma el precio del vaso y la galleta.", "¿Cuánto te sobra del billete de 20?"], "title": "El cambio de don Beto", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/23810ba32601d8b82680cf82e5f86c8a283f3f30aed8c18658fa963de8d4a9de.png", "prompt_md": "Don Beto paga con un billete de 20. Arma el cambio exacto con las monedas.", "difficulty": 2, "explanation_md": "El vaso cuesta 5 y la galleta 3, total 8. De 20 sobran 12. Las monedas 10+2 dan 12.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/014ff30ae98e4ea9e8dbd4fbeec259eb322a3d413bbbc6e566f2d3cafd7f6a12.mp3", "hash": "882d4bdb2e7f3a2d92521d89d54ffb4327ff03b4e587f9e8b69ceb14a828550e", "bytes": 15696, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/014ff30ae98e4ea9e8dbd4fbeec259eb322a3d413bbbc6e566f2d3cafd7f6a12.mp3", "duration_ms": 2560}, "s1-make-change.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cf9ebe54077d695c986b7eda6a818602d82198c5fd68c877d55ec505e17226f8.mp3", "hash": "1f4534e83976d0fb885c785ead7f12fbabeaae205434b62eb36b962fa99736a2", "bytes": 15696, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/cf9ebe54077d695c986b7eda6a818602d82198c5fd68c877d55ec505e17226f8.mp3", "duration_ms": 2560}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/45b86eca4b6ec8fc5c16ea565b172d05d62aea5e4f468c5bb8eb915fb37f8069.mp3", "hash": "b04c6c8e072957f99191921972acf9942cc312fc66b5f1f7f7a46aa31920c84f", "bytes": 33984, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/45b86eca4b6ec8fc5c16ea565b172d05d62aea5e4f468c5bb8eb915fb37f8069.mp3", "duration_ms": 5600}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/00fc2e35d7604e33b6bd1c34775d3108d401791811126712861028fb0c6bd779.mp3", "hash": "324ceb49045b83d0fec6e37bb94997418465a33de01018292cb0a455b1d9fe18", "bytes": 55008, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/00fc2e35d7604e33b6bd1c34775d3108d401791811126712861028fb0c6bd779.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Necessidades e desejos na barraca", "locale": "pt-BR", "subject": "money", "objectives": ["Separar necessidades da barraca (limões, gelo) de desejos pessoais (picolé, gibi): a barraca vem primeiro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["Pense: sem o quê Liruf não conseguiria fazer limonada?", "A barraca precisa de coisas para fazer e vender limonada."], "title": "O que a barraca precisa?", "payload": {"items": [{"id": "item-limones", "icon": "nutrition", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/1275e2e2fdcc025953c1db0a590ea1636f7b2ac78e5e8cc40be1b7b764d6d28c.png"}, {"id": "item-hielo", "icon": "ac_unit", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/3ced258d3d17b3337109d7338b65f97f4fba774ac61a967a2a340fb14ff73511.png"}, {"id": "item-paleta", "icon": "icecream", "text_md": "Picolé", "image_url": "http://localhost:4006/files/lesson-images/9d46963ba0c49b9a217edb4fd47574dcf49e34497a464f67d5236422c0b6b20f.png"}, {"id": "item-comic", "icon": "auto_stories", "text_md": "Gibi"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Ajude Liruf a separar o que a barraca precisa do que ele deseja. Toque no que a barraca precisa para continuar vendendo.", "difficulty": 1, "explanation_md": "A barraca precisa de limões e gelo para fazer limonada. O picolé e o gibi são desejos pessoais de Liruf, não da barraca.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["item-limones", "item-hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/decf122f1e67fcf1be9621c9920595d69cb5c84e9bf2c8cfb3d1079a631d4cf7.mp3", "hash": "88c1507b0c118c6bad190ad05daae854d159dc3b404f4bb5b3c3416e57e9f84d", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/decf122f1e67fcf1be9621c9920595d69cb5c84e9bf2c8cfb3d1079a631d4cf7.mp3", "duration_ms": 4160}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2a6a710c1ff4961b816d47b853dd0aa24f1d0dff98e9dd936e4220aef6ac2578.mp3", "hash": "2f2118a7d4404cadbb171391b5988ed8c2e26b5042b4fde3858644438e854f2e", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2a6a710c1ff4961b816d47b853dd0aa24f1d0dff98e9dd936e4220aef6ac2578.mp3", "duration_ms": 3840}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/edea579c17ef49b95d0a7964cb23c69144d217a0a24cc5f74f330768d5125821.mp3", "hash": "78e7c8e8585a34d512753e0536ccd4e610c6cf210946c29737c63fe96b377719", "bytes": 47808, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/edea579c17ef49b95d0a7964cb23c69144d217a0a24cc5f74f330768d5125821.mp3", "duration_ms": 7920}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/f444226eeaf6bae97d696961e2a5d7c31eaa47c9425b4e0b3cf94a29e1f5fd98.mp3", "hash": "294b2e9dbf4bb5a480264e2e5d355242e171064c887883143c8558490036f01e", "bytes": 58464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f444226eeaf6bae97d696961e2a5d7c31eaa47c9425b4e0b3cf94a29e1f5fd98.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "dialogue-choice", "title": "Escolher o que dizer ao cliente que pede desconto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher uma resposta gentil que não abra mão do lucro quando um cliente pede desconto"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cliente-rebaja", "xp": 15, "type": "dialogue_choice", "hints": ["Pense: se você abaixar muito, ganha alguma coisa?", "Você pode ser gentil sem perder seu lucro."], "title": "Você abaixa o preço?", "payload": {"turns": [{"id": "t1", "npc_md": "Cliente: ''Me deixa por 3?''", "replies": [{"id": "r1", "text_md": "Claro, por ser você, deixo por 3."}, {"id": "r2", "text_md": "Desculpe, o preço é 5 reais. Está bem fresquinha!"}, {"id": "r3", "text_md": "Não, não posso. Se não gostou, vá embora."}]}, {"id": "t2", "npc_md": "Cliente: ''Tá bom, obrigado. Então levo uma.''", "replies": [{"id": "r4", "text_md": "Obrigado a você! Aproveite."}, {"id": "r5", "text_md": "Tem certeza? Posso te dar duas por 8 reais."}, {"id": "r6", "text_md": "Tá bom, mas se apresse."}]}], "persona": {"name": "Liruf", "role_md": "dono da barraca de limonada", "character": "liruf"}, "opening_md": "Um cliente se aproxima e diz: ''Ei, você me deixa por 3 reais? Só tenho isso!''"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/4c9b1fbf90e473b1019cb7ae4a31c6400c8299b8ca8d7b80456a95fb8fc8f449.png", "prompt_md": "Um cliente quer um copo de limonada mas pede desconto. O que você diz?", "difficulty": 2, "explanation_md": "Liruf ganha 5 reais por copo. Se ele deixar por 3, ganha só 2 reais. Melhor oferecer o mesmo preço com gentileza.", "audio_segment_id": "s1-cliente-rebaja.prompt"}], "schema_version": 1}', '{"s1-cliente-rebaja": {"turns": [{"turn_id": "t1", "qualities": {"r1": 20, "r2": 100, "r3": 10}, "reactions": {"r1": "El cliente paga 3, pero Liruf gana solo 2 pesos. No alcanza para la guitarra.", "r2": "El cliente sonríe y paga 5. ¡Liruf gana su ganancia completa!", "r3": "El cliente se va enojado. Liruf no vende nada."}}, {"turn_id": "t2", "qualities": {"r4": 100, "r5": 80, "r6": 30}, "reactions": {"r4": "El cliente se va contento. ¡Venta exitosa!", "r5": "El cliente duda, pero acepta. Liruf vende 2 vasos, gana 10 pesos.", "r6": "El cliente se siente apurado y se va sin comprar."}}]}}', '{"units": {"s1-cliente-rebaja.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6fc3e7507c392d3f299117682bbf354977a96d54c78d126fc70cbfa019f2d251.mp3", "hash": "45168e7bb0abcb596a06f260f2b4102aeb61f154be4cf00a9a209d4deb25a29d", "bytes": 24768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6fc3e7507c392d3f299117682bbf354977a96d54c78d126fc70cbfa019f2d251.mp3", "duration_ms": 4080}, "s1-cliente-rebaja.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f7f592bf3aba4ade84fc8eb860d2b99f4326012b929bfc201ccc72079a4bb443.mp3", "hash": "f2a1fc6a04cbe282d11484532293e05b1bbda3542098fe3a5f3d0702e6f0f9c1", "bytes": 19584, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f7f592bf3aba4ade84fc8eb860d2b99f4326012b929bfc201ccc72079a4bb443.mp3", "duration_ms": 3200}, "s1-cliente-rebaja.prompt": {"url": "http://localhost:4006/files/lesson-audio/ecf69bd02cd7684c312081935d4ba5db27ea7b51dce6605e426c2c78dd38b43d.mp3", "hash": "cae3ed10b640e314af5b2fd58575c4844425a092da1221bc5397cdd537cc75c3", "bytes": 33408, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ecf69bd02cd7684c312081935d4ba5db27ea7b51dce6605e426c2c78dd38b43d.mp3", "duration_ms": 5520}, "s1-cliente-rebaja.explanation": {"url": "http://localhost:4006/files/lesson-audio/36249c515ca1479f31df1a0f29a3d187d982079bf4aae8fea5d539eea4acabf9.mp3", "hash": "19eff4817ad2be34a14cafc153dfcc117c1921f570f227707dbcf01e722e500c", "bytes": 62784, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/36249c515ca1479f31df1a0f29a3d187d982079bf4aae8fea5d539eea4acabf9.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "count-objects", "title": "Count Liruf''s coins", "locale": "en-US", "subject": "mixed", "objectives": ["Count coins at a glance to know how much Liruf sold today."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta-monedas", "xp": 10, "type": "count_objects", "hints": ["Count only the coins, not the cookies or the glass.", "You can touch them one by one so you don''t get lost."], "title": "Coins on the table", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 6}, {"icon": "cookie", "tint": "accent", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "How many coins do you see?", "difficulty": 1, "explanation_md": "There are 6 coins. Each coin is a $5 glass that Liruf sold today. That adds up to 30 dollars for the $80 guitar.", "audio_segment_id": "s1-cuenta-monedas.prompt"}], "schema_version": 1}', '{"s1-cuenta-monedas": {"value": 6}}', '{"units": {"s1-cuenta-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b482c0fc241a5272a5eb91345307286cd5dfb06188db5b68675f71342ac0f786.mp3", "hash": "837ea5a5305bc71d5eda4bfe9a0813818397581c1d155fa89b60a8c9c8d8d7f0", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b482c0fc241a5272a5eb91345307286cd5dfb06188db5b68675f71342ac0f786.mp3", "duration_ms": 3120}, "s1-cuenta-monedas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/73b39cf9770ed4704d0ef9c7d384a801deeed7c167962d9e0389aac1c0e322b8.mp3", "hash": "cf31a12a62646453890143cc9d46a1bf791968883f84fcdc3d4f51d0ef1e1e04", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/73b39cf9770ed4704d0ef9c7d384a801deeed7c167962d9e0389aac1c0e322b8.mp3", "duration_ms": 2880}, "s1-cuenta-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/c22eeec883ac6ba1679ce23c713d7f8e0d16e80569f96fa398fd6d855c96e89a.mp3", "hash": "b9f6c9914401dd991dea972252b126022556a9cfca5367d566fae7f568d1d0b2", "bytes": 8496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c22eeec883ac6ba1679ce23c713d7f8e0d16e80569f96fa398fd6d855c96e89a.mp3", "duration_ms": 1360}, "s1-cuenta-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/5e2e55ffbd48ad9177164e4c57d9f306beb79a00f65c52cd80c27dfa3ff9885d.mp3", "hash": "3d7145a0877970ce50afc920351a66dbe18c6206b149dbe741b3579153b7ac14", "bytes": 45936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5e2e55ffbd48ad9177164e4c57d9f306beb79a00f65c52cd80c27dfa3ff9885d.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "O violão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Dividir 80 por diferentes quantidades semanais para calcular semanas necessárias", "Comparar resultados com um prazo de 4 semanas", "Escolher o plano que atinge a meta a tempo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guitar-plan", "xp": 15, "type": "savings_goal", "hints": ["Pense: se você economizar R$10 a cada semana, em 4 semanas teria R$40, não é suficiente.", "Com R$20 a cada semana, em 4 semanas você junta R$80 exato."], "title": "Escolha seu plano", "payload": {"goal": 80, "currency": "BRL", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf quer um violão de R$80. O concurso é em 4 semanas. Qual plano economiza o suficiente a tempo?", "difficulty": 1, "explanation_md": "Com R$20 a cada semana, em 4 semanas você junta exatamente R$80. Liruf pode comprar o violão a tempo!", "audio_segment_id": "s1-guitar-plan.prompt"}], "schema_version": 1}', '{"s1-guitar-plan": {}}', '{"units": {"s1-guitar-plan.hint.0": {"url": "http://localhost:4006/files/lesson-audio/36b1b554bf6e0e99a0b12c8799a4b9ebce0aab6bb6fa0282ab9d05a13bec51ba.mp3", "hash": "741709e3f5072fa512a847082e2957512ea320a18ef88ad33f036f631739e01b", "bytes": 47808, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/36b1b554bf6e0e99a0b12c8799a4b9ebce0aab6bb6fa0282ab9d05a13bec51ba.mp3", "duration_ms": 7920}, "s1-guitar-plan.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a76bcc657160a068c73c199b84a574213067df219e578927e46852864a65ce6e.mp3", "hash": "a729a285ac79e15e9281e39566aecd88bb5b5d93ce9ee7dc6bd1fe735e8bfd4f", "bytes": 40608, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a76bcc657160a068c73c199b84a574213067df219e578927e46852864a65ce6e.mp3", "duration_ms": 6720}, "s1-guitar-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/58f439c95eed253836f66a4d0ac9327ca26de66c131f68387ae7094fda314f5e.mp3", "hash": "b1fe929238de4f78c21652e20e09eaecc959b69bc8eb24ffb70f0456e5697ab3", "bytes": 52704, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/58f439c95eed253836f66a4d0ac9327ca26de66c131f68387ae7094fda314f5e.mp3", "duration_ms": 8720}, "s1-guitar-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/e19702681e5866004d9e777ffe06e5c23594a4cfd68e8a4603f9b1f9973c6a01.mp3", "hash": "94a9f8365d0183f87281be4cda52db3894aa771017bb87e3bf5b4d59ffa6934d", "bytes": 60336, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e19702681e5866004d9e777ffe06e5c23594a4cfd68e8a4603f9b1f9973c6a01.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "The savings line", "locale": "en-US", "subject": "mixed", "objectives": ["Place amounts on a number line from 0 to 100", "Identify how much is needed to reach a savings goal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 10, "type": "number_line", "hints": ["Liruf''s savings are closer to 0 than to 100.", "Count by 10s from 0: 10, 20..."], "title": "Where is Liruf?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": true}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Move the marker to where Liruf''s savings are: 20 dollars.", "difficulty": 1, "explanation_md": "Liruf has 20 dollars saved. On the line, 20 is two jumps of 10 from 0.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6c18cb32a72a3e40194d28f606269529801a903e1b90d7bb645ea0d559fa76b3.mp3", "hash": "d1c1e87225b32a66176f0b8ae91b38b3adb674bfd59f48bb3ee3192e1f9a3dd3", "bytes": 24768, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6c18cb32a72a3e40194d28f606269529801a903e1b90d7bb645ea0d559fa76b3.mp3", "duration_ms": 4080}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e82032c93143933e4b698950396c6dbf450e83bdfa99839ace36ccf029a3753f.mp3", "hash": "d5f36e754bdc61eff8960b5e549ec00e02e732ff8954f2e5c7b809f0ebdd1616", "bytes": 24336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/e82032c93143933e4b698950396c6dbf450e83bdfa99839ace36ccf029a3753f.mp3", "duration_ms": 4000}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/846b00bf0628af1696c34ffddaafde7530751a26ac3b1a71ba486b57ee363769.mp3", "hash": "9f358b317e09f859a7b4036cf15224c2c8f5caf78f72b9d2f33ae95b714da8c0", "bytes": 24336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/846b00bf0628af1696c34ffddaafde7530751a26ac3b1a71ba486b57ee363769.mp3", "duration_ms": 4000}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/8e7f3d78b6888f834a29fe9ae73f34eef95c1533222f20c89d3e2044daffb4b5.mp3", "hash": "2fb3a9ba52e37577d25e1f06290fc7d020c2052dea19366ed3de371fdeaede88", "bytes": 38736, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/8e7f3d78b6888f834a29fe9ae73f34eef95c1533222f20c89d3e2044daffb4b5.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "Un día real del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "title": "Sábado soleado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/6b0f434c15877511fb8d9b240ecb38496c8db9ae5306bffbf8df03337976bd17.png"}, "action": "idle", "body_md": "Es sábado por la mañana. El sol brilla y Liruf ha preparado una jarra grande de limonada. Ya hay tres clientes esperando. ¡Es hora de decidir el precio de hoy!", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Liruf abre su puesto de limonada. ¡Ya hay fila de clientes!", "difficulty": 1, "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-precio-del-dia", "xp": 15, "type": "quiz_mcq", "hints": ["Piensa en un precio que sea justo para los clientes y que le dé ganancias a Liruf.", "Recuerda que hacer limonada cuesta dinero: limones, azúcar, vasos."], "title": "Precio del día", "payload": {"options": [{"id": "a", "text_md": "2 pesos", "rationale_md": "2 pesos es muy poco. Liruf no ganaría suficiente para comprar más limones."}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos", "rationale_md": "10 pesos es muy caro. Los clientes podrían irse a otro puesto."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "¿Cuánto cobrará Liruf por cada vaso de limonada hoy?", "difficulty": 2, "explanation_md": "Liruf decide cobrar 5 pesos por vaso, el mismo precio de siempre. Así los clientes saben qué esperar y Liruf cubre sus costos.", "audio_segment_id": "s2-precio-del-dia.prompt"}], "schema_version": 1}', '{"s2-precio-del-dia": {"correct_option_id": "b"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/05bc9ab4d2674228845ba37ae8a015e3ee56ffc53eb839b27e0990d0515266b7.mp3", "hash": "7ce56d113361efb83e3d47240575a9b56edf78664491587eb63e5e7bc5c053ff", "bytes": 66096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/05bc9ab4d2674228845ba37ae8a015e3ee56ffc53eb839b27e0990d0515266b7.mp3", "duration_ms": 10960}, "s2-precio-del-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b136a695c51fb0c2feb1d102b36866453e2dcf93a85702e1dcba428dc92776c9.mp3", "hash": "0e43376df19bcfb8e0039d34fe18ed821539ea4d1a20c1c5c7320060d65ee335", "bytes": 32544, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b136a695c51fb0c2feb1d102b36866453e2dcf93a85702e1dcba428dc92776c9.mp3", "duration_ms": 5360}, "s2-precio-del-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fe68c3045343441e38adc1e80229975c490e27d140c2d980fc787d9f42af8ed1.mp3", "hash": "f1f63b80c8133c41a0dc862fb93feef62655e100bee5ef3160583c665673f4d2", "bytes": 34416, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fe68c3045343441e38adc1e80229975c490e27d140c2d980fc787d9f42af8ed1.mp3", "duration_ms": 5680}, "s2-precio-del-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/1710873dc728502ea0b1b6bde29e16f30161f8ac6cddeb9aa116b9873d455efc.mp3", "hash": "026196f621854cd9ca63558eb0d911287ebcda00dfb1151d34fdd8151e528b7a", "bytes": 28224, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/1710873dc728502ea0b1b6bde29e16f30161f8ac6cddeb9aa116b9873d455efc.mp3", "duration_ms": 4640}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/1cdae65f1d4078250dc61726b47a1ca03801e549af7f5583eb260b8ecf5a1087.mp3", "hash": "118ff83265d4f0828ec9c2cc7354896762b041684269c5d4c4073ffab6be8e57", "bytes": 28656, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/1cdae65f1d4078250dc61726b47a1ca03801e549af7f5583eb260b8ecf5a1087.mp3", "duration_ms": 4720}, "s2-precio-del-dia.choices": {"url": "http://localhost:4006/files/lesson-audio/bbc1c79aae6ce1958576f658b274eecd12f3e9b5d0bfd2d3d9013efcc10f66f7.mp3", "hash": "abb544f69bc3aad9ec8c28ad2ddcc846562f63ce039a199bac511daa39653af5", "bytes": 21456, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/bbc1c79aae6ce1958576f658b274eecd12f3e9b5d0bfd2d3d9013efcc10f66f7.mp3", "duration_ms": 3520}, "s2-precio-del-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/6d7dc3c8ccdf83ddb26399207c7960a5b17eed5321f2cdef3e64da50dfecf210.mp3", "hash": "20248a5f99e45eca9fe0bcbbf528f8c28976220d9e25e7705e5d1ad110933902", "bytes": 52128, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6d7dc3c8ccdf83ddb26399207c7960a5b17eed5321f2cdef3e64da50dfecf210.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Ordena el día de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar los pasos del día de venta en orden cronológico"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 15, "type": "timeline_order", "hints": ["¿Qué haces primero al llegar al puesto?", "Piensa: antes de vender, hay que preparar."], "title": "El día de Liruf", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Comprar limones y azúcar", "image_url": "http://localhost:4006/files/lesson-images/6e34fbc8d65fcb71a33a775dea3a30907a0e675709c6af02f62f5d44908376b8.png"}, {"id": "preparar", "icon": "local_drink", "text_md": "Preparar la limonada", "image_url": "http://localhost:4006/files/lesson-images/01bc7713d51db561e721d2dde76b74e9a9c6cdc15f74acff596e5f0f0f87f271.png"}, {"id": "vender", "icon": "storefront", "text_md": "Vender vasos al mediodía", "image_url": "http://localhost:4006/files/lesson-images/335ae04858aef88f0d7ca7d0a0e6126298280e077500c73c17fc0ad8edd78e89.png"}, {"id": "contar", "icon": "payments", "text_md": "Contar dinero y guardar", "image_url": "http://localhost:4006/files/lesson-images/cefe10e90af7e4344746e1b2776e88b488de4759547d052c9beb06be522187ab.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Toca los eventos en orden, de la mañana al cierre.", "difficulty": 2, "explanation_md": "Liruf compra ingredientes temprano, luego prepara la limonada, vende al mediodía y al final cuenta el dinero y guarda.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e0b91488894290324777bc1ffda4d77f41b973598b5b84128bc96900d5ffd1a9.mp3", "hash": "3b2211c7e19be39108b543ecf0c81a8e1ea00d32723a3add89ee2e021d6d73f4", "bytes": 12816, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e0b91488894290324777bc1ffda4d77f41b973598b5b84128bc96900d5ffd1a9.mp3", "duration_ms": 2080}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/dcdd4969ad2aab176d8a98235ccd5c006b02c03520d050c4fca1ee47bff4da04.mp3", "hash": "01e053abe9d027c18b7a2e37e52673c553db0489ab792f8303aed8631dbcd28c", "bytes": 21888, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/dcdd4969ad2aab176d8a98235ccd5c006b02c03520d050c4fca1ee47bff4da04.mp3", "duration_ms": 3600}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/e4496e191b0b9a62e8680b27b0cee47246c01153c6495ecc1186c694f96b7151.mp3", "hash": "96626a0c93549823b7b8086b8e9e6fd34afc84f2577a6b0456b872e597a0dc3a", "bytes": 21456, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e4496e191b0b9a62e8680b27b0cee47246c01153c6495ecc1186c694f96b7151.mp3", "duration_ms": 3520}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/e11f431f9f7f20c056acf1411ba9b4add9e7eea0747ce8fa8f282730fc1dc550.mp3", "hash": "d60f8c57a07009b0db3d5ea1036d2bc5de585ba0c872ff87344e8d8007a7f0ee", "bytes": 48384, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e11f431f9f7f20c056acf1411ba9b4add9e7eea0747ce8fa8f282730fc1dc550.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "pattern-complete", "title": "La escalera de precios", "locale": "es-MX", "subject": "money", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Observa el patrón: chico, mediano, grande, chico, mediano... ¿qué tamaño viene después de mediano?", "Cada tamaño cuesta más que el anterior. El que sigue debe costar más que $10."], "title": "¿Qué vaso sigue?", "payload": {"options": [{"id": "chico", "icon": "local_drink", "tint": "primary"}, {"id": "mediano", "icon": "local_drink", "tint": "accent"}, {"id": "grande", "icon": "local_drink", "tint": "success"}, {"id": "limon", "icon": "nutrition", "tint": "primary"}], "sequence": [{"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}, {"icon": "local_drink", "tint": "success"}, {"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Los precios: chico $5, mediano $10, grande $15. ¿Qué vaso va en el hueco?", "difficulty": 2, "explanation_md": "El patrón sube de precio: chico $5, mediano $10, grande $15, y vuelve a empezar. Después de mediano ($10) viene grande ($15).", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "grande"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d70f7a12bbad0bd510b481eb87bd788fb4ed6d22fed4f29a1501a75fbd06b841.mp3", "hash": "e66feffbea2fedfd229d2a7b68cba63ff779c55788a73303f45a4fb306275017", "bytes": 40176, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d70f7a12bbad0bd510b481eb87bd788fb4ed6d22fed4f29a1501a75fbd06b841.mp3", "duration_ms": 6640}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b63e99bc1e9ac953c5bf76bf0d9e8bcc216664300ecfaa572097f3ec85df0301.mp3", "hash": "345c93ebe6f4d2cf6e6263647856a1664842596a90f51036333c65914b64db8f", "bytes": 31968, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b63e99bc1e9ac953c5bf76bf0d9e8bcc216664300ecfaa572097f3ec85df0301.mp3", "duration_ms": 5280}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/75f87d55a14476c54e3b9ba82feda4ab2214407142aaa639d9a9cf60a3da532a.mp3", "hash": "fde2dfc45f61e48a90d26c1c5608de5fbafc53b9bbdee6dc214b5926cf110d83", "bytes": 40176, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/75f87d55a14476c54e3b9ba82feda4ab2214407142aaa639d9a9cf60a3da532a.mp3", "duration_ms": 6640}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/45a8d242c926b1e99103257adda70f302b3deed2035d9c6e46dff5cc6fa5e49d.mp3", "hash": "9d8c09fb04b93dc0a8ecde995562fd16b23fd05f63b606045d2208af69dcace8", "bytes": 67968, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/45a8d242c926b1e99103257adda70f302b3deed2035d9c6e46dff5cc6fa5e49d.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Um dia real da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ouvir dois clientes conversando sobre a limonada e responder duas perguntas seguidas: uma de certo/falso e uma com imagens."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo-clientes", "xp": 0, "type": "story_dialogue", "title": "Vizinhos opinam", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Nossa, a limonada do Liruf é bem gostosa. E só custa 5 reais o copo.", "character": "rho"}, {"action": "idle", "emotion": "surprised", "text_md": "5 reais? Que barato! Na loja da esquina custa 8.", "character": "zara"}, {"action": "idle", "emotion": "happy", "text_md": "Sim, e o Liruf sempre coloca muito gelo. Vou comprar dois copos.", "character": "rho"}, {"action": "idle", "emotion": "thinking", "text_md": "Eu também. Com 10 reais dá para dois.", "character": "zara"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/74229a83515b3b18efc3c40656ef1fd0d059bfd893cee80a942f2a63ac8bfa82.png", "prompt_md": "Ouça o que os vizinhos dizem sobre a barraca de limonada.", "difficulty": 1, "audio_segment_id": "s1-dialogo-clientes.prompt"}, {"id": "s2-precio-verdadero", "xp": 10, "type": "true_false", "title": "Certo ou falso?", "payload": {"statement_md": "A limonada do Liruf custa 5 reais o copo.", "justifications": [{"id": "j1", "text_md": "Rho disse que custa 5 reais e Zara disse que é barato."}, {"id": "j2", "text_md": "Zara disse que custa 8 reais na loja."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Segundo a conversa, a limonada custa 5 reais?", "difficulty": 1, "explanation_md": "Rho disse ''só custa 5 reais o copo'', então é verdade. Zara comparou com outro preço de 8 reais, mas esse não é o da barraca.", "audio_segment_id": "s2-precio-verdadero.prompt"}, {"id": "s3-cuantos-vasos", "xp": 10, "type": "picture_choice", "title": "Quantos copos?", "payload": {"options": [{"id": "opt1", "icon": "local_cafe", "label": "1 copo", "image_url": "http://localhost:4006/files/lesson-images/46af6d772b221291dd17d00534ad529312329e6f3b728983bf69cc21cfbbc59e.png", "rationale_md": "Com 10 reais você pode comprar mais de um copo se cada um custa 5."}, {"id": "opt2", "icon": "local_cafe", "label": "2 copos", "image_url": "http://localhost:4006/files/lesson-images/b8e5fb42eda0d4386c70f5b92af914dbf372391b78e1429e39eac054b1800e45.png"}, {"id": "opt3", "icon": "local_cafe", "label": "3 copos", "image_url": "http://localhost:4006/files/lesson-images/b9545f1c5a103a448519b501774aa653b64fcb71113bda1c8a87e8b7e8fa2efd.png", "rationale_md": "Com 10 reais não dá para 3 copos porque 3×5=15, e você só tem 10."}]}, "narrator": {"emotion": "encouraging", "character": "liruf"}, "prompt_md": "Zara tem 10 reais. Quantos copos de limonada ela pode comprar se cada um custa 5 reais?", "difficulty": 1, "explanation_md": "Cada copo custa 5 reais. Com 10 reais você pode comprar 2 copos porque 5+5=10.", "audio_segment_id": "s3-cuantos-vasos.prompt"}], "schema_version": 1}', '{"s3-cuantos-vasos": {"correct_option_id": "opt2"}, "s2-precio-verdadero": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s3-cuantos-vasos.prompt": {"url": "http://localhost:4006/files/lesson-audio/feb0f50918abfa52c6ea26fac67b3f13d0e640fb35380848549a3ad8ff85c941.mp3", "hash": "4e6bbe7dc801ab41bd2dc0bdeb014beb1ae9cb24d2c14662bcdff40e551ffc84", "bytes": 38736, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/feb0f50918abfa52c6ea26fac67b3f13d0e640fb35380848549a3ad8ff85c941.mp3", "duration_ms": 6400}, "s3-cuantos-vasos.choices": {"url": "http://localhost:4006/files/lesson-audio/7278721608fd1baa21423cd46d7796bd10ddb496e2651a06599b823ab4bb3793.mp3", "hash": "e9defd9027c23408e5b03c74b166096db489841e4399ea475702fe03d9a1c5de", "bytes": 18576, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7278721608fd1baa21423cd46d7796bd10ddb496e2651a06599b823ab4bb3793.mp3", "duration_ms": 3040}, "s1-dialogo-clientes.line.0": {"url": "http://localhost:4006/files/lesson-audio/2715c1ce27fd886f43e0e846f4d9f8662954b1f25bd2cd4436e8a0895f91f186.mp3", "hash": "936712069f93f22dd901e59369df44ad1362b46bf3f77e723d9faeb49cbb0b67", "bytes": 42624, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2715c1ce27fd886f43e0e846f4d9f8662954b1f25bd2cd4436e8a0895f91f186.mp3", "duration_ms": 7040}, "s1-dialogo-clientes.line.1": {"url": "http://localhost:4006/files/lesson-audio/07f43528e8b2ceca2b0831acb812d2550398c6376af35a7372bd3b5893317c84.mp3", "hash": "800547a7d6c5eda839c0c2e65643b043f1fb21d43bf769a9b9d33f2dcb40b4b7", "bytes": 30528, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/07f43528e8b2ceca2b0831acb812d2550398c6376af35a7372bd3b5893317c84.mp3", "duration_ms": 5040}, "s1-dialogo-clientes.line.2": {"url": "http://localhost:4006/files/lesson-audio/ab5fd92cd3908764ca1016fa1526338ade5f1022be371bece87cca9a6fcd22d6.mp3", "hash": "e116ac1f98adfbd790797aa42ee437037bd1c003feb2ad56fea11f278418b47e", "bytes": 35856, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/ab5fd92cd3908764ca1016fa1526338ade5f1022be371bece87cca9a6fcd22d6.mp3", "duration_ms": 5920}, "s1-dialogo-clientes.line.3": {"url": "http://localhost:4006/files/lesson-audio/8c925df2f0135916b0eab1b2c2c2ae99f0bcf1118dfd442a6ba1515016f29abb.mp3", "hash": "b27c9a8d0386a0d13d3c931ee25252c67ac40c9f738c97ca0df67129513e7ddb", "bytes": 21024, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8c925df2f0135916b0eab1b2c2c2ae99f0bcf1118dfd442a6ba1515016f29abb.mp3", "duration_ms": 3440}, "s1-dialogo-clientes.prompt": {"url": "http://localhost:4006/files/lesson-audio/5187d911b4a82f0703c72e5af4c90d5f3636b74ac1df036162764e36a9252cbf.mp3", "hash": "e62673481281ab1539d69c33c1bc963a69ebe058d1db7f3fc134ba77f2a79b1f", "bytes": 22464, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5187d911b4a82f0703c72e5af4c90d5f3636b74ac1df036162764e36a9252cbf.mp3", "duration_ms": 3680}, "s2-precio-verdadero.prompt": {"url": "http://localhost:4006/files/lesson-audio/23004de0444cbc42e09990cf3dba85ae589ad10a37272045b2f35540f670ab03.mp3", "hash": "40177e65ce6523b5960b9ff446e96ceedd7ad964f7dc37d0a8a5e5708937ca35", "bytes": 22896, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/23004de0444cbc42e09990cf3dba85ae589ad10a37272045b2f35540f670ab03.mp3", "duration_ms": 3760}, "s3-cuantos-vasos.explanation": {"url": "http://localhost:4006/files/lesson-audio/de48be4ef2d27b7feeec806351d7f40ea2486b90561f26ff6ad1b202c739c7cc.mp3", "hash": "b56ace98d3a532ddbc8f9eda9ac60d3014c0c3b3ba39879bdda22a00214a48c1", "bytes": 45504, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/de48be4ef2d27b7feeec806351d7f40ea2486b90561f26ff6ad1b202c739c7cc.mp3", "duration_ms": 7520}, "s2-precio-verdadero.explanation": {"url": "http://localhost:4006/files/lesson-audio/4242a5ba2947eb1f389349198eebe32e20d91fb2b1f2c75c828c90d399ceea92.mp3", "hash": "a40ab6473d6cfa17f476a2978ff2378111473a1b46653023e8c410893d8e008f", "bytes": 61776, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4242a5ba2947eb1f389349198eebe32e20d91fb2b1f2c75c828c90d399ceea92.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "speed-tap", "title": "Decisiones rápidas de limonada", "locale": "es-MX", "subject": "money", "objectives": ["Distinguir gastos que ayudan al puesto de limonada de caprichos que no ayudan."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 10, "type": "speed_tap", "hints": ["Piensa: ¿esto ayuda a hacer o vender limonada?", "Los caprichos como juguetes no ayudan a vender."], "title": "¡Atrapa lo que ayuda!", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/44fba0b1ddd0ebb2b8483f774d3b4b7457cc547c21ae4c9c6d934b67c18f6ad0.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/e70143f1ac5ee53250ff7898efca3a47aa0041b02633636d1793edc224cc17ec.png"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/e3b3b4b8173084e591ade5a91ab296ffbc558befc204f0cc8d3b354ee8d26e30.png"}, {"id": "hielo", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/3ac94a7a0e561ed4b05893a6ab97e9e5f50d5b9aa1ce0fe1d7da9756aecaf47f.png"}, {"id": "cartel", "text_md": "Cartel llamativo", "image_url": "http://localhost:4006/files/lesson-images/bd3fbd5baf4f09ba19518826ce31a6af9b610c262ab0381fb5697b14e62de799.png"}, {"id": "calcomania", "text_md": "Calcomanía de dinosaurio"}, {"id": "dulce", "text_md": "Dulce", "image_url": "http://localhost:4006/files/lesson-images/83da2ff7ee850d1eefece86e657b52c9b1155098395247d0bd7bb6e158ac70ab.png"}, {"id": "juguete", "text_md": "Juguetito", "image_url": "http://localhost:4006/files/lesson-images/30bcd760187a7ef0c954d00a0b9d069340d411222739df6004bd718e22c45f8e.png"}], "seconds": 15, "instruction_md": "Toca las tarjetas que ayudan al puesto de limonada."}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho pasa volando tarjetas. Toca solo las que ayudan a vender más limonada.", "difficulty": 1, "explanation_md": "Los limones, vasos, azúcar, hielo y cartel ayudan a vender más limonada. La calcomanía, el dulce y el juguete son caprichos que no ayudan.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f5cce4789ab5a0348bfbc8ad55404d1d063d835d6c83457efad99c909d444317.mp3", "hash": "b74c6a35b9c21ba38793887f8364602e372009ad7af6ed37f22293a99f7ea736", "bytes": 23328, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f5cce4789ab5a0348bfbc8ad55404d1d063d835d6c83457efad99c909d444317.mp3", "duration_ms": 3840}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ff68c47241a7b7697dd2d9488b969cd2c60915c27916ae1bf145e3f7591b228a.mp3", "hash": "c1f7f757e83437325777aece1a2b8e49f98fa484b575c17a036bfa3d9bcde96d", "bytes": 21024, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/ff68c47241a7b7697dd2d9488b969cd2c60915c27916ae1bf145e3f7591b228a.mp3", "duration_ms": 3440}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/9309dc5354789b6243bee3f3c391d1303e86acd194448e6ece1e753dd25096f3.mp3", "hash": "e009fd984547a77ef588395f3a69f55c2d541c3d2487543a169a4aea1c5c6401", "bytes": 35856, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9309dc5354789b6243bee3f3c391d1303e86acd194448e6ece1e753dd25096f3.mp3", "duration_ms": 5920}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/c5fb3c0db919ae100c89ee8970fac74af34dbbff02df62fbdfb232fa48ea5d6e.mp3", "hash": "c2a0a3654a4afdaf29f71d179640e66236680757b69ed3156a529c800ffe9754", "bytes": 70848, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/c5fb3c0db919ae100c89ee8970fac74af34dbbff02df62fbdfb232fa48ea5d6e.mp3", "duration_ms": 11760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classify the stand''s purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Sort the day''s purchases into two buckets: NEED for the stand (lemons, cups) or WANT that can wait (stickers, balloons)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Think: without this, can the stand not sell lemonade?", "Lemons and cups run out quickly. Stickers and balloons are for decoration."], "title": "Need or want", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/11d41dd8ef963c5f212956a3a0c3735cec5f9561d9231393d31d3ae2c22cd0d6.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/9f5beaa61380bcb0e56849081b8bd24d108cfccacb837323436c0550a64419a9.png"}, {"id": "stickers", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/ca906abc477d46e8333bc121cbdc9c42e783f4e02396c473719944540726ab32.png"}, {"id": "globos", "text_md": "Balloons", "image_url": "http://localhost:4006/files/lesson-images/462588077ce15682d4ff7a6659f54a5537292dc7b54dba0a73bd219c3fccedaf.png"}], "buckets": [{"id": "necesidad", "label": "NEED for the stand"}, {"id": "gusto", "label": "WANT that can wait"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Touch each item and put it in the correct bucket: what the stand NEEDS today, or a WANT that can wait.", "difficulty": 1, "explanation_md": "The stand needs lemons and cups to sell lemonade. Stickers and balloons are wants that can wait for another day.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/10dc3d6b8ddf5f9d42bed39663d96fb8dbe7b2e65883beb664ef914156359513.mp3", "hash": "df468a552a0031a96f0423745388c126c04477636cc2bd8eea57dc17b52e20fc", "bytes": 20448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/10dc3d6b8ddf5f9d42bed39663d96fb8dbe7b2e65883beb664ef914156359513.mp3", "duration_ms": 3360}, "s1-sort-buckets.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e19f77f05c564bd680e2d8c9853f98f49a02581d0aec8f814ba087cedc07f9ba.mp3", "hash": "d6204af6fb383bae9815f821af1723b4c3f427fe900b725f6692a4ba9a63e017", "bytes": 26784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e19f77f05c564bd680e2d8c9853f98f49a02581d0aec8f814ba087cedc07f9ba.mp3", "duration_ms": 4400}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/f55b79940131f0991f21edda41c4bc13a19bb4eb79ef9252142ac3468283e6df.mp3", "hash": "e37a1f41c09bd64691372f6a6721a2f6e83b9bb215edda5aaeb65df120ab4be9", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f55b79940131f0991f21edda41c4bc13a19bb4eb79ef9252142ac3468283e6df.mp3", "duration_ms": 5840}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/1f56f7a9c4b665e1c814ad34e0834dcd3eb26ffe2a33c8ca6d7b1578f21fc9f8.mp3", "hash": "f634fc141e9a42725afcf84d3e36b3d5a82830b580b223e500ff2980674cd4e2", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1f56f7a9c4b665e1c814ad34e0834dcd3eb26ffe2a33c8ca6d7b1578f21fc9f8.mp3", "duration_ms": 5920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "Viver o posto em histórias jogáveis", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o preço da limonada considerando o custo e o lucro", "Observar como cada decisão afeta o progresso em direção à meta de economia"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-limonada", "xp": 20, "type": "story_branch", "hints": ["Pense: se cobrar muito caro, talvez não comprem. Se cobrar muito barato, ganha pouco por copo.", "Lembre-se que sua meta é juntar R$80 para o violão."], "title": "Escolha o preço de hoje", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "R$5 (o preço de sempre)"}, {"id": "precio3", "next": "final3", "text_md": "R$3 (mais barato)"}, {"id": "precio10", "next": "final10", "text_md": "R$10 (o dobro)"}], "emotion": "thinking", "text_md": "É meio-dia e está um calorão! Seis vizinhos fazem fila no seu posto de limonada. Você decide o preço de cada copo. Cada copo custa R$2 para fazer. Quanto você cobra?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "Fim"}], "emotion": "happy", "text_md": "Os 6 vizinhos compram! Cada copo te dá R$3 de lucro (5 - 2 = 3). No total, você ganhou R$18. Bom progresso em direção ao violão de R$80!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "Fim"}], "emotion": "thinking", "text_md": "Estão vendendo como água! Mas cada copo só te dá R$1 de lucro (3 - 2 = 1). No total, você ganhou apenas R$6. Quase não avança em direção ao violão…", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "Fim"}], "emotion": "surprised", "text_md": "Os vizinhos fazem careta e vão para a sorveteria. Você não vendeu nenhum copo. Ganhou R$0 e fica com a jarra cheia. O violão parece muito distante…", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8b4d9abc72273f8d5e2b18089135da35b5e60c11c06e2256db93446551f109fd.png", "prompt_md": "Está calor e 6 vizinhos esperam limonada. Cada copo custa R$2 para fazer. A que preço você vende cada copo?", "difficulty": 2, "explanation_md": "Liruf escolheu um preço e viu quanto avançou em direção ao violão de R$80.", "audio_segment_id": "s1-precio-limonada.prompt"}], "schema_version": 1}', '{"s1-precio-limonada": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-limonada.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3f296bef6f2796b4b6efe271938eee86042fecd8a4887bbad8bd5e2c72ed11b.mp3", "hash": "b27d59080add513defebaba7296380997fc256e7df9fca3523c4aa413bc61c10", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b3f296bef6f2796b4b6efe271938eee86042fecd8a4887bbad8bd5e2c72ed11b.mp3", "duration_ms": 7200}, "s1-precio-limonada.hint.1": {"url": "http://localhost:4006/files/lesson-audio/510f5b9d344ab5160784bdb6692150d366a9217b955f8c96eea3cae4a2df13d5.mp3", "hash": "4960788699b3d31cd4ed2bf8d083b57387228ede4943177087e90c5b64af3055", "bytes": 27648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/510f5b9d344ab5160784bdb6692150d366a9217b955f8c96eea3cae4a2df13d5.mp3", "duration_ms": 4560}, "s1-precio-limonada.prompt": {"url": "http://localhost:4006/files/lesson-audio/3b0b9ff2689f1e438364fa69a794127fff888507d19c0e63a3c46fb6b022482d.mp3", "hash": "4a37fd14506bdbfafff1c9a7de261c626620e832723a1fce5fe9b63e78f1b23c", "bytes": 56016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3b0b9ff2689f1e438364fa69a794127fff888507d19c0e63a3c46fb6b022482d.mp3", "duration_ms": 9280}, "s1-precio-limonada.explanation": {"url": "http://localhost:4006/files/lesson-audio/5f213d7790c27bf304a14880034a65cf3f6062dc23210951c4ac0d2e12aead89.mp3", "hash": "2d2f9303e3886d7893e10bf1b8ced98211b625fa7968d602dcea635c5542512f", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5f213d7790c27bf304a14880034a65cf3f6062dc23210951c4ac0d2e12aead89.mp3", "duration_ms": 5440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Clasifica las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Clasificar las compras del día en dos cubetas: NECESIDAD del puesto (limones, vasos) o GUSTO que puede esperar (stickers, globos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Piensa: ¿sin esto el puesto no puede vender limonada?", "Los limones y los vasos se acaban rápido. Los stickers y globos son para decorar."], "title": "Necesidad o gusto", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/b282bd403c26ab10db070434bd0ead824a8725c9a44b29c6945522f5d9be8058.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/169e9d722f49a900bb62c5d219f539b9d8d1efb046c3bc6b4f1d332263edf5e5.png"}, {"id": "stickers", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/ac5f9d882ba0d7e3eac68a879c69954509552b017d8b2cccef0f320399266ff4.png"}, {"id": "globos", "text_md": "Globos", "image_url": "http://localhost:4006/files/lesson-images/18cbcec7743476140b820bdcc586578fecd25794d4163396ad4b7bb0cda9aebb.png"}], "buckets": [{"id": "necesidad", "label": "NECESIDAD del puesto"}, {"id": "gusto", "label": "GUSTO que puede esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toca cada cosa y ponla en la cubeta correcta: lo que el puesto NECESITA hoy, o un GUSTO que puede esperar.", "difficulty": 1, "explanation_md": "El puesto necesita limones y vasos para vender limonada. Los stickers y globos son gustos que pueden esperar a otro día.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/de2a32a80c77234e8914e119f4b2b3c277b5755d654bb3655f50b9488473c800.mp3", "hash": "95bcac6e1af2fe82c453ea7e173b355b96e1468e24080de9644cc2679c27a8ab", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/de2a32a80c77234e8914e119f4b2b3c277b5755d654bb3655f50b9488473c800.mp3", "duration_ms": 3920}, "s1-sort-buckets.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5986a7de14a3062007c785d530abbc3d1b2026853b18db7b2500f311daaaceba.mp3", "hash": "ec93e53ec004db57c754513c2904eac90d752557cf9820c90786a918787be9a7", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5986a7de14a3062007c785d530abbc3d1b2026853b18db7b2500f311daaaceba.mp3", "duration_ms": 6400}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/aef2498c31d1c568525ba2f91100c1fa56554653624f000e50186a5b0a7971c0.mp3", "hash": "133f354dc36f020cee68bed03d0845e8eb5f5228db2f08b39a83bc38f61d8d5f", "bytes": 42048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/aef2498c31d1c568525ba2f91100c1fa56554653624f000e50186a5b0a7971c0.mp3", "duration_ms": 6960}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/99e5b9a7e163754d02d710940fea334715fee2aadb0301bf0e42c9be7d9120f6.mp3", "hash": "19db466497e899e20a7c327c0292fea45e752f64378ba4bedd39c66dda8c9979", "bytes": 48816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/99e5b9a7e163754d02d710940fea334715fee2aadb0301bf0e42c9be7d9120f6.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "La mejor decisión de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir la mejor decisión cuando un cliente paga con billete de 20 por un vaso de 5: contar el cambio con calma."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cambio-correcto", "xp": 10, "type": "best_decision", "hints": ["El vaso cuesta 5 pesos. Si le pagan con 20, ¿cuánto tiene que devolver?", "Cuenta el cambio despacio para no equivocarte."], "title": "El cambio de Liruf", "payload": {"options": [{"id": "contar-cambio", "text_md": "Contar el cambio con calma: dar 15 pesos", "rationale_md": "Es la mejor decisión porque así Liruf entrega el cambio exacto y la clienta confía en él."}, {"id": "adivinar-cambio", "text_md": "Adivinar el cambio rápido y dar 10 pesos", "rationale_md": "Adivinar puede hacer que des cambio de menos y la clienta se enoje."}, {"id": "quedarse-dinero", "text_md": "Quedarse con todo el billete y no dar cambio", "rationale_md": "Quedarse con el billete completo es deshonesto y la clienta perdería su dinero."}], "scenario_md": "Liruf está nervioso porque la primera clienta paga con un billete de $20 por un vaso de $5. ¿Qué decisión es la mejor?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/f3c54c1e67916fe735b131fec9c356c2f14f66d797f015cf0b40d391b08de989.png", "prompt_md": "Una clienta paga con un billete de $20 por un vaso de $5. ¿Qué debe hacer Liruf?", "difficulty": 1, "explanation_md": "Liruf debe contar el cambio con calma: 20 menos 5 son 15 pesos. Así no se equivoca y la clienta queda contenta.", "audio_segment_id": "s1-cambio-correcto.prompt"}], "schema_version": 1}', '{"s1-cambio-correcto": {"qualities": {"contar-cambio": 100, "adivinar-cambio": 30, "quedarse-dinero": 0}}}', '{"units": {"s1-cambio-correcto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a95ae666031547d67ec00f2605dc691b4ddc5ce3ed95d6c20fa3aa0f668e5179.mp3", "hash": "deea3ecd65684986bc2a08f2c881304e42154b26cea7f0dd89143f319eadaba9", "bytes": 32976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a95ae666031547d67ec00f2605dc691b4ddc5ce3ed95d6c20fa3aa0f668e5179.mp3", "duration_ms": 5440}, "s1-cambio-correcto.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5e9d6681ee740fff6c146587e8aa892c4c7c9e1f9bb446b0ed9c3f5b02a2be1f.mp3", "hash": "f21cd6b92ab7bd19e6473c33fdf1dd8d60d487307c596d223172f5eae5e91787", "bytes": 19584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5e9d6681ee740fff6c146587e8aa892c4c7c9e1f9bb446b0ed9c3f5b02a2be1f.mp3", "duration_ms": 3200}, "s1-cambio-correcto.prompt": {"url": "http://localhost:4006/files/lesson-audio/c6ebb7639e0be3a76b37c7c78c46296f0a9f0425f97659504177c57eceb30b22.mp3", "hash": "898d08fd1df8ad5284e45d3fccb9a58e36a82d9d95ed07f2abc34313c369510a", "bytes": 37296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c6ebb7639e0be3a76b37c7c78c46296f0a9f0425f97659504177c57eceb30b22.mp3", "duration_ms": 6160}, "s1-cambio-correcto.choices": {"url": "http://localhost:4006/files/lesson-audio/228953d39d1480911afa71fa94b975106c2757a338a4c8cbef96d5b73d4abf01.mp3", "hash": "ee8440b5be73a84c84301f76a69c6002d22b6dda5a6bbf27d5a62c4925aa4566", "bytes": 57456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/228953d39d1480911afa71fa94b975106c2757a338a4c8cbef96d5b73d4abf01.mp3", "duration_ms": 9520}, "s1-cambio-correcto.explanation": {"url": "http://localhost:4006/files/lesson-audio/506b18da28df6a998ac2802e6c580165b0033a6052cdfa23e1d57220f59b0591.mp3", "hash": "63f18f474ea9efdf492ee9e4886f50ab9f6931cde2ad5061c93f75793892b3e1", "bytes": 54144, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/506b18da28df6a998ac2802e6c580165b0033a6052cdfa23e1d57220f59b0591.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "order-steps", "title": "Ordene as compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar compras por prioridade de venda: primeiro o que gera receita hoje, depois o que melhora a venda, por último o luxo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-compras", "xp": 15, "type": "order_steps", "hints": ["Pense: sem o que você não pode vender nem um copo de limonada?", "O que dá lucro hoje vai primeiro; o que é luxo vai por último."], "title": "Ordene as compras da barraca", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/a2a415c9ebb2c2b0c7f7a12dc2faaf2e1a4e83d23f182217dbde324ad2244ae9.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/a15e5725db10d7ee516911dcef9e7b9fa055d228cad995ea2490ffc3c56c34d2.png"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/f89d8530b3a7d4c429972194b0975a3913c0b63a28435553a0ba411c78add6ab.png"}, {"id": "calcomanias", "text_md": "Adesivos", "image_url": "http://localhost:4006/files/lesson-images/7d938a514e079011888113a5f957a2952228e713ea3cb8bed5bdd43e2716d597.png"}], "slots": 4}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Liruf tem 20 reais. Ordene as compras da mais necessária para vender hoje à que pode esperar.", "difficulty": 2, "explanation_md": "Os limões são o mais urgente porque sem eles não há limonada para vender. Os copos vêm depois, porque sem eles você não pode servir. O açúcar melhora o sabor, mas você pode vender sem ele. Os adesivos são um capricho que pode esperar.", "audio_segment_id": "s1-ordenar-compras.prompt"}], "schema_version": 1}', '{"s1-ordenar-compras": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-ordenar-compras.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5c0015369af551096f3e433b7884e57165da5370937d19c55aa1fcfa9ac0e803.mp3", "hash": "946c0a179054014abdf2905fd52de3183fc50233a55b1308c8700dc7e4baec3e", "bytes": 25344, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/5c0015369af551096f3e433b7884e57165da5370937d19c55aa1fcfa9ac0e803.mp3", "duration_ms": 4160}, "s1-ordenar-compras.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0218762270815c862366585a40f0b1849d374ade9a0d8845e1beec7278ab8fe5.mp3", "hash": "522d28630fefcd84d7bb215b204cc24ac125c855a5f816a2221b56026b48e708", "bytes": 26784, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/0218762270815c862366585a40f0b1849d374ade9a0d8845e1beec7278ab8fe5.mp3", "duration_ms": 4400}, "s1-ordenar-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/8aa39530660bb283722aa385e5400fe257714d30d08c47474ddf33657068ee3a.mp3", "hash": "425b992b6ca9f354e1b1b16a3457c7d7a8544f3c4fa478aeb5bb9174601eb48d", "bytes": 39744, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8aa39530660bb283722aa385e5400fe257714d30d08c47474ddf33657068ee3a.mp3", "duration_ms": 6560}, "s1-ordenar-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/b5771376e7187c3bf0e4f746725fe9640de6a77f6810098e906ca2adb1a04036.mp3", "hash": "1bbd7526852a5700f78bdb98df66fca0c076b7304d2d3a3447cfba604119dd4d", "bytes": 90576, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b5771376e7187c3bf0e4f746725fe9640de6a77f6810098e906ca2adb1a04036.mp3", "duration_ms": 15040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "make-change", "title": "Dar troco exato", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular troco de uma nota de 20 após comprar dois produtos", "Montar o troco com moedas de 1, 2, 5 e 10"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Some o preço do copo e do biscoito.", "Quanto sobra da nota de 20?"], "title": "O troco do seu Beto", "payload": {"price": 8, "currency": "BRL", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/b1062ed1f6fb580b104ca95bf97a2a8b3ccb1b23181e55b239a67ce010c87d55.png", "prompt_md": "Seu Beto paga com uma nota de 20. Monte o troco exato com as moedas.", "difficulty": 2, "explanation_md": "O copo custa 5 e o biscoito 3, total 8. De 20 sobram 12. As moedas 10+2 dão 12.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/56a3caca01b817f986c992a2fc12587a66275b2a8a0493250bf14f80bc7762d6.mp3", "hash": "f5dad1ecfcc142068d806084d74268ed5337f1916c84b4d7479d2e1e51ea0e3f", "bytes": 16704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/56a3caca01b817f986c992a2fc12587a66275b2a8a0493250bf14f80bc7762d6.mp3", "duration_ms": 2720}, "s1-make-change.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8d4599e7f4d6e29654ea922bc23cc051e8eaf14e52f67c392deb81b462a4201f.mp3", "hash": "3de128909c73631100897bb20ba4275e297ceb4b39ad9ba0be6c83af4f1749d8", "bytes": 15696, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8d4599e7f4d6e29654ea922bc23cc051e8eaf14e52f67c392deb81b462a4201f.mp3", "duration_ms": 2560}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/532f27a49db9c1ff690392d8ce8fdbacac996534aa92185206d4a222a456a6b9.mp3", "hash": "f0da7569bca6722bc790493270b9bbf44f4e62ae52b4d97c0054f35d8969702b", "bytes": 31104, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/532f27a49db9c1ff690392d8ce8fdbacac996534aa92185206d4a222a456a6b9.mp3", "duration_ms": 5120}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/3d14e336aeb8faa9fb9dde75b639aa6beaf7025c5d0122d1b57bad41fa61239f.mp3", "hash": "f1a40abce6f2742e3fa9f1860c15a5033660a8feb68bf36edcfa6f7258435dba", "bytes": 52704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3d14e336aeb8faa9fb9dde75b639aa6beaf7025c5d0122d1b57bad41fa61239f.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Cerrar la caja del domingo", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de 1, 5 y 10 pesos para saber el total de ventas del día.", "Calcular el cambio correcto al pagar un vaso de 5 pesos con un billete de 20.", "Determinar cuántos domingos más se necesitan para ahorrar 80 pesos para una guitarra, partiendo de 40 pesos y ahorrando 20 cada domingo."], "estimated_minutes": 8}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Agrupa las monedas del mismo valor y luego súmalas."], "title": "Contar las monedas del día", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/65d3a193e4f77d0392109689825a38e1da63e2aad4ea7ae497e13ba344df96c7.png", "prompt_md": "Liruf vendió 1 vaso de 5 pesos, 1 de 10 y 5 de 1. ¿Cuánto juntó?", "difficulty": 1, "explanation_md": "Liruf juntó 1 moneda de 10, 1 de 5 y 5 de 1. 10 + 5 + 5 = 20 pesos en total.", "audio_segment_id": "s1-contar-monedas.prompt"}, {"id": "s2-dar-cambio", "xp": 15, "type": "make_change", "hints": ["Piensa cuánto dinero te dio y cuánto cuesta el vaso."], "title": "Dar cambio a la última clienta", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/ad81f33cc898159aaee022091cb7e676c4e48033fd4969580f695d44f8616256.png", "prompt_md": "La clienta paga su vaso de 5 pesos con un billete de 20. ¿Cuánto cambio le das?", "difficulty": 2, "explanation_md": "La clienta pagó 20 pesos y el vaso cuesta 5. 20 - 5 = 15 pesos de cambio.", "audio_segment_id": "s2-dar-cambio.prompt"}, {"id": "s3-ahorro-guitarra", "xp": 25, "type": "savings_goal", "hints": ["Si ya tiene 40, ¿cuánto le falta para 80? Luego, cada domingo ahorra 20."], "title": "¿Cuántos domingos para la guitarra?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf tiene 40 pesos y cada domingo guarda 20. ¿Cuántos domingos faltan para tener 80?", "difficulty": 2, "explanation_md": "Le faltan 40 pesos. Como cada domingo ahorra 20, necesita 2 domingos: 20+20=40.", "audio_segment_id": "s3-ahorro-guitarra.prompt"}], "schema_version": 1}', '{"s2-dar-cambio": {}, "s1-contar-monedas": {}, "s3-ahorro-guitarra": {}}', '{"units": {"s2-dar-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/38840c07298c2733bb79df3a4d4940c83db5a1fc3f06593e450255a1aee483b7.mp3", "hash": "f41e0c81d1c333f1e79a2fe803f55fc7f849acc8a5da3c1c82f0bb7f669e7261", "bytes": 21888, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/38840c07298c2733bb79df3a4d4940c83db5a1fc3f06593e450255a1aee483b7.mp3", "duration_ms": 3600}, "s2-dar-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/31be3f6fedcc6f4c5cac645645fed7dca3667eb6caeed2d7a867395c91389143.mp3", "hash": "b9d9c33d430470f831a43269b2c47ae2df82aca4bfc13fd56c4fc6f6a4433761", "bytes": 34848, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/31be3f6fedcc6f4c5cac645645fed7dca3667eb6caeed2d7a867395c91389143.mp3", "duration_ms": 5760}, "s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/aea41c81769e102ceb6d179e98c4474ab5fb8ba58e7a2cba855d0f901fc98a8a.mp3", "hash": "aa769f7fa5e93ccfb139714429c50485b4077cedcdf58c0c07389429b8a73312", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/aea41c81769e102ceb6d179e98c4474ab5fb8ba58e7a2cba855d0f901fc98a8a.mp3", "duration_ms": 3680}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/d1f55193d9622207f15f47c577e11a7d7142c31a40c813169bd9bf7f7cef8474.mp3", "hash": "db7e4eac7e38a9f8983a1a61b9ecd6db4d2ac90d8db2ba82d8e926815a03dc88", "bytes": 41184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d1f55193d9622207f15f47c577e11a7d7142c31a40c813169bd9bf7f7cef8474.mp3", "duration_ms": 6800}, "s2-dar-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/deb24e31a769e48a29c43c6156505b7028d7a9ae3405221b7bd89b3e1d317efb.mp3", "hash": "832faf9286a0248249df4119ab8f1acae89dabe2b5a32998783eb22d7f7fdda3", "bytes": 40176, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/deb24e31a769e48a29c43c6156505b7028d7a9ae3405221b7bd89b3e1d317efb.mp3", "duration_ms": 6640}, "s3-ahorro-guitarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0ca8df717547b452ce1dc82a7404296822364d470d697e6d69f6ef149c1edcd7.mp3", "hash": "6905ca4e1f52eda57dae24decc452c64dca674312c23ee3d90a0e63ba7c1b110", "bytes": 39168, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0ca8df717547b452ce1dc82a7404296822364d470d697e6d69f6ef149c1edcd7.mp3", "duration_ms": 6480}, "s3-ahorro-guitarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/200b7fbf674291389214f24799e062d1a9cf39d9ecad429869dab0b98626430c.mp3", "hash": "0eb80ba42a5f169cd5cce90b083ad8d824e2bd664258b256e4333081e87ed53f", "bytes": 47808, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/200b7fbf674291389214f24799e062d1a9cf39d9ecad429869dab0b98626430c.mp3", "duration_ms": 7920}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/499c20cabca27b733b951db3d0d7699266cca82982c8a3c2608ecebc81d45e5f.mp3", "hash": "480d278fa6df9359d58f8fd42b7baa65d186e66b9ea1300d61c64d5b51b772e9", "bytes": 48816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/499c20cabca27b733b951db3d0d7699266cca82982c8a3c2608ecebc81d45e5f.mp3", "duration_ms": 8080}, "s3-ahorro-guitarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/b7beb107c7676498f69ffa407883a3e00a9b5b55e1ac2d11df81e3feb8f75929.mp3", "hash": "235f361c6b280c4b4395bcd32f77a3b6ba6ce4bd2b0170dd23ef7911c420582c", "bytes": 53568, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b7beb107c7676498f69ffa407883a3e00a9b5b55e1ac2d11df81e3feb8f75929.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "The night before opening", "locale": "en-US", "subject": "mixed", "objectives": ["Review the goal of the 80-dollar guitar, the lemonade price of 5 dollars per cup, and that profit is what''s left after paying the cost and goes into the guitar jar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "The night before opening", "payload": {"recap_md": "It''s the night before opening. Dina sits next to Liruf and his empty guitar jar. Instead of a test, they point out the three things they already have ready: the goal taped to the wall (guitar, 80 dollars), the lemonade sign (5 dollars per cup), and the secret they learned — that from each cup, what''s left after cost is the profit that pushes the jar toward 80. Liruf breathes: the idea is no longer just a dream, tomorrow it''s truly tested. Dina smiles and asks him how close he already feels that guitar.", "mood_prompt_md": "Liruf looks at the empty jar but smiles. Tomorrow he starts filling it."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina and Liruf review what they have prepared.", "difficulty": 1, "explanation_md": "Liruf has his goal of 80 dollars, his lemonade at 5 dollars per cup, and knows that profit is what''s left after cost. Tomorrow he puts it to the test.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/508c5c76b51b3e28b3a0ebf41fd184d913619bfb1f6d68362d33788dca130fdf.mp3", "hash": "5736dda0c5c8b67df76185e30faa6778f8fd51945b3fb91f50855aef0985fcef", "bytes": 155376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/508c5c76b51b3e28b3a0ebf41fd184d913619bfb1f6d68362d33788dca130fdf.mp3", "duration_ms": 25840}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/5e88856d7a301ea639a6da19f8d12da5a5fc7385f5a9e0cdcae34d60cd2b4652.mp3", "hash": "b87be9397e16c6ab66afbf0d40ec8477014523c3d2fab76e4db7fc85fc768a30", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5e88856d7a301ea639a6da19f8d12da5a5fc7385f5a9e0cdcae34d60cd2b4652.mp3", "duration_ms": 2400}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/6568f3b663fa94648c30cad9eb554b2f2d3c40b548e7a450b498a0909110b466.mp3", "hash": "70d332a21cbc2db734baefe45b53c987fb4d2afab8b013c9361e9cd368bab470", "bytes": 50688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6568f3b663fa94648c30cad9eb554b2f2d3c40b548e7a450b498a0909110b466.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "A noite antes de abrir", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar a meta do violão de 80 reais, o preço da limonada a 5 reais o copo, e que o lucro é o que sobra depois de pagar o custo e vai para o pote do violão."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "A noite antes de abrir", "payload": {"recap_md": "É a noite antes de abrir. Dina senta ao lado de Liruf e seu pote vazio do violão. Em vez de uma prova, eles apontam as três coisas que já estão prontas: a meta colada na parede (violão, 80 reais), o cartaz da limonada (5 reais o copo) e o segredo que aprenderam — que de cada copo, o que sobra depois do custo é o lucro que empurra o pote rumo aos 80. Liruf respira: a ideia já não é só um sonho, amanhã é testada de verdade. Dina sorri e pergunta quão perto ele já sente aquele violão.", "mood_prompt_md": "Liruf olha o pote vazio mas sorri. Amanhã começa a enchê-lo."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina e Liruf revisam o que prepararam.", "difficulty": 1, "explanation_md": "Liruf tem sua meta de 80 reais, sua limonada a 5 reais o copo, e sabe que o lucro é o que sobra depois do custo. Amanhã ele coloca à prova.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/9e8e1fc62eb39f1b01d62ef2350f020dfa1f778e82bd74df28b6c3458b4f724f.mp3", "hash": "71fbab9850a67af447ebe09c282ff437b058d877365f0e0e0f1840dc7f466e9e", "bytes": 196704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9e8e1fc62eb39f1b01d62ef2350f020dfa1f778e82bd74df28b6c3458b4f724f.mp3", "duration_ms": 32720}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/2a498430b538ed3d411ee2706dbb3139178021280d58bfa13d9d5c759dd48b28.mp3", "hash": "5999fe14ef938b6cf342eb11d4b6f8d682e7e9c71c7124db77e0f1b154c367ca", "bytes": 17136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2a498430b538ed3d411ee2706dbb3139178021280d58bfa13d9d5c759dd48b28.mp3", "duration_ms": 2800}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/9cc455fd1564203ab1869e06029fabf28fd5213ecaa9f190c33e5589d9289dbe.mp3", "hash": "5c4b0738cd22c8d2e92a2407640ffa769c00c34368c9d6bfd7f60c0ed98468ad", "bytes": 71424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9cc455fd1564203ab1869e06029fabf28fd5213ecaa9f190c33e5589d9289dbe.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "rank-choices", "title": "Prioridades na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar do mais urgente para o menos urgente em que gastar o lucro de hoje: repor limões primeiro, depois copos, e por último enfeites."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 10, "type": "rank_choices", "hints": ["Sem limões não dá para fazer limonada.", "Os enfeites são bonitos, mas não são urgentes."], "title": "O que comprar primeiro?", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/829cabf1499dd372fa87964c6c917f64bf902b210fcee67a26ae32d75b4966f5.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/f33ed77356f578ea664aae0d1358d13475e7a7989fde5fbb014b0167860e9723.png"}, {"id": "adornos", "text_md": "Enfeites", "image_url": "http://localhost:4006/files/lesson-images/c2b29f5b1e1d32c172051633bd2af8fd3957979dfef489b2c3845a754e96953f.png"}], "criterion_md": "Urgência para a barraca: o que você mais precisa hoje vem primeiro."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Ordene as compras da mais urgente para a menos urgente para a barraca da Liruf.", "difficulty": 1, "explanation_md": "Os limões são o mais urgente porque sem eles não há limonada. Os copos são necessários para servir. Os enfeites podem esperar.", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank-choices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c68ba6fc523463c17f8fb141033097d4b98407d5e625356333f463c1c37561ce.mp3", "hash": "93183bf14774a16d4f68ee38e5214de5a7d1d80d7df4b07006f7e76f5e81ac18", "bytes": 19584, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/c68ba6fc523463c17f8fb141033097d4b98407d5e625356333f463c1c37561ce.mp3", "duration_ms": 3200}, "s1-rank-choices.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4e69ceeaf456692e6c17c197661a461b5c85eac29e4353d41972943899620274.mp3", "hash": "5fd9b57f5a80219ca8a0500fab3a255347bb623115deb5f9a533412e88426a0a", "bytes": 24768, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/4e69ceeaf456692e6c17c197661a461b5c85eac29e4353d41972943899620274.mp3", "duration_ms": 4080}, "s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/d5736968fbb22345eebb36b4a3e6a86531b5a9324fe67062761496e60bd23b8d.mp3", "hash": "204b3190871f8d0f2dd4edcdd55bd5fc7579e3be0ea797fab0ae29dba70db062", "bytes": 32544, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d5736968fbb22345eebb36b4a3e6a86531b5a9324fe67062761496e60bd23b8d.mp3", "duration_ms": 5360}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/d5303471dd697c918464094354dcb1c2b94227b41c2e3c60cfac9cf3e41d1e5e.mp3", "hash": "1beb59f61c36113d0fafd0b51fb2429c25d6ad970406a08f8c377eb76f321303", "bytes": 62784, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d5303471dd697c918464094354dcb1c2b94227b41c2e3c60cfac9cf3e41d1e5e.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Fechar a caixa do domingo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de 1, 5 e 10 reais para saber o total de vendas do dia.", "Calcular o troco correto ao pagar um copo de 5 reais com uma nota de 20.", "Determinar quantos domingos a mais são necessários para economizar 80 reais para um violão, partindo de 40 reais e economizando 20 a cada domingo."], "estimated_minutes": 8}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Agrupe as moedas do mesmo valor e depois some-as."], "title": "Contar as moedas do dia", "payload": {"target": 20, "currency": "BRL", "denominations": [1, 5, 10]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8bd5489f163ad7d6784e35c07e7410a71065fe9bdfc24d0a2140a491bfa3829f.png", "prompt_md": "Liruf vendeu 1 copo de 5 reais, 1 de 10 e 5 de 1. Quanto ele juntou?", "difficulty": 1, "explanation_md": "Liruf juntou 1 moeda de 10, 1 de 5 e 5 de 1. 10 + 5 + 5 = 20 reais no total.", "audio_segment_id": "s1-contar-monedas.prompt"}, {"id": "s2-dar-cambio", "xp": 15, "type": "make_change", "hints": ["Pense em quanto dinheiro ela te deu e quanto custa o copo."], "title": "Dar troco à última cliente", "payload": {"price": 5, "currency": "BRL", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/108a5b07f70959ad160b78b2226b416a6ca7498a00c67328fc2dc1813d66617e.png", "prompt_md": "A cliente paga seu copo de 5 reais com uma nota de 20. Quanto troco você dá?", "difficulty": 2, "explanation_md": "A cliente pagou 20 reais e o copo custa 5. 20 - 5 = 15 reais de troco.", "audio_segment_id": "s2-dar-cambio.prompt"}, {"id": "s3-ahorro-guitarra", "xp": 25, "type": "savings_goal", "hints": ["Se ele já tem 40, quanto falta para 80? Depois, cada domingo ele economiza 20."], "title": "Quantos domingos para o violão?", "payload": {"goal": 80, "currency": "BRL", "weekly_options": [20]}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf tem 40 reais e cada domingo guarda 20. Quantos domingos faltam para ter 80?", "difficulty": 2, "explanation_md": "Faltam 40 reais. Como cada domingo ele economiza 20, precisa de 2 domingos: 20+20=40.", "audio_segment_id": "s3-ahorro-guitarra.prompt"}], "schema_version": 1}', '{"s2-dar-cambio": {}, "s1-contar-monedas": {}, "s3-ahorro-guitarra": {}}', '{"units": {"s2-dar-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dbd9ee76f3ab4ecac7369ca489e85457fd2c5a1903cfa70a70ccbccbbf7b616e.mp3", "hash": "a6b0af02f8952b5cb4d8569931268422e7d1099a962bcaf8c6eb3cd4740061c7", "bytes": 23328, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/dbd9ee76f3ab4ecac7369ca489e85457fd2c5a1903cfa70a70ccbccbbf7b616e.mp3", "duration_ms": 3840}, "s2-dar-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/3fe770bfe326c9a0f927ec358f04d4aaccf0cc44151e39c38ce923eb53e08515.mp3", "hash": "ac633e4d74b23152804184ac1a428306476f2b0fc3a2524a6beed5e40b0a2764", "bytes": 36288, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3fe770bfe326c9a0f927ec358f04d4aaccf0cc44151e39c38ce923eb53e08515.mp3", "duration_ms": 6000}, "s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/576753773bf33e71da22a80a0789648fa45ba043daf9c97234594812eac68deb.mp3", "hash": "8ef2d235c715f015e3e75b48e4fb1c0fe9727a8fa0db766b18e7fb1d7486b735", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/576753773bf33e71da22a80a0789648fa45ba043daf9c97234594812eac68deb.mp3", "duration_ms": 3440}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/bfb5ace1933ffa42266d78b63d112ea08dccf0876d29369b2ffc41aa8f259310.mp3", "hash": "2269624f1ddc00d59c197b0f702790e1ec100ebc3a41c9e00d7039d8ca8d7155", "bytes": 41616, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bfb5ace1933ffa42266d78b63d112ea08dccf0876d29369b2ffc41aa8f259310.mp3", "duration_ms": 6880}, "s2-dar-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/661718728aa0153cc114085682a7900729581148dfea303b60a2e41536f7f141.mp3", "hash": "277f4d8f12043eec01e6443f304d2825225e938376c10fc559066a432afb13c8", "bytes": 43488, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/661718728aa0153cc114085682a7900729581148dfea303b60a2e41536f7f141.mp3", "duration_ms": 7200}, "s3-ahorro-guitarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/28773c3738a407423466d68f88f20fda77c9d23ffacf37b25397a2e1e5add162.mp3", "hash": "e002590c282343e0cb3df6daff5c57a02f8a1c938bf6a70f4dc0bb9e7761a5a3", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/28773c3738a407423466d68f88f20fda77c9d23ffacf37b25397a2e1e5add162.mp3", "duration_ms": 7040}, "s3-ahorro-guitarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/bc8273bcd2a057cfc7b1e58a20607a3f271762183bbdf5348e8c5917e86ac01c.mp3", "hash": "12acd19b5b4a048c717d57eb66e47f6015ce5d8630af4e64952c8c1ed870ea7e", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bc8273bcd2a057cfc7b1e58a20607a3f271762183bbdf5348e8c5917e86ac01c.mp3", "duration_ms": 6720}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/80fe82c9a4dd67cda36d83fdb847240fb30ce03490e4a155d61d1e7e75a9e857.mp3", "hash": "92ee866de785587a021c175c83784ae2e788b3a017d14add2420dd8ea0176054", "bytes": 49824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/80fe82c9a4dd67cda36d83fdb847240fb30ce03490e4a155d61d1e7e75a9e857.mp3", "duration_ms": 8240}, "s3-ahorro-guitarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/37bc1ed18d2189e16698e838e26d466ca370aada13e94ba578dac2ed40aaf5b3.mp3", "hash": "6d76b959bfc99f4ff97932ff8efda5c3497bb48b11464ee6bdf97ff089f7f2be", "bytes": 55008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/37bc1ed18d2189e16698e838e26d466ca370aada13e94ba578dac2ed40aaf5b3.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "repaso-true-false", "title": "Review: True or False?", "locale": "en-US", "subject": "money", "objectives": ["Distinguishing between total income and profit at a lemonade stand", "Remember that each cup costs 2 dollars in supplies, so the profit per cup is 3 dollars"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Remember: each cup costs 2 dollars for lemon and sugar. How much do you really keep per cup?", "If you sell 10 cups at 5 dollars, you get 50 dollars. But from that you have to subtract what it cost to make them."], "title": "True or False?", "payload": {"statement_md": "Liruf sold 10 cups at 5 dollars each, so he earned 50 dollars.", "justifications": [{"id": "j-verdadero", "text_md": "True: 10 cups × 5 dollars = 50 dollars, that is the profit."}, {"id": "j-falso", "text_md": "False: 10 cups × 5 dollars = 50 dollars of income, but each cup cost 2 dollars to make, so the profit is 30 dollars."}]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Rho says: ''You sold 10 cups at 5 dollars each, so you earned 50 dollars!'' Is it true or is it a trick?", "difficulty": 1, "explanation_md": "It is **false**. You got 50 dollars, but each cup cost 2 dollars to make (lemon and sugar). The profit per cup is 5 - 2 = 3 dollars. For 10 cups, the real profit is 10 × 3 = 30 dollars, not 50. What comes in is not what you earn!", "audio_segment_id": "s1-verdadero-falso.prompt"}], "schema_version": 1}', '{"s1-verdadero-falso": {"is_true": false, "correct_justification_id": "j-falso"}}', '{"units": {"s1-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6695a85a32816d1e831dc09d3b7bdb30fba395dd5a25f33027b6c29e1a0d3df2.mp3", "hash": "64bae948e5e482d09758355ac4662479fb7c14307cd1ced7bd87c628fc30d66c", "bytes": 42048, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6695a85a32816d1e831dc09d3b7bdb30fba395dd5a25f33027b6c29e1a0d3df2.mp3", "duration_ms": 6960}, "s1-verdadero-falso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a1394382904a18b90ab69d2a5097e94180a34ef81683d77440efd56ecbfb7bb8.mp3", "hash": "63cde4c2af4ec208c1ee2ed08c8e60d7e357a18278d84d06ac7b136dfc5fdfcf", "bytes": 47808, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a1394382904a18b90ab69d2a5097e94180a34ef81683d77440efd56ecbfb7bb8.mp3", "duration_ms": 7920}, "s1-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/43daafd8778875a1112991421d64cb9f9cfbbf08dc3a8ba78533cd4b8bae1a92.mp3", "hash": "7669fe3a950a37c5b9bed3e07d07852112ca6d7d95cabc0493fe15d86ad190ce", "bytes": 49824, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/43daafd8778875a1112991421d64cb9f9cfbbf08dc3a8ba78533cd4b8bae1a92.mp3", "duration_ms": 8240}, "s1-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/6f9873f9e79ca6af56e6d8bff1ef704a29f10e3e055c085548f551fe1f1f61f6.mp3", "hash": "a4d3ddeee50023ce0685793d425bc00858e6f2c78b74aae970da40858dcd3f5c", "bytes": 111744, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/6f9873f9e79ca6af56e6d8bff1ef704a29f10e3e055c085548f551fe1f1f61f6.mp3", "duration_ms": 18560}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Necesidades y deseos en el puesto", "locale": "es-MX", "subject": "money", "objectives": ["Separar necesidades del puesto (limones, hielo) de deseos personales (paleta, cómic): el puesto come primero."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["Piensa: ¿sin qué no podría Liruf hacer limonada?", "El puesto necesita cosas para hacer y vender limonada."], "title": "¿Qué necesita el puesto?", "payload": {"items": [{"id": "item-limones", "icon": "nutrition", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/167c3b8939dd1e9fc963472236e3db92916cf5311c149def19882dc4c98e8a77.png"}, {"id": "item-hielo", "icon": "ac_unit", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/96efa8087ed993cd200314d98803012b9b78624ab9725e1eae203ba1394641ef.png"}, {"id": "item-paleta", "icon": "icecream", "text_md": "Paleta", "image_url": "http://localhost:4006/files/lesson-images/92599ccd48e44880ef31fb522e176b2c7963c8bebaea73030403fec410edb9e2.png"}, {"id": "item-comic", "icon": "auto_stories", "text_md": "Cómic"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Ayuda a Liruf a separar lo que el puesto necesita de lo que él desea. Toca los que el puesto necesita para seguir vendiendo.", "difficulty": 1, "explanation_md": "El puesto necesita limones y hielo para hacer limonada. La paleta y el cómic son deseos personales de Liruf, no del puesto.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["item-limones", "item-hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f9daf40ed1fcf4221e7168068d022e2fdcda4c555263393152212bf006b4f1b3.mp3", "hash": "afba3920d51acc0d31cf2bcf6474226e1b713951d0971cba2fe35fb9c5598289", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f9daf40ed1fcf4221e7168068d022e2fdcda4c555263393152212bf006b4f1b3.mp3", "duration_ms": 3440}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a8138a370b9aee611835389a391562ae2006e74c81bdafbf31dcf604df493fff.mp3", "hash": "54b8806e044bcecf9bd6d28babd6a1c0660d36329a796d170085827f2cdf1c01", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a8138a370b9aee611835389a391562ae2006e74c81bdafbf31dcf604df493fff.mp3", "duration_ms": 3600}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/76816de101be4ddcfa530a5db71819f500d1a852fd739277cb6a7e3d3f7641b5.mp3", "hash": "86136f5934051dfc364bca3ba63adc36430104efb3faf9e288a28f332ce5d62f", "bytes": 48384, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/76816de101be4ddcfa530a5db71819f500d1a852fd739277cb6a7e3d3f7641b5.mp3", "duration_ms": 8000}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/893a089e878e083f189b6f76f3c265a6fb0bd5f17e164b6d37d6c9e1c4b0eabd.mp3", "hash": "76faf833538252916d39e83c113c2e36961eacb4d7d6c81a4fb350f2345b2ef5", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/893a089e878e083f189b6f76f3c265a6fb0bd5f17e164b6d37d6c9e1c4b0eabd.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Fechar a barraca: tudo junto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Emparelhar pagamentos com o troco correto", "Ordenar os passos para calcular o lucro", "Separar necessidades de desejos para a barraca", "Ordenar eventos do dia para manter troco disponível"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Se pagarem com 10, o troco é 10 menos 5.", "Calcule quanto sobra de cada pagamento depois de pagar um copo."], "title": "Troco para cada pagamento", "payload": {"left": [{"id": "pago-10", "text_md": "Pagar com 10", "image_url": "http://localhost:4006/files/lesson-images/1b45dc7e6874900afac35463d8b1344a42870fb70f7fb6b4b8eb2f3a0e20107e.png"}, {"id": "pago-20", "text_md": "Pagar com 20", "image_url": "http://localhost:4006/files/lesson-images/f13b73b6d1b37379b084d34b54c6ea6ea12a4045f37bec111d0b56770f99c1a1.png"}, {"id": "pago-6", "text_md": "Pagar com 6", "image_url": "http://localhost:4006/files/lesson-images/35760abe880ca39c51c3a1798c74a222e77c05fabff14145a04f0783e1042c5f.png"}], "right": [{"id": "cambio-5", "text_md": "Troco: 5"}, {"id": "cambio-15", "text_md": "Troco: 15"}, {"id": "cambio-1", "text_md": "Troco: 1"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toque cada pagamento com seu troco correto. Um copo custa 5 reais.", "difficulty": 2, "explanation_md": "Com 10 reais você paga 5 e sobram 5; com 20 sobram 15; com 6 sobra 1.", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["Antes de contar o ganho, é preciso separar o que custou fazer a limonada.", "O lucro é o que sobra depois de subtrair o custo."], "title": "Ordem para obter o lucro", "payload": {"items": [{"id": "costo", "text_md": "Separar o custo (limões e copos)", "image_url": "http://localhost:4006/files/lesson-images/c489f79f9e0cb08b1397dabfd71d334d5d7402ac689c80b8af558d2ee3c4723a.png"}, {"id": "restar", "text_md": "Subtrair o custo do total de vendas", "image_url": "http://localhost:4006/files/lesson-images/08b354c4ab3ae94f59d435b5fb4b049de8cda8bb0b83465e39ef8056a1917531.png"}, {"id": "ganancia", "text_md": "Essa subtração é o lucro", "image_url": "http://localhost:4006/files/lesson-images/86318c33b80a192c1f28b5be20aac5501d7c9898d4d35b1c2104115fb848bff3.png"}], "slots": 3}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ordene os passos para saber quanto Liruf ganhou hoje. Primeiro separe o custo.", "difficulty": 2, "explanation_md": "Primeiro você separa o custo dos limões e copos, depois subtrai isso do total de vendas, e assim você sabe o lucro.", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Sem limões e copos não se pode vender limonada.", "O gelo e os adesivos são desejos, não urgentes."], "title": "O que a barraca precisa", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/254e8d0a1bc576d410c79ed70f115441d4ae469cab08dc401251b71b94a51764.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/e38490c699fb52d9c04f3ce170eae2308821dca3e079d977c8ae60629bff31d3.png"}, {"id": "hielo", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/71f63c1a0cf866c7e97635348bedcf3b4c9ac50d69637e85139368b81a6f35cf.png"}, {"id": "calcomania", "text_md": "Adesivo", "image_url": "http://localhost:4006/files/lesson-images/46e33a124a5e989087de30cc20e2e621cc41a46c4442628dfff5187560a3939d.png"}], "buckets": [{"id": "necesita", "label": "Precisa para abrir"}, {"id": "esperar", "label": "Pode esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Com apenas 20 reais, separe o que a barraca PRECISA para abrir amanhã do que pode esperar.", "difficulty": 2, "explanation_md": "Liruf precisa de limões e copos para vender; o gelo e os adesivos podem esperar.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-cambio", "xp": 25, "type": "timeline_order", "hints": ["Se primeiro você gasta troco e depois recebe, você fica sem troco.", "Uma venda deve ocorrer antes de um gasto que precise de troco."], "title": "O dia sem ficar sem troco", "payload": {"events": [{"id": "venta-10", "icon": "payments", "text_md": "Cliente paga com 10", "image_url": "http://localhost:4006/files/lesson-images/4d99678972fd5332172b725a2d2dc089c2323c5d0454936946ee48223e421fa7.png"}, {"id": "cambio-5", "icon": "currency_exchange", "text_md": "Dar troco de 5", "image_url": "http://localhost:4006/files/lesson-images/10d7d12d868bb7510c35ea459379b762e49faf94819a3ead2951cae03334186e.png"}, {"id": "gasto-2", "icon": "local_atm", "text_md": "Gastar 2 em gelo", "image_url": "http://localhost:4006/files/lesson-images/bcbdd674ceee72c1bc2985e04a2b1558ce3d9c4d28643795891c8b313c12df0a.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ordene os eventos do dia para que o caixa nunca fique sem troco. Um copo custa 5 reais.", "difficulty": 3, "explanation_md": "Liruf primeiro recebe 10 reais de uma venda, depois dá troco de 5, e no final gasta 2 em gelo. Assim nunca falta troco.", "audio_segment_id": "s4-timeline-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["pago-10", "cambio-5"], ["pago-20", "cambio-15"], ["pago-6", "cambio-1"]]}, "s2-order-ganancia": {"order": ["costo", "restar", "ganancia"]}, "s4-timeline-cambio": {"order": ["venta-10", "cambio-5", "gasto-2"]}, "s3-sort-necesidades": {"assignments": {"hielo": "esperar", "vasos": "necesita", "limones": "necesita", "calcomania": "esperar"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0135c61d1b3dc2880040574c5c29c9d5639b95e31d1daa65bf777d31abe0e25e.mp3", "hash": "1fce257ee9edbc0e03711fdb702df44183b47b3acb00e3db0bac17787d978e82", "bytes": 23904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0135c61d1b3dc2880040574c5c29c9d5639b95e31d1daa65bf777d31abe0e25e.mp3", "duration_ms": 3920}, "s1-match-cambio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0ea4d6d0bc9c7147d4c1f79a481d9640cf09f4f0a0d2d4bdac36c465905d791e.mp3", "hash": "6a7d271a8471f3e3ec5ca9906bae664eb2788f057e1d07b91eaf535804fe30fa", "bytes": 25776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0ea4d6d0bc9c7147d4c1f79a481d9640cf09f4f0a0d2d4bdac36c465905d791e.mp3", "duration_ms": 4240}, "s1-match-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/f6b1909bf0cea7320e47c600a8417bd682f7585ae1b2957600c8d007b9ad0143.mp3", "hash": "0a17b385afba7a07d610d1e11b3d316b9258a586dfadf6a377add6970c6e9d15", "bytes": 31536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f6b1909bf0cea7320e47c600a8417bd682f7585ae1b2957600c8d007b9ad0143.mp3", "duration_ms": 5200}, "s2-order-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a3c408e02cee1c7d74c12f2d31ffc28f2e8e6bbeb150c54d9831dd696db568d1.mp3", "hash": "8c3ebcdeb500abd6fd1bad3bd304298f06c51f313decbbad8e50b90c0321f20a", "bytes": 27648, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a3c408e02cee1c7d74c12f2d31ffc28f2e8e6bbeb150c54d9831dd696db568d1.mp3", "duration_ms": 4560}, "s2-order-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7873a43428b8369bd58ec5f8ee21dc2beb52323165624975fd7234b0009dd3ab.mp3", "hash": "8b841f75f8370a1b1cbbb75f0d4af4186a4d15c05602e4d118a58afef412ecdb", "bytes": 22464, "voice": "qw