"s4-timeline-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/692a301cd54c7fc4bbc5dca1bc0a4fffc4452ccbd928aa113e0d5dc592ab8ad6.mp3", "hash": "1123e1a16dd0497c9e57836487a4787dfdb00c4ffd3fe2241d4a638b3acb192b", "bytes": 59904, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/692a301cd54c7fc4bbc5dca1bc0a4fffc4452ccbd928aa113e0d5dc592ab8ad6.mp3", "duration_ms": 9920}, "s3-sort-necesidades.explanation": {"url": "http://localhost:4006/files/lesson-audio/fef2d31fa36600c4c4aff82d1059f3fcd0fe47c1684b759726712642ff91b67d.mp3", "hash": "fbf62582678963390bfa60a55b833ff560ddb5787631ff879ed57ff99ba99ff9", "bytes": 38304, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fef2d31fa36600c4c4aff82d1059f3fcd0fe47c1684b759726712642ff91b67d.mp3", "duration_ms": 6320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "quiz-mcq", "title": "Choose the fair price", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the fair price for a glass of lemonade (5 dollars) among exaggerated options"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["If the price is too high, no one will buy. If it''s too low, Liruf earns nothing.", "Think about how much it costs to make a glass of lemonade: lemons, water, sugar."], "title": "How much per glass?", "payload": {"options": [{"id": "a", "text_md": "1 dollar", "rationale_md": "1 dollar is too little: it''s not even enough to buy the lemons. Liruf would lose money."}, {"id": "b", "text_md": "5 dollars"}, {"id": "c", "text_md": "50 dollars", "rationale_md": "50 dollars is too expensive for a glass of lemonade. Almost no one would buy it."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf sets the price for a glass of lemonade. Which one is fair for everyone?", "difficulty": 1, "explanation_md": "The fair price is 5 dollars. That way customers buy and Liruf earns a little for his work.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "b"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3a255c693d9b1b1d1ae3ebca4b787ca349fc65ccd4aef6614782a9f1d244941c.mp3", "hash": "8b6856f706c07ef9227fb2e10c8a8639b41ac56196f13925f3f35f8859b1c082", "bytes": 27648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a255c693d9b1b1d1ae3ebca4b787ca349fc65ccd4aef6614782a9f1d244941c.mp3", "duration_ms": 4560}, "s1-precio-justo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e6b51cf54ef13dcb66259451a61a607594f2aec39fc26497c322bbc1fb6e3336.mp3", "hash": "962b79f1a56ebac6aae3c6e6786fff06c2c00fcb52d8428ae4c7e519d981558c", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e6b51cf54ef13dcb66259451a61a607594f2aec39fc26497c322bbc1fb6e3336.mp3", "duration_ms": 4640}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/02d6b915975de1c39e90689f41bab65d211daf87fa71d09764576c74aa750097.mp3", "hash": "3a658ffdb5e1664ff3471267e6d06759f861fe0497fbb80b23c9909d79dcc615", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/02d6b915975de1c39e90689f41bab65d211daf87fa71d09764576c74aa750097.mp3", "duration_ms": 4480}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/1f8fa446acf236f9e19befe82a1047b09d9a20e7e5180ad5a2b7938950c59451.mp3", "hash": "1b69dcc75d0f3d9f4713bda7973765ff9fb35c50ec2d85f37dde3c6c70a12945", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1f8fa446acf236f9e19befe82a1047b09d9a20e7e5180ad5a2b7938950c59451.mp3", "duration_ms": 2880}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/3413eca690070fc0fa3c7565300f27e118c4e1558a0ad0910a9137f222512793.mp3", "hash": "b1d701d17fb54f2af77be886134edc95296bfbf780a6b332dcd569e969c48469", "bytes": 31536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3413eca690070fc0fa3c7565300f27e118c4e1558a0ad0910a9137f222512793.mp3", "duration_ms": 5200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Needs and wants at the stand", "locale": "en-US", "subject": "money", "objectives": ["Separate stand needs (lemons, ice) from personal wants (lollipop, comic): the stand comes first."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["Think: what could Liruf not make lemonade without?", "The stand needs things to make and sell lemonade."], "title": "What does the stand need?", "payload": {"items": [{"id": "item-limones", "icon": "nutrition", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/d2037ac8f7c7848616a6d637698b6670c9767ec22ec2c7a1f7864bbc42d72e32.png"}, {"id": "item-hielo", "icon": "ac_unit", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/51c09fff8a4f9dd2086bcd879494937a2d9a386087b4f021cb569281e5e8dd9d.png"}, {"id": "item-paleta", "icon": "icecream", "text_md": "Lollipop", "image_url": "http://localhost:4006/files/lesson-images/fa994e274eecfb2e6bec74189b9617140a7c642a0c0dc48dcad4ef3bcca4304e.png"}, {"id": "item-comic", "icon": "auto_stories", "text_md": "Comic"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Help Liruf separate what the stand needs from what he wants. Tap the things the stand needs to keep selling.", "difficulty": 1, "explanation_md": "The stand needs lemons and ice to make lemonade. The lollipop and comic are Liruf''s personal wants, not the stand''s.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["item-limones", "item-hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1292fe071b11a45a9a6ab4b80d9817f947306c215cfc8603a087998889f39a37.mp3", "hash": "a159bfe942396bc71a1273f70f1220c8b77514662eb7c1703fa68c7039a8bb01", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1292fe071b11a45a9a6ab4b80d9817f947306c215cfc8603a087998889f39a37.mp3", "duration_ms": 2880}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9de6cf66dba7bd5b7ba7676d49ce5a423deb39f4275f8f1ce95678ff8706fda2.mp3", "hash": "43e7fc1a57062e7d3d9815b625e09903a2f9603a73e42ac0fd977fa2232bec88", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9de6cf66dba7bd5b7ba7676d49ce5a423deb39f4275f8f1ce95678ff8706fda2.mp3", "duration_ms": 2640}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/650057264e33ad7b87480786f1276313bfc6f8ebac33e7409f9eb1847bd66520.mp3", "hash": "cca1b529536a1bc2fc66eae5ecf375701f79740a5376c9cc3ac59b09d6806da0", "bytes": 34416, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/650057264e33ad7b87480786f1276313bfc6f8ebac33e7409f9eb1847bd66520.mp3", "duration_ms": 5680}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/db7ecbd01b7eaffbf1746469245ce5c0f1abb43e1235aee596e2a70ed05fbc61.mp3", "hash": "04fe7e55ffb6aeb5b36b1160a7b596a97f76f820e82ac1a6bc6e5745273c65ea", "bytes": 42624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/db7ecbd01b7eaffbf1746469245ce5c0f1abb43e1235aee596e2a70ed05fbc61.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "quiz-mcq", "title": "Escolha o preço justo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o preço justo para um copo de limonada (5 reais) entre opções exageradas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Se o preço for muito alto, ninguém comprará. Se for muito baixo, Liruf não ganha nada.", "Pense em quanto custa fazer um copo de limonada: limões, água, açúcar."], "title": "A quanto o copo?", "payload": {"options": [{"id": "a", "text_md": "1 real", "rationale_md": "1 real é muito pouco: não dá nem para comprar os limões. Liruf perderia dinheiro."}, {"id": "b", "text_md": "5 reais"}, {"id": "c", "text_md": "50 reais", "rationale_md": "50 reais é muito caro para um copo de limonada. Quase ninguém compraria."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf define o preço do copo de limonada. Qual é justo para todos?", "difficulty": 1, "explanation_md": "O preço justo é 5 reais. Assim os clientes compram e Liruf ganha um pouco pelo seu trabalho.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "b"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/672f2ce1d14592bb91b612ca584d945785a7330d7b7b11c8a3506ebcc201ddb5.mp3", "hash": "5f7c044cd64cc092159284a9b07b7f1abd5a798d14dd76861aeb20cbd81897ba", "bytes": 43056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/672f2ce1d14592bb91b612ca584d945785a7330d7b7b11c8a3506ebcc201ddb5.mp3", "duration_ms": 7120}, "s1-precio-justo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/12ab6a0b383eaa5c7f6220e53f2693a4c9bd773dae8132879bc4d55551fd172d.mp3", "hash": "1a40a07feb24b20900a3e1f57d57ad39408f00a6e1c2e5e85280e3a2f9667e8a", "bytes": 35424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/12ab6a0b383eaa5c7f6220e53f2693a4c9bd773dae8132879bc4d55551fd172d.mp3", "duration_ms": 5840}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/f5a2ccc84d78042ba0f9696ced948c50b8554d4c74b310d5f0cb69054d53c091.mp3", "hash": "d1b6bb2c536c8b052f11bbd95dfc1d0a5d0fa65eea091cd576faabf61bded52a", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f5a2ccc84d78042ba0f9696ced948c50b8554d4c74b310d5f0cb69054d53c091.mp3", "duration_ms": 5440}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/b9be85ff811f09b491e859ef88b4d57b7b384beda58a9dd62e4de0b59fbc1229.mp3", "hash": "8522c20a78d3b6a606290197317dc9010dd449acd0981025b93ff44e1efd36be", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b9be85ff811f09b491e859ef88b4d57b7b384beda58a9dd62e4de0b59fbc1229.mp3", "duration_ms": 3840}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/a00a8288e46d85ed45f0907a08dbe07db90e977a4971aa0e792ae23a51cbdb99.mp3", "hash": "a2be099ecf5b789c1510a6dcb2fd6e0901784441ea7cceaf6c3c96ac068921dc", "bytes": 46368, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a00a8288e46d85ed45f0907a08dbe07db90e977a4971aa0e792ae23a51cbdb99.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "O cofrinho que agradece a paciência", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se deixar dinheiro em um cofrinho que dá moedinhas extras toda semana vale mais do que gastá-lo agora.", "Prever o total depois de esperar, entendendo que cresce um pouco, mas não dobra."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana o cofrinho dá 2 moedas de 1 real. Quantas moedas extras ele dá em 2 semanas?", "Começa com 20. Soma as moedinhas extras."], "title": "Deixar os 20 ou tirá-los agora?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Fica em 20"}, {"id": "opt2", "text_md": "24 reais"}, {"id": "opt3", "text_md": "Quase 40 reais"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tem 20 reais guardados para um violão que custa 80. Rho diz: ''Se você guardar seu dinheiro neste cofrinho especial, toda semana ele te dá 2 moedas de 1 real extra por deixá-lo lá.'' Liruf coloca seus 20 reais. Ele pensa: ''Se eu esperar 2 semanas, terei mais ou menos do que se gastar tudo agora?'' Quanto Liruf terá depois de 2 semanas?", "difficulty": 1, "explanation_md": "O cofrinho dá 2 moedas de 1 real por semana, então em 2 semanas dá 4 reais extras. 20 + 4 = 24. O dinheiro cresce pouquinho a pouquinho em direção ao violão! Se tivesse gasto tudo agora, não teria esses 4 reais extras.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "hash": "196538f34b2819eb47de5903748f77e7b49d10d4e2c8ca5d7ae70a964f276120", "bytes": 41184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "duration_ms": 6800}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "hash": "68205f29a78766e858fb87c5bed3698e0edd3e76f3e3815689d9c9fdf3bf0983", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "hash": "a49d13c1d700898ab76f3de6d66edef95a7a3fc75e1a1d6b73c925bba2331ffd", "bytes": 152064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "duration_ms": 25280}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "hash": "10d7c733f96ddee36b970195711bac0efc7e1d2b84b73366148a2065d5f44a1a", "bytes": 110736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "duration_ms": 18400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Yes or no: spending decisions", "locale": "en-US", "subject": "mixed", "objectives": ["Say yes or no, case by case: does this expense help the stand?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Think: does this help sell more lemonade or take care of the money?", "An expense that helps the stand lets you keep selling or sell more."], "title": "Yes or no: spending decisions", "payload": {"cases": [{"id": "case-1", "text_md": "Buying more lemons to make more lemonade.", "image_url": "http://localhost:4006/files/lesson-images/7116388b8a97cb793aa4ebd43f670702a976ee47d09101ac30bb91f04e4b5ea4.png"}, {"id": "case-2", "text_md": "Buying a new toy to play with at home.", "image_url": "http://localhost:4006/files/lesson-images/b95516e4a2eae2ecdc306aa78fe9e2f28734739093fbb2ca8612c1243672e29c.png"}, {"id": "case-3", "text_md": "Buying disposable cups to serve the lemonade.", "image_url": "http://localhost:4006/files/lesson-images/7dee596bc1df2670edf464c3114052383449a1c63228f57bdb33a15fd54967ae.png"}, {"id": "case-4", "text_md": "Buying a video game that just came out.", "image_url": "http://localhost:4006/files/lesson-images/d6fc07d08fda7f7225f084466259a8756ef7b6c53d6f4226bed0001ce9676941.png"}], "rule_md": "Say **yes** if the expense helps the lemonade stand (more lemons, more cups, fix something broken). Say **no** if it''s a treat that doesn''t help sell (a toy, a candy, a video game)."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf checks her list. Which expenses help the lemonade stand?", "difficulty": 1, "explanation_md": "Buying more lemons and cups helps the stand because without them there is no lemonade. The new toy doesn''t help today, because it''s not needed to sell.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case-1", "case-3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f601a4965d5c6aa4d894ac6a121f9ff61fe3431cda8717e7ee85c5f19b7c4b30.mp3", "hash": "34e3b1c6608b84152eeca85c61d16e91ee2913d4a15d40165b21ba4b7b84a0f9", "bytes": 23904, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f601a4965d5c6aa4d894ac6a121f9ff61fe3431cda8717e7ee85c5f19b7c4b30.mp3", "duration_ms": 3920}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b0a38988ba5491fdc093d6f5ad0df5c1d045cb41861cbd495e2e318500d5a557.mp3", "hash": "7143024c33afad285646fdf0a3b9b1ad1abd828b853cf427b01a367f905ed590", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b0a38988ba5491fdc093d6f5ad0df5c1d045cb41861cbd495e2e318500d5a557.mp3", "duration_ms": 3680}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/6b9c67e0bc8adf314e1d9abb6cd3b137bcfee43edbafff92aac0ca1b0a5e7266.mp3", "hash": "f5add00537ab430d6a13ded10807cdb5d0b3e7c961c1d507c9f5bb25c4ab029d", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6b9c67e0bc8adf314e1d9abb6cd3b137bcfee43edbafff92aac0ca1b0a5e7266.mp3", "duration_ms": 3760}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/8f5fc0e91b429ffb67d637e73c02af0d3d6d35359cd11f813fe4acfeccb984d8.mp3", "hash": "9943e33c20f4948cc8d28ea7362ff21e6cf99212812669e0302b99bdc3bcced3", "bytes": 52704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8f5fc0e91b429ffb67d637e73c02af0d3d6d35359cd11f813fe4acfeccb984d8.mp3", "duration_ms": 8720}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/6775584092410890f54941e0b1a6577d5d647f869310d9c488ebfd470cc46693.mp3", "hash": "1fba7360fcc4c84bd0f73722bb9a8cd847876de0427350255233499a8010587c", "bytes": 45936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6775584092410890f54941e0b1a6577d5d647f869310d9c488ebfd470cc46693.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'en-US', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "True or False? Savings that grow", "locale": "en-US", "subject": "mixed", "objectives": ["Decide if it''s true or false: ''If I save 5 dollars from each sale, my savings GROW every day.''"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Think: on Monday she saved 5, on Tuesday she saved another 5, on Wednesday another 5. Is the total more than at the beginning?"], "title": "True or false?", "payload": {"statement_md": "Zara saved 5 dollars each day for 3 days. Her savings grew.", "justifications": [{"id": "j-crece", "text_md": "Each day she added 5 new dollars, so the total increased."}, {"id": "j-no-crece", "text_md": "Each day she spent the 5 dollars she saved, so the total didn''t change."}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara sold lemonade for 3 days in a row and saved 5 dollars each day. Did her savings grow?", "difficulty": 1, "explanation_md": "Yes, her savings grew. Each day she added 5 new dollars: on Monday she had 5, on Tuesday 10, on Wednesday 15. Saving from each sale makes savings increase.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j-crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/343aad5129d886ea23b176ba0f7fa9d09b115e01cea5609b4e0093b79cc9b454.mp3", "hash": "d38659b23931b50ae0ea97aa3889eca3347745843b64d166916d48074cddbc7f", "bytes": 58464, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/343aad5129d886ea23b176ba0f7fa9d09b115e01cea5609b4e0093b79cc9b454.mp3", "duration_ms": 9680}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/923b579a33079759bea927a681c4032c14bd2ba25287788b4d0cf62f46cfe9bd.mp3", "hash": "b29ebf1a0c59e77e9a0ddc963b7a37ae5f9bd624471df7e3334b562912535af5", "bytes": 42624, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/923b579a33079759bea927a681c4032c14bd2ba25287788b4d0cf62f46cfe9bd.mp3", "duration_ms": 7040}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/e30853d1d6d3e840f18a1da846c0bf5e15f73ad91e24b8ea084c9bebce3040c7.mp3", "hash": "652f6ed4dcdd7342429d830b429869ea2c7ae2c3cf87aec3ec95e80cfe7626f3", "bytes": 68544, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/e30853d1d6d3e840f18a1da846c0bf5e15f73ad91e24b8ea084c9bebce3040c7.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimate glasses of lemonade", "locale": "en-US", "subject": "mixed", "objectives": ["Estimate amounts using a slider bar", "Develop number sense by estimating before counting"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jarra", "xp": 10, "type": "estimate_slider", "hints": ["Think about the size of the pitcher compared to a glass.", "It''s not 1 or 100, it''s between those two numbers."], "title": "How many glasses come out?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/323bf44f47a2502a0adc7c174b6215283d29f26e3eea18c5b7810580f6786b92.png", "prompt_md": "Without counting, slide to estimate: how many glasses of lemonade come out of this pitcher?", "difficulty": 1, "explanation_md": "The large pitcher fills about 8 glasses. Good eye for estimating!", "audio_segment_id": "s1-estimate-jarra.prompt"}], "schema_version": 1}', '{"s1-estimate-jarra": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0b26fff81c9260c623bd360e2c5d60e037e0b9a13b6444479558361bd9de2ae2.mp3", "hash": "3ac8bfb15ce80c864ab61c0fa983e5b73c3d812356815c6bc984e81eb7d15552", "bytes": 19584, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/0b26fff81c9260c623bd360e2c5d60e037e0b9a13b6444479558361bd9de2ae2.mp3", "duration_ms": 3200}, "s1-estimate-jarra.hint.1": {"url": "http://localhost:4006/files/lesson-audio/755bc119a6e64a3acf2da824bd50d77b42cbf2431bd7958fe82101774da073b3.mp3", "hash": "bc8a05bb96065e6b7e7a490857d2ff785b06def742033f806045d159fbd36be5", "bytes": 26208, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/755bc119a6e64a3acf2da824bd50d77b42cbf2431bd7958fe82101774da073b3.mp3", "duration_ms": 4320}, "s1-estimate-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/2f9111c39aff95b79ec0a4f795b32d9fa95a47ed70638334c4fdffd4e16630ec.mp3", "hash": "08285f451309932a08837a71762eb5db5364fec3d1e1f24ab5cb6589fdc90a16", "bytes": 32976, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/2f9111c39aff95b79ec0a4f795b32d9fa95a47ed70638334c4fdffd4e16630ec.mp3", "duration_ms": 5440}, "s1-estimate-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/a1c6028490599daa79708a7e90c2d22341f013828099e9755c6e26a956dc5060.mp3", "hash": "42b21484abfaa29b71f3a483bb9a6d098bb8612d045e9b232c2563cc34adb70d", "bytes": 29088, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a1c6028490599daa79708a7e90c2d22341f013828099e9755c6e26a956dc5060.mp3", "duration_ms": 4800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "Liruf''s Best Decision", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the best decision when a customer pays with a $20 bill for a $5 cup: counting the change calmly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cambio-correcto", "xp": 10, "type": "best_decision", "hints": ["The cup costs 5 dollars. If they pay with 20, how much change must he give back?", "Count the change slowly so you don''t make a mistake."], "title": "Liruf''s Change", "payload": {"options": [{"id": "contar-cambio", "text_md": "Count the change calmly: give 15 dollars", "rationale_md": "It is the best decision because Liruf gives the exact change and the customer trusts him."}, {"id": "adivinar-cambio", "text_md": "Guess the change quickly and give 10 dollars", "rationale_md": "Guessing might make you give too little change and the customer gets angry."}, {"id": "quedarse-dinero", "text_md": "Keep the whole bill and give no change", "rationale_md": "Keeping the whole bill is dishonest and the customer would lose their money."}], "scenario_md": "Liruf is nervous because the first customer pays with a $20 bill for a $5 cup. Which decision is best?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/97c6035d3a37490beee6e4a18287e125e1b2526515e2aed88a2d4069cf123052.png", "prompt_md": "A customer pays with a $20 bill for a $5 cup. What should Liruf do?", "difficulty": 1, "explanation_md": "Liruf must count the change calmly: 20 minus 5 is 15 dollars. That way he doesn''t make a mistake and the customer is happy.", "audio_segment_id": "s1-cambio-correcto.prompt"}], "schema_version": 1}', '{"s1-cambio-correcto": {"qualities": {"contar-cambio": 100, "adivinar-cambio": 30, "quedarse-dinero": 0}}}', '{"units": {"s1-cambio-correcto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4f1fc2ff7723180b0689a84f0af4f3d338ce0ea9c73a8e76777f035bb69e0c7a.mp3", "hash": "aca33d9d46a2e43a05156c4335369dc4841632751b7d9f9f50725de5cb2b0ce8", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4f1fc2ff7723180b0689a84f0af4f3d338ce0ea9c73a8e76777f035bb69e0c7a.mp3", "duration_ms": 4720}, "s1-cambio-correcto.hint.1": {"url": "http://localhost:4006/files/lesson-audio/19d63a7d99be4ddf4d6daeda337bca142862cba2dd06adf6647469f9548878d6.mp3", "hash": "eab2c65724f845cfd24f2973560a6355511d4d79da4c46ff46826d17dfdfcdc9", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/19d63a7d99be4ddf4d6daeda337bca142862cba2dd06adf6647469f9548878d6.mp3", "duration_ms": 2720}, "s1-cambio-correcto.prompt": {"url": "http://localhost:4006/files/lesson-audio/7ab470c566952e416940f1b64d0dc23aafa593784c6622cc1eb5eebbc3be42fd.mp3", "hash": "b3095b2b027c5bdced75d685932a4dc7ba666f1cb8d5291aa178470ad831a57e", "bytes": 29088, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7ab470c566952e416940f1b64d0dc23aafa593784c6622cc1eb5eebbc3be42fd.mp3", "duration_ms": 4800}, "s1-cambio-correcto.choices": {"url": "http://localhost:4006/files/lesson-audio/1b0872a20a0e083624003a1960276496ab9d84cb5e0f486c21bc1cff5628a617.mp3", "hash": "cf90e360c9faa85d3351470ceadfab94e560b0fd85971f2352c7c85076e866a6", "bytes": 44496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1b0872a20a0e083624003a1960276496ab9d84cb5e0f486c21bc1cff5628a617.mp3", "duration_ms": 7360}, "s1-cambio-correcto.explanation": {"url": "http://localhost:4006/files/lesson-audio/25f5049be31313e081792747f5e6a948daaa21245bef016d6397d29f32b3b7c7.mp3", "hash": "67b00919e2542380cdaea1ea5a74bfc22adbb4b3eca7f24993beb22cae78c0ae", "bytes": 45504, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/25f5049be31313e081792747f5e6a948daaa21245bef016d6397d29f32b3b7c7.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "speed-tap", "title": "Decisões rápidas de limonada", "locale": "pt-BR", "subject": "money", "objectives": ["Distinguir gastos que ajudam a barraca de limonada de caprichos que não ajudam."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 10, "type": "speed_tap", "hints": ["Pense: isso ajuda a fazer ou vender limonada?", "Caprichos como brinquedos não ajudam a vender."], "title": "Pegue o que ajuda!", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/e11316191c8470f48b2d250db7dfc79a138be39d213fc9b99ea4b43eca34c197.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/bf0ee5b3320f89a841ea9ccebecaa4a8e4e8a53864e2c6a136f83708867946ae.png"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/12214baaf04374245a70ee947fd461337f1197bb4266461566521500a027b89b.png"}, {"id": "hielo", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/ec00bd6d1f3a665052b7297a85cfa3157ee40e3932a9d2c3754f70185dcdfc6e.png"}, {"id": "cartel", "text_md": "Cartaz chamativo", "image_url": "http://localhost:4006/files/lesson-images/47254310a6145c7b684b1c2a75a364e152cc3ac8bea4c6bf103a5129c73a0523.png"}, {"id": "calcomania", "text_md": "Adesivo de dinossauro"}, {"id": "dulce", "text_md": "Doce", "image_url": "http://localhost:4006/files/lesson-images/3efbf49d870a4704ce5b973490a44b017dca9e04d43dec80898b5b955869a669.png"}, {"id": "juguete", "text_md": "Brinquedo", "image_url": "http://localhost:4006/files/lesson-images/4c5e4dd34f60ed08c257fc3c232cac2d983c0f54a527b09a29e778fac53d4243.png"}], "seconds": 15, "instruction_md": "Toque nos cartões que ajudam a barraca de limonada."}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho passa voando com cartões. Toque apenas nos que ajudam a vender mais limonada.", "difficulty": 1, "explanation_md": "Limões, copos, açúcar, gelo e cartaz ajudam a vender mais limonada. O adesivo, o doce e o brinquedo são caprichos que não ajudam.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5dadbeae5fc533937b06fd5dd975acbd9b71798c8a6d88cba623c0c059b8a1b6.mp3", "hash": "645def84edd1185cdbd851d0dca18b00d2b3c23ee3f4456994719952c73a0791", "bytes": 21456, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/5dadbeae5fc533937b06fd5dd975acbd9b71798c8a6d88cba623c0c059b8a1b6.mp3", "duration_ms": 3520}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2df645585c72385d9964b9cd45b68766664ebd3b1ff1441db55114e66f4072a2.mp3", "hash": "1732f9117d5c5113bfd793a2d8c2f9e68aa1d34ce46a01f320a45dca939ee623", "bytes": 19008, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2df645585c72385d9964b9cd45b68766664ebd3b1ff1441db55114e66f4072a2.mp3", "duration_ms": 3120}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/5ae2638830d6162da794826d464c3a318163cd672fdd1f0d444c95521113b582.mp3", "hash": "06b18668ce8d1fe83e94527beeeacfc073c5332152f654de6d655bfd98fa541d", "bytes": 39744, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/5ae2638830d6162da794826d464c3a318163cd672fdd1f0d444c95521113b582.mp3", "duration_ms": 6560}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/47daacacbefad46e7c54e2dc5cf53249081e61dc46cac2bc0fb92ec79e6f36eb.mp3", "hash": "43892514f0da9bfae27b2298e490128632c134cfac44e42c15a8083a15073a28", "bytes": 67536, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/47daacacbefad46e7c54e2dc5cf53249081e61dc46cac2bc0fb92ec79e6f36eb.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Cerrar el puesto: todo junto", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar pagos con su cambio correcto", "Ordenar los pasos para calcular la ganancia", "Separar necesidades de deseos para el puesto", "Ordenar eventos del día para mantener cambio disponible"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["Si pagan con 10, el cambio es 10 menos 5.", "Calcula cuánto sobra de cada pago después de pagar un vaso."], "title": "Cambio para cada pago", "payload": {"left": [{"id": "pago-10", "text_md": "Paga con 10", "image_url": "http://localhost:4006/files/lesson-images/6b9c6054d2f2cb5fd85e29ca79792ae68693c809b6787bf1994088eb922e4655.png"}, {"id": "pago-20", "text_md": "Paga con 20", "image_url": "http://localhost:4006/files/lesson-images/99656ef5ed168dcf85250f42ddfe6d6d0f9fc1ddcd93c2475ac38ca4a9460d5d.png"}, {"id": "pago-6", "text_md": "Paga con 6", "image_url": "http://localhost:4006/files/lesson-images/aeec6bf1b72808975f318aa8c833103bce68f3228b8b26bcfc43f6ab56bd8a13.png"}], "right": [{"id": "cambio-5", "text_md": "Cambio: 5"}, {"id": "cambio-15", "text_md": "Cambio: 15"}, {"id": "cambio-1", "text_md": "Cambio: 1"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toca cada pago con su cambio correcto. Un vaso cuesta 5 pesos.", "difficulty": 2, "explanation_md": "Con 10 pesos pagas 5 y sobran 5; con 20 sobran 15; con 6 sobra 1.", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["Antes de contar lo ganado, hay que apartar lo que costó hacer la limonada.", "La ganancia es lo que queda después de restar el costo."], "title": "Orden para sacar la ganancia", "payload": {"items": [{"id": "costo", "text_md": "Apartar el costo (limones y vasos)", "image_url": "http://localhost:4006/files/lesson-images/50fe0e2e00f4386265612bb9cb76c46de406aa9b5abab7323cd82a878f468b84.png"}, {"id": "restar", "text_md": "Restar el costo del total de ventas", "image_url": "http://localhost:4006/files/lesson-images/1884858db6af1b8753668271f1e71f1424a4e58fdf032288963e531af0b72674.png"}, {"id": "ganancia", "text_md": "Esa resta es la ganancia", "image_url": "http://localhost:4006/files/lesson-images/c7c5191cfa33c757d95cb55f2d30694768bfcd81afcd1979b25bf488ba8d31c9.png"}], "slots": 3}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ordena los pasos para saber cuánto ganó Liruf hoy. Primero aparta el costo.", "difficulty": 2, "explanation_md": "Primero apartas el costo de los limones y vasos, luego restas eso del total de ventas, y así sabes la ganancia.", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Sin limones y vasos no se puede vender limonada.", "El hielo y las calcomanías son deseos, no urgentes."], "title": "Lo que el puesto necesita", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/1a79393fdfd9ebf2dc3b5467e6b5f909af13158f8d4677fa18f6163e747c6d60.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/8c2db28f7ac626bfcabf6d83d6e2aa1e0519ce6b66f57b43dfa5ddffb0dcce05.png"}, {"id": "hielo", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/02c5d54877f2e69e5d811824e43bcacb9df284d38b471fbb34985f8d4ea3e4c2.png"}, {"id": "calcomania", "text_md": "Calcomanía", "image_url": "http://localhost:4006/files/lesson-images/f796d3632b6706abd04d457aac2688def2dbd954a41d667c2f3bf95c48a3bb19.png"}], "buckets": [{"id": "necesita", "label": "Necesita para abrir"}, {"id": "esperar", "label": "Puede esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Con solo 20 pesos, separa lo que el puesto NECESITA para abrir mañana de lo que puede esperar.", "difficulty": 2, "explanation_md": "Liruf necesita limones y vasos para vender; el hielo y las calcomanías pueden esperar.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-cambio", "xp": 25, "type": "timeline_order", "hints": ["Si primero gastas cambio y luego recibes, te quedas sin cambio.", "Una venta debe ocurrir antes de un gasto que necesite cambio."], "title": "El día sin quedarse sin cambio", "payload": {"events": [{"id": "venta-10", "icon": "payments", "text_md": "Cliente paga con 10", "image_url": "http://localhost:4006/files/lesson-images/171752821ebbae9a81ff7ca0a83f9d43a4c81f9e7e3e9c789969cdf2f7c10dae.png"}, {"id": "cambio-5", "icon": "currency_exchange", "text_md": "Dar cambio de 5", "image_url": "http://localhost:4006/files/lesson-images/7c1f27ebacabf960ff949158dba8d498dd1735059394dc7220fa769de2874028.png"}, {"id": "gasto-2", "icon": "local_atm", "text_md": "Gastar 2 en hielo", "image_url": "http://localhost:4006/files/lesson-images/e894cd62af0b7283431713423e3f5a8cb932d13536527a65ec8fd30a2773d5b6.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ordena los eventos del día para que la caja nunca se quede sin cambio. Un vaso cuesta 5 pesos.", "difficulty": 3, "explanation_md": "Liruf primero recibe 10 pesos de una venta, luego da cambio de 5, y al final gasta 2 en hielo. Así nunca falta cambio.", "audio_segment_id": "s4-timeline-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["pago-10", "cambio-5"], ["pago-20", "cambio-15"], ["pago-6", "cambio-1"]]}, "s2-order-ganancia": {"order": ["costo", "restar", "ganancia"]}, "s4-timeline-cambio": {"order": ["venta-10", "cambio-5", "gasto-2"]}, "s3-sort-necesidades": {"assignments": {"hielo": "esperar", "vasos": "necesita", "limones": "necesita", "calcomania": "esperar"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b05d10d1483e6a498fa1c71e6172b732bb2cc8a9c33e5e7d1e84de92666a33d8.mp3", "hash": "b0c8736cae403e327bd95bb88205f90038e6ec2e1e78615c6e3363306d0c67ec", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b05d10d1483e6a498fa1c71e6172b732bb2cc8a9c33e5e7d1e84de92666a33d8.mp3", "duration_ms": 3760}, "s1-match-cambio.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a18bd1a3062b9fe997eef4ce2081028d410bf8033124e74ac2d200925914681b.mp3", "hash": "a84e3693989569b8dcb597233d5a9f10d284a7f4743b259f8432bf49f5f235d2", "bytes": 23904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a18bd1a3062b9fe997eef4ce2081028d410bf8033124e74ac2d200925914681b.mp3", "duration_ms": 3920}, "s1-match-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/a65d4c2b22423ea9117a03a9fe28d10b845d21aacb71d271714297f28ec313db.mp3", "hash": "3a5a932a69e1e1b5a1950fda759a2a26a338f8d052119ac56f1982b8f6642618", "bytes": 29088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a65d4c2b22423ea9117a03a9fe28d10b845d21aacb71d271714297f28ec313db.mp3", "duration_ms": 4800}, "s2-order-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/61e96c943612025b22212b548fcbf3194aa436dc99a1be57a2e58a3d17fe4e0d.mp3", "hash": "c7888415961ac24fe082f80c4e6931e0af6c07b604e00a6a37688fe47940f80a", "bytes": 29088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/61e96c943612025b22212b548fcbf3194aa436dc99a1be57a2e58a3d17fe4e0d.mp3", "duration_ms": 4800}, "s2-order-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f331c52b24d0d4cbe3de954979bed27dfdfc5c340ac03adbd0cf363853a70647.mp3", "hash": "5cdb3da79039ce137f24e1324e2d4e76e00b4392f1ec940bbc4d72a9a9aceba8", "