INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Close the stand: all together", "locale": "en-US", "subject": "mixed", "objectives": ["Match payments with their correct change", "Order the steps to calculate profit", "Separate needs from wants for the stand", "Order the day''s events to keep change available"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-cambio", "xp": 15, "type": "match_pairs", "hints": ["If they pay with 10, the change is 10 minus 5.", "Calculate how much is left from each payment after paying for one cup."], "title": "Change for each payment", "payload": {"left": [{"id": "pago-10", "text_md": "Pay with 10", "image_url": "http://localhost:4006/files/lesson-images/844d22a753dc620ab20c11e0cb73e87c4ccdbfd3599982c5d31467ddc3fa4bb0.png"}, {"id": "pago-20", "text_md": "Pay with 20", "image_url": "http://localhost:4006/files/lesson-images/bc71089d61502942bf5543b3aa1d45852033f29127f0b8534c980d3057efeb08.png"}, {"id": "pago-6", "text_md": "Pay with 6", "image_url": "http://localhost:4006/files/lesson-images/6fc95be40340258b37e5e42e38ba08a1cf8bcb3438fa868be5390cfae57855ee.png"}], "right": [{"id": "cambio-5", "text_md": "Change: 5"}, {"id": "cambio-15", "text_md": "Change: 15"}, {"id": "cambio-1", "text_md": "Change: 1"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Tap each payment with its correct change. One cup costs 5 dollars.", "difficulty": 2, "explanation_md": "With 10 dollars you pay 5 and have 5 left; with 20 you have 15 left; with 6 you have 1 left.", "audio_segment_id": "s1-match-cambio.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["Before counting what you earned, you must set aside what it cost to make the lemonade.", "Profit is what remains after subtracting the cost."], "title": "Order to find profit", "payload": {"items": [{"id": "costo", "text_md": "Set aside the cost (lemons and cups)"}, {"id": "restar", "text_md": "Subtract the cost from total sales", "image_url": "http://localhost:4006/files/lesson-images/64064701920c31db38643184c7e3d847d0dc953ea581952a048d52114d72e2c6.png"}, {"id": "ganancia", "text_md": "That subtraction is the profit", "image_url": "http://localhost:4006/files/lesson-images/5b623bc1218201372af288d5a6548419e583e9c1393c9af6c9e9878706004ea9.png"}], "slots": 3}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Order the steps to know how much Liruf earned today. First set aside the cost.", "difficulty": 2, "explanation_md": "First you set aside the cost of lemons and cups, then subtract that from total sales, and that''s how you know the profit.", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Without lemons and cups you can''t sell lemonade.", "Ice and stickers are wants, not urgent."], "title": "What the stand needs", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/9094506ed05b5ef161ce5249f1cedde5d367436a5e7c25927dd5105ce5b01449.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/3a0d85ca261147a38fff307e69690522fe48eb93e9edf8a398e19a8932f82d0b.png"}, {"id": "hielo", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/149d99ebd4742635ddd5a68b1fa0b622c05459d1450d22de7bc71036a3e29997.png"}, {"id": "calcomania", "text_md": "Sticker", "image_url": "http://localhost:4006/files/lesson-images/93b6ae8f3154faa13d3b6e28bca87389693e03e8b8b007f42dd5daa650c0f023.png"}], "buckets": [{"id": "necesita", "label": "Needs to open"}, {"id": "esperar", "label": "Can wait"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "With only 20 dollars, separate what the stand NEEDS to open tomorrow from what can wait.", "difficulty": 2, "explanation_md": "Liruf needs lemons and cups to sell; ice and stickers can wait.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-cambio", "xp": 25, "type": "timeline_order", "hints": ["If you first spend change and then receive it, you run out of change.", "A sale must happen before an expense that needs change."], "title": "The day without running out of change", "payload": {"events": [{"id": "venta-10", "icon": "payments", "text_md": "Customer pays with 10", "image_url": "http://localhost:4006/files/lesson-images/9b2718a3347bc32aba6750c3b3b4298bc228a230c3ac4370f7b56340986ea402.png"}, {"id": "cambio-5", "icon": "currency_exchange", "text_md": "Give 5 change", "image_url": "http://localhost:4006/files/lesson-images/6291977f5c8ac786485011a3c6d4ab7a209d3f8d0b9299b8269040c91e539472.png"}, {"id": "gasto-2", "icon": "local_atm", "text_md": "Spend 2 on ice", "image_url": "http://localhost:4006/files/lesson-images/80c24c240c7c04dd352f51f195f07e2709dd6537975791e5e76cc70d36a7c823.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Order the day''s events so the cash box never runs out of change. One cup costs 5 dollars.", "difficulty": 3, "explanation_md": "Liruf first receives 10 dollars from a sale, then gives 5 change, and finally spends 2 on ice. That way change never runs out.", "audio_segment_id": "s4-timeline-cambio.prompt"}], "schema_version": 1}', '{"s1-match-cambio": {"pairs": [["pago-10", "cambio-5"], ["pago-20", "cambio-15"], ["pago-6", "cambio-1"]]}, "s2-order-ganancia": {"order": ["costo", "restar", "ganancia"]}, "s4-timeline-cambio": {"order": ["venta-10", "cambio-5", "gasto-2"]}, "s3-sort-necesidades": {"assignments": {"hielo": "esperar", "vasos": "necesita", "limones": "necesita", "calcomania": "esperar"}}}', '{"units": {"s1-match-cambio.hint.0": {"url": "http://l