INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "odd-one-out", "title": "The strange ingredient", "locale": "en-US", "subject": "mixed", "objectives": ["Identify which items are not lemonade ingredients and therefore do not cost money to produce."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Think about what you need to make lemonade: lemons, water, sugar...", "You don''t eat or drink a ball, it doesn''t go in lemonade."], "title": "The strange ingredient", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/b286fdda092869c12f3b1b832c418599018cc556114e091c227b1391721183e3.png"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/c3c7f4d9b4c02cc1e8b7d8bcc17644342c8616819011f839471ab18e12a16d0a.png"}, {"id": "agua", "text_md": "Water", "image_url": "http://localhost:4006/files/lesson-images/a1ae5c67a9aa23375f7c45c340e67b5682f7d51ff76b185456ada0561a8700d8.png"}, {"id": "pelota", "text_md": "Ball", "image_url": "http://localhost:4006/files/lesson-images/a46a8130fd625c97a6ff98d07e51306be464e56d1835308c5dc98bd3e2544dd9.png"}], "reasons": [{"id": "r1", "text_md": "It is not a lemonade ingredient."}, {"id": "r2", "text_md": "It is a lemonade ingredient."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho checks the shopping list. Which thing is NOT a lemonade ingredient?", "difficulty": 1, "explanation_md": "The ball is not a lemonade ingredient, so it doesn''t cost money to produce. Lemons, sugar, and water are ingredients that do cost money.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c4aeb307468abc815abfa4cebaaf32b95ae01fa0543d81f7c5498de09d805838.mp3", "hash": "5ca1ca52aa7dd3ab5ed4083ba81fad83d4042f2fb5cd34f0febb483e8a3969ef", "bytes": 28656, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c4aeb307468abc815abfa4cebaaf32b95ae01fa0543d81f7c5498de09d805838.mp3", "duration_ms": 4720}, "s1-odd-one-out.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2a282ac0a7538d5cc2a8330f96fba913af0ed58414e6ec48175035fd6ff16270.mp3", "hash": "351895c896c81bb3dd714a4048a26da1a280747f6db5660da08e652640236222", "bytes": 23328, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2a282ac0a7538d5cc2a8330f96fba913af0ed58414e6ec48175035fd6ff16270.mp3", "duration_ms": 3840}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/fe4ce5b3abfc2a2f1abec1e3729e86628dc49bc3daa3153ea5d8f78635d1023d.mp3", "hash": "232d379a19165134307b062a9d62cf3453217b779ec737b166104e6a37e8e69f", "bytes": 30096, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/fe4ce5b3abfc2a2f1abec1e3729e86628dc49bc3daa3153ea5d8f78635d1023d.mp3", "duration_ms": 4960}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/9c66aa0295465cf323bdb96db67d7d3f355b837b2e587117d74f2fc8d91fdde2.mp3", "hash": "3e8da1da7d919271b370b33b88cfc47018742bcaa3fbd0da086a2edd01cca212", "bytes": 17136, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9c66aa0295465cf323bdb96db67d7d3f355b837b2e587117d74f2fc8d91fdde2.mp3", "duration_ms": 2800}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/2d24f9577017d390a216582ad16fcc8e37ddd23c8da0b1bec5ede3d17e4a3740.mp3", "hash": "6501b80c4d18fd497aafbdcd048d1c29116bce65301ff9e585101815c31ee9b2", "bytes": 59904, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2d24f9577017d390a216582ad16fcc8e37ddd23c8da0b1bec5ede3d17e4a3740.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'pt-BR', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "true-false", "title": "Certo ou Falso? A poupança que cresce", "locale": "pt-BR", "subject": "mixed", "objectives": ["Decidir se é certo ou falso: ''Se eu guardo 5 reais de cada venda, minha poupança CRESCE a cada dia''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Pense: na segunda-feira ela guardou 5, na terça-feira guardou outros 5, na quarta-feira outros 5. O total é maior do que no começo?"], "title": "Certo ou falso?", "payload": {"statement_md": "Zara guardou 5 reais cada dia por 3 dias. A poupança dela cresceu.", "justifications": [{"id": "j-crece", "text_md": "Cada dia ela somou 5 reais novos, então o total aumentou."}, {"id": "j-no-crece", "text_md": "Cada dia ela gastou os 5 reais que guardou, então o total não mudou."}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Zara vendeu limonada 3 dias seguidos e guardou 5 reais cada dia. A poupança dela cresceu?", "difficulty": 1, "explanation_md": "Sim, a poupança dela cresceu. Cada dia ela somou 5 reais novos: na segunda-feira tinha 5, na terça-feira 10, na quarta-feira 15. Guardar de cada venda faz a poupança aumentar.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j-crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/48b78ee912fc616748af3180ec5a624295d12de59515a586aa2b7f4380f2972f.mp3", "hash": "fb272ef62c8bc3259122df325ccc92fda70c51cac8ae337df068262fd5ba57b8", "bytes": 58464, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/48b78ee912fc616748af3180ec5a624295d12de59515a586aa2b7f4380f2972f.mp3", "duration_ms": 9680}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/0233ca95b0c75a1264e76d501c38d868cc60bba653b39409b2ef6d6b00cd55ca.mp3", "hash": "1e9d8571d54c4985b9b4ce17436360fac1fef6e7fdb8b78853382fd810415356", "bytes": 45504, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/0233ca95b0c75a1264e76d501c38d868cc60bba653b39409b2ef6d6b00cd55ca.mp3", "duration_ms": 7520}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/282baff46687164afa47c4ce5e31c425a9bd25a2b71652058cee8e90b026a689.mp3", "hash": "40322d7a40c05158564c113809b30169e86e0d22a9e206214413356396706df6", "bytes": 84816, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/282baff46687164afa47c4ce5e31c425a9bd25a2b71652058cee8e90b026a689.mp3", "duration_ms": 14080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Agrupa o dinheiro do caixa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar passos, combinar produtos com preços e classificar compras entre necessidades da barraca e desejos que podem esperar.", "Agrupar o dinheiro do caixa: moedas com moedas e notas com notas, para contar mais fácil."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 10, "type": "group_sets", "hints": ["As moedas são redondas e de metal, as notas são de papel.", "Procure o grupo que diz ''Moedas'' e o que diz ''Notas''."], "title": "Agrupa o dinheiro", "payload": {"items": [{"id": "item1", "text_md": "Moeda de R$1", "image_url": "http://localhost:4006/files/lesson-images/265149f2252c753251c8c971468f1c11f245492dca2e06fbea46374cccde8f47.png"}, {"id": "item2", "text_md": "Moeda de R$5", "image_url": "http://localhost:4006/files/lesson-images/fb98a720349fe00fe342113b658060f325d26bfa690f89d92bd15baa5ab08ff8.png"}, {"id": "item3", "text_md": "Moeda de R$10", "image_url": "http://localhost:4006/files/lesson-images/3032e63a2c95e64941b8f1c863ac143ce0b0bfc638ed0b7e59d521bea6d45824.png"}, {"id": "item4", "text_md": "Nota de R$20"}, {"id": "item5", "text_md": "Nota de R$50"}, {"id": "item6", "text_md": "Nota de R$100"}], "set_a": "Moedas", "set_b": "Notas"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toque em cada moeda ou nota e coloque no grupo correto.", "difficulty": 1, "explanation_md": "As moedas vão com moedas e as notas com notas, assim é mais fácil contar quanto dinheiro você tem.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b", "item6": "b"}}}', '{"units": {"s1-group-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8d3263ea2cc78e9077a85b61da7f5fa1bacf8f4b288467729b31a73bfd800468.mp3", "hash": "c3eb8b8dfebb4135cc7460682eccb8030da94425aad3e5f171249e6619634793", "bytes": 26208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8d3263ea2cc78e9077a85b61da7f5fa1bacf8f4b288467729b31a73bfd800468.mp3", "duration_ms": 4320}, "s1-group-money.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c3ae388c4fb484d67e7e0c0003d59a828e65811492f9c56fb7ae900f30e8b1c2.mp3", "hash": "f918f6569c06624081d0455f66a200acd5a343c3e131c7ddd5025a1b0dbf0974", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c3ae388c4fb484d67e7e0c0003d59a828e65811492f9c56fb7ae900f30e8b1c2.mp3", "duration_ms": 4160}, "s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/1db9750b8f71ca17446b4f3300bef1b0d6032a3453fbba6219ef56d913b6acb7.mp3", "hash": "7c3e592d880bbef89759c4a09f02b58c5050c90252ea62bc4d3135f002652608", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1db9750b8f71ca17446b4f3300bef1b0d6032a3453fbba6219ef56d913b6acb7.mp3", "duration_ms": 4160}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/bd0f93a35ab36cc9db0ab56978177a15206b66768323f9f5e2e89bb97e127ed6.mp3", "hash": "aa7346b3800e5aa4e920a487d803e392012b5cad45a6bfb8bd091df6bb008aad", "bytes": 44496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bd0f93a35ab36cc9db0ab56978177a15206b66768323f9f5e2e89bb97e127ed6.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Emparelhe os preços da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Emparelhar produtos com seus preços exatos usando moedas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 10, "type": "memory_flip", "hints": ["Lembre-se: o biscoito custa 3 moedas, o copo pequeno 5, e a jarra grande 20."], "title": "Memória de preços", "payload": {"pairs": [{"a_md": "Biscoito", "b_md": "3 reais (1+2)", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/2ac15f9b207c4be166502b1979c9e3a45edc259af5e60111ef5cfb52a8c57fd8.png", "b_image_url": "http://localhost:4006/files/lesson-images/5b03a040e5c1b67fe6414ed9ae88886601840d6a4249dc78adfa55a8a45f24fc.png"}, {"a_md": "Copo pequeno", "b_md": "5 reais", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/e6a4e9a95c1ff3666c647a1d4dc49d68dbe6409a8c541aa262f5be269b82bf0e.png", "b_image_url": "http://localhost:4006/files/lesson-images/54522151bc48a76c0dc4d258aa9f0b475cdd286affe496556b6a82500df8742c.png"}, {"a_md": "Jarra grande", "b_md": "20 reais (10+10)", "a_icon": "local_bar", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/a6d12279f5517ba82361dbd32d6eac734aa351529ca9c96c5da0d81a7db27e69.png", "b_image_url": "http://localhost:4006/files/lesson-images/fdcbac21b05e8107452923230b198536dedae4c9bc9f04f5a3339ca51bb877b2.png"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Toque nas cartas para emparelhar cada produto com seu pagamento exato. Biscoito = 3, copo pequeno = 5, jarra grande = 20.", "difficulty": 1, "explanation_md": "Cada produto tem um preço fixo: biscoito 3, copo pequeno 5, jarra grande 20. Assim Liruf pode cobrar rápido!", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/182ef9156c03737ba78d4dbe3334cb82911781413174c72d5a8b5b8a5ea0b8b4.mp3", "hash": "2a6d370558f88de95e04b74d2439bb96e63e20641eea2b0d9a4f143a093174f3", "bytes": 38304, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/182ef9156c03737ba78d4dbe3334cb82911781413174c72d5a8b5b8a5ea0b8b4.mp3", "duration_ms": 6320}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/2f81f020cccaca6f9042fd987e91d2ef94a095147ed1448531e7b55026e5e634.mp3", "hash": "35206717dda382694944438ab6d1704d711b0fcee2b88fa370d6e24d690bfb30", "bytes": 60336, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/2f81f020cccaca6f9042fd987e91d2ef94a095147ed1448531e7b55026e5e634.mp3", "duration_ms": 10000}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/6173aa1b2d06f991cc24eebff816d237f0d1a5c13baf6680e187153268719ada.mp3", "hash": "abccede267ea89e22f9c3ae08431693183f52f626e75d61f7280d3df96d92b9e", "bytes": 52128, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/6173aa1b2d06f991cc24eebff816d237f0d1a5c13baf6680e187153268719ada.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparar precios de limones", "locale": "es-MX", "subject": "money", "objectives": ["Comparar precios de limones en dos puestos del mercado y elegir el más barato para gastar menos (costo más bajo = más ganancia)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Mira cuánto cuestan 5 limones en cada puesto.", "Resta el precio de los limones de tus $15 para ver cuánto te sobra."], "title": "¿Cuál puesto de limones es más barato?", "payload": {"offers": [{"id": "puesto-liruf", "qty": 5, "unit": "limones", "label": "Puesto de Liruf", "price": 10, "image_url": "http://localhost:4006/files/lesson-images/6102e577e581f07a2264965d35b49ae34acc308b7ecf552899efb3cf3954c4c6.png"}, {"id": "puesto-otro", "qty": 5, "unit": "limones", "label": "Otro puesto", "price": 15, "image_url": "http://localhost:4006/files/lesson-images/12d2aa073c68b09bf28c3d25a75dc418b592c21f790442cb41e2b4768dfd946d.png"}], "currency": "MXN"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Tienes $15. ¿En qué puesto te sobra más dinero si compras 5 limones?", "difficulty": 1, "explanation_md": "En el puesto de Liruf, 5 limones cuestan $10. Te sobran $5. En el otro puesto, cuestan $15, no te sobra nada. ¡Elegir el más barato te deja dinero para tu alcancía!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-liruf"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a5ba43b0a8d2a045028a2d2b04e3dd0cbba92773f168b00d2a655f039fb2d71f.mp3", "hash": "29144dda0e45d641acc352ba3d0b08b8463445a60171f100a0446b7ac1a317a8", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a5ba43b0a8d2a045028a2d2b04e3dd0cbba92773f168b00d2a655f039fb2d71f.mp3", "duration_ms": 3600}, "s1-price-compare.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2feefe5f0927d5c9764443bcb10779978df40771e4f9192703a980a747af05a6.mp3", "hash": "11702c5f7023917a143b659402ebdcbeb6863dfc62d0ad48a4138f895845f369", "bytes": 29088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2feefe5f0927d5c9764443bcb10779978df40771e4f9192703a980a747af05a6.mp3", "duration_ms": 4800}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/d7da4d0b9f97ed6d02f53d35f5ee58b5617f8828d322ff59df69f82882dbc7cc.mp3", "hash": "32e463f779bf199cd58b587def69723c78a0bf698c795c8e537e032a8c6b5684", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d7da4d0b9f97ed6d02f53d35f5ee58b5617f8828d322ff59df69f82882dbc7cc.mp3", "duration_ms": 5600}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/caaa1f261e017383bebea7993bfd8f7c7d21ef135473100644c80180e5e666e0.mp3", "hash": "114ec96343fc735c9a8ed49620d01a202dafc917b94a335aee0e8d351b903c87", "bytes": 81936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/caaa1f261e017383bebea7993bfd8f7c7d21ef135473100644c80180e5e666e0.mp3", "duration_ms": 13600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "rank-choices", "title": "Prioridades en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar de más a menos urgente en qué gastar la ganancia de hoy: reponer limones primero, luego vasos, y al final adornos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 10, "type": "rank_choices", "hints": ["Sin limones no se puede hacer limonada.", "Los adornos son bonitos, pero no urgentes."], "title": "¿Qué comprar primero?", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/8c4be1fc65fc29b73be9ede7f6eec9c3d642f4d580cf16d03dbf11fef444a8e5.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/1ee79e2fdae1015823bf2c2f21c2f5063f2704f769fdcb5999312dca301b8512.png"}, {"id": "adornos", "text_md": "Adornos", "image_url": "http://localhost:4006/files/lesson-images/05a6fb990cbedc3b9984718b29edf6997f0b2d61b59aadfdc8dd4205401c236f.png"}], "criterion_md": "Urgencia para el puesto: lo que más necesitas hoy va primero."}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Ordena las compras de más urgente a menos urgente para el puesto de Liruf.", "difficulty": 1, "explanation_md": "Los limones son lo más urgente porque sin ellos no hay limonada. Los vasos son necesarios para servir. Los adornos pueden esperar.", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank-choices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7a97c355d7ad3cc3ca1b2d0f077dc2d8eb327ab3e756ee38948e7a6122a27b69.mp3", "hash": "292ff0d0449c959693d34fdc780687d1607106059107a75653c7fb1e5f59ac35", "bytes": 17136, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7a97c355d7ad3cc3ca1b2d0f077dc2d8eb327ab3e756ee38948e7a6122a27b69.mp3", "duration_ms": 2800}, "s1-rank-choices.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a0b11c43278aff16d061737a907106a1d865cea372917910462af84fc2571bbe.mp3", "hash": "f6629c0f626570421e4483e6bd1a8d40d4de73e1304fac01ef7b916d871dc9e9", "bytes": 20016, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/a0b11c43278aff16d061737a907106a1d865cea372917910462af84fc2571bbe.mp3", "duration_ms": 3280}, "s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/5b200e254b29631a38f4c8226a83e4dd4471f55c63eaa715ea226ca8eb9c4d20.mp3", "hash": "84a3b149887dfeb6ddbfa8269fb74986e1c62e0388522f5de22c4af0e3a5dd36", "bytes": 29088, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5b200e254b29631a38f4c8226a83e4dd4471f55c63eaa715ea226ca8eb9c4d20.mp3", "duration_ms": 4800}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/a582563408c5735226ebe572bb316b7c4f359b72942ebb8b2d2945977e55cdd1.mp3", "hash": "55ee0d269a30378f2ef454df525250e1052930feca19f13f2f72ae085127098a", "bytes": 58464, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/a582563408c5735226ebe572bb316b7c4f359b72942ebb8b2d2945977e55cdd1.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Compare lemon prices", "locale": "en-US", "subject": "money", "objectives": ["Compare lemon prices at two market stalls and choose the cheapest one to spend less (lower cost = more profit)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Look at how much 5 lemons cost at each stall.", "Subtract the price of the lemons from your $15 to see how much you have left."], "title": "Which lemon stall is cheaper?", "payload": {"offers": [{"id": "puesto-liruf", "qty": 5, "unit": "limones", "label": "Liruf''s stall", "price": 10, "image_url": "http://localhost:4006/files/lesson-images/a986ee39fd32c817b4d9cf14311aa9f51d758e481f40f5090c5fee94524674c0.png"}, {"id": "puesto-otro", "qty": 5, "unit": "limones", "label": "Other stall", "price": 15, "image_url": "http://localhost:4006/files/lesson-images/849877f9e65272966bd1a29153bbd42eb2e3f9ed522a4b70c5f34499bef44dba.png"}], "currency": "USD"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "You have $15. At which stall do you have more money left if you buy 5 lemons?", "difficulty": 1, "explanation_md": "At Liruf''s stall, 5 lemons cost $10. You have $5 left. At the other stall, they cost $15, you have nothing left. Choosing the cheaper one leaves you money for your piggy bank!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-liruf"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/626c2155a68b3b93fa8a25e6b5f9630f6bb90924165c0c469fd8a0144bb9f123.mp3", "hash": "27f47c4ce0cd73d1c510c8fbeb177379e1fcbdd0f96a446b43e4d036a246859b", "bytes": 15696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/626c2155a68b3b93fa8a25e6b5f9630f6bb90924165c0c469fd8a0144bb9f123.mp3", "duration_ms": 2560}, "s1-price-compare.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0bdaf6146543fd5c134a965f98b4e58f2de080532664f46337d1f2c0966d3e93.mp3", "hash": "c3e4f4e92b51f12b262a760828753fc21219c89866e9a3dec3816d27b461c25e", "bytes": 25776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0bdaf6146543fd5c134a965f98b4e58f2de080532664f46337d1f2c0966d3e93.mp3", "duration_ms": 4240}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/4ff87d83fe87b5b81df6b24dc36d5aacee843f5becd6623f819b6865651016d3.mp3", "hash": "428f45a91af19bcff2ed1cfc5a0e7107585c1d08340baacf6d0c10bde26bab9a", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4ff87d83fe87b5b81df6b24dc36d5aacee843f5becd6623f819b6865651016d3.mp3", "duration_ms": 4880}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/e1a8dea2257da398023ae122d6e84e6922d8d2ba1683760d253f64c8ef6baf98.mp3", "hash": "368fb12e4174e70bdb285d7fbe5570d402d035f9784d6f91979ebbfaf1f00c64", "bytes": 68544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e1a8dea2257da398023ae122d6e84e6922d8d2ba1683760d253f64c8ef6baf98.mp3", "duration_ms": 11360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Match products and prices", "locale": "en-US", "subject": "mixed", "objectives": ["Match each product at the stand with its correct price (small cup–5, pitcher–20, cookie–3)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["The small cup costs the same as a 5-dollar coin.", "The pitcher costs 20 dollars, like 4 coins of 5."], "title": "Mixed-up labels", "payload": {"left": [{"id": "vaso", "text_md": "Small cup", "image_url": "http://localhost:4006/files/lesson-images/d8b19086a35b4fb4a8e3a1695a7dfdf5e46f1804e94da0fe8da011fbb41f62c9.png"}, {"id": "jarra", "text_md": "Pitcher", "image_url": "http://localhost:4006/files/lesson-images/adf251bc091747814024e834196a81c79b9256bc7127fba80d7d51b57af4a677.png"}, {"id": "galleta", "text_md": "Cookie", "image_url": "http://localhost:4006/files/lesson-images/d74e80874716ff367cc2ef570b6404f0ab1caf0a40d86789091b9ddefba51a0c.png"}], "right": [{"id": "precio5", "text_md": "5 dollars"}, {"id": "precio20", "text_md": "20 dollars"}, {"id": "precio3", "text_md": "3 dollars"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Tap each product and then its price to match them.", "difficulty": 1, "explanation_md": "The small cup costs 5 dollars, the pitcher costs 20, and the cookie costs 3. Now the stand is organized!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "precio5"], ["jarra", "precio20"], ["galleta", "precio3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0f23865ff8dfd573e589093be246c942a91dac6cbf631ac2b9e85cc08665baa5.mp3", "hash": "2a40dc9700b79bfd015e14b3155baa7470d165f57cf0f0f0ec62879aa8ed7be3", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0f23865ff8dfd573e589093be246c942a91dac6cbf631ac2b9e85cc08665baa5.mp3", "duration_ms": 2720}, "s1-match-prices.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7d15f6e5d970cb5620817bb297444810f29330c9762625629cd4702db785febc.mp3", "hash": "683ba8731abe011cfd4a06f70106415a110b69a00f1421710c202fba8462c736", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7d15f6e5d970cb5620817bb297444810f29330c9762625629cd4702db785febc.mp3", "duration_ms": 3040}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/e8e6b5b3cb2ca65d1be0858d5de0d0923e6cb08ecd3016ea3810817700cc5429.mp3", "hash": "4df6ba77efb96bf7b6582263d033ba77e6e2b7b87e54a6b38430517f99e0733a", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e8e6b5b3cb2ca65d1be0858d5de0d0923e6cb08ecd3016ea3810817700cc5429.mp3", "duration_ms": 2640}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/215ab3c13e1f3400718a233850b9642e20ecd447adfa250e890d09865532d074.mp3", "hash": "bde90d906545b8df18c105d01fdc5dd640b75b19ec7889539007f77feebb25f3", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/215ab3c13e1f3400718a233850b9642e20ecd447adfa250e890d09865532d074.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Sí o no: decisiones de gasto", "locale": "es-MX", "subject": "mixed", "objectives": ["Decir sí o no, caso por caso: ¿este gasto ayuda al puesto?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Piensa: ¿esto ayuda a vender más limonada o a cuidar el dinero?", "Un gasto que ayuda al puesto hace que puedas seguir vendiendo o vender más."], "title": "Sí o no: decisiones de gasto", "payload": {"cases": [{"id": "case-1", "text_md": "Comprar más limones para hacer más limonada.", "image_url": "http://localhost:4006/files/lesson-images/2d9c25c1dd6e13faa4ec5713e0829a290c31e91785312a2a922eb3ed6c872407.png"}, {"id": "case-2", "text_md": "Comprar un juguete nuevo para jugar en casa.", "image_url": "http://localhost:4006/files/lesson-images/7e4dda685b3abbed16a370f3fa4b7834176a093a9d8d8f4eb0f71ed189c2ab1a.png"}, {"id": "case-3", "text_md": "Comprar vasos desechables para servir la limonada.", "image_url": "http://localhost:4006/files/lesson-images/2a8f35049791db4c9d3066c51bb5cb6663c459e1ca775b1013464db1bd263d72.png"}, {"id": "case-4", "text_md": "Comprar un videojuego que acaba de salir.", "image_url": "http://localhost:4006/files/lesson-images/1a1c37bb831023bcaecdef565b7c7c11d671792baf2815c25012fcfa2b710333.png"}], "rule_md": "Di **sí** si el gasto ayuda al puesto de limonada (más limones, más vasos, reparar algo roto). Di **no** si es un gusto que no ayuda a vender (un juguete, un dulce, un videojuego)."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf revisa su lista. ¿Cuáles gastos ayudan al puesto de limonada?", "difficulty": 1, "explanation_md": "Comprar más limones y vasos ayuda al puesto porque sin ellos no hay limonada. El juguete nuevo no ayuda hoy, porque no es necesario para vender.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case-1", "case-3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3520ca21ec88da69ae3d78d3af21cdce9f823427f384923ea5e2c532e7a543c.mp3", "hash": "e623038145e065774a7d0043f3a05f055c6bee80845cda28391c6ce7dcc391ef", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b3520ca21ec88da69ae3d78d3af21cdce9f823427f384923ea5e2c532e7a543c.mp3", "duration_ms": 4400}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1a1e3abbc0dce20d293d17d021ebd264f41acf54b7552fc2a08ad6cb5ae6d95f.mp3", "hash": "828ca729ca1de4e45a59b74320f401871b36f9652f14a51e330dc2f7808fd63b", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1a1e3abbc0dce20d293d17d021ebd264f41acf54b7552fc2a08ad6cb5ae6d95f.mp3", "duration_ms": 4400}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/4259f4fc787e17cf573ea9587815c29a667529bf8e229bff33c64404fe05b94c.mp3", "hash": "b0b2dea0f8f6c5d88741cc4872cd97e368e7f79d60ee41c8a53aaf296310dcf9", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4259f4fc787e17cf573ea9587815c29a667529bf8e229bff33c64404fe05b94c.mp3", "duration_ms": 5120}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/b425cea8ea4a2aa5ec4d7efe50c3f22fa6c0c20e15082a10e40b1dacce582b6b.mp3", "hash": "b6ea756a92b501464e09f5cfd4d7c1222a6a809aaffbe0f8e47227281de32a6a", "bytes": 68544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b425cea8ea4a2aa5ec4d7efe50c3f22fa6c0c20e15082a10e40b1dacce582b6b.mp3", "duration_ms": 11360}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/f97c0d3dcd0e9f466d711399a1409cb2571aa4431f546fdde3d12c34d052e0a8.mp3", "hash": "c64ee35ba9463658a84e52a329233fa9a1a8664959892641434ca94f9e509c90", "bytes": 54576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f97c0d3dcd0e9f466d711399a1409cb2571aa4431f546fdde3d12c34d052e0a8.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganhar dinheiro começa com uma ideia", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que outros querem", "Reconhecer que uma meta clara ajuda a começar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "O violão de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Olho o violão na loja… custa 80 reais. Não tenho dinheiro.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "E se você ganhar ele mesmo? Poderia vender limonada na vizinhança.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "Vender limonada? Boa ideia! Assim posso ganhar o dinheiro sozinho.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Olha, já vendi um copo. Me deram 10 reais. Já tenho 10 dos 80! Quantos copos mais preciso vender para ter os 80?", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/ba17f7b10be4bdb63140114db4f8f5a1021024e938a11dd2507b0482baace8f0.png", "prompt_md": "Liruf quer um violão de 80 reais. Vende limonada a 10 reais cada copo.", "difficulty": 1, "explanation_md": "Liruf vende um copo de limonada por 10 reais. Assim ganha dinheiro aos poucos.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/8d2c5f36ff8b2253583b2f76d9ecc38f5c2cb59502f29cfcda765b6000e625bb.mp3", "hash": "a7d2aaab7d40a0ff6b3e63f910a7ccc5ff6f4b9e3d3b65a430c582ec613b09c9", "bytes": 42624, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8d2c5f36ff8b2253583b2f76d9ecc38f5c2cb59502f29cfcda765b6000e625bb.mp3", "duration_ms": 7040}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/27cd009a21102020b5558685c66d6d139116bbf31351b53d5276ade4e3fd6c2d.mp3", "hash": "f4188f48d6b5ec3250d84305f3f0b458c2d4e01b7eb82063e486d8ed67cc9fef", "bytes": 28656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/27cd009a21102020b5558685c66d6d139116bbf31351b53d5276ade4e3fd6c2d.mp3", "duration_ms": 4720}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/76e773fc53dd7610fc18cb4b470f17bc7370648a555acaad7d53f3e06831b3ce.mp3", "hash": "e84f1336617f8b7de42c2b56b4a896f242ea77a169b65aea11a2c4ad91cd6ae0", "bytes": 29664, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/76e773fc53dd7610fc18cb4b470f17bc7370648a555acaad7d53f3e06831b3ce.mp3", "duration_ms": 4880}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/4a873609ce285b3b1d772fe21143a0a4e702dfbd5bd1c2bde96907b48d76c24a.mp3", "hash": "f362fd5789ee5618215cfaac7f4f15610feda59ad4851cb4c94253b367a18d5d", "bytes": 65664, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4a873609ce285b3b1d772fe21143a0a4e702dfbd5bd1c2bde96907b48d76c24a.mp3", "duration_ms": 10880}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/94c477fed6b9c220aacab60ad0b47427d2168794fdb5c635077931f85a090235.mp3", "hash": "da12d1dcbd857151417bdd71d5efaff8bb6120f3681fcaf9a5076dbe4085df3e", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/94c477fed6b9c220aacab60ad0b47427d2168794fdb5c635077931f85a090235.mp3", "duration_ms": 6720}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/9d08eb3951975e8dbffabaf390395a4cb8c9868b1c8e14b1f063872e8785b0c8.mp3", "hash": "ecf01057196a677e05afd8daa167bf9ecaa278e1fc07aba85945b182ebbada35", "bytes": 37728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9d08eb3951975e8dbffabaf390395a4cb8c9868b1c8e14b1f063872e8785b0c8.mp3", "duration_ms": 6240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Agrupa el dinero de la caja", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar.", "Agrupar el dinero de la caja: monedas con monedas y billetes con billetes, para contarlo más fácil."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 10, "type": "group_sets", "hints": ["Las monedas son redondas y de metal, los billetes son de papel.", "Busca el grupo que dice ''Monedas'' y el que dice ''Billetes''."], "title": "Agrupa el dinero", "payload": {"items": [{"id": "item1", "text_md": "Moneda de $1", "image_url": "http://localhost:4006/files/lesson-images/cc6f44afe6d4638999c7a8587dd6be64506b28790bae3324360b5a6da76bc552.png"}, {"id": "item2", "text_md": "Moneda de $5", "image_url": "http://localhost:4006/files/lesson-images/2c7ed1cf73fa00b78f55ec00e56b79777196ad47d1cd51c86a168816366790c8.png"}, {"id": "item3", "text_md": "Moneda de $10", "image_url": "http://localhost:4006/files/lesson-images/d6ee58f25df993aa62e038c050cab864280be398efa4fe9051261c68108b7c4e.png"}, {"id": "item4", "text_md": "Billete de $20"}, {"id": "item5", "text_md": "Billete de $50"}, {"id": "item6", "text_md": "Billete de $100", "image_url": "http://localhost:4006/files/lesson-images/66ef40ee60d09d8810065f2699163cdabe44b198afdc9c02094f888cc6eb3e2a.png"}], "set_a": "Monedas", "set_b": "Billetes"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toca cada moneda o billete y ponlo en el grupo correcto.", "difficulty": 1, "explanation_md": "Las monedas van con monedas y los billetes con billetes, así es más fácil contar cuánto dinero tienes.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b", "item6": "b"}}}', '{"units": {"s1-group-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1b5b22e965c3b32900c561a186b4fb56b0c72c439507700428e0b48945c19b3a.mp3", "hash": "02d842ae492cc4b66929aa8f04a8a734a37730daf806e31c9ab0cb213dc1a064", "bytes": 25776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1b5b22e965c3b32900c561a186b4fb56b0c72c439507700428e0b48945c19b3a.mp3", "duration_ms": 4240}, "s1-group-money.hint.1": {"url": "http://localhost:4006/files/lesson-audio/47a86a801cadabe96b9c4e46b019b2b540126600a8afa869e1eeb1a2b529bfd3.mp3", "hash": "8e8b1a9df9351cafe6f38712494d97c52b81a7dbbef92635e92062ae4d9036ba", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/47a86a801cadabe96b9c4e46b019b2b540126600a8afa869e1eeb1a2b529bfd3.mp3", "duration_ms": 4000}, "s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/3b09012ff539be739896a5cb7586fb7688aac594d78ab7c5747908e4691d160c.mp3", "hash": "13a572dab840c9b27c4f82a236c6212dda0becc3561e1bd03670c78ffe326378", "bytes": 23328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3b09012ff539be739896a5cb7586fb7688aac594d78ab7c5747908e4691d160c.mp3", "duration_ms": 3840}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/8de5bc070def08e25b218608ca43a37252a495cc8c6b46204d5e37484dba62fb.mp3", "hash": "a232a6f00b664cf0d763f2075fb9862e9d32bdea80dc2b44676546dea3841187", "bytes": 41184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8de5bc070def08e25b218608ca43a37252a495cc8c6b46204d5e37484dba62fb.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparar preços de limões", "locale": "pt-BR", "subject": "money", "objectives": ["Comparar preços de limões em duas barracas do mercado e escolher a mais barata para gastar menos (custo mais baixo = mais lucro)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Veja quanto custam 5 limões em cada barraca.", "Subtraia o preço dos limões dos seus R$15 para ver quanto sobra."], "title": "Qual barraca de limões é mais barata?", "payload": {"offers": [{"id": "puesto-liruf", "qty": 5, "unit": "limones", "label": "Barraca da Liruf", "price": 10, "image_url": "http://localhost:4006/files/lesson-images/e7d7f0b10ca40f6a814e0f064f078f13016293e284532e864529f8587ba83b3e.png"}, {"id": "puesto-otro", "qty": 5, "unit": "limones", "label": "Outra barraca", "price": 15, "image_url": "http://localhost:4006/files/lesson-images/f4fc3f5a83361c759239da7444f6fcd9257b13ab57b5d2a6586e8ef627dd5330.png"}], "currency": "BRL"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Você tem R$15. Em qual barraca sobra mais dinheiro se você comprar 5 limões?", "difficulty": 1, "explanation_md": "Na barraca da Liruf, 5 limões custam R$10. Sobram R$5. Na outra barraca, custam R$15, não sobra nada. Escolher a mais barata deixa dinheiro para o seu cofrinho!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-liruf"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/02e517abe5f3ac9d1019803546ad09b9145a6f5b33a561874d78925c14820881.mp3", "hash": "a715a20f02ca27fb20273cf4369f307b92c3b150e4a5e0fa56cec2837fc77ae8", "bytes": 21888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/02e517abe5f3ac9d1019803546ad09b9145a6f5b33a561874d78925c14820881.mp3", "duration_ms": 3600}, "s1-price-compare.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4349b7330c4abd5201b6281d0017c0f7f5faaa4b05c6401601fcb46370688832.mp3", "hash": "f0418302b87480c02db042bee6f308489cb43f733e10db32014e28886e45593a", "bytes": 30096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4349b7330c4abd5201b6281d0017c0f7f5faaa4b05c6401601fcb46370688832.mp3", "duration_ms": 4960}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/d5cea7025a061d331065da99070a93548972dfab3e703bc0ad329e76fba394a7.mp3", "hash": "080e187ede0a99c2c3f66a3d09214184cfb4e4276ac3a8cfa075229ecc063857", "bytes": 40176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d5cea7025a061d331065da99070a93548972dfab3e703bc0ad329e76fba394a7.mp3", "duration_ms": 6640}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/1709f240da9f88939395ab5a324a61a4808c11cd0e545e6a139e9950d8e527f2.mp3", "hash": "d4dd71b5ef7be97d8d2572e863d9ea243a0da18567dcf3e6a1b0b49f78b9a389", "bytes": 80496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1709f240da9f88939395ab5a324a61a4808c11cd0e545e6a139e9950d8e527f2.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confianza en tus cuentas", "locale": "es-MX", "subject": "mixed", "objectives": ["Sumar 5 + 5 para calcular el total de dos vasos vendidos", "Evaluar el nivel de confianza en el resultado de una suma simple"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 10, "type": "confidence_quiz", "hints": ["Piensa: un vaso son 5 pesos, dos vasos son 5 más 5.", "Puedes contar con los dedos: 5 y luego 5 más."], "title": "Ventas de Liruf", "payload": {"options": [{"id": "opt-10", "text_md": "10 pesos", "rationale_md": "¡Correcto! 5 + 5 = 10."}, {"id": "opt-5", "text_md": "5 pesos", "rationale_md": "5 pesos es el precio de un solo vaso, pero Liruf vendió dos vasos."}, {"id": "opt-15", "text_md": "15 pesos", "rationale_md": "15 sería si cada vaso costara 7.50, pero cada vaso cuesta 5 pesos."}, {"id": "opt-8", "text_md": "8 pesos", "rationale_md": "8 sería si un vaso costara 3 y otro 5, pero ambos cuestan 5."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vendió dos vasos de limonada. Cada vaso cuesta 5 pesos. ¿Cuánto dinero juntó?", "difficulty": 1, "explanation_md": "Dos vasos de 5 pesos cada uno suman 10 pesos. Liruf juntó 10 pesos por las dos ventas.", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confidence-quiz.hint.0": {"url": "http://localhost:4006/files/lesson-audio/53fb39dd070a98cec0f856bb1771f4e14a6bc322fee4674407f1672ed5b6fb7a.mp3", "hash": "a03d9173825bf42439abe6890f125af94f179705aab3dff6b7e3a25252d12dc3", "bytes": 29664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/53fb39dd070a98cec0f856bb1771f4e14a6bc322fee4674407f1672ed5b6fb7a.mp3", "duration_ms": 4880}, "s1-confidence-quiz.hint.1": {"url": "http://localhost:4006/files/lesson-audio/858612134785569382afcb259a746eda4b7beec9b71548356a0fac61b488ce1a.mp3", "hash": "e6d6aaa8f7a65683e31b8e50581d125e36239e88e43a43804115535d8a02ffd0", "bytes": 25344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/858612134785569382afcb259a746eda4b7beec9b71548356a0fac61b488ce1a.mp3", "duration_ms": 4160}, "s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/af5a396a7ccc2936cd3527c999586c934e98f35973f7a05c06ae84b5a3584397.mp3", "hash": "a67824a835aa84ceab2c9d1ab826f75d7e8e7035bd42b61505ac5670bbafa882", "bytes": 42048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/af5a396a7ccc2936cd3527c999586c934e98f35973f7a05c06ae84b5a3584397.mp3", "duration_ms": 6960}, "s1-confidence-quiz.choices": {"url": "http://localhost:4006/files/lesson-audio/cfbf695c56a64fdca78969305d06634838d99f96d588990f5c2e1248c29a7d9a.mp3", "hash": "f14eadd9cf8a886d47c95834939bf4210123c6ebbb5121ed16b3a3eb3882f345", "bytes": 27216, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cfbf695c56a64fdca78969305d06634838d99f96d588990f5c2e1248c29a7d9a.mp3", "duration_ms": 4480}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/8ab4da323d7dcd0f5625a96d9bc5ab04284a2ddfe256725f4c8db7ce5e537519.mp3", "hash": "0eba6aa9295f4148b3d599138544c26334baf0fa09b29e10f92bf897930c2030", "bytes": 41184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8ab4da323d7dcd0f5625a96d9bc5ab04284a2ddfe256725f4c8db7ce5e537519.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Repartir la ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Repartir una ganancia de 10 pesos entre dos alcancías: una para la meta de la guitarra y otra para reponer ingredientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 10, "type": "piggy_split", "hints": ["Puedes poner más en una alcancía y menos en la otra, pero entre las dos deben sumar 10.", "La alcancía de la guitarra necesita ahorrar, y la del puesto necesita reponer ingredientes."], "title": "Repartir 10 pesos", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Alcancía de la guitarra", "hint_md": "Esta alcancía guarda dinero para comprar la guitarra de 80 pesos.", "image_url": "http://localhost:4006/files/lesson-images/7b0aa4a314c0f21c2fd1f8a0c659d82e46947c7a1d18937e46ce24f924fc8b8b.png"}, {"id": "stand", "icon": "storefront", "label": "Alcancía del puesto", "hint_md": "Esta alcancía guarda dinero para reponer limones y vasos.", "image_url": "http://localhost:4006/files/lesson-images/ecb0fb3846d36000e98109345430d9277aa3327d572e012dbf2e75deeef852db.png"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf ganó 10 pesos hoy. ¿Cuánto pones en cada alcancía?", "difficulty": 1, "explanation_md": "Repartiste los 10 pesos entre las dos alcancías. La suma de ambas partes debe ser 10. ¡Bien pensado!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"stand": {"max": 10, "min": 0}, "guitar": {"max": 10, "min": 0}}, "rationale_md": "La suma de lo que pongas en las dos alcancías debe ser exactamente 10 pesos. Puedes repartirlos como quieras, pero no más de 10 en total."}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/821171878ea23c2807ab74319a3ec198e4ea144d2cbc2eb245519c24ced9ac9f.mp3", "hash": "8e2084b60b5d504318d7566a43fccafec2aa7bd69d3eab13d8f32cc4265c8449", "bytes": 40176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/821171878ea23c2807ab74319a3ec198e4ea144d2cbc2eb245519c24ced9ac9f.mp3", "duration_ms": 6640}, "s1-piggy-split.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f0c208892186cfbd1f2e48df8fbab1220226aadb4cbbc173d74e2da3634441a8.mp3", "hash": "2a13447599e1ba4cf91edd8fc8a95c78ff137c36a29071b15eff734dc6523275", "bytes": 35856, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f0c208892186cfbd1f2e48df8fbab1220226aadb4cbbc173d74e2da3634441a8.mp3", "duration_ms": 5920}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/4059ef3737fa470858b9a28e53a9d2abd8c60af823d8e4f136881d1ed189a7d6.mp3", "hash": "f820795d91bc2c662d6cebf315b3a0e6d0e67110d50c98b138e8d4df4cbdd6f7", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4059ef3737fa470858b9a28e53a9d2abd8c60af823d8e4f136881d1ed189a7d6.mp3", "duration_ms": 5120}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/697d379caa39bed1835c24bc7353bd0f8316b47119d9bd13064844de13a84e47.mp3", "hash": "1f4199fe49e844705f5ae36203ad1ba38b46aa519609b00071df0c48f125cb87", "bytes": 45936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/697d379caa39bed1835c24bc7353bd0f8316b47119d9bd13064844de13a84e47.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'es-MX', '1', E'{"meta": {"cast": ["liruf", "zara", "dina"], "slug": "build-sentence", "title": "El letrero del combo", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el precio de 2 vasos de limonada a 5 pesos cada uno y armar el letrero correcto."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-letrero", "xp": 15, "type": "build_sentence", "hints": ["Cada vaso cuesta 5 pesos. ¿Cuánto cuestan dos?", "Piensa: 5 más 5 son..."], "title": "El letrero del combo", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "vasos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "10"}, {"id": "t6", "text_md": "15"}, {"id": "t7", "text_md": "20"}, {"id": "t8", "text_md": "pesos"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf quiere un letrero que diga: \\"2 vasos por ___ pesos\\". Toca las fichas en orden para armarlo.", "difficulty": 2, "explanation_md": "El letrero debe decir \\"2 vasos por 10 pesos\\" porque cada vaso cuesta 5 y dos cuestan 5+5=10. Si pusieras 5, solo alcanzaría para un vaso. 15 es lo que gastó Dina en otra cosa, y 20 es el billete con que pagan.", "audio_segment_id": "s1-combo-letrero.prompt"}], "schema_version": 1}', '{"s1-combo-letrero": {"order": ["t1", "t2", "t3", "t5", "t8"]}}', '{"units": {"s1-combo-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3bee4f10843fe5d475c2ad1ad3d18b695c72c14ad886beaca629f826d5c61a8.mp3", "hash": "b73c53cdd00ccec90e6fae8ebf440d9ee1d8bb222c94837722f6034c41dbfefc", "bytes": 26208, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b3bee4f10843fe5d475c2ad1ad3d18b695c72c14ad886beaca629f826d5c61a8.mp3", "duration_ms": 4320}, "s1-combo-letrero.hint.1": {"url": "http://localhost:4006/files/lesson-audio/bbde760cb760ed93a431709e8dc29d21037e71cfb8813bd933ea04047aa79868.mp3", "hash": "6fb540e4eadcbc55358523dee30e5279286bc35e6c2c6da66febae9573a1fb4f", "bytes": 17568, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/bbde760cb760ed93a431709e8dc29d21037e71cfb8813bd933ea04047aa79868.mp3", "duration_ms": 2880}, "s1-combo-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/37565884e35e7fb3d6e04b04a2954fe615c556a6267ddc4d274154ab38f4cdf3.mp3", "hash": "ab51ffdcd5c04b5858336b3165ff2936e2f7f6b8ce2e74f17f19c3c9d5ff2706", "bytes": 44928, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/37565884e35e7fb3d6e04b04a2954fe615c556a6267ddc4d274154ab38f4cdf3.mp3", "duration_ms": 7440}, "s1-combo-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/9b7c0739e3a8e60159cd249e21c321fb90fd7c114523f3b5bcb461ba99d4b81e.mp3", "hash": "6bc3ce59a0335727a4854ffc6b738630f93346983f62a0d2639b77324c0ba69f", "bytes": 106416, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/9b7c0739e3a8e60159cd249e21c321fb90fd7c114523f3b5bcb461ba99d4b81e.mp3", "duration_ms": 17680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Organize o dia de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Organizar as etapas do dia de vendas em ordem cronológica"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline", "xp": 15, "type": "timeline_order", "hints": ["O que você faz primeiro ao chegar na barraca?", "Pense: antes de vender, é preciso preparar."], "title": "O dia de Liruf", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Comprar limões e açúcar", "image_url": "http://localhost:4006/files/lesson-images/5ced991bc62105f98ce96a99020714e08e0bb3230df2e17824f027b74f6e7774.png"}, {"id": "preparar", "icon": "local_drink", "text_md": "Preparar a limonada", "image_url": "http://localhost:4006/files/lesson-images/e21c35b06fb450229940c921e97c345a10b656b813d2f4162e4e7eddd1e72026.png"}, {"id": "vender", "icon": "storefront", "text_md": "Vender copos ao meio-dia", "image_url": "http://localhost:4006/files/lesson-images/e97ccdf2dfaa497b2de68d29f1d853f37f4dbadf8acc8525f4de6d1b4fa553c1.png"}, {"id": "contar", "icon": "payments", "text_md": "Contar dinheiro e guardar", "image_url": "http://localhost:4006/files/lesson-images/76419f1eadea4affc97d2e90a55d8b7dba97810db5f61da5113ff714d1eecb14.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Toque nos eventos em ordem, da manhã ao fechamento.", "difficulty": 2, "explanation_md": "Liruf compra ingredientes cedo, depois prepara a limonada, vende ao meio-dia e no final conta o dinheiro e guarda.", "audio_segment_id": "s1-timeline.prompt"}], "schema_version": 1}', '{"s1-timeline": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-timeline.hint.0": {"url": "http://localhost:4006/files/lesson-audio/084832d531b92e52ab676ffcdaf717ef29412830815fdf09c2e289ddd3588aea.mp3", "hash": "9135c22d5bb8b8ff3da3491068b82d94e2c56df349a145f7671e25ca4b95f8e4", "bytes": 16704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/084832d531b92e52ab676ffcdaf717ef29412830815fdf09c2e289ddd3588aea.mp3", "duration_ms": 2720}, "s1-timeline.hint.1": {"url": "http://localhost:4006/files/lesson-audio/dd5d645165f194558fd499cf9600b9abe26dec51397a265d570d31d460eba70d.mp3", "hash": "c1cf66c7b77b8d6d3cf4cd3ae90339c99f07f2bde9cb79fd92657e95a341573e", "bytes": 21888, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/dd5d645165f194558fd499cf9600b9abe26dec51397a265d570d31d460eba70d.mp3", "duration_ms": 3600}, "s1-timeline.prompt": {"url": "http://localhost:4006/files/lesson-audio/58c466ad11ae11531e59ad82ea7d9c5287c93f45b49cb4f881069a73c36de546.mp3", "hash": "35058cdeaff21b1be7584d844b85ac88388ec296f70329735bb8cfe6c98706d5", "bytes": 21456, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/58c466ad11ae11531e59ad82ea7d9c5287c93f45b49cb4f881069a73c36de546.mp3", "duration_ms": 3520}, "s1-timeline.explanation": {"url": "http://localhost:4006/files/lesson-audio/44ba8a215fd67dbe16feadc51ee5b376b0c369274ca1db8459d53a60533d5a53.mp3", "hash": "3313d488ceaff8e8d253905064dad5210124cdf4b207e0366bd12f53443f8604", "bytes": 45936, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/44ba8a215fd67dbe16feadc51ee5b376b0c369274ca1db8459d53a60533d5a53.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "balance-scale", "title": "Balance the barter scale", "locale": "en-US", "subject": "mixed", "objectives": ["Balance a scale by placing equivalent dollars to achieve a fair trade"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-trueque", "xp": 15, "type": "balance_scale", "hints": ["Each glass is worth 5 dollars. How much are the 3 glasses together worth?", "Each cookie is worth 3 dollars. Find how many cookies add up to the same as the 3 glasses."], "title": "Fair trade", "payload": {"weights": [{"id": "galleta1", "label": "Cookie", "value": 3}, {"id": "galleta2", "label": "Cookie", "value": 3}, {"id": "galleta3", "label": "Cookie", "value": 3}, {"id": "galleta4", "label": "Cookie", "value": 3}, {"id": "galleta5", "label": "Cookie", "value": 3}], "left_fixed": [{"label": "Glass of lemonade", "value": 5}, {"label": "Glass of lemonade", "value": 5}, {"label": "Glass of lemonade", "value": 5}], "unknown_label": "Cookie"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf puts 3 glasses of lemonade (5 dollars each). The cookie seller puts cookies worth 3 dollars. Place cookies until the scale balances.", "difficulty": 2, "explanation_md": "3 glasses of 5 dollars add up to 15 dollars. 5 cookies of 3 dollars also add up to 15 dollars. The scale balances!", "audio_segment_id": "s1-balance-trueque.prompt"}], "schema_version": 1}', '{"s1-balance-trueque": {}}', '{"units": {"s1-balance-trueque.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e06948732a5bb8b0a96041da008592495b41adaa5ceb82a2e707eba3ee75716d.mp3", "hash": "c6b3462ecad4c420046bcf69e77e10e85e6bd4470aeaba36eff6f8b6aee746a8", "bytes": 29088, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e06948732a5bb8b0a96041da008592495b41adaa5ceb82a2e707eba3ee75716d.mp3", "duration_ms": 4800}, "s1-balance-trueque.hint.1": {"url": "http://localhost:4006/files/lesson-audio/dec221d599e9af3276aa92f35cd6d76ef8c59c64d92cab209468d9e236dcf173.mp3", "hash": "430b906758c1a5eee38e55f0a851ff578288d0f51a9edafc65f9c56c41f41ed8", "bytes": 34416, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/dec221d599e9af3276aa92f35cd6d76ef8c59c64d92cab209468d9e236dcf173.mp3", "duration_ms": 5680}, "s1-balance-trueque.prompt": {"url": "http://localhost:4006/files/lesson-audio/41743e3e0d422efa12342f749498541cd8c652c88ce94435f01d2fad4c0ee225.mp3", "hash": "3ec47899842fc450d3acd3d5ede46b1d9f2a82a37bdda0279f422bc77ef9542c", "bytes": 51696, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/41743e3e0d422efa12342f749498541cd8c652c88ce94435f01d2fad4c0ee225.mp3", "duration_ms": 8560}, "s1-balance-trueque.explanation": {"url": "http://localhost:4006/files/lesson-audio/478e79127d163f3ffb65fc0bdb9c53924129bcb4181235974d82f1f8c65a8886.mp3", "hash": "20d6de5588f4817864530764056de293a503825962a2404e6e476611c7b018a9", "bytes": 53568, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/478e79127d163f3ffb65fc0bdb9c53924129bcb4181235974d82f1f8c65a8886.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "El plan de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren", "Ver el plan completo: vender vasos de limonada a 5 pesos hasta juntar 80 para la guitarra"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "title": "El plan de Liruf", "payload": {"art": {"icon": "local_cafe", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/ec5f401e6242c59db11f1206fbe8965fb9bfb75ddf7a14a6fb0b6e1bc82228ac.png"}, "action": "idle", "body_md": "Liruf dibuja en una cartulina: un vaso de limonada cuesta 5 pesos. Muchos vasos juntan los 80 pesos de la guitarra. ¡Es su plan para ganar el dinero! ¿Cuántos vasos necesitará vender?", "emotion": "excited", "backdrop": "base", "character": "liruf"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf dibuja su plan para la guitarra.", "difficulty": 1, "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/8b69ed6fa49fca949fdc794512d4b08081b50e4121b2f3a2ce8d5b7883e8202b.mp3", "hash": "38984a08ea256afd77f27f0ec8a31fae95c182da8dbc78304e82f2b5dfd559e6", "bytes": 90576, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/8b69ed6fa49fca949fdc794512d4b08081b50e4121b2f3a2ce8d5b7883e8202b.mp3", "duration_ms": 15040}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/7e1336c0ac6435381c5f631d6bca875f9c1aa2c26ebac8dc93160a48940998b4.mp3", "hash": "367d56fd5cfa32057af3eb7c942ca6132dc8eb961fd96bd6c98a1cb4d85e09d1", "bytes": 17568, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7e1336c0ac6435381c5f631d6bca875f9c1aa2c26ebac8dc93160a48940998b4.mp3", "duration_ms": 2880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganar dinero empieza con una idea", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren", "Reconocer que una meta clara ayuda a empezar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "La guitarra de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Miro la guitarra en la tienda… cuesta 80 pesos. No tengo dinero.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "¿Y si la ganas tú mismo? Podrías vender limonada en el vecindario.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "¿Vender limonada? ¡Buena idea! Así puedo ganar el dinero yo solo.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Mira, ya vendí un vaso. Me dieron 10 pesos. ¡Ya tengo 10 de los 80! ¿Cuántos vasos más necesito vender para tener los 80?", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/b863258386fa8326cb792af3b7d8b423ecf151b3c83b8042985d768bd808b13d.png", "prompt_md": "Liruf quiere una guitarra de 80 pesos. Vende limonada a 10 pesos cada vaso.", "difficulty": 1, "explanation_md": "Liruf vende un vaso de limonada por 10 pesos. Así gana dinero poco a poco.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/b0c68067d6d3c81a2e518f0f17689a54c317093a21e006f2a957de13e7242ba8.mp3", "hash": "2b08ec446bf3d46027b395ccc003c1e23e9bd0cd56938c01c4eff88e1ef027aa", "bytes": 31536, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b0c68067d6d3c81a2e518f0f17689a54c317093a21e006f2a957de13e7242ba8.mp3", "duration_ms": 5200}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/5392b1d34e798105f57e7e71cf47220969c7e34e7b819a09d7fe580973441653.mp3", "hash": "210f513010e86f3babb6218ea2952370d5cc6caa49c0b12a47951495f6951d93", "bytes": 32544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5392b1d34e798105f57e7e71cf47220969c7e34e7b819a09d7fe580973441653.mp3", "duration_ms": 5360}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/69d8e98a2cf9446664993b0c3466a6f2bc8fae7cc5894adf940178cf15bb0c44.mp3", "hash": "f77042d7ff665b86fe031e72db1981686e79d74c21051b701c30a9eb1049ee7b", "bytes": 33984, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/69d8e98a2cf9446664993b0c3466a6f2bc8fae7cc5894adf940178cf15bb0c44.mp3", "duration_ms": 5600}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/108713561eae6a482b2d6a0d06ff3181383075f514abf5cac5b3dd17baea7b8f.mp3", "hash": "948eb9ab8b6c650adaf9f10293b2331bd0604d8965a9c63cd56a3837045fb5de", "bytes": 57888, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/108713561eae6a482b2d6a0d06ff3181383075f514abf5cac5b3dd17baea7b8f.mp3", "duration_ms": 9600}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/45f5c1e24ef6e63b0db775aaf0174e91f7c7e2f88091310afe3bb7965bb3226b.mp3", "hash": "c0e1060f98fb8b252c74c71ecdbf0b3e7de21d66c44a84e4589d5198c4d40b48", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/45f5c1e24ef6e63b0db775aaf0174e91f7c7e2f88091310afe3bb7965bb3226b.mp3", "duration_ms": 5840}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/a4ae3668b93e8e1f7a7a8a0fa5190bbfb7e1867b1e39a26c9c11d88c9bdf4bf4.mp3", "hash": "1628e4ce2fe94ab65362eb76c58cc2e09407ca28dc78c6e41f80bf71a7078a56", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a4ae3668b93e8e1f7a7a8a0fa5190bbfb7e1867b1e39a26c9c11d88c9bdf4bf4.mp3", "duration_ms": 5600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "Las tres reglas de oro del pequeño vendedor", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar las tres ideas clave del plan: tener una meta, ofrecer algo que la gente quiera, y guardar lo ganado."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Piensa en lo que Liruf quiere comprar.", "¿Qué va a vender Liruf para ganar dinero?"], "title": "Las tres reglas de oro", "payload": {"ideas": [{"icon": "flag", "title": "Tener una meta", "body_md": "Liruf quiere una guitarra que cuesta **80 pesos**. Esa es su meta.", "image_url": "http://localhost:4006/files/lesson-images/223ffe61d8c655dd978be184d1493aaf805070d89f29fc8f1dd0a5b88b1c97c1.png"}, {"icon": "local_cafe", "title": "Ofrecer algo que la gente quiera", "body_md": "Venderá **limonada fría** a 5 pesos el vaso. ¡A todos les gusta!", "image_url": "http://localhost:4006/files/lesson-images/b07f3778f9ca901993b6d8c20214b6b07d9f8e7188ac635676d7d008e84ecfd9.png"}, {"icon": "savings", "title": "Guardar lo ganado", "body_md": "Cada peso que gane lo guardará para la guitarra.", "image_url": "http://localhost:4006/files/lesson-images/98af5d671cfa23614a63243f7fd35328b23c323b40afe3566d6027c016c2ea16.png"}]}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Rho dibujó tres ideas en su pizarra. Toca cada una para verla bien.", "difficulty": 1, "explanation_md": "Rho anotó las tres reglas: una meta clara (la guitarra de 80 pesos), algo que vender (limonada fría), y guardar lo que se gana.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/41cf4b4c132401edd2389c908155373b66e9223dd0d166c229f70f0fba176629.mp3", "hash": "55bde822ca36a8cf447e287177d9d6f253ce54c5b67bd01169da8a38b75b5d0a", "bytes": 14688, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/41cf4b4c132401edd2389c908155373b66e9223dd0d166c229f70f0fba176629.mp3", "duration_ms": 2400}, "s1-key-ideas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/85e2df0d410e925229cda30d8633723f8809f94bcff0426dead308027b9d6e6a.mp3", "hash": "51c9787d764efbffb14060d227a8eaae97a98927384b210dd2755698f7475f29", "bytes": 18576, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/85e2df0d410e925229cda30d8633723f8809f94bcff0426dead308027b9d6e6a.mp3", "duration_ms": 3040}, "s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/8f32494590dabbe23c461260886082ae29bbb69b6679cec5fdf1a4d6929e12c2.mp3", "hash": "8c6f413ab93f12d2f1b4a81b30cbafacbf17c05fc2ef86af58a1bcb36b9a7948", "bytes": 30096, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/8f32494590dabbe23c461260886082ae29bbb69b6679cec5fdf1a4d6929e12c2.mp3", "duration_ms": 4960}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/68af14276d6c70bfad0ada9dad337dd2237d81bbefbd5ec16a0b3e7d11e73409.mp3", "hash": "1117b26b76ba282a61d69f5e84883cdcb04d68094b8c977098d1cdca999bf4c8", "bytes": 35856, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/68af14276d6c70bfad0ada9dad337dd2237d81bbefbd5ec16a0b3e7d11e73409.mp3", "duration_ms": 5920}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/3e090d9272574d29b380ff4d5195e3e3e020722dc32f6bc2eda15b20468f9a21.mp3", "hash": "635ed07d3ebd217c201c8afbbac19cfcdb9ec7dbae87167f7e6f705116aebe92", "bytes": 18144, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3e090d9272574d29b380ff4d5195e3e3e020722dc32f6bc2eda15b20468f9a21.mp3", "duration_ms": 2960}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/50e696e5436bbfbee9c9cff97d3fe0960cd2ac15992585bf908c4430f77c2eea.mp3", "hash": "48d61630a8e6662e814d89e23dab7f687132c7eef780af5b493db1f274d6d4d8", "bytes": 34416, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/50e696e5436bbfbee9c9cff97d3fe0960cd2ac15992585bf908c4430f77c2eea.mp3", "duration_ms": 5680}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/651d4132188a585ddcc5fce0630d44631e07abeb16b3f44d9f98c85755285330.mp3", "hash": "f3d9cff778943b9586d4797126105f61d346a89936ba03a2b2c3e82b6c8813f0", "bytes": 60768, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/651d4132188a585ddcc5fce0630d44631e07abeb16b3f44d9f98c85755285330.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "measure-read", "title": "La jarra medidora de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer medidas en una jarra graduada para servir vasos parejos de 5 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Observa las marcas de la jarra: 200, 250, 300 ml.", "El líquido llegó justo a la línea de en medio."], "title": "La jarra medidora", "payload": {"max": 300, "min": 200, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "encouraging", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/42368ef75ea2ca0785061300c3c1912faba54866c04873b360833dcdaa6e189a.png", "prompt_md": "Rho llenó la jarra hasta la línea. ¿Cuántos mililitros tiene?", "difficulty": 1, "explanation_md": "El líquido llegó a la línea de 250 ml, justo entre 200 y 300. Así todos los vasos de 5 pesos quedan iguales.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 250, "tolerance": 0}}', '{"units": {"s1-measure-read.hint.0": {"url": "http://localhost:4006/files/lesson-audio/49d969116aefd19f22ef82cc9da821e628d4da65a78c0f5744aae2d1ebdae9a8.mp3", "hash": "cde931db655cddf553bb3ce99b400f3bc32a9807c1d4908bebb6f754dca95def", "bytes": 40608, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/49d969116aefd19f22ef82cc9da821e628d4da65a78c0f5744aae2d1ebdae9a8.mp3", "duration_ms": 6720}, "s1-measure-read.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2d16635af0edda4fd7d1ee5f745ec1bdb1d2957a6736b4f327295e664ff083fa.mp3", "hash": "bce50ddacba05177834ac56e1fe9ecda3a0d5d13f24a1373fb4f29b4005be8cc", "bytes": 20016, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2d16635af0edda4fd7d1ee5f745ec1bdb1d2957a6736b4f327295e664ff083fa.mp3", "duration_ms": 3280}, "s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/fa55adbaab21cc6d79a5548d9a9a8e11d19a9d298ae5eeb5f237866d824167e7.mp3", "hash": "d92feb8d36cac06a0e03c2f7db2cce980ac8fe410ac35aba70d13f82cec338d0", "bytes": 29088, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/fa55adbaab21cc6d79a5548d9a9a8e11d19a9d298ae5eeb5f237866d824167e7.mp3", "duration_ms": 4800}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/cdb8f298eed32b4295f4e2f0c75ff6d2ffe2b7e79b77329634dcf417b46ef84d.mp3", "hash": "1dd24e716016654a55fae525e7560a361d38d11901d21c036bd57a4a7e7d5e5f", "bytes": 66096, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/cdb8f298eed32b4295f4e2f0c75ff6d2ffe2b7e79b77329634dcf417b46ef84d.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "As três regras de ouro do pequeno vendedor", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar as três ideias-chave do plano: ter uma meta, oferecer algo que as pessoas queiram e guardar o que ganhou."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Pense no que Liruf quer comprar.", "O que Liruf vai vender para ganhar dinheiro?"], "title": "As três regras de ouro", "payload": {"ideas": [{"icon": "flag", "title": "Ter uma meta", "body_md": "Liruf quer um violão que custa **80 reais**. Essa é a meta dele.", "image_url": "http://localhost:4006/files/lesson-images/a29465dcf62c6813dfaff490d9ebb15f99a135cd433de4c51403b6f7f0a963e7.png"}, {"icon": "local_cafe", "title": "Oferecer algo que as pessoas queiram", "body_md": "Ele venderá **limonada gelada** a 5 reais o copo. Todo mundo gosta!", "image_url": "http://localhost:4006/files/lesson-images/86c5e435532eb4b534c7debf189757f8bcee2f0b3a8eaab478db19f18f6edff4.png"}, {"icon": "savings", "title": "Guardar o que ganhou", "body_md": "Cada real que ele ganhar, guardará para o violão.", "image_url": "http://localhost:4006/files/lesson-images/ee277343cbffbb0bcdb4a96c72a421f4e72a470a509e8be54f2c6d78f0251021.png"}]}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Rho desenhou três ideias em seu quadro. Toque em cada uma para vê-la bem.", "difficulty": 1, "explanation_md": "Rho anotou as três regras: uma meta clara (o violão de 80 reais), algo para vender (limonada gelada) e guardar o que se ganha.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/dd98595e866892fb01681bd3a52e71c5eac6c0573d09aa6cb856936bafbb02bc.mp3", "hash": "bb51fd37c30b9797ed889ebd83856f5712390a73cf328c076ffdd6189e98e52f", "bytes": 13824, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/dd98595e866892fb01681bd3a52e71c5eac6c0573d09aa6cb856936bafbb02bc.mp3", "duration_ms": 2240}, "s1-key-ideas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9489231eabf025bba3f53a75a31c35f733dc4002c4e77239389dfc474ab23d33.mp3", "hash": "f0a248155291c7237a40163df2b34a7612dcbedc3aec63832d03d53fdf517110", "bytes": 18576, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9489231eabf025bba3f53a75a31c35f733dc4002c4e77239389dfc474ab23d33.mp3", "duration_ms": 3040}, "s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/240847ecdd67329bac2c4def5fe25d8ec3a1be20f9a16bb82ac3a727c08c9310.mp3", "hash": "63dcfbd151f8894ffc784f40926377daedf56f769442ee94145365b0ea745151", "bytes": 33984, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/240847ecdd67329bac2c4def5fe25d8ec3a1be20f9a16bb82ac3a727c08c9310.mp3", "duration_ms": 5600}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/f0a674f1723cc6a498aeb1374e4b4238599862afcc862831b45ac2fe9dfaf7cc.mp3", "hash": "9884689a7af79068170bbfd8e425da7fcb2e6c45c4340d022edf6140e91d399b", "bytes": 35424, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f0a674f1723cc6a498aeb1374e4b4238599862afcc862831b45ac2fe9dfaf7cc.mp3", "duration_ms": 5840}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/5a4d89be17e770cd6d7691488a189df18b3be7b7f9e38bcb30d084259ed12b46.mp3", "hash": "3220561a265e9be340ba342d6685a6806f14de655183b12a70350375912bea1f", "bytes": 21024, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/5a4d89be17e770cd6d7691488a189df18b3be7b7f9e38bcb30d084259ed12b46.mp3", "duration_ms": 3440}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/f6278f9e1ca0e5d17cca4a262e6e65f956be366118108c990e638c7d059614a0.mp3", "hash": "43244bd707b733f5808eaa8a3739a1cb9c9a224ec78e38ce509da2cdcadd467c", "bytes": 34848, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f6278f9e1ca0e5d17cca4a262e6e65f956be366118108c990e638c7d059614a0.mp3", "duration_ms": 5760}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/679c3a3fe9e514f345dd51b2c1352f38aa18dab5be13e87076022e96c7c8f6d3.mp3", "hash": "dac662ae16d704aee66f832c73a0a54ab74b2ffc04e151b09ef60acf7033b884", "bytes": 65664, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/679c3a3fe9e514f345dd51b2c1352f38aa18dab5be13e87076022e96c7c8f6d3.mp3", "duration_ms": 10880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "The delivery driver''s route", "locale": "en-US", "subject": "mixed", "objectives": ["Guide the delivery cart through the neighborhood grid to the customer''s house using the fewest steps."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["The cart moves forward. Turn left or right."], "title": "Shortest route", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "commands": ["forward", "forward"], "max_commands": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Zara is waiting for her juice at house 2. Give the cart the shortest route.", "difficulty": 2, "explanation_md": "The cart turns right, moves two blocks, and arrives at house 2. Zara gets her juice!", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/483cf3174e6bed63eb17225a3b714b8b0e8ec564f1ab210856f42f589c545fc2.mp3", "hash": "1e6776cce3b9008363e41a3c2338dac3291cfc151bcff11ec031b772d8d86bf9", "bytes": 17136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/483cf3174e6bed63eb17225a3b714b8b0e8ec564f1ab210856f42f589c545fc2.mp3", "duration_ms": 2800}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/e3814ff9ce45c96e4f91abd244161a1b9e516439be5bf7b51b67d03e75059aab.mp3", "hash": "de8d532e18019f08dd2b1437306ec86ede99c11f7f335e0ba77f6aa7b001f938", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e3814ff9ce45c96e4f91abd244161a1b9e516439be5bf7b51b67d03e75059aab.mp3", "duration_ms": 4080}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/809678a348971b2e9885cfe2f215ecfe6623a115032c9f365c70e8ec1117f70f.mp3", "hash": "976197019f710accf32e6b59dab9110ef2321ef72068acc2e4aa935fc9677f0f", "bytes": 33408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/809678a348971b2e9885cfe2f215ecfe6623a115032c9f365c70e8ec1117f70f.mp3", "duration_ms": 5520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escribir y calcular números reales del puesto", "locale": "es-MX", "subject": "money", "objectives": ["Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20).", "Escribir la palabra que nombra el dinero que guardas para después: ''ahorro''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Si ahorra 5 pesos el día 1, ya tiene 5. ¿Cuánto le falta?", "El día 2 ahorra otros 5. Suma 5 + 5."], "title": "¿Cuántos días para la guitarra?", "payload": {"max_chars": 2, "placeholder": "Escribe el número"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho ahorra 5 pesos cada día. La guitarra cuesta 10 pesos. ¿Cuántos días debe ahorrar para comprarla?", "difficulty": 1, "explanation_md": "¡Así es! 5 pesos el primer día y 5 el segundo suman 10. Rho necesita 2 días de ahorro para la guitarra.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["2", "dos"], "keywords": ["2", "dos"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e4b816a0cc523ae3c0c420d2502484d6933f7f144c377e6f0ab7b0e8b2a27fe5.mp3", "hash": "0e2518ebd167dbb73f69416dff8a9bf32fa0a015a0dcc0c1438bb1cf15990fb6", "bytes": 33408, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/e4b816a0cc523ae3c0c420d2502484d6933f7f144c377e6f0ab7b0e8b2a27fe5.mp3", "duration_ms": 5520}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/83533cc9c1ba1bb7eede7f741533418cc00ebae0aa1d373a7e62eef0655079fd.mp3", "hash": "03fe85a00a6e704050f008e24171d64634b40a3fe72caa47afc6e456d17024ce", "bytes": 31536, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/83533cc9c1ba1bb7eede7f741533418cc00ebae0aa1d373a7e62eef0655079fd.mp3", "duration_ms": 5200}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/2ae5cc66dafff384173d963fc5b46ca98afab3fa27701ffa4103a850b8a36fa4.mp3", "hash": "d57e22b569fe23020ee86270b28b0304a8beabf4bd762dba65496b6282856a2d", "bytes": 50256, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2ae5cc66dafff384173d963fc5b46ca98afab3fa27701ffa4103a850b8a36fa4.mp3", "duration_ms": 8320}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/60f8e8bab474da975eacaaa17249104bee1dc4a984e26eae9de60e774478d31d.mp3", "hash": "e83d262807a9881b0f48bb02405bb7e407f58680b90ab7d4171f42b8b21f3fdf", "bytes": 59904, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/60f8e8bab474da975eacaaa17249104bee1dc4a984e26eae9de60e774478d31d.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Find the error in the account", "locale": "en-US", "subject": "mixed", "objectives": ["Detect an error in a sales sum", "Read a simple graph of cups sold per day", "Recognize signs of a bad deal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 10, "type": "spot_error", "hints": ["Count how many 5s are in the sum.", "What is three times 5?"], "title": "Liruf''s account", "payload": {"steps": [{"id": "step1", "text_md": "5 + 5 = 10"}, {"id": "step2", "text_md": "10 + 5 = 15"}, {"id": "step3", "text_md": "The result is 20"}], "context_md": "Liruf sold 3 cups of lemonade for 5 dollars each. He wrote in his notebook: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/cf71c378f9b6baa48ad18ba0f92797461e4b9829e68cc021736d2e8a7d0f4166.png", "prompt_md": "Liruf wrote: 5 + 5 + 5 = 20. Which step is wrong?", "difficulty": 1, "explanation_md": "Liruf added 5 + 5 + 5, which is 15, not 20. The error is in the result.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step3"], "correction_md": "El resultado correcto es 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/cd79c5e8696d50a2ad116f0fdbf59389caca3413fafccea9d83ab954faf37855.mp3", "hash": "6a76590dc81043c19c601068b6f5171f8f61a3a0e4646033deb0bb7c4ec16cb5", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cd79c5e8696d50a2ad116f0fdbf59389caca3413fafccea9d83ab954faf37855.mp3", "duration_ms": 2400}, "s1-spot-error.hint.1": {"url": "http://localhost:4006/files/lesson-audio/deef81a45f85429275cc8a25fee505a2a75277b6aecb25ba19a807cc6e46fef2.mp3", "hash": "8f85236754a3d66aea8b59713f806ffc35270a6f0e2681d059a6c6032f0c3c35", "bytes": 11376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/deef81a45f85429275cc8a25fee505a2a75277b6aecb25ba19a807cc6e46fef2.mp3", "duration_ms": 1840}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/aa74ebf1caa6bbab78f88720be06ff4f952b42bbba2668a7b0efc12c9bd6bab5.mp3", "hash": "0eda3dcb4906d17f272f1562d735fe7d2071249d2159d51e485bfc91bf3e6df3", "bytes": 34416, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/aa74ebf1caa6bbab78f88720be06ff4f952b42bbba2668a7b0efc12c9bd6bab5.mp3", "duration_ms": 5680}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/fef51c81f129015bc2551f39e8428bdd259a5b7967c5a96246081e028f3aa765.mp3", "hash": "b98fe6010d2c4748e9c68d6933796cf637e84b7007b4a931d2b78f4152747e42", "bytes": 36288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fef51c81f129015bc2551f39e8428bdd259a5b7967c5a96246081e028f3aa765.mp3", "duration_ms": 6000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Troca justa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Decidir se uma troca é justa comparando valores"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 10, "type": "fair_trade", "hints": ["Cada copo vale 5 reais. Quanto valem 2 copos?", "O saco de limões vale 10 reais. Compare os dois valores."], "title": "Troca justa", "payload": {"offer_a": {"qty": 2, "icon": "local_cafe", "label": "Copo de limonada", "image_url": "http://localhost:4006/files/lesson-images/427ddc3d853e1bc6cd329376ee4ec4ad6a8359e8cc8d592b3fa07ccfa256e1cd.png"}, "offer_b": {"qty": 1, "icon": "eco", "label": "Saco de limões", "image_url": "http://localhost:4006/files/lesson-images/13af25e32a8f11c0a533c0d7cf0e840ddc7112b7638debf0907eeafb9236f108.png"}, "rate_md": "Cada copo custa 5 reais. O saco de limões custa 10 reais."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "O vendedor de frutas oferece trocar 2 copos de limonada por um saco de limões. A troca é justa?", "difficulty": 1, "explanation_md": "2 copos custam 10 reais (2 × 5 = 10), igual ao saco de limões. É justo!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ebec4fa106ff02acfc188245e489a5ab652e8233bcead4ffa84f62ecb4a3c621.mp3", "hash": "c676cfdc37fd7d9347cf1aa48459d5a9e6e48e8ebf1cc0af8788849389f07ba6", "bytes": 29088, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ebec4fa106ff02acfc188245e489a5ab652e8233bcead4ffa84f62ecb4a3c621.mp3", "duration_ms": 4800}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f9b66a67cedc7e31f0f853c86acbf674f231dc5c596ca482456fe5fb5cca14c1.mp3", "hash": "1aa6e53cbff70cd498ed47eaac446d7c01712548c02f0b6d88494cdfaa1925e8", "bytes": 30096, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f9b66a67cedc7e31f0f853c86acbf674f231dc5c596ca482456fe5fb5cca14c1.mp3", "duration_ms": 4960}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/2a6ea62c6cd168d1c0f535166ae76c80f6a9a0e61ece359d15a556dbf569bd16.mp3", "hash": "b0ad8bfc7d67e185bbb341b559afb179f307347bd2f968ae105babcce1d6ea0c", "bytes": 44928, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2a6ea62c6cd168d1c0f535166ae76c80f6a9a0e61ece359d15a556dbf569bd16.mp3", "duration_ms": 7440}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/95ecbbccaa95069fa324b781e158ce4559acf11657f4601f5dbdcbca599f28dd.mp3", "hash": "58001c1abfb6a305c27591b00c6ba0a1d58ffa7d3b9d89e7ea9f4938e6e3eda7", "bytes": 49824, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/95ecbbccaa95069fa324b781e158ce4559acf11657f4601f5dbdcbca599f28dd.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "The receipt trail", "locale": "en-US", "subject": "mixed", "objectives": ["Search the market receipt for the exact evidence of how much the lemons cost."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Look on the receipt for the line that says ''lemons''.", "Look at the number next to ''lemons''."], "title": "The crumpled receipt", "payload": {"claim_md": "Liruf claims: ''I spent 20 dollars on lemons.''", "sentences": [{"id": "s1", "text_md": "Lemons: 15 dollars"}, {"id": "s2", "text_md": "Sugar: 5 dollars"}, {"id": "s3", "text_md": "Cups: 10 dollars"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/b367c6ece048b996ef8a3ca98588194d22148747630cd8f78f80e1d8e3661159.png", "prompt_md": "Liruf says: ''I spent 20 dollars on lemons.'' The receipt says something else. What evidence does the receipt show?", "difficulty": 1, "explanation_md": "The receipt shows that the lemons cost 15 dollars, not 20. Liruf made a mistake adding up.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/39ce1b345ebff1d0293050600eeeef939a2431b874df8eacadc02b7d0a3b75b4.mp3", "hash": "d845bcab10265500dd3ee2674d508c787b97d4e026f462d1bc60c6122145cbcf", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/39ce1b345ebff1d0293050600eeeef939a2431b874df8eacadc02b7d0a3b75b4.mp3", "duration_ms": 2880}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/741fff711d70967db3663d80ef1b4f524770ef5114cc430c922f23a687ac1d49.mp3", "hash": "17564a5e44fd8e5d5ade08d8dc567a7144e3d0fb980c40beaf3caee2d54e91f2", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/741fff711d70967db3663d80ef1b4f524770ef5114cc430c922f23a687ac1d49.mp3", "duration_ms": 1920}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/95a8b1cc44f22911ca7a9498d384edae06ca29476be573d364cfac268505622a.mp3", "hash": "e946e4ce77ccefca568e59e880230c7e346921144c1caa8ac18cd3c5620df407", "bytes": 39744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/95a8b1cc44f22911ca7a9498d384edae06ca29476be573d364cfac268505622a.mp3", "duration_ms": 6560}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/f5c28d2296b0e6c8a766a34cfb3dc0cce49dd7aa7744810784470496361563a2.mp3", "hash": "eb851cd986f09c0c583aa02b38ae72343a295402219758981c7f169186b7e4cc", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f5c28d2296b0e6c8a766a34cfb3dc0cce49dd7aa7744810784470496361563a2.mp3", "duration_ms": 5440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Sharing the profit", "locale": "en-US", "subject": "mixed", "objectives": ["Sharing a profit of 10 dollars between two piggy banks: one for the guitar goal and one for restocking ingredients."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 10, "type": "piggy_split", "hints": ["You can put more in one piggy bank and less in the other, but together they must add up to 10.", "The guitar piggy bank needs to save, and the stand piggy bank needs to restock ingredients."], "title": "Share 10 dollars", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Guitar piggy bank", "hint_md": "This piggy bank saves money to buy the 80-dollar guitar.", "image_url": "http://localhost:4006/files/lesson-images/4be4947a0c6dbf85c3f8a3969552db936a2348d7c6a072a2293a39b462937afe.png"}, {"id": "stand", "icon": "storefront", "label": "Stand piggy bank", "hint_md": "This piggy bank saves money to restock lemons and cups.", "image_url": "http://localhost:4006/files/lesson-images/42ad697252e734ac7c6dfac01ed6d5c473a4cbb694281bb8e92b615c2b8b27b6.png"}], "step": 1, "unit": "USD", "income": 10}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf earned 10 dollars today. How much do you put in each piggy bank?", "difficulty": 1, "explanation_md": "You shared the 10 dollars between the two piggy banks. The sum of both parts must be 10. Well thought!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"stand": {"max": 10, "min": 0}, "guitar": {"max": 10, "min": 0}}, "rationale_md": "La suma de lo que pongas en las dos alcancías debe ser exactamente 10 pesos. Puedes repartirlos como quieras, pero no más de 10 en total."}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/904924e57b337810fc9f39f7cc9dd9eb5c18b928e22a264758aca595e84a1e58.mp3", "hash": "8768951642cff6fd63d54d7add50e9ef08b043b1cedf3a07b150e25e9f1d29a4", "bytes": 30528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/904924e57b337810fc9f39f7cc9dd9eb5c18b928e22a264758aca595e84a1e58.mp3", "duration_ms": 5040}, "s1-piggy-split.hint.1": {"url": "http://localhost:4006/files/lesson-audio/765e6d9a25c89b0f9c7884db7887e130474114000d2878f5687f766c5f6e2cab.mp3", "hash": "5401832bcf97b59435a13d88f4c1965ac97299e35726b39119fca5c8401175bf", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/765e6d9a25c89b0f9c7884db7887e130474114000d2878f5687f766c5f6e2cab.mp3", "duration_ms": 4880}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/45b34937073a515a90580c95e2dae31ed5edcc0ab87b295ceb25bfbd6efaff70.mp3", "hash": "569f658ef603e1393a21a177ca873a9610c1092a13e6b101099cfcf6509b5ca7", "bytes": 25344, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/45b34937073a515a90580c95e2dae31ed5edcc0ab87b295ceb25bfbd6efaff70.mp3", "duration_ms": 4160}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/0a1a4dffbff0cf0a7bf833ceda23ba56d66b4233ec159bb325db01c2890a47f2.mp3", "hash": "475df940baff6eedfa9156b526dcfaf17549f9fcf6c03a425e4379c4032dc962", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0a1a4dffbff0cf0a7bf833ceda23ba56d66b4233ec159bb325db01c2890a47f2.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Preencha os números do posto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar dinheiro para comprar uma limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "fill_blank", "hints": ["Conte as moedas que sobram depois de pagar."], "title": "Lucro do dia", "payload": {"bank": [{"id": "b1", "text_md": "2"}, {"id": "b2", "text_md": "5"}, {"id": "b3", "text_md": "8"}], "mode": "typed", "text_md": "Sobraram {{1}} moedas de R$1 para Liruf."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tem 5 moedas de R$1. A limonada custa R$3. Quantas moedas sobram?", "difficulty": 1, "explanation_md": "Liruf pagou R$3 e sobraram 2 moedas de R$1. Ele ainda tem dinheiro para outro agrado!", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["2"], "bank_id": "b1"}]}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3f970845697389c266186c991467ca188ba67761767d584f713fb5e215087f53.mp3", "hash": "4fdc536a8ebb0503e62e7e5d9ed357a45105c6d670a75c6f3697dd92058970b2", "bytes": 17568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3f970845697389c266186c991467ca188ba67761767d584f713fb5e215087f53.mp3", "duration_ms": 2880}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/77fae340e01d2694c33eb02baf64ba566f933580aef113cf3a75421cd854a214.mp3", "hash": "002e47e26e9243deae49f459462506da964436d18c79e79125a252c9934f9f43", "bytes": 44496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/77fae340e01d2694c33eb02baf64ba566f933580aef113cf3a75421cd854a214.mp3", "duration_ms": 7360}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/dd1f9bb3d9736d53090cbe6c695da2b324707e1b6fd3ea85696d86a7c8ec54ba.mp3", "hash": "e50ffbd5bd0f5e550ded560fde0d5e3016a3181309ea9e3a73bbb247a75f27fa", "bytes": 45936, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dd1f9bb3d9736d53090cbe6c695da2b324707e1b6fd3ea85696d86a7c8ec54ba.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Emparejar productos y precios", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar cada producto del puesto con su precio correcto (vaso chico–5, jarra–20, galleta–3)."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["El vaso chico cuesta lo mismo que una moneda de 5 pesos.", "La jarra cuesta 20 pesos, como 4 monedas de 5."], "title": "Etiquetas revueltas", "payload": {"left": [{"id": "vaso", "text_md": "Vaso chico", "image_url": "http://localhost:4006/files/lesson-images/8fcc914b917b8aac9d840f437328a75ef01a95ab584723e023219a86bfded859.png"}, {"id": "jarra", "text_md": "Jarra", "image_url": "http://localhost:4006/files/lesson-images/52304bd3822386f01d742617ac76334596bee91d5478858c64273a3e128f858f.png"}, {"id": "galleta", "text_md": "Galleta", "image_url": "http://localhost:4006/files/lesson-images/617ac8824f272c3b201ad0e5f745f697ef24954f2966d5cd81a5733f3ca3c2e2.png"}], "right": [{"id": "precio5", "text_md": "5 pesos"}, {"id": "precio20", "text_md": "20 pesos"}, {"id": "precio3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toca cada producto y luego su precio para emparejarlos.", "difficulty": 1, "explanation_md": "El vaso chico cuesta 5 pesos, la jarra cuesta 20 y la galleta cuesta 3. ¡Así el puesto queda ordenado!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "precio5"], ["jarra", "precio20"], ["galleta", "precio3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fcbea33f1e1d527074c06f46867ff563c4b0617df3697c958c47a328d5cd0e8f.mp3", "hash": "7a4b6455948dfd5a451ac2229e4402c4366fb6fff084b914faaf70ea67d71ca6", "bytes": 25776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fcbea33f1e1d527074c06f46867ff563c4b0617df3697c958c47a328d5cd0e8f.mp3", "duration_ms": 4240}, "s1-match-prices.hint.1": {"url": "http://localhost:4006/files/lesson-audio/26f27ac984ebd02113f91cbc1755a3b3c6ec477ea3439c4adad61964670598a4.mp3", "hash": "fd35d7081c1364de8a3e44b49b9b1453f70e432ddfd57209a0baa7e15acb370a", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/26f27ac984ebd02113f91cbc1755a3b3c6ec477ea3439c4adad61964670598a4.mp3", "duration_ms": 4560}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/ddcf0b7fabaf7014f89a37094ba9766357b3f377a2a52306ad5870636455afd0.mp3", "hash": "a4bd6106d5952835757795b0e228c9c18daf6fe917dfd48b75bd42105cf1d9aa", "bytes": 24768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ddcf0b7fabaf7014f89a37094ba9766357b3f377a2a52306ad5870636455afd0.mp3", "duration_ms": 4080}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/5cb08e44e12231fadc38fac64b7c2fa394bf7270e8f4f33567fbef65eec630ba.mp3", "hash": "3040efa83c90653273a1f3b42a7651f450efb86065f268a2ad43228037de9629", "bytes": 48384, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5cb08e44e12231fadc38fac64b7c2fa394bf7270e8f4f33567fbef65eec630ba.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "would-you-rather", "title": "O que você faria? Dilemas da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher entre dois caminhos do vendedor e defendê-lo: ganhar R$10 hoje ou R$20 na próxima semana?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-wyr", "xp": 15, "type": "would_you_rather", "hints": ["Pense: Liruf precisa do dinheiro hoje ou pode esperar uma semana?", "Não há resposta errada, só consequências diferentes."], "title": "Ganhar hoje ou esperar?", "payload": {"a": {"icon": "payments", "text_md": "**Ganhar R$10 hoje** vendendo 2 copos de limonada agora mesmo.", "image_url": "http://localhost:4006/files/lesson-images/b26aa043e3f65bd9a213f62e13bda9b3122df1c38c7b74865289239296bf7203.png"}, "b": {"icon": "trending_up", "text_md": "**Ganhar R$20 na próxima semana** se preparar mais limonada e vender o dobro.", "image_url": "http://localhost:4006/files/lesson-images/5aa1d1b769ee05471b032ec4bb30939d7b56a7a028676006fee10837939b1b8f.png"}, "followup_md": "Por que você escolheu essa opção? Conte para Dina o seu motivo."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina te propõe um dilema: o que você escolhe para Liruf?", "difficulty": 2, "explanation_md": "Dina sorri: ''Ambas as opções têm sua razão. O importante é que você pense antes de decidir.''", "audio_segment_id": "s1-wyr.prompt"}], "schema_version": 1}', '{"s1-wyr": {"qualities": {"a": 50, "b": 50}, "reveal_md": "Dina asiente: ''Ambos caminos tienen sentido. Lo importante es que sepas por qué eliges.''"}}', '{"units": {"s1-wyr.hint.0": {"url": "http://localhost:4006/files/lesson-audio/395da1dfb479d22796692127a57486943aa985fdea3be9059b3e9f54bb2362ba.mp3", "hash": "fa5b48ca8f6c5b7b3f6183a2edb5f6d1965cb84ae17e7074b75e4a7fa4189752", "bytes": 31104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/395da1dfb479d22796692127a57486943aa985fdea3be9059b3e9f54bb2362ba.mp3", "duration_ms": 5120}, "s1-wyr.hint.1": {"url": "http://localhost:4006/files/lesson-audio/21223ee33843c4dbd59081149901f6f52278cf1c50e7a3fc2a3f89cb1dfb739b.mp3", "hash": "42f586df2709ffb5247d979addb156aa2e97e7ad8a485c0bed691643c225f46a", "bytes": 23904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/21223ee33843c4dbd59081149901f6f52278cf1c50e7a3fc2a3f89cb1dfb739b.mp3", "duration_ms": 3920}, "s1-wyr.prompt": {"url": "http://localhost:4006/files/lesson-audio/730a35c6bb8db778c1a9dea82a341fadcc1fd09b53e69e674df890cdaef3b5ca.mp3", "hash": "27b5753b148533d95b40f016a7f6b4d5f298c9069e283dd201d2c9bd3cb47c23", "bytes": 22896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/730a35c6bb8db778c1a9dea82a341fadcc1fd09b53e69e674df890cdaef3b5ca.mp3", "duration_ms": 3760}, "s1-wyr.choices": {"url": "http://localhost:4006/files/lesson-audio/c19837302d078a78d1682a5e439c2bf910c027bff93f5ff177dc5363c37e46ed.mp3", "hash": "18ce1f9f3b163761e5eca5fbacf072e12445c2e481446507d222259a27b3b89d", "bytes": 71856, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c19837302d078a78d1682a5e439c2bf910c027bff93f5ff177dc5363c37e46ed.mp3", "duration_ms": 11920}, "s1-wyr.explanation": {"url": "http://localhost:4006/files/lesson-audio/06c8b7bc553eb2cea3dd94a730b0f160f3047948262c6219c018abf601b9413e.mp3", "hash": "3e8243deae66dba339eba80e72a41cd279d3d32c149ca3efc75c1d464d820722", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/06c8b7bc553eb2cea3dd94a730b0f160f3047948262c6219c018abf601b9413e.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Liruf''s Market", "locale": "en-US", "subject": "money", "objectives": ["Counting money with 1, 2, 5, and 10 dollar coins", "Calculating change from a 20 dollar bill", "Planning how many weeks until the goal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 15, "type": "budget_fit", "hints": ["Add the price of lemons and sugar: 8 + 6 = 14. Then subtract 14 from 20 to find out how much is left."], "title": "Restocking the stand", "payload": {"items": [{"id": "limones", "icon": "nutrition", "need": true, "label": "Lemons", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/96320b8c76e81cbbcbf30a0049a1adfe937d6b7bf3aa95a81082803ac48e0744.png"}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Sugar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/c78736cdd338adfa366abf88889fd73ffdfacb4d8928a18a2c24672856950252.png"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Ice", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/151eb2710f1790bf5e79bcbe631bd6e4a98de0126a93ad8ca1f2baa7b98fb69a.png"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Straws", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/67a718df3773392542679a535f891e04f389866cdf4d9789bfed374eae2f990b.png"}, {"id": "jarra", "icon": "local_bar", "need": false, "label": "Pretty pitcher", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/fe41c5d8b930f2d5af8d81b06d4202bf0c6103c7c07fcea82dd94b335f169275.png"}], "budget": 20, "currency": "USD", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf has a $20 bill. He needs to buy lemons ($8) and sugar ($6). What else fits without going over $20?", "difficulty": 2, "explanation_md": "Liruf needs lemons and sugar for lemonade. If he spends 8 + 6 = 14, he has 6 dollars left. Ice costs 5, straws cost 3, and the pitcher costs 8. Only ice (5) fits in the 6 he has left. If he buys the pitcher (8), he goes over and the vendor takes something away; if he buys straws (3), he still has leftover, but ice is better for lemonade.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ef5de12dec9ff0c411234e8a944b5fa54c2f313c921ea2341359e6213f1a1759.mp3", "hash": "5cc4419c7252a3a362690f7595b7d313bf390e6a0999a2a094885022e008bfa1", "bytes": 42624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ef5de12dec9ff0c411234e8a944b5fa54c2f313c921ea2341359e6213f1a1759.mp3", "duration_ms": 7040}, "s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/eda7b7f1804c03b1caf79eca15c188114c296dc7f4a39402114321821e18a63c.mp3", "hash": "c1b45d5f70235c536f2fa99a25c3f7b2ee46ecf7f1773b881e16dff7e656aeac", "bytes": 47808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/eda7b7f1804c03b1caf79eca15c188114c296dc7f4a39402114321821e18a63c.mp3", "duration_ms": 7920}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/0b0202e14f44c6369cfcfe5463ac93f321cdb15d7fe0f35e471bd39a575e84cf.mp3", "hash": "762956f45dddb7ac1460ce15788bc698311f7aea8eea3b8704345cfffe45790e", "bytes": 116928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0b0202e14f44c6369cfcfe5463ac93f321cdb15d7fe0f35e471bd39a575e84cf.mp3", "duration_ms": 19440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'pt-BR', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "flash-match", "title": "Flash Match: Conceitos do Cargo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Relacionar cada palavra do cargo com seu exemplo concreto (poupança→cofrinho, custo→limões, lucro→o que sobra)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "hints": ["Pense no que cada palavra significa no cargo de limonada.", "A poupança é o que você guarda, o custo é o que você paga, o lucro é o que sobra."], "title": "¡Conecte os conceitos!", "payload": {"left": [{"id": "ahorro", "text_md": "Poupança", "image_url": "http://localhost:4006/files/lesson-images/e73a88b7130557db1c60a2630587bcb3cb070d3b3fbd97342b5414721edfa745.png"}, {"id": "costo", "text_md": "Custo", "image_url": "http://localhost:4006/files/lesson-images/310c0ef766fb0472606932b3e7f9aa6baddd7c94543f0b6ed0fd4ca358e5d3fb.png"}, {"id": "ganancia", "text_md": "Lucro", "image_url": "http://localhost:4006/files/lesson-images/66231cf7891716b5b39ef8d58fa8d8f45ca861a0433e9b2f84441f61a903a0c9.png"}], "right": [{"id": "alcancia", "text_md": "Cofrinho"}, {"id": "limones", "text_md": "Limões"}, {"id": "lo-que-sobra", "text_md": "O que sobra"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toque em cada palavra da esquerda e depois no seu exemplo à direita. Rápido!", "difficulty": 1, "explanation_md": "Poupança é guardar dinheiro no cofrinho, custo são os limões que você compra, lucro é o que sobra depois de vender.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "lo-que-sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2d22a946ddc92ead367898dd06c354e120bea7ff552837643a5e0e21a5289c15.mp3", "hash": "9f915e0d599e36242f9b3a8cfaac21acd490644fca1c39bd917fdefce1e4ad1e", "bytes": 21456, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/2d22a946ddc92ead367898dd06c354e120bea7ff552837643a5e0e21a5289c15.mp3", "duration_ms": 3520}, "s1-flash-match.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6008bf4c73cf30b7fa5c1c6a2514bd83b655a53b71bf64587925e4f96ae53de7.mp3", "hash": "001ead6d3098c9b6be15effd62433016c79d2ea26e890f67d72ff5b13d6df0d4", "bytes": 39744, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/6008bf4c73cf30b7fa5c1c6a2514bd83b655a53b71bf64587925e4f96ae53de7.mp3", "duration_ms": 6560}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/a0a507eb8c74c0b788ebcdbee05d97ee0e7c37ed53e105b2cf2df68c90d79bd9.mp3", "hash": "4103d51361fd3ea38e9c1a213b4766320c78d72407edc2df035b176531d82863", "bytes": 34848, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a0a507eb8c74c0b788ebcdbee05d97ee0e7c37ed53e105b2cf2df68c90d79bd9.mp3", "duration_ms": 5760}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/04cbf422b88d2028f7b0df899c22e706a80f00ddf8bb6beaa6f665c9cd94395e.mp3", "hash": "b131588b590fe50996b94a609a49a98661dacef83e80610676fe167720954388", "bytes": 44496, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/04cbf422b88d2028f7b0df899c22e706a80f00ddf8bb6beaa6f665c9cd94395e.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encontre o erro na conta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas", "Ler um gráfico simples de copos vendidos por dia", "Reconhecer sinais de um mau negócio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 10, "type": "spot_error", "hints": ["Conte quantos 5 há na soma.", "Quanto somam três vezes 5?"], "title": "A conta de Liruf", "payload": {"steps": [{"id": "step1", "text_md": "5 + 5 = 10"}, {"id": "step2", "text_md": "10 + 5 = 15"}, {"id": "step3", "text_md": "O resultado é 20"}], "context_md": "Liruf vendeu 3 copos de limonada a 5 reais cada um. Anotou em seu caderno: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/65955a0684105bb3fbe95d1d46c8d9a4cc2b1606422fd11e5e5d89059b0cd467.png", "prompt_md": "Liruf anotou: 5 + 5 + 5 = 20. Qual passo está errado?", "difficulty": 1, "explanation_md": "Liruf somou 5 + 5 + 5, que dá 15, não 20. O erro está no resultado.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step3"], "correction_md": "El resultado correcto es 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c65f44050edc2f5a9f85d7acfee1b4817b3b65133d16ea1c9cb34c915387b011.mp3", "hash": "a495af47dc628afeb25655ae68352aa1adc6da284d4e3d2e3047d0e69c646ca0", "bytes": 16128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c65f44050edc2f5a9f85d7acfee1b4817b3b65133d16ea1c9cb34c915387b011.mp3", "duration_ms": 2640}, "s1-spot-error.hint.1": {"url": "http://localhost:4006/files/lesson-audio/57b82321a403061107e87b0387f2a97c3c19c2e258ecfb23acdf3008509224b6.mp3", "hash": "1e770f10339df72839c634b82feaf253e323d29255b79c2ae552cb79045091f9", "bytes": 14256, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/57b82321a403061107e87b0387f2a97c3c19c2e258ecfb23acdf3008509224b6.mp3", "duration_ms": 2320}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/cba0675cbf629b3a91ee0d0d48fd41eaec2b825d4428f0a6cd883bb84dc54696.mp3", "hash": "1d34b45bb3bda80a8e31794b1bbdcd93b9c90af4d221b84f1b603cbed0dfde76", "bytes": 39168, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cba0675cbf629b3a91ee0d0d48fd41eaec2b825d4428f0a6cd883bb84dc54696.mp3", "duration_ms": 6480}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/08f4a019ce6a9a086712ceb795a779245f0623138bef68e9482200e3c6d40b2e.mp3", "hash": "72dced1abd5a142588cc118fbe7653c6ecb356feb4a28ab5394bd52c3dd29776", "bytes": 45936, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/08f4a019ce6a9a086712ceb795a779245f0623138bef68e9482200e3c6d40b2e.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "speed-tap", "title": "Quick lemonade decisions", "locale": "en-US", "subject": "money", "objectives": ["Distinguish expenses that help the lemonade stand from treats that don''t help."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 10, "type": "speed_tap", "hints": ["Think: does this help make or sell lemonade?", "Treats like toys don''t help sell."], "title": "Catch what helps!", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/2d7396dacdd9d11a983d9749dca165a7fe12ac75f90f8544669f3ba336c56872.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/cc535b5d5f7d58b509bb6abf0564159ee5f0452437fd18b7fcbdce8d950ae40a.png"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/c423695899f49c66f41cd0d744a7deff033e50cfe11656a361b3443b0e6958da.png"}, {"id": "hielo", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/b0523a6e5fb1b216621693d6e8b90270acd8a63bab5bb5ad4680860d76122b04.png"}, {"id": "cartel", "text_md": "Eye-catching sign", "image_url": "http://localhost:4006/files/lesson-images/50d4ba55979f56ac117c7554afd772552d727992928d5f57ac43bc5af6196966.png"}, {"id": "calcomania", "text_md": "Dinosaur sticker"}, {"id": "dulce", "text_md": "Candy", "image_url": "http://localhost:4006/files/lesson-images/dc2e1115e4bd5529bf49976cd649079ff32c38c744f6fe753eddd08502dd3b2a.png"}, {"id": "juguete", "text_md": "Little toy", "image_url": "http://localhost:4006/files/lesson-images/7193e354c27418f5a55aa0c9523515690408a363405b7533956e60f0e7fa6937.png"}], "seconds": 15, "instruction_md": "Tap the cards that help the lemonade stand."}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho flies cards by. Tap only the ones that help sell more lemonade.", "difficulty": 1, "explanation_md": "Lemons, cups, sugar, ice, and a sign help sell more lemonade. The sticker, candy, and toy are treats that don''t help.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2f0e980ab293d565a55ddbc124d94d2fc0741fcd4a9b8da19683ca8ca92eaf15.mp3", "hash": "7b5cd823d44c18768fd6c6eee908f50ddc0ac55be238d6b0df47cab8eab4d2a7", "bytes": 22896, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2f0e980ab293d565a55ddbc124d94d2fc0741fcd4a9b8da19683ca8ca92eaf15.mp3", "duration_ms": 3760}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a259412af60b3613876e756bb86f79c386be01efa2c61a12fbbbc9fcb0cc08bb.mp3", "hash": "bbc862aa922e43fdc2dda49707db3b71dc4469c601dc62934d2b8e5c104f26b1", "bytes": 15696, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a259412af60b3613876e756bb86f79c386be01efa2c61a12fbbbc9fcb0cc08bb.mp3", "duration_ms": 2560}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/380de3d08b738946ea53f126db06f0a97eeb8435d95e01db90422012623ad92a.mp3", "hash": "26494d9c71464e70d39f972a9dcee858e88377c4a9a6b0862dbc49baa256e856", "bytes": 32544, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/380de3d08b738946ea53f126db06f0a97eeb8435d95e01db90422012623ad92a.mp3", "duration_ms": 5360}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/9ae0c34b502edb232e4e5e39615094d032d893b7e17c55ad9f3d952edb3db01f.mp3", "hash": "a7b07f3cb83660e6f07109bb3da26e086e63f0d7007c004b3836e358382b5580", "bytes": 55584, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9ae0c34b502edb232e4e5e39615094d032d893b7e17c55ad9f3d952edb3db01f.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "equation-builder", "title": "Arma la cuenta de la tarde", "locale": "es-MX", "subject": "mixed", "objectives": ["Armar con fichas la suma de la tarde: 5 + 5 + 5 = 15 pesos (tres vasos vendidos)"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-cuenta", "xp": 10, "type": "equation_builder", "hints": ["Cada vaso cuesta 5 pesos. ¿Cuánto es 5 + 5?", "Luego suma el tercer 5 al resultado."], "title": "Arma la suma de la tarde", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Rho vendió 3 vasos de limonada esta tarde. Arma la suma con las fichas.", "difficulty": 1, "explanation_md": "Tres vasos de 5 pesos cada uno suman 5 + 5 + 5 = 15 pesos. ¡Así se arma la cuenta de la tarde!", "audio_segment_id": "s1-arma-cuenta.prompt"}], "schema_version": 1}', '{"s1-arma-cuenta": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-arma-cuenta.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d2aba16dc93bd2490b8bf509e287424ce395e7a539f5fc999d1022627c9da6c0.mp3", "hash": "c73b47cef774224aa87fbeb449972e0bfcb1b571c29f70e3898fa49ffeb0b4eb", "bytes": 31968, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/d2aba16dc93bd2490b8bf509e287424ce395e7a539f5fc999d1022627c9da6c0.mp3", "duration_ms": 5280}, "s1-arma-cuenta.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ae519522c8c28d99fb6caba4acaf79127915649c2aec4fda40d467914675de7d.mp3", "hash": "4f8be3e18d70978ef35bf3b1abe8ce68412cf486f02b40c921833b3a98a29792", "bytes": 18576, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/ae519522c8c28d99fb6caba4acaf79127915649c2aec4fda40d467914675de7d.mp3", "duration_ms": 3040}, "s1-arma-cuenta.prompt": {"url": "http://localhost:4006/files/lesson-audio/8652624b51815e8b89b3c686c15b7da61d45478dfe073abacf3a9fcea1bb84be.mp3", "hash": "a11510534c7275330d65eee8c866327ce574e7cb173c8c5e5a78e4b47407402e", "bytes": 34416, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/8652624b51815e8b89b3c686c15b7da61d45478dfe073abacf3a9fcea1bb84be.mp3", "duration_ms": 5680}, "s1-arma-cuenta.explanation": {"url": "http://localhost:4006/files/lesson-audio/40cb43cf6e8db0e56fe60910981605ac3c1d448d186da6d305eaff57a6c8b48c.mp3", "hash": "dcb7570dc786c50265a0f13de60741bd06c1e714fe82a4164ba400516a06cc31", "bytes": 58896, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/40cb43cf6e8db0e56fe60910981605ac3c1d448d186da6d305eaff57a6c8b48c.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa y efecto en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Conectar causas y efectos del puesto: día soleado → más sed → más vasos vendidos; subir el precio al doble → menos clientes."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 10, "type": "cause_effect", "hints": ["Piensa: ¿qué pasó primero?", "El sol hace que la gente tenga más sed."], "title": "¿Qué pasó?", "payload": {"slots": 5, "events": [{"id": "e1", "text_md": "Día soleado y caluroso"}, {"id": "e2", "text_md": "La gente tiene más sed"}, {"id": "e3", "text_md": "Liruf vende 12 vasos de limonada"}, {"id": "e4", "text_md": "Rho sube el precio a 10 pesos por vaso"}, {"id": "e5", "text_md": "Menos clientes compran limonada"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toca los eventos en orden: causa → efecto.", "difficulty": 1, "explanation_md": "El día soleado hizo que la gente tuviera sed, por eso compraron más limonada. ¡Liruf vendió 12 vasos!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bbcd52187e05499d6e52223cd8ad34f1eb5f0ac4fd8db35d804a628cf125cdd2.mp3", "hash": "6033cc72ae52f27a05e067d22a9ffb437d2e1b8c0577c677c90dde1b4d297d83", "bytes": 11808, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/bbcd52187e05499d6e52223cd8ad34f1eb5f0ac4fd8db35d804a628cf125cdd2.mp3", "duration_ms": 1920}, "s1-cause-effect.hint.1": {"url": "http://localhost:4006/files/lesson-audio/104ce38bb51baf4e0e9a23c4d434634124a44b321c1f84e917c354b2ccaeafa2.mp3", "hash": "9ba6d554357fffd919a80a7fd45f0d708a3482988e0c48d163c5a3d5d335627a", "bytes": 15696, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/104ce38bb51baf4e0e9a23c4d434634124a44b321c1f84e917c354b2ccaeafa2.mp3", "duration_ms": 2560}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/5a97aa7d5b527893215145ca2977da2c0bafcf80b4636c0e60a9d9fc5e234c00.mp3", "hash": "656e3617f300cf565fcb1fc37576de57bb48e80afc33807c4e524cd0058b6e7f", "bytes": 20448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5a97aa7d5b527893215145ca2977da2c0bafcf80b4636c0e60a9d9fc5e234c00.mp3", "duration_ms": 3360}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/10e5e4460f835a07e87c39b1657d047935cf0bd55f7e554d8560f683bbfabab1.mp3", "hash": "8c48393067d3a6191b25b4e7d421645b198c5a061da76547307c6ff479fcb43f", "bytes": 46944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/10e5e4460f835a07e87c39b1657d047935cf0bd55f7e554d8560f683bbfabab1.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confiança nas suas contas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Somar 5 + 5 para calcular o total de dois copos vendidos", "Avaliar o nível de confiança no resultado de uma soma simples"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 10, "type": "confidence_quiz", "hints": ["Pense: um copo são 5 reais, dois copos são 5 mais 5.", "Você pode contar nos dedos: 5 e depois mais 5."], "title": "Vendas de Liruf", "payload": {"options": [{"id": "opt-10", "text_md": "10 reais", "rationale_md": "¡Correto! 5 + 5 = 10."}, {"id": "opt-5", "text_md": "5 reais", "rationale_md": "5 reais é o preço de um único copo, mas Liruf vendeu dois copos."}, {"id": "opt-15", "text_md": "15 reais", "rationale_md": "15 seria se cada copo custasse 7,50, mas cada copo custa 5 reais."}, {"id": "opt-8", "text_md": "8 reais", "rationale_md": "8 seria se um copo custasse 3 e outro 5, mas ambos custam 5."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vendeu dois copos de limonada. Cada copo custa 5 reais. Quanto dinheiro ele juntou?", "difficulty": 1, "explanation_md": "Dois copos de 5 reais cada um somam 10 reais. Liruf juntou 10 reais pelas duas vendas.", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confidence-quiz.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b1be5d369c3caaf039cfff5c39949b8b3577b597439d194fca1dbabe00dc9689.mp3", "hash": "f009391e1a652884cd56b8b0687104becf1ac62ae0f566342b062015cfa7f3c8", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b1be5d369c3caaf039cfff5c39949b8b3577b597439d194fca1dbabe00dc9689.mp3", "duration_ms": 5440}, "s1-confidence-quiz.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5c1f92948f9e72043c80468b42dd4651a5de9fcd1ff00e09f996b18426910978.mp3", "hash": "3d805eed5af23c0b7568c99e6f5441d7b6d68ede6008dc4278907bafa18e6bd5", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5c1f92948f9e72043c80468b42dd4651a5de9fcd1ff00e09f996b18426910978.mp3", "duration_ms": 4080}, "s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/d1255406ffa6478d98391e190ff83f5a8edbbab2a4a3afde09bdb6c112dfba3d.mp3", "hash": "12204b13b3af40c1cc5fb9ed6ff4faccfe6063e662b1ecd28464a28e07689138", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d1255406ffa6478d98391e190ff83f5a8edbbab2a4a3afde09bdb6c112dfba3d.mp3", "duration_ms": 7200}, "s1-confidence-quiz.choices": {"url": "http://localhost:4006/files/lesson-audio/677d715c35f8feea6d537d2dde215a7c06c3cf9568546f1de0aedd6029b254c6.mp3", "hash": "37f3a70534ec4fbb31877a706af22255fa01f46569e890bc2236b982cfa637bc", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/677d715c35f8feea6d537d2dde215a7c06c3cf9568546f1de0aedd6029b254c6.mp3", "duration_ms": 5440}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/d9f752e0d2622b467453db2e28aed117df3ee2d3443e99c2ee0cdabec1eb386e.mp3", "hash": "ceafb0a74a21272eb70253e3acc9587d11685dee1db74552834e751474534572", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d9f752e0d2622b467453db2e28aed117df3ee2d3443e99c2ee0cdabec1eb386e.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "A registradora de papelão", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar as instruções da registradora caseira: receber pagamento → verificar valor → dar troco → anotar a venda."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-registradora", "xp": 15, "type": "code_order", "hints": ["Primeiro, recebe o pagamento do cliente.", "Depois de dar o troco, anota a venda."], "title": "Ordene os passos", "payload": {"blocks": [{"id": "recibir", "text_md": "Receber pagamento"}, {"id": "verificar", "text_md": "Verificar valor"}, {"id": "dar_cambio", "text_md": "Dar troco"}, {"id": "anotar", "text_md": "Anotar a venda"}], "language_hint": "Passo a passo"}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Rho vende limonada a 5 reais. Um cliente paga com 10. O que Rho faz primeiro?", "difficulty": 2, "explanation_md": "Rho recebe os 10 reais, vê que são mais que 5, dá 5 de troco e anota a venda. Assim funciona a registradora!", "audio_segment_id": "s1-ordenar-registradora.prompt"}], "schema_version": 1}', '{"s1-ordenar-registradora": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"s1-ordenar-registradora.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f27e32ed59f1464921a6c19f2ffdbf0c6f1d8ede6ca2ee0e7ed9d4d3802da628.mp3", "hash": "0d7b6d2d06ae74d8a64fbd92ed48d0310b15ad6c175a98eae98c12cb43f8c00d", "bytes": 18576, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f27e32ed59f1464921a6c19f2ffdbf0c6f1d8ede6ca2ee0e7ed9d4d3802da628.mp3", "duration_ms": 3040}, "s1-ordenar-registradora.hint.1": {"url": "http://localhost:4006/files/lesson-audio/14a2a0982de67390ab92ebbdab6a7efaf91100b1e63119774cbad6f644ec2b72.mp3", "hash": "0f59e33bdef43cff48de5fded9e98c6da927edb1551f970e2dba27a51994b32e", "bytes": 19008, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/14a2a0982de67390ab92ebbdab6a7efaf91100b1e63119774cbad6f644ec2b72.mp3", "duration_ms": 3120}, "s1-ordenar-registradora.prompt": {"url": "http://localhost:4006/files/lesson-audio/f195e1fe41eb1166bd0e0b249c867a10da2c96db206a663d3fa35bb1c3d0a4bd.mp3", "hash": "177660d749594256979cc7abcc01d12732301175a553ebcd8f1910ddfdbcc26c", "bytes": 40608, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/f195e1fe41eb1166bd0e0b249c867a10da2c96db206a663d3fa35bb1c3d0a4bd.mp3", "duration_ms": 6720}, "s1-ordenar-registradora.explanation": {"url": "http://localhost:4006/files/lesson-audio/45b7378b2ab92df1e9dd1fafee5db4c2ec5113011a1fd314d6b0b499f3a08ac2.mp3", "hash": "bacf78e1452fa09f65472db9992b685573f6a38cbad9081e865390602f5b7204", "bytes": 57888, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/45b7378b2ab92df1e9dd1fafee5db4c2ec5113011a1fd314d6b0b499f3a08ac2.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Match the stall prices", "locale": "en-US", "subject": "mixed", "objectives": ["Match products with their exact prices using coins"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 10, "type": "memory_flip", "hints": ["Remember: the cookie costs 3 coins, the small cup 5, and the large pitcher 20."], "title": "Price memory", "payload": {"pairs": [{"a_md": "Cookie", "b_md": "3 coins (1+2)", "a_icon": "cookie", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/2ac15f9b207c4be166502b1979c9e3a45edc259af5e60111ef5cfb52a8c57fd8.png", "b_image_url": "http://localhost:4006/files/lesson-images/5b03a040e5c1b67fe6414ed9ae88886601840d6a4249dc78adfa55a8a45f24fc.png"}, {"a_md": "Small cup", "b_md": "5 coins", "a_icon": "water_drop", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/e6a4e9a95c1ff3666c647a1d4dc49d68dbe6409a8c541aa262f5be269b82bf0e.png", "b_image_url": "http://localhost:4006/files/lesson-images/54522151bc48a76c0dc4d258aa9f0b475cdd286affe496556b6a82500df8742c.png"}, {"a_md": "Large pitcher", "b_md": "20 coins (10+10)", "a_icon": "local_bar", "b_icon": "monetization_on", "a_image_url": "http://localhost:4006/files/lesson-images/a6d12279f5517ba82361dbd32d6eac734aa351529ca9c96c5da0d81a7db27e69.png", "b_image_url": "http://localhost:4006/files/lesson-images/fdcbac21b05e8107452923230b198536dedae4c9bc9f04f5a3339ca51bb877b2.png"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Tap the cards to match each product with its exact payment. Cookie = 3, small cup = 5, large pitcher = 20.", "difficulty": 1, "explanation_md": "Each product has a fixed price: cookie 3, small cup 5, large pitcher 20. That way Liruf can charge quickly!", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/575beae49480652d6e3c26f89739c5718db5c055aca3128cc653cd21ccb4f1fb.mp3", "hash": "d7742b56d6d910831810b20e5608e32348dfb80eed6d8d659dee13f8822ee580", "bytes": 39744, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/575beae49480652d6e3c26f89739c5718db5c055aca3128cc653cd21ccb4f1fb.mp3", "duration_ms": 6560}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/38e1d567bdd9c346dd7c3b91372400f43d51939cc15e0979b588ead8e9b02c3e.mp3", "hash": "ad8fe1c9c68efb40c61f856bee537675293c06364a8536615afe6e60e2844b16", "bytes": 57456, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/38e1d567bdd9c346dd7c3b91372400f43d51939cc15e0979b588ead8e9b02c3e.mp3", "duration_ms": 9520}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/22970e776af7ce8b44252da7bc1eed0a920d8bbe0442fb03c7a0bb704657131a.mp3", "hash": "5f066a91578d2beed1c2a89b2486873f136300d2ca05db8687547077499df1bd", "bytes": 48384, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/22970e776af7ce8b44252da7bc1eed0a920d8bbe0442fb03c7a0bb704657131a.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Dividir o lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Dividir um lucro de 10 reais entre dois cofrinhos: um para a meta do violão e outro para repor ingredientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 10, "type": "piggy_split", "hints": ["Você pode colocar mais em um cofrinho e menos no outro, mas entre os dois devem somar 10.", "O cofrinho do violão precisa economizar, e o da barraca precisa repor ingredientes."], "title": "Dividir 10 reais", "payload": {"jars": [{"id": "guitar", "icon": "savings", "label": "Cofrinho do violão", "hint_md": "Este cofrinho guarda dinheiro para comprar o violão de 80 reais.", "image_url": "http://localhost:4006/files/lesson-images/886a1d8c5cdb95e76e00e55fe6d930b9770c602c13c68cc46074b910b3136ad3.png"}, {"id": "stand", "icon": "storefront", "label": "Cofrinho da barraca", "hint_md": "Este cofrinho guarda dinheiro para repor limões e copos.", "image_url": "http://localhost:4006/files/lesson-images/ac8ca3ac5d4b75dc58754d5a2f3d42a10975371c4bc8ab58bd7b1f6b717759c1.png"}], "step": 1, "unit": "BRL", "income": 10}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf ganhou 10 reais hoje. Quanto você coloca em cada cofrinho?", "difficulty": 1, "explanation_md": "Você dividiu os 10 reais entre os dois cofrinhos. A soma de ambas as partes deve ser 10. Muito bem pensado!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"stand": {"max": 10, "min": 0}, "guitar": {"max": 10, "min": 0}}, "rationale_md": "La suma de lo que pongas en las dos alcancías debe ser exactamente 10 pesos. Puedes repartirlos como quieras, pero no más de 10 en total."}}', '{"units": {"s1-piggy-split.hint.0": {"url": "http://localhost:4006/files/lesson-audio/66e5f73ec5bf50ee3b3c9b810205a322f323afd59e9f066fe30e58247f4dcae8.mp3", "hash": "7e92f7ac53e4dbba28f6bbad4bd71b0cd48eee6eb274ed8d3d113a290755a763", "bytes": 37296, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/66e5f73ec5bf50ee3b3c9b810205a322f323afd59e9f066fe30e58247f4dcae8.mp3", "duration_ms": 6160}, "s1-piggy-split.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4bdecd75b68445872fd3ee78531162b17819b667ba36a2d203d168a80377a8bf.mp3", "hash": "89cec14ef37c4a25d4fed489f6a67b405c650c03ea1db17eba4a0c92b4bad494", "bytes": 35856, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4bdecd75b68445872fd3ee78531162b17819b667ba36a2d203d168a80377a8bf.mp3", "duration_ms": 5920}, "s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/4ada472ee6ba49d5aec891a294decf1018d485811a6307dd31991bf3c48fdb42.mp3", "hash": "7efdcbb467da295b7a0d7e30e58b13648a52cefae56ab8c9f66d5d47a5c08642", "bytes": 34848, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4ada472ee6ba49d5aec891a294decf1018d485811a6307dd31991bf3c48fdb42.mp3", "duration_ms": 5760}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/cfd743caf1706c14800830cfe5ae12f081ede51e15c6095cd0cbf35be4508f52.mp3", "hash": "24ea8c47b86ca9ea9de4e7be02dafc2c1c90677401952f07e60943ef336b2d82", "bytes": 53136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cfd743caf1706c14800830cfe5ae12f081ede51e15c6095cd0cbf35be4508f52.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'pt-BR', '1', E'{"meta": {"cast": ["liruf", "zara", "dina"], "slug": "build-sentence", "title": "O letreiro do combo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o preço de 2 copos de limonada a 5 reais cada um e montar o letreiro correto."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-letrero", "xp": 15, "type": "build_sentence", "hints": ["Cada copo custa 5 reais. Quanto custam dois?", "Pense: 5 mais 5 são..."], "title": "O letreiro do combo", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "copos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "10"}, {"id": "t6", "text_md": "15"}, {"id": "t7", "text_md": "20"}, {"id": "t8", "text_md": "reais"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf quer um letreiro que diga: \\"2 copos por ___ reais\\". Toque nas fichas em ordem para montá-lo.", "difficulty": 2, "explanation_md": "O letreiro deve dizer \\"2 copos por 10 reais\\" porque cada copo custa 5 e dois custam 5+5=10. Se você colocasse 5, só daria para um copo. 15 é o que Dina gastou em outra coisa, e 20 é a nota com que pagam.", "audio_segment_id": "s1-combo-letrero.prompt"}], "schema_version": 1}', '{"s1-combo-letrero": {"order": ["t1", "t2", "t3", "t5", "t8"]}}', '{"units": {"s1-combo-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9cf63abc71377470d588bb77c39dedd12f368a207eb9ad4f4d053f9f01420b49.mp3", "hash": "6ba12800298e4878be434a21e1151bffca91c7f347ec9988eaf89e3ca545166f", "bytes": 26784, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9cf63abc71377470d588bb77c39dedd12f368a207eb9ad4f4d053f9f01420b49.mp3", "duration_ms": 4400}, "s1-combo-letrero.hint.1": {"url": "http://localhost:4006/files/lesson-audio/17c7e8b4e23e06f528c9dc2129a24a76a7f945786dd24a58d0522dcd5e90afef.mp3", "hash": "a00eb0698179fc7fd34a2063a25d66b53f7f28ef1794414a9d65fe884b1af1f3", "bytes": 16704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/17c7e8b4e23e06f528c9dc2129a24a76a7f945786dd24a58d0522dcd5e90afef.mp3", "duration_ms": 2720}, "s1-combo-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/c80e1c441c560ecbe4e2a75c22abfbf703c226441291c54d6a10e9a0bbad50e1.mp3", "hash": "2eb2ea48864ebb6d0cd60f2dcdcca0c7364229e0b6d93c2033f980364d2a0fb7", "bytes": 40176, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c80e1c441c560ecbe4e2a75c22abfbf703c226441291c54d6a10e9a0bbad50e1.mp3", "duration_ms": 6640}, "s1-combo-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/48899ea7059c7090360dbf16340a541e5d7842629074b1f1284eab7a26499dfa.mp3", "hash": "16b32e477c1ddcd314728235cf4a54bf32d2880739eab9edcf4f35ef2ead0605", "bytes": 105408, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/48899ea7059c7090360dbf16340a541e5d7842629074b1f1284eab7a26499dfa.mp3", "duration_ms": 17520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Cause and effect at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Connect causes and effects at the stand: sunny day → more thirst → more cups sold; doubling the price → fewer customers."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cause-effect", "xp": 10, "type": "cause_effect", "hints": ["Think: what happened first?", "The sun makes people thirstier."], "title": "What happened?", "payload": {"slots": 5, "events": [{"id": "e1", "text_md": "Sunny and hot day"}, {"id": "e2", "text_md": "People are thirstier"}, {"id": "e3", "text_md": "Liruf sells 12 cups of lemonade"}, {"id": "e4", "text_md": "Rho raises the price to 10 dollars per cup"}, {"id": "e5", "text_md": "Fewer customers buy lemonade"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Tap the events in order: cause → effect.", "difficulty": 1, "explanation_md": "The sunny day made people thirsty, so they bought more lemonade. Liruf sold 12 cups!", "audio_segment_id": "s1-cause-effect.prompt"}], "schema_version": 1}', '{"s1-cause-effect": {"chain": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-cause-effect.hint.0": {"url": "http://localhost:4006/files/lesson-audio/de589473b776844f382fdbfe39753603f017f527c3dfa06d1c7384c22bcb659d.mp3", "hash": "829cc9ba232b0692269d886917c3369a7589f012431de3684209b21ad5a479b2", "bytes": 10944, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/de589473b776844f382fdbfe39753603f017f527c3dfa06d1c7384c22bcb659d.mp3", "duration_ms": 1760}, "s1-cause-effect.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9c310635142f52b5c74fa518fd226a6c97a1b814317a8f27c7b8a38a78eb9ce1.mp3", "hash": "fdd11729399e880812c9cd6ac3390efeadc183af9713ca0f57f6e68ead2c0dc2", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9c310635142f52b5c74fa518fd226a6c97a1b814317a8f27c7b8a38a78eb9ce1.mp3", "duration_ms": 1920}, "s1-cause-effect.prompt": {"url": "http://localhost:4006/files/lesson-audio/2c0532b92c6fc239bc520ef2ba7abf215c1f42e5c257ec6b1c5a58661e66ea73.mp3", "hash": "8cf276bba76ca04f6c7053f509dfdc615ed5d21b78e899e50ff69cbb00bfe136", "bytes": 15696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2c0532b92c6fc239bc520ef2ba7abf215c1f42e5c257ec6b1c5a58661e66ea73.mp3", "duration_ms": 2560}, "s1-cause-effect.explanation": {"url": "http://localhost:4006/files/lesson-audio/8b151cd336d1605c7166104069ea917879f56ee13242534dd347c2bc36e7d41c.mp3", "hash": "eed6eedeade1af29568e4c54747f495bf4968887271208fd665f82f1a51aac74", "bytes": 31104, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8b151cd336d1605c7166104069ea917879f56ee13242534dd347c2bc36e7d41c.mp3", "duration_ms": 5120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Cost and profit", "locale": "en-US", "subject": "mixed", "objectives": ["Understand that money is earned by offering something others want, and that a clear goal (the 80-dollar guitar) helps you get started."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["Think about what Liruf spends to make the lemonade (lemons, sugar). That''s the cost.", "What''s left after selling and paying the cost is the profit."], "title": "Cost and profit", "payload": {"cards": [{"icon": "payments", "back_md": "What you spend on lemons and sugar", "front_md": "Cost", "image_url": "http://localhost:4006/files/lesson-images/2450d7fa727faf4ed9bfa9cb9856129b1827c3c122c49b9f4138260c92b393f3.png"}, {"icon": "monetization_on", "back_md": "What you have left after paying the cost", "front_md": "Profit", "image_url": "http://localhost:4006/files/lesson-images/3c9e772cdcaf6ca58789bceca9b441a7b03e779e18ec283bb927f2b47fafbc13.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Tap the cards to discover what ''cost'' and ''profit'' mean.", "difficulty": 1, "explanation_md": "The cost is the 5 dollars Liruf spends on lemons and sugar per glass. The profit is what''s left after subtracting the cost.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/57b8522cd94f6c4c0043586a13dd5347044a27447181904e132b9a14e7fc7b2e.mp3", "hash": "4a42edca879873140f5258425ab90418f94b3060d4c1e015d36292df3775a561", "bytes": 34416, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/57b8522cd94f6c4c0043586a13dd5347044a27447181904e132b9a14e7fc7b2e.mp3", "duration_ms": 5680}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5432c956cbbcee037f284f5d6e36cfeb35fa44da1c1069c2d5f13b3ff9c86eba.mp3", "hash": "93783022bf613025ec5784ee0cf675b2c43944ad7793b9807588bb5304cbc46e", "bytes": 24336, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/5432c956cbbcee037f284f5d6e36cfeb35fa44da1c1069c2d5f13b3ff9c86eba.mp3", "duration_ms": 4000}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/a01eaa9783d3fd6472e564d9fffdb4d589488dd50d1a7f1573e651a820c95dd7.mp3", "hash": "c1d3ab883ee0c80d501bf086bafa2a0845f261b3d1242e3e22d4d7094fd88965", "bytes": 23904, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a01eaa9783d3fd6472e564d9fffdb4d589488dd50d1a7f1573e651a820c95dd7.mp3", "duration_ms": 3920}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/2920e809034b4f18dfc672a03d49da7ef7d5fe974b0c43497be3b30816360091.mp3", "hash": "35c7cd36c24e13e0722e5a71f90aa27f9cc610ce90fcbe1cb5618e057bf748e1", "bytes": 13824, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/2920e809034b4f18dfc672a03d49da7ef7d5fe974b0c43497be3b30816360091.mp3", "duration_ms": 2240}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/200431f2bb80fc1e569db6891bc7b009dc0a95123b4f72ee9dc999ec0dd13825.mp3", "hash": "3c0da736340e777f8930ec28ce900931c41a083a8ddb87b9c2aa00fb97cf50a0", "bytes": 16128, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/200431f2bb80fc1e569db6891bc7b009dc0a95123b4f72ee9dc999ec0dd13825.mp3", "duration_ms": 2640}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/a1eeb6085526de3dfad20ca3411aeced7a10a4c31c5176d7b21264c40d704544.mp3", "hash": "1979580efcbbbd4416e5ee40a4309c043f1e9e24417f7febf5f24069ef3ea8bc", "bytes": 54144, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a1eeb6085526de3dfad20ca3411aeced7a10a4c31c5176d7b21264c40d704544.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "odd-one-out", "title": "O ingrediente estranho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar quais itens não são ingredientes da limonada e, portanto, não custam dinheiro para produzir."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Pense no que você precisa para fazer limonada: limões, água, açúcar...", "A bola não se come nem se bebe, não vai na limonada."], "title": "O ingrediente estranho", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/7084762f63d0eb583d4c9fd2a888aa033d81eb7d72330490aa78a1e30b730ea5.png"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/ec76cac749b469f4210841686ce0f0c1e9b597ba4d6a544dd694bf7661efcb05.png"}, {"id": "agua", "text_md": "Água", "image_url": "http://localhost:4006/files/lesson-images/5e9446c7f4ff2b1ffab1e3cb1f271256351cedb2b1f0721fb4e72da3b93fc463.png"}, {"id": "pelota", "text_md": "Bola", "image_url": "http://localhost:4006/files/lesson-images/8126b61b1e066b16be7bb22e64b9922d9cd9306d708a346e9316463e7d23059e.png"}], "reasons": [{"id": "r1", "text_md": "Não é um ingrediente da limonada."}, {"id": "r2", "text_md": "Sim, é um ingrediente da limonada."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho revisa a lista de compras. Qual coisa NÃO é um ingrediente da limonada?", "difficulty": 1, "explanation_md": "A bola não é um ingrediente da limonada, então não custa dinheiro produzi-la. Os limões, o açúcar e a água são ingredientes que custam dinheiro.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9083cef0d34ac47c0a34cadb5bf8be13aa55364c4a79260b5fecaa9d59f306c5.mp3", "hash": "ed67e596127471141745e6b666faacd184e7f2a1a77513bdb00645623014138a", "bytes": 34416, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9083cef0d34ac47c0a34cadb5bf8be13aa55364c4a79260b5fecaa9d59f306c5.mp3", "duration_ms": 5680}, "s1-odd-one-out.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0eb2c08ce3c03b24492083c742db9c80aa073de0919ac69dd69a9ee1ef46b74d.mp3", "hash": "f5edea782c0d6e0ad03ffecf11b03c76a8232878cc4649a4bcfb061305181e6d", "bytes": 25776, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/0eb2c08ce3c03b24492083c742db9c80aa073de0919ac69dd69a9ee1ef46b74d.mp3", "duration_ms": 4240}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/6ffe517b2ad77a72087a31ecff755348e0fc01a61f50a5ad31605e1cddd781fc.mp3", "hash": "ad82a7c9f5b375b40a65cf61c971c22981ca9da06e10a7fa51872088b7327646", "bytes": 34848, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/6ffe517b2ad77a72087a31ecff755348e0fc01a61f50a5ad31605e1cddd781fc.mp3", "duration_ms": 5760}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/636509a60cf5f976647afb2354ad6322d13cd1f4bc54fa8a92660f65158e34cc.mp3", "hash": "b5ba5173a71400fbd7c728712c602b49ab782785d5cb1615058e22dfb4e79ae3", "bytes": 24768, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/636509a60cf5f976647afb2354ad6322d13cd1f4bc54fa8a92660f65158e34cc.mp3", "duration_ms": 4080}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/45ef5955e8bb945b6a0fb5088aeff960981e3879221d69b8237646a24c5e3ed2.mp3", "hash": "ca338cbbdfd07d75133e89dc0e41e0adf4dade35670238bb61e69cac37181462", "bytes": 64656, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/45ef5955e8bb945b6a0fb5088aeff960981e3879221d69b8237646a24c5e3ed2.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "odd-one-out", "title": "El ingrediente extraño", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar qué artículos no son ingredientes de la limonada y por lo tanto no cuestan dinero producir."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Piensa en lo que necesitas para hacer limonada: limones, agua, azúcar...", "La pelota no se come ni se bebe, no va en la limonada."], "title": "El ingrediente extraño", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/b943806eb72d371c1585abf4eb5487c31f1927ee4ec77ef3627c9563c21bd8e7.png"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/203469db4cf8d5205dde0f3139234500c9f8caabf635b96dc0fe771a32432b09.png"}, {"id": "agua", "text_md": "Agua", "image_url": "http://localhost:4006/files/lesson-images/18755f48f13a82fad0ee7efa0214fdecda1e981ccf2347314a82e7a6ec5300e0.png"}, {"id": "pelota", "text_md": "Pelota", "image_url": "http://localhost:4006/files/lesson-images/b79f9f395333c8322be2d90f696e1dbde17be4bdd85cce34465849bfd877210e.png"}], "reasons": [{"id": "r1", "text_md": "No es un ingrediente de la limonada."}, {"id": "r2", "text_md": "Sí es un ingrediente de la limonada."}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho revisa la lista de compras. ¿Qué cosa NO es un ingrediente de la limonada?", "difficulty": 1, "explanation_md": "La pelota no es un ingrediente de la limonada, así que no cuesta dinero producirla. Los limones, el azúcar y el agua sí son ingredientes que cuestan dinero.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/37681c8f4c1e5f3e7f29b14e2f06abafb9d1baf33435bdedbe8d828c266ad52b.mp3", "hash": "1032cbf84275fc8ac56611704850fac8dcad37cb815b819118054a82fbc0a252", "bytes": 31968, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/37681c8f4c1e5f3e7f29b14e2f06abafb9d1baf33435bdedbe8d828c266ad52b.mp3", "duration_ms": 5280}, "s1-odd-one-out.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5d1768a14ebedf3ea40bcca86b830dd3d72e0cf82d6ea6f0bcdd2f4f644a700d.mp3", "hash": "c3103bbae7ae9e8f2584366b5c6645514cb99a79a32922b0738f0e529afd0777", "bytes": 24336, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5d1768a14ebedf3ea40bcca86b830dd3d72e0cf82d6ea6f0bcdd2f4f644a700d.mp3", "duration_ms": 4000}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/d4c97a3fc023f99f11b7a386577976607432c7951bd0212d54dee8ea14ede1f5.mp3", "hash": "9c5835fcc94ce5f904e1499a34fb1fca1d5af44336bda6a8df8311f5f7fcca85", "bytes": 37296, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/d4c97a3fc023f99f11b7a386577976607432c7951bd0212d54dee8ea14ede1f5.mp3", "duration_ms": 6160}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/3d493c2afd21e808a9145366b6416be260b86a2f5c962f609f1665aeb0e8efde.mp3", "hash": "a1a2bef575005d71f01810e0c5e01bc1f3b3ffeba747c0b6eca175da695f8cc5", "bytes": 22464, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3d493c2afd21e808a9145366b6416be260b86a2f5c962f609f1665aeb0e8efde.mp3", "duration_ms": 3680}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/4c3283997576a0e103a148e76cfbfbce0be0073c0e7da05527ff38ec6cab2cf2.mp3", "hash": "13d60ad164f1c1503b8e9bd388cdb7e139c8130242611cece588e71d318c1124", "bytes": 61776, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/4c3283997576a0e103a148e76cfbfbce0be0073c0e7da05527ff38ec6cab2cf2.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "read-chart", "title": "Reading the sales chart", "locale": "en-US", "subject": "mixed", "objectives": ["Read a bar chart of cups sold per day and determine the best day of the week"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 15, "type": "read_chart", "hints": ["Look for the tallest bar in the chart.", "Each bar represents a day. The tallest one is the day with the most cups sold."], "title": "Which was the best day?", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Cups sold", "points": [{"x": "Monday", "y": 3}, {"x": "Tuesday", "y": 5}, {"x": "Wednesday", "y": 4}, {"x": "Thursday", "y": 6}, {"x": "Friday", "y": 8}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Monday"}, {"id": "martes", "text_md": "Tuesday"}, {"id": "jueves", "text_md": "Thursday"}, {"id": "viernes", "text_md": "Friday"}], "prompt_md": "Which day were the most cups sold?"}]}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Zara wants to buy a skateboard for $10. She has been selling lemonade for 7 days. Which day did she sell the most cups?", "difficulty": 2, "explanation_md": "On Friday she sold 8 cups, more than any other day. That was her best day! With that she has $8, she only needs $2 more for the skateboard.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b467d662612e2f44eba1c0a52d760c472816cdf82fe0ab0447e22655a34352a9.mp3", "hash": "c44e8ce4153c8e5bc60d23cf5633aee26e06cfd252ee9603f79ba23f84ce056c", "bytes": 14256, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/b467d662612e2f44eba1c0a52d760c472816cdf82fe0ab0447e22655a34352a9.mp3", "duration_ms": 2320}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2a9e2acfe0b09e8ec251b02082ce7c214d79d1bd980bef6a9d7fb10061744ebe.mp3", "hash": "92c8e91ee31a119d57d3acc0fee560375debfa7d599adba6773b82098eaca149", "bytes": 29664, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/2a9e2acfe0b09e8ec251b02082ce7c214d79d1bd980bef6a9d7fb10061744ebe.mp3", "duration_ms": 4880}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/0dd0d120d21db139f2b9c18f172732fe143c722c9e19b1d05d2da7a6acd54ed0.mp3", "hash": "474903fe5d734de4470a63dc7a3a519c1f749e66aff7167ceb18ba7a602da0ef", "bytes": 53568, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/0dd0d120d21db139f2b9c18f172732fe143c722c9e19b1d05d2da7a6acd54ed0.mp3", "duration_ms": 8880}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/03d537d9796a78e080be9cef8feb0ff6637fb73211013178f73a817efe734102.mp3", "hash": "f271cacb591fea03d3cadce931d62824ade74dc3ae54e0a1a550f37c07de9142", "bytes": 63216, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/03d537d9796a78e080be9cef8feb0ff6637fb73211013178f73a817efe734102.mp3", "duration_ms": 10480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "picture-choice", "title": "Escolha o lugar mais seguro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar o lugar mais seguro para guardar dinheiro comparando opções visuais."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Pense: onde o dinheiro não pode cair nem se perder?", "Procure um lugar que se feche com chave."], "title": "Onde você guarda seu dinheiro?", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Cofrinho com chave", "image_url": "http://localhost:4006/files/lesson-images/8327eba19a18088c2789d9e8efe1b941a8221c8adaa979e059121d8f8e3e1fdd.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolso furado", "image_url": "http://localhost:4006/files/lesson-images/9a9cd66339fcfddbb645400ccdfe97b3f71db7fcf3e4142515e7d2251c9bbe91.png", "rationale_md": "O bolso furado tem um buraco: as moedas caem e se perdem."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa da barraca", "image_url": "http://localhost:4006/files/lesson-images/fec20665ba590574cdc059adac4ab77a41028513e4af0abf9790e33f356b7c2f.png", "rationale_md": "A mesa da barraca está ao ar livre: qualquer um pode pegar o dinheiro."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf fechou sua barraca. Toque no lugar mais seguro para guardar seus ganhos.", "difficulty": 1, "explanation_md": "O cofrinho com chave é seguro porque só você pode abri-lo. O bolso furado deixa as moedas caírem, e a mesa da barraca está à vista de todos.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e0dd6da3a4aa990e3656664241b1caa80d458cb100c4effe644f8b9a0c466270.mp3", "hash": "bdf2f961f0c0a4610347ca821cc55493fffe98f7604c457b430c94e9bea30c2e", "bytes": 19584, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/e0dd6da3a4aa990e3656664241b1caa80d458cb100c4effe644f8b9a0c466270.mp3", "duration_ms": 3200}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6fa5e5d607106793fef195f35a54dd48df8c2c30ce343378c8b540b9e5b9bba8.mp3", "hash": "3c9d26533f399d7729e7a4fd3d4dd6dfbbdd98c97eab62e4f197846dc924088b", "bytes": 16704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6fa5e5d607106793fef195f35a54dd48df8c2c30ce343378c8b540b9e5b9bba8.mp3", "duration_ms": 2720}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/4c052c6d55040d7bdacf4fa9dcd9c48fafb8ad34f6a4e2c51f8d39c00e55d6be.mp3", "hash": "90fff7bd5870ad86f54edf5b0b4c50aed60bd75d2d5973237e7c4ee68eb00208", "bytes": 34416, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4c052c6d55040d7bdacf4fa9dcd9c48fafb8ad34f6a4e2c51f8d39c00e55d6be.mp3", "duration_ms": 5680}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/6deae78db5997ee8f7c89dba04295c207d2d6d7a09e9f7e481b01e350e218e86.mp3", "hash": "7d104123a6d68ded4a1247d48431c8474b2180e6c95cef249ac77132f7b70187", "bytes": 28224, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6deae78db5997ee8f7c89dba04295c207d2d6d7a09e9f7e481b01e350e218e86.mp3", "duration_ms": 4640}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/3470947285f75d52ce61d94a0097f01777bcae376938dd5c9114559c8f310fe8.mp3", "hash": "2e232a56ea0c7595d932d33d41c0c2a9772dd7fb0e2126204a1d185710bc7edf", "bytes": 63648, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3470947285f75d52ce61d94a0097f01777bcae376938dd5c9114559c8f310fe8.mp3", "duration_ms": 10560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Sim ou não: decisões de gasto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Dizer sim ou não, caso a caso: este gasto ajuda o posto?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Pense: isso ajuda a vender mais limonada ou a cuidar do dinheiro?", "Um gasto que ajuda o posto faz com que você possa continuar vendendo ou vender mais."], "title": "Sim ou não: decisões de gasto", "payload": {"cases": [{"id": "case-1", "text_md": "Comprar mais limões para fazer mais limonada.", "image_url": "http://localhost:4006/files/lesson-images/dbe8928f0ee4f74bf5cddb72de792a52505f880f986da7125acd4ee03eec5823.png"}, {"id": "case-2", "text_md": "Comprar um brinquedo novo para brincar em casa.", "image_url": "http://localhost:4006/files/lesson-images/ed8cdd52f2de59517fcbc6f0203bec6b3b1057b0a95a805e5c74a56db36d322f.png"}, {"id": "case-3", "text_md": "Comprar copos descartáveis para servir a limonada.", "image_url": "http://localhost:4006/files/lesson-images/2d3761cab4fa611c745605704c37c357c9f1e72bf7aaf6efe044d958528d6071.png"}, {"id": "case-4", "text_md": "Comprar um videogame que acabou de lançar.", "image_url": "http://localhost:4006/files/lesson-images/6ff9c798b4699194a804f68c458b35bfc1e4d246bddae36b25c96a06195630c4.png"}], "rule_md": "Diga **sim** se o gasto ajuda o posto de limonada (mais limões, mais copos, consertar algo quebrado). Diga **não** se é um gosto que não ajuda a vender (um brinquedo, um doce, um videogame)."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf revisa sua lista. Quais gastos ajudam o posto de limonada?", "difficulty": 1, "explanation_md": "Comprar mais limões e copos ajuda o posto porque sem eles não há limonada. O brinquedo novo não ajuda hoje, porque não é necessário para vender.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case-1", "case-3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e40bf59aa5d4174b53fdde72238b6dff3d728aac45e19df24c6de13d2a4de9b2.mp3", "hash": "b6123b7c958d24b643b3ea468ced6c0c09f89f70af0ccbcc1e0e49cf88f0ae14", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e40bf59aa5d4174b53fdde72238b6dff3d728aac45e19df24c6de13d2a4de9b2.mp3", "duration_ms": 4800}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2d9ec311144cad5b6469990e943534fdf73fc69139c57984c2b1e6a3883f55b7.mp3", "hash": "3aac128db9a4b73c158586d82d3539b778d5fb44d1a33b53cf08be68f401ef84", "bytes": 35424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2d9ec311144cad5b6469990e943534fdf73fc69139c57984c2b1e6a3883f55b7.mp3", "duration_ms": 5840}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/119891998e30e9abfaa52b084f0e3e0688acf3af939d566629fdb6d4daf2a8cc.mp3", "hash": "66c8cbfb3a48659dac45cffdc1d02e118888953fb5cbb5f59d3890083cac10f8", "bytes": 36288, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/119891998e30e9abfaa52b084f0e3e0688acf3af939d566629fdb6d4daf2a8cc.mp3", "duration_ms": 6000}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/0fa5ee7107b4b006f75e38c18f4b6973def614f87b804012030fb00b26495d43.mp3", "hash": "42c82d5482bba5d63d548705f590aad2a32759d2fc39bdb7d2195d1252e8d8c2", "bytes": 80064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0fa5ee7107b4b006f75e38c18f4b6973def614f87b804012030fb00b26495d43.mp3", "duration_ms": 13280}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/6c63b1bd95c05541a1e2839340e5ad711b498d31f345497b2c58f44362757f50.mp3", "hash": "61dc9d4e72d953bb6d3107f637d9fda9250a9d3efd1a928c9fe1d47d1812c9aa", "bytes": 58896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6c63b1bd95c05541a1e2839340e5ad711b498d31f345497b2c58f44362757f50.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "La guitarra de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Dividir 80 entre diferentes cantidades semanales para calcular semanas necesarias", "Comparar resultados con un plazo de 4 semanas", "Elegir el plan que alcanza la meta a tiempo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guitar-plan", "xp": 15, "type": "savings_goal", "hints": ["Piensa: si ahorras $10 cada semana, en 4 semanas tendrías $40, no alcanza.", "Con $20 cada semana, en 4 semanas juntas $80 justo."], "title": "Elige tu plan", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf quiere una guitarra de $80. El concurso es en 4 semanas. ¿Cuál plan ahorra suficiente a tiempo?", "difficulty": 1, "explanation_md": "Con $20 cada semana, en 4 semanas juntas exactamente $80. ¡Liruf puede comprar la guitarra a tiempo!", "audio_segment_id": "s1-guitar-plan.prompt"}], "schema_version": 1}', '{"s1-guitar-plan": {}}', '{"units": {"s1-guitar-plan.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9b84da002386ec783cf0215148f0e1c836602ea4b2ef84765553031bd13f02e6.mp3", "hash": "8ad6b1c2fe3998038e9c0f39b4ddabf5f2c6f241004c3945697268b7e00002b8", "bytes": 44928, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9b84da002386ec783cf0215148f0e1c836602ea4b2ef84765553031bd13f02e6.mp3", "duration_ms": 7440}, "s1-guitar-plan.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5baa90ecedcdeec777bd04e7dde27cd5f61911b96b889fd89a874cb9a94004c4.mp3", "hash": "4d3df36599ea3d60181d49f91b934af1e1c27385c1b9f5c36c33a10667fb08b7", "bytes": 35856, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5baa90ecedcdeec777bd04e7dde27cd5f61911b96b889fd89a874cb9a94004c4.mp3", "duration_ms": 5920}, "s1-guitar-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/d988573ec9f02c32a87e1bb24a06b224ef2fe2b9c591ea8c702c2656d4bc2e47.mp3", "hash": "fe3fa363c9939f6e4e19e96b956a7953ba951f209720200b8d4b1f46e6cf8fc4", "bytes": 48816, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/d988573ec9f02c32a87e1bb24a06b224ef2fe2b9c591ea8c702c2656d4bc2e47.mp3", "duration_ms": 8080}, "s1-guitar-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/3e64ae376df39ef64fe0e47232674c6e1becac63be236fd5635a9345e1a62393.mp3", "hash": "b6e5257a86d702e7199cc65c2f573b48bd95db8fc8b31ba574ca5995da1f1a40", "bytes": 52128, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3e64ae376df39ef64fe0e47232674c6e1becac63be236fd5635a9345e1a62393.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "read-chart", "title": "Ler o gráfico de vendas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler um gráfico de barras de copos vendidos por dia e determinar o melhor dia da semana"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 15, "type": "read_chart", "hints": ["Procure a barra mais alta no gráfico.", "Cada barra representa um dia. A mais alta é a que vendeu mais copos."], "title": "Qual foi o melhor dia?", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Copos vendidos", "points": [{"x": "segunda-feira", "y": 3}, {"x": "terça-feira", "y": 5}, {"x": "quarta-feira", "y": 4}, {"x": "quinta-feira", "y": 6}, {"x": "sexta-feira", "y": 8}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Segunda-feira"}, {"id": "martes", "text_md": "Terça-feira"}, {"id": "jueves", "text_md": "Quinta-feira"}, {"id": "viernes", "text_md": "Sexta-feira"}], "prompt_md": "Em qual dia foram vendidos mais copos?"}]}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Zara quer comprar um skate de R$10. Ela está vendendo limonada há 7 dias. Em qual dia ela vendeu mais copos?", "difficulty": 2, "explanation_md": "Na sexta-feira ela vendeu 8 copos, mais do que qualquer outro dia. Esse foi o melhor dia dela! Com isso ela já tem R$8, só faltam R$2 para o skate.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c78c3342ef9856955d67636b0843f16efa40aa4d17c266914404dd375276c4f3.mp3", "hash": "0a3fe0b567c7383b091bdd4d17129ef7f5c5649ca87a6caf8fd48db8a769c137", "bytes": 14688, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c78c3342ef9856955d67636b0843f16efa40aa4d17c266914404dd375276c4f3.mp3", "duration_ms": 2400}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2ae5a26c1160de456cfe62db420834a3ebdcb029f20e5684016b887a9f226cbc.mp3", "hash": "9735553005222c650de96c2760f8127956b1db6e9d4803c21eed1314f521554c", "bytes": 33408, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/2ae5a26c1160de456cfe62db420834a3ebdcb029f20e5684016b887a9f226cbc.mp3", "duration_ms": 5520}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/a20526c1323434dba3d3c36375c80d569d69ec8d0b4c74ef395ae03470826aab.mp3", "hash": "96b60d892c456b928540cbd955f0692c88127f2a308e17eff7e43678112e9067", "bytes": 51696, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a20526c1323434dba3d3c36375c80d569d69ec8d0b4c74ef395ae03470826aab.mp3", "duration_ms": 8560}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/c8ff0cee107c2c339b31c75c37be7ad4b37027472daa5ce935bf2be9181c2e58.mp3", "hash": "46b628afece8b6fa883bde4c7e6ec195a63937cdae214f1403292153b869c22b", "bytes": 71856, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c8ff0cee107c2c339b31c75c37be7ad4b37027472daa5ce935bf2be9181c2e58.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "Liruf''s plan", "locale": "en-US", "subject": "mixed", "objectives": ["Understand that money is earned by offering something others want", "See the full plan: sell glasses of lemonade for 5 dollars until you save 80 for the guitar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "title": "Liruf''s plan", "payload": {"art": {"icon": "local_cafe", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/ab81ae0bab527631e1c26b841639570e474a38e1bb3bc2c1587d47ff39f43a5b.png"}, "action": "idle", "body_md": "Liruf draws on a poster: one glass of lemonade costs 5 dollars. Many glasses add up to the 80 dollars for the guitar. That''s his plan to earn the money! How many glasses will he need to sell?", "emotion": "excited", "backdrop": "base", "character": "liruf"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf draws his plan for the guitar.", "difficulty": 1, "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/d21bab6a9f91df58f348dee94d06368867a841fd920473cad9daa0f78ec46b97.mp3", "hash": "727d3ff37b3c54d8e04b9ebc6f2acfdbb5483c1fee0bec81eaf01ca75d17a1b3", "bytes": 70416, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d21bab6a9f91df58f348dee94d06368867a841fd920473cad9daa0f78ec46b97.mp3", "duration_ms": 11680}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/662222f1dd700f8a9d4592b170b547a0391fe6d45006c49366c27a6909630072.mp3", "hash": "9f8c44e987fd2e4873b06716467d4cb911b1c98083ba681f94223b08c855921d", "bytes": 13248, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/662222f1dd700f8a9d4592b170b547a0391fe6d45006c49366c27a6909630072.mp3", "duration_ms": 2160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Close the Sunday cash box", "locale": "en-US", "subject": "mixed", "objectives": ["Count 1, 5, and 10 dollar coins to find the day''s total sales.", "Calculate the correct change when paying for a 5-dollar cup with a 20-dollar bill.", "Determine how many more Sundays are needed to save 80 dollars for a guitar, starting with 40 dollars and saving 20 each Sunday."], "estimated_minutes": 8}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Group coins of the same value, then add them up."], "title": "Count the day''s coins", "payload": {"target": 20, "currency": "USD", "denominations": [1, 5, 10]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/c2ac19e9170a1ba12c100c162ac45b1173d0eb3d54da460a5ac04b872af8af93.png", "prompt_md": "Liruf sold 1 cup for 5 dollars, 1 for 10, and 5 for 1. How much did he collect?", "difficulty": 1, "explanation_md": "Liruf collected 1 coin of 10, 1 of 5, and 5 of 1. 10 + 5 + 5 = 20 dollars total.", "audio_segment_id": "s1-contar-monedas.prompt"}, {"id": "s2-dar-cambio", "xp": 15, "type": "make_change", "hints": ["Think about how much money she gave you and how much the cup costs."], "title": "Give change to the last customer", "payload": {"price": 5, "currency": "USD", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/67c64acdda208cef6578f05bb8fe6a35aac8b55ecb6bbab951f7bade491af1e4.png", "prompt_md": "The customer pays for her 5-dollar cup with a 20-dollar bill. How much change do you give her?", "difficulty": 2, "explanation_md": "The customer paid 20 dollars and the cup costs 5. 20 - 5 = 15 dollars change.", "audio_segment_id": "s2-dar-cambio.prompt"}, {"id": "s3-ahorro-guitarra", "xp": 25, "type": "savings_goal", "hints": ["If he already has 40, how much more does he need for 80? Then, each Sunday he saves 20."], "title": "How many Sundays for the guitar?", "payload": {"goal": 80, "currency": "USD", "weekly_options": [20]}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf has 40 dollars and saves 20 each Sunday. How many Sundays until he has 80?", "difficulty": 2, "explanation_md": "He needs 40 more dollars. Since he saves 20 each Sunday, he needs 2 Sundays: 20+20=40.", "audio_segment_id": "s3-ahorro-guitarra.prompt"}], "schema_version": 1}', '{"s2-dar-cambio": {}, "s1-contar-monedas": {}, "s3-ahorro-guitarra": {}}', '{"units": {"s2-dar-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6ef4e5b15ea1a6c422a192adb7d646e9ad0aae2db6ac35b4cd10e74abe7954d9.mp3", "hash": "5f308bea0160de132c82a7d4891cabfdc3f9cc6836913ee9eaf1ab43ce7630e3", "bytes": 22896, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6ef4e5b15ea1a6c422a192adb7d646e9ad0aae2db6ac35b4cd10e74abe7954d9.mp3", "duration_ms": 3760}, "s2-dar-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/9ba6e1acf7ec8eabc3eb779b1aa688fe895b43fdc609050b26c5ee8811ba3d57.mp3", "hash": "74fca1a5af8c9c90aba668c9348c329365085f76d1ec2ac1ebd1e3c752aec76c", "bytes": 34416, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9ba6e1acf7ec8eabc3eb779b1aa688fe895b43fdc609050b26c5ee8811ba3d57.mp3", "duration_ms": 5680}, "s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/068f749c83495c68a0e251c415d1dcf2833d1656c5a9bf608698834ab018d6f1.mp3", "hash": "b59d6401561f611f0321014c662219317129082152aba84f54a2123de0300d41", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-2026071410560