d4ec5ef8a464ff97b45e9c8002ca459167e57197f4ca59f1afbb9", "bytes": 44496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/99f02d99b7383316d041d441af5085e45ce7f32d05ceb9740d7111821e581400.mp3", "duration_ms": 7360}, "s3-ahorro-guitarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/ff1455147a262c19458e70ee2164c0ea7bc8f046d445906975986ba833acafc5.mp3", "hash": "2cefcf0193bf70129c066424af3058e2e7d5c6f8db3d24e6752bb059b0d6f3ac", "bytes": 41184, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ff1455147a262c19458e70ee2164c0ea7bc8f046d445906975986ba833acafc5.mp3", "duration_ms": 6800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "pattern-complete", "title": "The price ladder", "locale": "en-US", "subject": "money", "objectives": ["Order steps, match products with prices, and sort purchases between stall needs and wants that can wait."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Look at the pattern: small, medium, large, small, medium... what size comes after medium?", "Each size costs more than the one before. The next one must cost more than $10."], "title": "Which cup comes next?", "payload": {"options": [{"id": "chico", "icon": "local_drink", "tint": "primary"}, {"id": "mediano", "icon": "local_drink", "tint": "accent"}, {"id": "grande", "icon": "local_drink", "tint": "success"}, {"id": "limon", "icon": "nutrition", "tint": "primary"}], "sequence": [{"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}, {"icon": "local_drink", "tint": "success"}, {"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Prices: small $5, medium $10, large $15. Which cup goes in the blank?", "difficulty": 2, "explanation_md": "The pattern goes up in price: small $5, medium $10, large $15, and then starts over. After medium ($10) comes large ($15).", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "grande"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/73be0ebfc06764f3726e60de36a5cccb30bd00eeab8a1db564fc9e29a2a86b35.mp3", "hash": "2212388d2d50161df6be82d7fc4dfbedf669ca65e048dc16802021fda82d5bb2", "bytes": 41184, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/73be0ebfc06764f3726e60de36a5cccb30bd00eeab8a1db564fc9e29a2a86b35.mp3", "duration_ms": 6800}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d352d8166a9a2b58f6c798fc6659b224eddd82adf5f87ea67a8fbd361f8dd417.mp3", "hash": "36c8f13a0dbe562ba1c5b0bd129ffefc235c6d56605ff9efc26b839bf0c72708", "bytes": 37728, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/d352d8166a9a2b58f6c798fc6659b224eddd82adf5f87ea67a8fbd361f8dd417.mp3", "duration_ms": 6240}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/4ae677027ec97c5d598ad9512b438c7248864e81f0c0f52cf277236d50d23418.mp3", "hash": "ecb26a3b3f3a709a16800d69743f94cc54f56d03a4233ac3d11a29bbe50b41ef", "bytes": 44064, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/4ae677027ec97c5d598ad9512b438c7248864e81f0c0f52cf277236d50d23418.mp3", "duration_ms": 7280}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/c0aa1ec110b1514396d4d3b99a52cdab3b1edf4e6a4ce41b8b647726a3588b09.mp3", "hash": "9a9e9a633b55aa475958445550c28c6958825049db0f00e073158e37e701b3a8", "bytes": 70848, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c0aa1ec110b1514396d4d3b99a52cdab3b1edf4e6a4ce41b8b647726a3588b09.mp3", "duration_ms": 11760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "key-ideas", "title": "The three golden rules of the little seller", "locale": "en-US", "subject": "mixed", "objectives": ["Identify the three key ideas of the plan: have a goal, offer something people want, and save what you earn."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Think about what Liruf wants to buy.", "What will Liruf sell to earn money?"], "title": "The three golden rules", "payload": {"ideas": [{"icon": "flag", "title": "Have a goal", "body_md": "Liruf wants a guitar that costs **80 dollars**. That is his goal.", "image_url": "http://localhost:4006/files/lesson-images/bfcb29a44949035c00b6dc6df8ca828d1c04f2762c51ee3b9e4982673e9de407.png"}, {"icon": "local_cafe", "title": "Offer something people want", "body_md": "He will sell **cold lemonade** for 5 dollars a glass. Everyone loves it!", "image_url": "http://localhost:4006/files/lesson-images/760919574a445620b4dc5ab83f705bd317ce09979f7317c0b4fb75cea772bebf.png"}, {"icon": "savings", "title": "Save what you earn", "body_md": "Every dollar he earns he will save for the guitar.", "image_url": "http://localhost:4006/files/lesson-images/8df9d4f0acc4063e37353e355a118587baedf42928de8ea7699d4c1936deaa69.png"}]}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Rho drew three ideas on his whiteboard. Tap each one to see it clearly.", "difficulty": 1, "explanation_md": "Rho wrote down the three rules: a clear goal (the guitar for 80 dollars), something to sell (cold lemonade), and saving what you earn.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2f3f2fe69b3eb71f725fe5f131b598f707bcbcfca7eab5462abb490ffb685414.mp3", "hash": "802a793d4c699193c7dba2408f944006f97199ff3499f29e0c274c1e9bcbd508", "bytes": 17568, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2f3f2fe69b3eb71f725fe5f131b598f707bcbcfca7eab5462abb490ffb685414.mp3", "duration_ms": 2880}, "s1-key-ideas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b270c72468cdec0dd269acb1fe05775a5999dcd2e1d18428888c88795c9ae406.mp3", "hash": "61dbb6986b941888429668b427f9d5306f84ec8c77dfcdc9410d3b84c6d34396", "bytes": 17568, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b270c72468cdec0dd269acb1fe05775a5999dcd2e1d18428888c88795c9ae406.mp3", "duration_ms": 2880}, "s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/425a674998ab3b714378d2072f5923ae46ac238f75d149b1aa2a8172b320a8a7.mp3", "hash": "41354606d7f805dc1e9b61596cf13c829d6eef722527b865b8330482b59656c6", "bytes": 28224, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/425a674998ab3b714378d2072f5923ae46ac238f75d149b1aa2a8172b320a8a7.mp3", "duration_ms": 4640}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/d401304c095f7d4a0cce3c4f85302f220e2fae3c3f83cc22accf07d8c92bb4aa.mp3", "hash": "d86eb14fac9f062c456656c1d938dcd3909087d3fc519578a7c6222ce391e76f", "bytes": 33984, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d401304c095f7d4a0cce3c4f85302f220e2fae3c3f83cc22accf07d8c92bb4aa.mp3", "duration_ms": 5600}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/4579d613ecc137561ebca36c0990385e867cf8c6348b09ae57f0f05094021932.mp3", "hash": "6b80b94bba9b37d8eaea8bba6458b3e3e6043e4e85dab872148729c42596ceb5", "bytes": 21024, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/4579d613ecc137561ebca36c0990385e867cf8c6348b09ae57f0f05094021932.mp3", "duration_ms": 3440}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/39698cd204660324c00ad32f7277fbecb1c1312a83f7fbcc2512fff017195595.mp3", "hash": "99a9b42d51c677ec67a9a28ef15d6a74c0f2a015044a477a2c1b6a034bf32e87", "bytes": 34848, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/39698cd204660324c00ad32f7277fbecb1c1312a83f7fbcc2512fff017195595.mp3", "duration_ms": 5760}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/aa9bc91dfc3f97f3ef8a48fd14b745bf8502b1760df09620663565dff7457655.mp3", "hash": "2e789ae33a50c1cafda5ee8a5596ab646b1628849a30ebdc14f89207e59a4405", "bytes": 60336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/aa9bc91dfc3f97f3ef8a48fd14b745bf8502b1760df09620663565dff7457655.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Trueque justo", "locale": "es-MX", "subject": "mixed", "objectives": ["Decidir si un trueque es justo comparando valores"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 10, "type": "fair_trade", "hints": ["Cada vaso vale 5 pesos. ¿Cuánto valen 2 vasos?", "La bolsa de limones vale 10 pesos. Compara los dos valores."], "title": "Trueque justo", "payload": {"offer_a": {"qty": 2, "icon": "local_cafe", "label": "Vaso de limonada", "image_url": "http://localhost:4006/files/lesson-images/b0fd672252bebc550739139a051f52d12ed777f435eac49de76c210484e54b26.png"}, "offer_b": {"qty": 1, "icon": "eco", "label": "Bolsa de limones", "image_url": "http://localhost:4006/files/lesson-images/a499407b456bf120c6bb01fb9114b6f6cd6197cb7fffdf03201e61d377af9006.png"}, "rate_md": "Cada vaso cuesta 5 pesos. La bolsa de limones cuesta 10 pesos."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "El frutero ofrece cambiar 2 vasos de limonada por una bolsa de limones. ¿Es justo el trueque?", "difficulty": 1, "explanation_md": "2 vasos cuestan 10 pesos (2 × 5 = 10), igual que la bolsa de limones. ¡Es justo!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/071796393d5c4984a02a058cfdbba39eb60166a9df3fff7bd7a32ed8c4fe2062.mp3", "hash": "a031ae422c1fdcdc26699725554e1d82e6d69f2ca8152a50289451f2de8d1c2c", "bytes": 28224, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/071796393d5c4984a02a058cfdbba39eb60166a9df3fff7bd7a32ed8c4fe2062.mp3", "duration_ms": 4640}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2d4f656ccb8cbbd1b67bbc495e10388cca689f90bd045c3720ff2284d38429f3.mp3", "hash": "ad38b0443e17e4d4b56d719cca3f649ab5f433ea26313ddb80e3e50ba62df6c3", "bytes": 30096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2d4f656ccb8cbbd1b67bbc495e10388cca689f90bd045c3720ff2284d38429f3.mp3", "duration_ms": 4960}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/71c61e084585966a880549da267b2fa33ff08f10192048dd130868a7a1e4f474.mp3", "hash": "9aeeaf3f62a1accc493bff63f4570da97f7fa8afb8985b1a60f5cd8439f1218b", "bytes": 38736, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/71c61e084585966a880549da267b2fa33ff08f10192048dd130868a7a1e4f474.mp3", "duration_ms": 6400}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/f5a1ecfe697677bfc03bc18ba54079626c821f28201c50ceef5ddcee1fb9780b.mp3", "hash": "24ad9dfd21deda4913cee8d05ae8d0c503634cea44ce9fdf0204c972892f13b9", "bytes": 48816, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f5a1ecfe697677bfc03bc18ba54079626c821f28201c50ceef5ddcee1fb9780b.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "picture-choice", "title": "Choose the safest place", "locale": "en-US", "subject": "mixed", "objectives": ["Identify the safest place to keep money by comparing visual options."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lugar-seguro", "xp": 10, "type": "picture_choice", "hints": ["Think: where can the money not fall or get lost?", "Look for a place that locks with a key."], "title": "Where do you keep your money?", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Piggy bank with a key", "image_url": "http://localhost:4006/files/lesson-images/8327eba19a18088c2789d9e8efe1b941a8221c8adaa979e059121d8f8e3e1fdd.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Torn pocket", "image_url": "http://localhost:4006/files/lesson-images/9a9cd66339fcfddbb645400ccdfe97b3f71db7fcf3e4142515e7d2251c9bbe91.png", "rationale_md": "The torn pocket has a hole: coins fall out and get lost."}, {"id": "mesa", "icon": "table_restaurant", "label": "Stand table", "image_url": "http://localhost:4006/files/lesson-images/fec20665ba590574cdc059adac4ab77a41028513e4af0abf9790e33f356b7c2f.png", "rationale_md": "The stand table is out in the open: anyone can take the money."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf closed his stand. Tap the safest place to keep his earnings.", "difficulty": 1, "explanation_md": "The piggy bank with a key is safe because only you can open it. The torn pocket lets coins fall out, and the stand table is in plain sight of everyone.", "audio_segment_id": "s1-lugar-seguro.prompt"}], "schema_version": 1}', '{"s1-lugar-seguro": {"correct_option_id": "alcancia"}}', '{"units": {"s1-lugar-seguro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e091e86143bc7c456cdd1c9943d0b88c368c3005926b7f402def09caf6fbf98d.mp3", "hash": "5819fae477b4d89b5a8c1666e1251e51d8cc42d7a6e9950fd1dd8db06ae546f2", "bytes": 19008, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e091e86143bc7c456cdd1c9943d0b88c368c3005926b7f402def09caf6fbf98d.mp3", "duration_ms": 3120}, "s1-lugar-seguro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9da03b91b2d9fc56743f2cca70ad14fb57ce528d590a72095fb3abd4d84eacf5.mp3", "hash": "4e21bab1b9eaf512d1174133da5b79cee89f992901252da70b003ab6b469cdcb", "bytes": 14688, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9da03b91b2d9fc56743f2cca70ad14fb57ce528d590a72095fb3abd4d84eacf5.mp3", "duration_ms": 2400}, "s1-lugar-seguro.prompt": {"url": "http://localhost:4006/files/lesson-audio/4d46c3b5a33d49dff2358a84c63de9564a4b33ae9c34cc1c90563ef6ac31d249.mp3", "hash": "6ab51e8ab64f91ad8c958fccebfe9734f73f3952c64af0f891403ad4213660c4", "bytes": 25776, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/4d46c3b5a33d49dff2358a84c63de9564a4b33ae9c34cc1c90563ef6ac31d249.mp3", "duration_ms": 4240}, "s1-lugar-seguro.choices": {"url": "http://localhost:4006/files/lesson-audio/bc8c3659e555f64b100476c278c07f8566c3df1f38e4fe13a214801c58fd66b0.mp3", "hash": "fd9f360a7148cb69d004dc1edef9e2e25af9985598730604c3549c746c41ba88", "bytes": 20448, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bc8c3659e555f64b100476c278c07f8566c3df1f38e4fe13a214801c58fd66b0.mp3", "duration_ms": 3360}, "s1-lugar-seguro.explanation": {"url": "http://localhost:4006/files/lesson-audio/8ea5ab3a4bd77ce7bc25e99013db9dbc98f7c16a9f4ab7ce458a9d76e931f57a.mp3", "hash": "4e26eb1a3f0b9f3dc0ff020248d9a2f526c61435d7c43babf49acb8a451aa265", "bytes": 51264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/8ea5ab3a4bd77ce7bc25e99013db9dbc98f7c16a9f4ab7ce458a9d76e931f57a.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "La ruta del repartidor", "locale": "es-MX", "subject": "mixed", "objectives": ["Guiar al carrito repartidor por la cuadrícula del barrio hasta la casa del cliente gastando la menor cantidad de pasos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["El carrito avanza hacia adelante. Gira con izquierda o derecha."], "title": "Ruta más corta", "payload": {"goal": {"x": 2, "y": 0}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "commands": ["forward", "forward"], "max_commands": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Zara espera su jugo en la casa 2. Dale al carrito la ruta más corta.", "difficulty": 2, "explanation_md": "El carrito gira a la derecha, avanza dos cuadras y llega a la casa 2. ¡Zara recibe su jugo!", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3ace694e892b48eee90afefa4cb3b08f5063ed1b3e4ea5ce406a9617092c4793.mp3", "hash": "18237da81cabc48e3118f6b5f8a270ef03c9cdba27526ade26e50ad3534ecee9", "bytes": 28224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3ace694e892b48eee90afefa4cb3b08f5063ed1b3e4ea5ce406a9617092c4793.mp3", "duration_ms": 4640}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/6d5107bcd895a6293bd985ac9abdec9b91d4c42f33ecd28dd2aaf6b9abe9d9ef.mp3", "hash": "aa67d03734556c4d92d6533edae144c3fe0c53a5c21d93523151b2ed0b8ac77c", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6d5107bcd895a6293bd985ac9abdec9b91d4c42f33ecd28dd2aaf6b9abe9d9ef.mp3", "duration_ms": 5520}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/ca8b027b47f1576bb53424ac52e9dff817f3404a78d1e07f5a042a1591c1d1d0.mp3", "hash": "693fba0743923cf615628bea172f8b41acf1421c1d3d631fd14e4184d7cd89d4", "bytes": 43056, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ca8b027b47f1576bb53424ac52e9dff817f3404a78d1e07f5a042a1591c1d1d0.mp3", "duration_ms": 7120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Fair trade", "locale": "en-US", "subject": "mixed", "objectives": ["Deciding if a trade is fair by comparing values"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 10, "type": "fair_trade", "hints": ["Each glass is worth 5 dollars. How much are 2 glasses worth?", "The bag of lemons is worth 10 dollars. Compare the two values."], "title": "Fair trade", "payload": {"offer_a": {"qty": 2, "icon": "local_cafe", "label": "Glass of lemonade", "image_url": "http://localhost:4006/files/lesson-images/674c26823e6c2aceee325f03b7479ddf0e75811bbcddf9d31d1c043a223ce830.png"}, "offer_b": {"qty": 1, "icon": "eco", "label": "Bag of lemons", "image_url": "http://localhost:4006/files/lesson-images/7fe5b99329690df7e37a47cb1483d788e989d7e957d709ee89593f0bb5a44e44.png"}, "rate_md": "Each glass costs 5 dollars. The bag of lemons costs 10 dollars."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "The fruit seller offers to trade 2 glasses of lemonade for a bag of lemons. Is the trade fair?", "difficulty": 1, "explanation_md": "2 glasses cost 10 dollars (2 × 5 = 10), same as the bag of lemons. It''s fair!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d747f481288174d21ee14c2a8b143e8ddde162f0944f5d161bfab8a5bf3a4ce3.mp3", "hash": "334404808bcd9793d3077d222ff8a5b4a769dadabe7f4285133c323076c63b80", "bytes": 24768, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d747f481288174d21ee14c2a8b143e8ddde162f0944f5d161bfab8a5bf3a4ce3.mp3", "duration_ms": 4080}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6a52a77b24dbb87992bf1d5e0594828bcdf31bd1722a3b033142ba28f89a40f7.mp3", "hash": "ea0d2c93104fbaf82131e3c9df937d20b95ca8b09fe2325e2f4923d1fa073696", "bytes": 23328, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6a52a77b24dbb87992bf1d5e0594828bcdf31bd1722a3b033142ba28f89a40f7.mp3", "duration_ms": 3840}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/e0af019bb2258f743aad3dbb6b3fa971aeadc69d58099995b316cfff3b066abb.mp3", "hash": "e4a001a78d48c9bc97f25e68ab40b872f827cf868812d3daaa5801f7f557b384", "bytes": 35424, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e0af019bb2258f743aad3dbb6b3fa971aeadc69d58099995b316cfff3b066abb.mp3", "duration_ms": 5840}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/e7d99e25ffc2a6e0cbcac46bd72786a3b48c21335e33d192b3223c488efefaad.mp3", "hash": "e3e90dee2f8813d5f299b2b8a2cf419545d16ed1bbcbad94647b69495d0d2c6b", "bytes": 41616, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e7d99e25ffc2a6e0cbcac46bd72786a3b48c21335e33d192b3223c488efefaad.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar copos de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Estimar quantidades usando uma barra deslizante", "Desenvolver senso numérico ao estimar antes de contar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jarra", "xp": 10, "type": "estimate_slider", "hints": ["Pense no tamanho da jarra comparado a um copo.", "Não é 1 nem 100, está entre esses dois números."], "title": "Quantos copos saem?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/82b8fce4441d7a546f5d2959ebe9ce5c5247ee7b18fc02f29a16159b0ae3910b.png", "prompt_md": "Sem contar, deslize para estimar: quantos copos de limonada saem desta jarra?", "difficulty": 1, "explanation_md": "A jarra grande enche aproximadamente 8 copos. Bom olho para estimar!", "audio_segment_id": "s1-estimate-jarra.prompt"}], "schema_version": 1}', '{"s1-estimate-jarra": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a30d02d380702a3384fbdda7904a74abfeffbb1cd405bdcc94546e47fb5730cd.mp3", "hash": "a30913fc303ee4762b219bedb2177d1b0341e8d75141947f3e7aade59e7c220f", "bytes": 19584, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a30d02d380702a3384fbdda7904a74abfeffbb1cd405bdcc94546e47fb5730cd.mp3", "duration_ms": 3200}, "s1-estimate-jarra.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8c79de3c7abf6d1f4fcbaea8c5360bd85b188d62047e7f2e5d32a6177ed92b39.mp3", "hash": "60e333878557aa117b23f1e321a72006e0943b0a5e223369b58ad6f4a296e9ff", "bytes": 22464, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8c79de3c7abf6d1f4fcbaea8c5360bd85b188d62047e7f2e5d32a6177ed92b39.mp3", "duration_ms": 3680}, "s1-estimate-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/b0383052941b37eb28986515a7b7b56ca74fd3914e8af158efe5c7085b919d94.mp3", "hash": "4c2e28d3546e1b0964f0d22dc4476999acdb814afac3710dcb65e3771830dd17", "bytes": 33984, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b0383052941b37eb28986515a7b7b56ca74fd3914e8af158efe5c7085b919d94.mp3", "duration_ms": 5600}, "s1-estimate-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/5cc7bd867bb2c5d05c7a6d061bfaf872a1e85ff9a0f57933d2ce06494622dcb9.mp3", "hash": "0dc4affa1d8f30fc549ff75993e1207664c40312b4b626fc2206ea6412a25a94", "bytes": 33408, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/5cc7bd867bb2c5d05c7a6d061bfaf872a1e85ff9a0f57933d2ce06494622dcb9.mp3", "duration_ms": 5520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Costo y ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["Piensa en lo que Liruf gasta para hacer la limonada (limones, azúcar). Eso es el costo.", "Lo que sobra después de vender y pagar el costo es la ganancia."], "title": "Costo y ganancia", "payload": {"cards": [{"icon": "payments", "back_md": "Lo que gastas en limones y azúcar", "front_md": "Costo", "image_url": "http://localhost:4006/files/lesson-images/1325db32979c3f42df0fdb4112bab28c36b44089baf58cb621e86df895e0fe07.png"}, {"icon": "monetization_on", "back_md": "Lo que te queda después de pagar el costo", "front_md": "Ganancia", "image_url": "http://localhost:4006/files/lesson-images/ff33b04a32826c4c208b8ffb1b3b5ff60f016ca24b62b51badf1a84c59273dda.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toca las tarjetas para descubrir qué significan ''costo'' y ''ganancia''.", "difficulty": 1, "explanation_md": "El costo son los 5 pesos que Liruf gasta en limones y azúcar por cada vaso. La ganancia es lo que le queda después de restar el costo.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/51b4328e594749b933c6db30f54a7a8758014daa0c34547b42e0829f93b7f794.mp3", "hash": "bdaebeb2215ee1007d6bdb13298873fbeb2ce38003b44a9332cdc51e7df09007", "bytes": 33984, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/51b4328e594749b933c6db30f54a7a8758014daa0c34547b42e0829f93b7f794.mp3", "duration_ms": 5600}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/60e87e0c8ae7ad61dbb39f10aa436f54fc7a6df40e92bed5d38a0b250964a8ba.mp3", "hash": "023fbc3d749532255ce39414c37786d55c3b053023ea2d7ecc4ff0de7b1b2c1d", "bytes": 23328, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/60e87e0c8ae7ad61dbb39f10aa436f54fc7a6df40e92bed5d38a0b250964a8ba.mp3", "duration_ms": 3840}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/ee104ae2fd319c0623ddca4f927037732c72108ccf8f28eaf99f2d1dedb210fc.mp3", "hash": "633e2ccef8b5f82ffd4ed90e7b108a9269f08c91472098e421851cdffd261c06", "bytes": 27216, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/ee104ae2fd319c0623ddca4f927037732c72108ccf8f28eaf99f2d1dedb210fc.mp3", "duration_ms": 4480}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/164f7b27cb98e5b975430e6a515313b2fd2629010c790a74fac91f837ba0ee17.mp3", "hash": "27a4a010d9a63d7bdd0c332ac4e17a661ea148bc449468a643b24d07e5853110", "bytes": 13248, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/164f7b27cb98e5b975430e6a515313b2fd2629010c790a74fac91f837ba0ee17.mp3", "duration_ms": 2160}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/0f711c9343d719f3d81f626c111c26cbdb19fa96f76d55a47db039fdb5872c22.mp3", "hash": "a66a18a75a771fa67d017a15fddbc7e1ea545b25cfebc2f061bc8e5b19ef79b5", "bytes": 14688, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/0f711c9343d719f3d81f626c111c26cbdb19fa96f76d55a47db039fdb5872c22.mp3", "duration_ms": 2400}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/0c9b099a9b9d96286e0e99ad5b10b9e77ed212df1645dedcac78b42dfaaa105d.mp3", "hash": "1b56153b4669582d5f62902fd4a29af2aa69f55519583fa8e170e95715a643f3", "bytes": 53136, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/0c9b099a9b9d96286e0e99ad5b10b9e77ed212df1645dedcac78b42dfaaa105d.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "La recta del ahorro", "locale": "es-MX", "subject": "mixed", "objectives": ["Ubicar cantidades en una recta numérica del 0 al 100", "Identificar cuánto falta para alcanzar una meta de ahorro"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 10, "type": "number_line", "hints": ["El ahorro de Liruf está más cerca del 0 que del 100.", "Cuenta de 10 en 10 desde el 0: 10, 20..."], "title": "¿Dónde está Liruf?", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": true}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Mueve el marcador al lugar donde está el ahorro de Liruf: 20 pesos.", "difficulty": 1, "explanation_md": "Liruf tiene 20 pesos ahorrados. En la recta, el 20 está dos saltos de 10 desde el 0.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f0e369e07cb46020989caa6c5349d8811a568f7d50db513022ca2c924265af0e.mp3", "hash": "5590f107a5ec2ac87707606fc8718448b736d62ffbe254ca7cd6a4a93bcedf02", "bytes": 22896, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f0e369e07cb46020989caa6c5349d8811a568f7d50db513022ca2c924265af0e.mp3", "duration_ms": 3760}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/03e6d8c443bd988965ac71c7e6990799f7648c78621803dda6369019d172e29f.mp3", "hash": "36c4c675056e72c5b0f5b5cbf725c73bf695f3a609dd99d4b625fec7df5f4c0a", "bytes": 23328, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/03e6d8c443bd988965ac71c7e6990799f7648c78621803dda6369019d172e29f.mp3", "duration_ms": 3840}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/7468442123c219c6655e68b6f465dd6e1af94fc4526aa282744230e2995f7a65.mp3", "hash": "ce3d7f8a462e5b8d84fa8f2f907b1d736bbdc3ffa05ce5d1429190e89f15cfdc", "bytes": 30528, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7468442123c219c6655e68b6f465dd6e1af94fc4526aa282744230e2995f7a65.mp3", "duration_ms": 5040}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/0a04d8d7e6c2a08914b19044598ebccd3fe00b2d53ec320ef54b9e5570672e85.mp3", "hash": "d3e8877643d79f33112413be468b2f04597ef7b0604b9c3e7895f7a16f40d8fa", "bytes": 46368, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/0a04d8d7e6c2a08914b19044598ebccd3fe00b2d53ec320ef54b9e5570672e85.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Red flags in a deal", "locale": "en-US", "subject": "mixed", "objectives": ["Spotting red flags in a stranger''s offer: promises that are too good to be true are not trustworthy."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Think: is it normal to earn so much money in one day without working?", "Do you know that person? Why would they offer you so much?"], "title": "The magic business", "payload": {"flags": [{"id": "f1", "text_md": "The person is a stranger"}, {"id": "f2", "text_md": "Promises a lot of money without explanation"}, {"id": "f3", "text_md": "Asks for money today in exchange for a promise"}, {"id": "f4", "text_md": "Says it''s ''magic'' or ''safe''"}], "artifact_md": "A stranger approaches Liruf''s stand and says: ''Hey, kid, give me your 20 dollars today. Tomorrow I''ll give you back 100. It''s a magic business, you lose nothing.''", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/ea1b5dc724e5a0e64188ee7f8cd8e9dd4018b2a614bc874ef42aa1745acc8567.png", "prompt_md": "Liruf is at his stand. A man approaches and says: ''Give me your 20 dollars today and tomorrow I''ll give you 100.'' What red flags do you see?", "difficulty": 1, "explanation_md": "Promises of making a lot of money fast and easy are usually false. If it sounds too good to be true, it probably isn''t true.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["f1", "f2", "f3", "f4"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ae9f7ec40b7d8fca3ec0209a744bc1c740060d4369d977391da725409d849117.mp3", "hash": "cb3a859e0a80d084907cdb177019b6cfa9a496ba9b27befb07f153b295745aa2", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ae9f7ec40b7d8fca3ec0209a744bc1c740060d4369d977391da725409d849117.mp3", "duration_ms": 3600}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/621ce630fbef7a3ba1adb080b56d3f633d59045ab927c902b56df08c3713e78e.mp3", "hash": "8fca7e2243243abe0c5bba6cca5bd4009bb72a02b18047707efc8b2bcf024436", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/621ce630fbef7a3ba1adb080b56d3f633d59045ab927c902b56df08c3713e78e.mp3", "duration_ms": 2880}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/bf800356e91249a27098686139ccda2e7c548ad2ae5c02e9f80406fb8dffd508.mp3", "hash": "b82bc828b858633561505e854bec476a17eb3745fdeff2697ef9428cff582a5c", "bytes": 50688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bf800356e91249a27098686139ccda2e7c548ad2ae5c02e9f80406fb8dffd508.mp3", "duration_ms": 8400}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/9ac67e874a2223d324932cb9603db64149b2b72bcb3a04d4f1c5afade94f5cc5.mp3", "hash": "c48e9c9119f0ddc9ff75c58e1f000ca3e5829a769ab52595ab67e461d1d2fc25", "bytes": 43056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9ac67e874a2223d324932cb9603db64149b2b72bcb3a04d4f1c5afade94f5cc5.mp3", "duration_ms": 7120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Rodada relâmpago na hora do rush", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o troco correto para clientes que pedem 1-3 copos de limonada a 5 reais e pagam com 10 ou 20 reais.", "Aplicar a estratégia: primeiro some o custo total, depois subtraia do pagamento."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning-round", "xp": 15, "type": "lightning_round", "hints": ["Primeiro some quanto custam os copos: 2 copos × 5 reais cada um.", "Depois subtraia esse total do pagamento de 20 reais."], "title": "Rodada relâmpago", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 reais"}, {"id": "b", "text_md": "5 reais"}, {"id": "c", "text_md": "15 reais"}, {"id": "d", "text_md": "20 reais"}], "prompt_md": "Dona Rosa: 2 copos, paga com 20. Quanto troco você dá?"}, {"id": "q2", "options": [{"id": "a", "text_md": "5 reais"}, {"id": "b", "text_md": "10 reais"}, {"id": "c", "text_md": "15 reais"}, {"id": "d", "text_md": "0 reais"}], "prompt_md": "Seu José: 3 copos, paga com 20. Quanto troco você dá?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 reais"}, {"id": "b", "text_md": "10 reais"}, {"id": "c", "text_md": "0 reais"}, {"id": "d", "text_md": "4 reais"}], "prompt_md": "Mamãe Lila: 1 copo, paga com 10. Quanto troco você dá?"}, {"id": "q4", "options": [{"id": "a", "text_md": "0 reais"}, {"id": "b", "text_md": "5 reais"}, {"id": "c", "text_md": "10 reais"}, {"id": "d", "text_md": "2 reais"}], "prompt_md": "Tio Toño: 2 copos, paga com 10. Quanto troco você dá?"}, {"id": "q5", "options": [{"id": "a", "text_md": "5 reais"}, {"id": "b", "text_md": "10 reais"}, {"id": "c", "text_md": "15 reais"}, {"id": "d", "text_md": "20 reais"}], "prompt_md": "Vovó Nena: 3 copos, paga com 20. Quanto troco você dá?"}, {"id": "q6", "options": [{"id": "a", "text_md": "15 reais"}, {"id": "b", "text_md": "10 reais"}, {"id": "c", "text_md": "5 reais"}, {"id": "d", "text_md": "20 reais"}], "prompt_md": "Seu Chuy: 1 copo, paga com 20. Quanto troco você dá?"}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dona Rosa: 2 copos, paga com 20. Quanto troco você dá?", "difficulty": 2, "explanation_md": "2 copos custam 10 reais (2×5). 20 menos 10 são 10 reais de troco.", "audio_segment_id": "s1-lightning-round.prompt"}], "schema_version": 1}', '{"s1-lightning-round": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a", "q5": "a", "q6": "a"}}}', '{"units": {"s1-lightning-round.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3b79b22b3f1a8a0f830c1777df9f116e51a6b58feaa887bc85404e7f4607f773.mp3", "hash": "beb9d1ede909a3d1a7993a6173d92e1492f582bc1342c437b7bcb75d024524c6", "bytes": 31536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3b79b22b3f1a8a0f830c1777df9f116e51a6b58feaa887bc85404e7f4607f773.mp3", "duration_ms": 5200}, "s1-lightning-round.hint.1": {"url": "http://localhost:4006/files/lesson-audio/57d06f966f1a57edc0373c0cac488e98fd3584954547761ecbdb1afae522eeaa.mp3", "hash": "1fa88103f35adecf8e2226c22ab507e2150ee95fecb8e249f3116e16742d17f6", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/57d06f966f1a57edc0373c0cac488e98fd3584954547761ecbdb1afae522eeaa.mp3", "duration_ms": 4080}, "s1-lightning-round.prompt": {"url": "http://localhost:4006/files/lesson-audio/db6709c4e9678b91beb2f0c9c652cef48707ee719859d434e0c54f6a9dd8b704.mp3", "hash": "a931c8a273adcd589a2cb949df812886c0450d6fc5ba74e833a009cfc3e9c00f", "bytes": 33408, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/db6709c4e9678b91beb2f0c9c652cef48707ee719859d434e0c54f6a9dd8b704.mp3", "duration_ms": 5520}, "s1-lightning-round.explanation": {"url": "http://localhost:4006/files/lesson-audio/86cc9a09b970dd67be26d8386d68cdd6424ce0d2a515e21052d1d56d98f99fbd.mp3", "hash": "4e39eca59e0dcce2110603a478ea954de82a92d28cc53e3419eea369ed543771", "bytes": 46368, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/86cc9a09b970dd67be26d8386d68cdd6424ce0d2a515e21052d1d56d98f99fbd.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "Live the role in playable stories", "locale": "en-US", "subject": "mixed", "objectives": ["Choose the lemonade price considering cost and profit", "See how each decision affects progress toward the savings goal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-limonada", "xp": 20, "type": "story_branch", "hints": ["Think: if you charge too much, they might not buy. If you charge too little, you earn little per cup.", "Remember your goal is to save 80 dollars for the guitar."], "title": "Choose today''s price", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 dollars (the usual price)"}, {"id": "precio3", "next": "final3", "text_md": "3 dollars (cheaper)"}, {"id": "precio10", "next": "final10", "text_md": "10 dollars (double)"}], "emotion": "thinking", "text_md": "It''s noon and it''s super hot! Six neighbors are in line at your lemonade stand. You decide the price of each cup. Each cup costs you 2 dollars to make. How much do you charge?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "End"}], "emotion": "happy", "text_md": "All 6 neighbors buy! Each cup gives you 3 dollars profit (5 - 2 = 3). In total you earned 18 dollars. Great progress toward the 80-dollar guitar!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "End"}], "emotion": "thinking", "text_md": "They sell like hotcakes! But each cup only gives you 1 dollar profit (3 - 2 = 1). In total you earned only 6 dollars. You barely make progress toward the guitar...", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "End"}], "emotion": "surprised", "text_md": "The neighbors make a face and go get ice cream. You didn''t sell a single cup. You earned 0 dollars and are left with a full pitcher. The guitar seems very far away...", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/06c7dc36450d1d08cff00df6f9df848b0a967b20521c34352a6dfddcbfa4bdd4.png", "prompt_md": "It''s hot and 6 neighbors are waiting for lemonade. Each cup costs you 2 dollars to make. At what price do you sell each cup?", "difficulty": 2, "explanation_md": "Liruf chose a price and saw how much progress he made toward the 80-dollar guitar.", "audio_segment_id": "s1-precio-limonada.prompt"}], "schema_version": 1}', '{"s1-precio-limonada": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio-limonada.hint.0": {"url": "http://localhost:4006/files/lesson-audio/46896e5febe9ddc13352137abdc4a5adcd9fd58ecd708cd6805e274938b65b54.mp3", "hash": "fac8f80f88d72686f5a8973d340d0287518f4bdf5f46b9592e32e53d4991a890", "bytes": 31536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/46896e5febe9ddc13352137abdc4a5adcd9fd58ecd708cd6805e274938b65b54.mp3", "duration_ms": 5200}, "s1-precio-limonada.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9438f0dc98a60e558097e7199282c1e455e442f07a6f88a8b95783f2bb6b89c1.mp3", "hash": "5091c6f952365d7869891987707680bee7463b790cebbf50acdccb576ce10395", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9438f0dc98a60e558097e7199282c1e455e442f07a6f88a8b95783f2bb6b89c1.mp3", "duration_ms": 3440}, "s1-precio-limonada.prompt": {"url": "http://localhost:4006/files/lesson-audio/f13964a84f37c992b4768b585ff7b3be7dae60a9ae62cfd2ebf45ff14c1453b6.mp3", "hash": "91a9473672ea2cc5db366c3b5ebb94cde88b00501a63b4eaa8f29c90941ce6e6", "bytes": 41184, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f13964a84f37c992b4768b585ff7b3be7dae60a9ae62cfd2ebf45ff14c1453b6.mp3", "duration_ms": 6800}, "s1-precio-limonada.explanation": {"url": "http://localhost:4006/files/lesson-audio/62efddb4f62d3d6c783fc99beaca14bb704c3fc10a6cb79c8deef872e96f3b2a.mp3", "hash": "97f2607646727d075564a555c04a04c216f2af6044e8d670eccfda679ce6350c", "bytes": 26784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/62efddb4f62d3d6c783fc99beaca14bb704c3fc10a6cb79c8deef872e96f3b2a.mp3", "duration_ms": 4400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "make-change", "title": "Give exact change", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate change from a 20-dollar bill after buying two products", "Make change with 1, 2, 5, and 10-dollar coins"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Add the price of the cup and the cookie.", "How much do you have left from the 20-dollar bill?"], "title": "Don Beto''s change", "payload": {"price": 8, "currency": "USD", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/77d62e42b4783170b9e57e60c1d928c66aebf1fd0f735137489daf9816676684.png", "prompt_md": "Don Beto pays with a 20-dollar bill. Make the exact change with the coins.", "difficulty": 2, "explanation_md": "The cup costs 5 and the cookie 3, total 8. From 20, 12 left. The coins 10+2 make 12.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e5cbb38604372eea654f9321a2ee1983d4365d7f636efcba186f31d9b3c05213.mp3", "hash": "bed5f7bc1343ad51dbb6541d89d9804c54c39d58e102de23e55fe6741ec9ec27", "bytes": 13824, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e5cbb38604372eea654f9321a2ee1983d4365d7f636efcba186f31d9b3c05213.mp3", "duration_ms": 2240}, "s1-make-change.hint.1": {"url": "http://localhost:4006/files/lesson-audio/dc75ef34ce74c440f0e1cd918c27dd7a9196b709c44f17713ed093080a117a60.mp3", "hash": "307b412a4896ff60367568a4a3d54bf177a6168e228b010fbbdb0f35982fa671", "bytes": 18144, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/dc75ef34ce74c440f0e1cd918c27dd7a9196b709c44f17713ed093080a117a60.mp3", "duration_ms": 2960}, "s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/f6b78fce287fa0d8f14a79768955b4c2e97fe6030d47b1736ddad47d478a018b.mp3", "hash": "041bd35ae62f98ddcd5d08e093d59ac088d1357661190a8b362e418bf1f24d68", "bytes": 31536, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f6b78fce287fa0d8f14a79768955b4c2e97fe6030d47b1736ddad47d478a018b.mp3", "duration_ms": 5200}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/d8243b26e730de0acf0ec9aabfca527b8f908235c9c930b2680fc392668cd972.mp3", "hash": "7e6c35c5f2ac3b6222c9b3b9ce12402ea6fd7ed856c9703e874ae11676e1edde", "bytes": 48816, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d8243b26e730de0acf0ec9aabfca527b8f908235c9c930b2680fc392668cd972.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "count-objects", "title": "Cuenta las monedas de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de un vistazo para saber cuánto vendió Liruf hoy."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta-monedas", "xp": 10, "type": "count_objects", "hints": ["Cuenta solo las monedas, no las galletas ni el vaso.", "Puedes tocarlas una por una para no perderte."], "title": "Monedas en la mesa", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 6}, {"icon": "cookie", "tint": "accent", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "¿Cuántas monedas ves?", "difficulty": 1, "explanation_md": "Hay 6 monedas. Cada moneda es un vaso de 5 pesos que Liruf vendió hoy. Eso suma 30 pesos para la guitarra de 80.", "audio_segment_id": "s1-cuenta-monedas.prompt"}], "schema_version": 1}', '{"s1-cuenta-monedas": {"value": 6}}', '{"units": {"s1-cuenta-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f2081af3ff8066cb26a51f6ddfd81435a089bbf695acbd5509f876bfb0088cb9.mp3", "hash": "a2689dce091ed410cdcdcd036a8a67f4810fb034dc967ac6ec1d40d7fb382700", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f2081af3ff8066cb26a51f6ddfd81435a089bbf695acbd5509f876bfb0088cb9.mp3", "duration_ms": 3600}, "s1-cuenta-monedas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3a98d52edd36f547da0fd1de5838b473b7f5f16f83d3f1e53a959af38eeb0a37.mp3", "hash": "449aa7a23cb46878f7883636abcc2d18f5a865e99575de6ea5db299ad20d2d14", "bytes": 18576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3a98d52edd36f547da0fd1de5838b473b7f5f16f83d3f1e53a959af38eeb0a37.mp3", "duration_ms": 3040}, "s1-cuenta-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/b84ddfeff263dea87fa0b2ecc873565d44991fb2c0c2699bb65d26f84bf7a33b.mp3", "hash": "2a7ed54843ef2f801858c8216c1c7e62d0decd046a3d266f4c8cfdbbd0e42b83", "bytes": 12384, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b84ddfeff263dea87fa0b2ecc873565d44991fb2c0c2699bb65d26f84bf7a33b.mp3", "duration_ms": 2000}, "s1-cuenta-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/6109c1388bef7248b90cb5daaaeb4270c53dbb964c841d83e2739f9b3d96d56e.mp3", "hash": "b6be3dbc610c162cc751c929339fc1be71c85692656faf6b1799e583f29738af", "bytes": 52128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6109c1388bef7248b90cb5daaaeb4270c53dbb964c841d83e2739f9b3d96d56e.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar moedas para a meta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de 1, 2 e 5 reais para pagar um copo de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Conte as moedinhas uma por uma. Quanto dá?"], "title": "Conte as moedas", "payload": {"target": 5, "currency": "BRL", "denominations": [1, 2, 2]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/e2e2c89f82abf8e6a17768ce5d3651a76b025d32e6c45f5ec58ffbd0c05d9772.png", "prompt_md": "Liruf vendeu um copo de limonada. O cliente paga com estas moedas. São exatamente 5 reais?", "difficulty": 1, "explanation_md": "As moedas somam 5 reais: 2 + 2 + 1 = 5. Exatamente o preço do copo!", "audio_segment_id": "s1-contar-monedas.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f6a54b84a62fa4cceef68923d9b08398a82f716b0e2a1efb0960e9cfe33e9deb.mp3", "hash": "1d1939f51d6a783c9291f8ce9d65c302095109be38be5e21f0322e59fb04529f", "bytes": 18144, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f6a54b84a62fa4cceef68923d9b08398a82f716b0e2a1efb0960e9cfe33e9deb.mp3", "duration_ms": 2960}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/46605931b77c3cf2479c03b540545298ea83ad4f1e9621495147c9ede447c749.mp3", "hash": "eadc48f8f1797eeca3ba2e7663ed5d5051f5b4f874525c0e2af8c057dc00e142", "bytes": 46944, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/46605931b77c3cf2479c03b540545298ea83ad4f1e9621495147c9ede447c749.mp3", "duration_ms": 7760}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/fa31a5e89dcdf887da6c02ab88f64faba48d4cb981f189de2ffbbd16f424d3bf.mp3", "hash": "675cbd363fda39794fd142de0b2ea61055ef2eb41ecca969d39f3a9e3fa552c3", "bytes": 47808, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fa31a5e89dcdf887da6c02ab88f64faba48d4cb981f189de2ffbbd16f424d3bf.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "balance-scale", "title": "Equilibra a balança do escambo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Equilibrar uma balança colocando pesos equivalentes para conseguir um escambo justo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-trueque", "xp": 15, "type": "balance_scale", "hints": ["Cada copo vale 5 reais. Quanto valem os 3 copos juntos?", "Cada biscoito vale 3 reais. Descubra quantos biscoitos somam o mesmo que os 3 copos."], "title": "Escambo justo", "payload": {"weights": [{"id": "galleta1", "label": "Biscoito", "value": 3}, {"id": "galleta2", "label": "Biscoito", "value": 3}, {"id": "galleta3", "label": "Biscoito", "value": 3}, {"id": "galleta4", "label": "Biscoito", "value": 3}, {"id": "galleta5", "label": "Biscoito", "value": 3}], "left_fixed": [{"label": "Copo de limonada", "value": 5}, {"label": "Copo de limonada", "value": 5}, {"label": "Copo de limonada", "value": 5}], "unknown_label": "Biscoito"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf coloca 3 copos de limonada (5 reais cada). O vendedor de biscoitos coloca biscoitos de 3 reais. Coloque biscoitos até a balança se equilibrar.", "difficulty": 2, "explanation_md": "3 copos de 5 reais somam 15 reais. 5 biscoitos de 3 reais também somam 15 reais. A balança se equilibra!", "audio_segment_id": "s1-balance-trueque.prompt"}], "schema_version": 1}', '{"s1-balance-trueque": {}}', '{"units": {"s1-balance-trueque.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c270b32c92420beecb1d6e93416a263f1b5adce9fd9e5eb2626dcd49f8ab2183.mp3", "hash": "262f0eae7c1e5e608663cf0afbc36e78bf7242c8bc12b00d7e885dcb1acd3f1c", "bytes": 30096, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c270b32c92420beecb1d6e93416a263f1b5adce9fd9e5eb2626dcd49f8ab2183.mp3", "duration_ms": 4960}, "s1-balance-trueque.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a16de53e903c4a4eb0f19a145885e1ee7213a86dd695c69acda87b98d418e034.mp3", "hash": "d59e0d192ed8f85265d80f0f4fae3f92c82b232b4631f5fff93ccb5d8b94e0d0", "bytes": 44496, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a16de53e903c4a4eb0f19a145885e1ee7213a86dd695c69acda87b98d418e034.mp3", "duration_ms": 7360}, "s1-balance-trueque.prompt": {"url": "http://localhost:4006/files/lesson-audio/35cfc5e3c1f80b2363b7779ec12c862d166ad6e8fb7eec4bdf46d88961956a99.mp3", "hash": "a520f15730e76d95eaf4cbdcb53f21aa23617883791c3d5774951cf2b557a141", "bytes": 70848, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/35cfc5e3c1f80b2363b7779ec12c862d166ad6e8fb7eec4bdf46d88961956a99.mp3", "duration_ms": 11760}, "s1-balance-trueque.explanation": {"url": "http://localhost:4006/files/lesson-audio/889c9b567223275a085f57c9f8ee4b96a45dbbf2d8a211cc57e84dde052233b7.mp3", "hash": "1d9f6d59fcf3e8070da9250f22e6004ab77941228ea70c61b4ab81924e7706f5", "bytes": 58896, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/889c9b567223275a085f57c9f8ee4b96a45dbbf2d8a211cc57e84dde052233b7.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Earning money starts with an idea", "locale": "en-US", "subject": "mixed", "objectives": ["Understanding that money is earned by offering something others want", "Recognizing that a clear goal helps you get started"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf''s Guitar", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "I look at the guitar in the store… it costs 80 dollars. I don''t have any money.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "What if you earn it yourself? You could sell lemonade in the neighborhood.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "Sell lemonade? Great idea! That way I can earn the money all by myself.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "Look, I already sold one cup. They gave me 10 dollars. Now I have 10 out of 80! How many more cups do I need to sell to get 80?", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/3a4da3b991e34c43dd434a8a79af27613e9f97b002f12cc4636ea2a22458f417.png", "prompt_md": "Liruf wants a guitar that costs 80 dollars. He sells lemonade for 10 dollars per cup.", "difficulty": 1, "explanation_md": "Liruf sells one cup of lemonade for 10 dollars. That''s how he earns money little by little.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/c7a9e8351950e9a67d203b6db62597c00f32de5d6f386e735f756031cfe29961.mp3", "hash": "cf3f9bae8f91cc62d309a93122417053507fedf16863a53e6c7182a7221e06d0", "bytes": 26784, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/c7a9e8351950e9a67d203b6db62597c00f32de5d6f386e735f756031cfe29961.mp3", "duration_ms": 4400}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/03397ef1f3f2d44b318d8473fcc28b2b82b052b20a674ebacb480d5fe02aa22e.mp3", "hash": "c689bc0a291081fde52aefc33ff9df8ab35a1f9791168667276dbfa60fd11795", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/03397ef1f3f2d44b318d8473fcc28b2b82b052b20a674ebacb480d5fe02aa22e.mp3", "duration_ms": 3440}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/bdfa37425de71a09397b7f908ecdf0c259d61a96a94532bcebe2e443e169ee80.mp3", "hash": "478252b0f51c2e2dbde7c3d6a43146ae69432f737885fc12562a8bf61c73d4f3", "bytes": 29664, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bdfa37425de71a09397b7f908ecdf0c259d61a96a94532bcebe2e443e169ee80.mp3", "duration_ms": 4880}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/f0b16f2260e1997053703e8951ed50b01199c5a9af0820b9084c5899e7cec8d6.mp3", "hash": "383cdcbd3faca6f5e026152ab5d21dee0afc7a155415003c72d91c7267837565", "bytes": 45936, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f0b16f2260e1997053703e8951ed50b01199c5a9af0820b9084c5899e7cec8d6.mp3", "duration_ms": 7600}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/b61bd71217a1e5b158ff0dedb892feb717e798fe1aa3cf681ce699b06df54c84.mp3", "hash": "3a224f02994282f1cdf48acb56de5270ab71cc2bf1a242b3c6eb17ba6cad3e12", "bytes": 29088, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b61bd71217a1e5b158ff0dedb892feb717e798fe1aa3cf681ce699b06df54c84.mp3", "duration_ms": 4800}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/5cfa9b50ffbc0a3e6ae519cd3756e07afafe1bab0f1ec8ea7dd993b76800d7f6.mp3", "hash": "0f45818a4f7e9a14a53c9896049c05921ec589894a41cdf040d2bfed2b0eb3b5", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5cfa9b50ffbc0a3e6ae519cd3756e07afafe1bab0f1ec8ea7dd993b76800d7f6.mp3", "duration_ms": 4960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare lemon suppliers", "locale": "en-US", "subject": "mixed", "objectives": ["Read a table of two lemon suppliers (price and quantity) and choose the one that gives more for less."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 10, "type": "compare_table", "hints": ["See how many lemons each gives for the same money."], "title": "Choose the best supplier", "payload": {"cols": [{"id": "precio", "label": "Price"}, {"id": "limones", "label": "Lemons"}], "rows": [{"id": "proveedor-a", "label": "Stand A"}, {"id": "proveedor-b", "label": "Stand B"}], "tokens": [{"id": "a-precio", "text_md": "20 dollars"}, {"id": "a-limones", "text_md": "10 lemons"}, {"id": "b-precio", "text_md": "20 dollars"}, {"id": "b-limones", "text_md": "6 lemons"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8693c7b5bb9bda6f8822f6e38a9d7271f3bd3aa9255b7399c91064510593973f.png", "prompt_md": "Dina has 20 dollars. Which supplier can she buy more lemons from?", "difficulty": 1, "explanation_md": "With 20 dollars, at stand A you get 10 lemons. At stand B, 20 dollars only get you 6 lemons (because 24 dollars give 8, so 20 dollars give fewer). Stand A gives you more lemons for your money.", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "20 pesos", "proveedor-b:precio": "20 pesos", "proveedor-a:limones": "10 limones", "proveedor-b:limones": "6 limones"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c2e2234386682f48b68dccc2e6612853d0fedb9ea6673c4b727b5209e0538743.mp3", "hash": "a6dbb645bf5edce3c1f654c1287557e866a4884d7abae46874e5268685d9819f", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c2e2234386682f48b68dccc2e6612853d0fedb9ea6673c4b727b5209e0538743.mp3", "duration_ms": 2720}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/62df143cb0bf50d524b58317450ee9a9de8cb9df5000b55349e07b04a875e0cf.mp3", "hash": "af22dccdb1d0495f7b94f78200696441133f9a2cede24fa40f1ee7c947258d21", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/62df143cb0bf50d524b58317450ee9a9de8cb9df5000b55349e07b04a875e0cf.mp3", "duration_ms": 4000}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/45e9da34c023fa70c28bccbe66f8e106429540c8cae6ddaf4b5c179c43db0604.mp3", "hash": "562385a06113d8e3e8703f061e3a9702e87c4f4f8dabc61236fbba9c2ff6c3cb", "bytes": 71856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/45e9da34c023fa70c28bccbe66f8e106429540c8cae6ddaf4b5c179c43db0604.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "machine-io", "title": "A máquina de gorjetas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir que a máquina duplica o que entra", "Prever a saída da máquina com um novo número"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 15, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. Que operação a máquina faz?", "Cada moeda que entra se transforma no dobro."], "title": "Descubra a regra", "payload": {"options": [{"id": "opt-7", "text_md": "7"}, {"id": "opt-8", "text_md": "8"}, {"id": "opt-10", "text_md": "10"}, {"id": "opt-15", "text_md": "15"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "A avó coloca 1 moeda e saem 2. Coloca 3 e saem 6. Quantas saem se colocar 5?", "difficulty": 2, "explanation_md": "A máquina duplica: 1 vira 2, 3 vira 6, então 5 vira 10.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt-10"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/00de43ff268b4c7e7a8ed6fbc3e30e03b5e607602491bfd7c143c6ef101a8123.mp3", "hash": "6ae078b3915ed3fce5b9071da4b34a8f68e142b2c284f38e95a62fe577f68a26", "bytes": 35424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/00de43ff268b4c7e7a8ed6fbc3e30e03b5e607602491bfd7c143c6ef101a8123.mp3", "duration_ms": 5840}, "s1-machine-io.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ad98ed4223492c494530941130147751fd8429f79999aebfb81672ebc364e5af.mp3", "hash": "68a4d2b6178cdc7e3d6e832d5642e349e23db011e27d362120df830361b39c0c", "bytes": 19584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ad98ed4223492c494530941130147751fd8429f79999aebfb81672ebc364e5af.mp3", "duration_ms": 3200}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/4bf2bbc867ca3d6928fa48ace7058f1dc5afe3c1b7745c92838d63f9c2cc9f1d.mp3", "hash": "282402911e4bd2c62a892a2ef050441b3d4fef4f6681eeaa766e3c9937056c43", "bytes": 45504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4bf2bbc867ca3d6928fa48ace7058f1dc5afe3c1b7745c92838d63f9c2cc9f1d.mp3", "duration_ms": 7520}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/902ea9d085878b81539e5c06af75d5a3faeecdc3306dc64aa7a84eb063b67a26.mp3", "hash": "181d0df6544b34865db4569b522c1fa63b6bc951c86e5908eaef56f49f2da340", "bytes": 41616, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/902ea9d085878b81539e5c06af75d5a3faeecdc3306dc64aa7a84eb063b67a26.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Spot the error in the promotion", "locale": "en-US", "subject": "mixed", "objectives": ["Find the error in a promotion poster and correct it"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-promo", "xp": 15, "type": "debug_hunt", "hints": ["Think about how much a single cup costs.", "Compare the price of 2 single cups with the 8 dollars of the promo."], "title": "The promo that doesn''t add up", "payload": {"blocks": [{"id": "block1", "text_md": "2 cups for 8 dollars"}, {"id": "block2", "text_md": "1 cup costs 5 dollars"}, {"id": "block3", "text_md": "Save 2 dollars!"}], "intro_md": "Liruf put up a poster: ''2 cups for 8 dollars''. But customers laugh: it''s more expensive than buying them separately!"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "What is the error in Liruf''s poster?", "difficulty": 2, "explanation_md": "Two single cups cost 10 dollars (5+5), but the promo sells them for 8. It''s cheaper, not more expensive!", "audio_segment_id": "s1-debug-promo.prompt"}], "schema_version": 1}', '{"s1-debug-promo": {"fix_md": "¡Ahorra 2 pesos! → ¡Ahorra 2 pesos! (en realidad es más caro, no ahorras)", "bug_ids": ["block3"]}}', '{"units": {"s1-debug-promo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9d000d92a12aecea8cf28f00d88ab7dd406abefccbd910a7297160480de3db5e.mp3", "hash": "28435bfa7287337128c6ce3350c0db1e0dbc6e14fa6bb28a8662562419afdfed", "bytes": 14256, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9d000d92a12aecea8cf28f00d88ab7dd406abefccbd910a7297160480de3db5e.mp3", "duration_ms": 2320}, "s1-debug-promo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/58d9a2d559c067392c382b7e14dd0ba82afa331245e10fdf57d7c51671b4b63c.mp3", "hash": "582f81da406f9cd17489d690f55756566f9ea8e82f6efa7c3bcca261e042a2cb", "bytes": 21456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/58d9a2d559c067392c382b7e14dd0ba82afa331245e10fdf57d7c51671b4b63c.mp3", "duration_ms": 3520}, "s1-debug-promo.prompt": {"url": "http://localhost:4006/files/lesson-audio/c868266e1016428b97409cf16dfe167415368063c53583aa2b033058b285559e.mp3", "hash": "da62c62967a6fadcdd0bbe09545c47e726f889ca4e189f20a8ed50157b4639c2", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c868266e1016428b97409cf16dfe167415368063c53583aa2b033058b285559e.mp3", "duration_ms": 2400}, "s1-debug-promo.explanation": {"url": "http://localhost:4006/files/lesson-audio/e087972818e322e3595e4070d0f8e9cf65a20bb00ddaecb909cdc086a1cf0ae6.mp3", "hash": "8ed6818e686cd48ef60c721b288207b902a3f92436583ffac35c3468b701c5fb", "bytes": 42048, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e087972818e322e3595e4070d0f8e9cf65a20bb00ddaecb909cdc086a1cf0ae6.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "would-you-rather", "title": "¿Qué harías tú? Dilemas del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir entre dos caminos del vendedor y defenderlo: ¿ganar 10 pesos hoy o 20 la próxima semana?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-wyr", "xp": 15, "type": "would_you_rather", "hints": ["Piensa: ¿Liruf necesita el dinero hoy o puede esperar una semana?", "No hay respuesta mala, solo distintas consecuencias."], "title": "¿Ganar hoy o esperar?", "payload": {"a": {"icon": "payments", "text_md": "**Ganar 10 pesos hoy** vendiendo 2 vasos de limonada ahora mismo.", "image_url": "http://localhost:4006/files/lesson-images/39b81722a3a24f30c1395abd33d5c3917e003d05916c2321b396e39560bed546.png"}, "b": {"icon": "trending_up", "text_md": "**Ganar 20 pesos la próxima semana** si preparas más limonada y vendes el doble.", "image_url": "http://localhost:4006/files/lesson-images/0af6e35f3bffb20ae9089740970cae78ccbbe52b4b072acf9d5a0472f3c9614e.png"}, "followup_md": "¿Por qué escogiste esa opción? Cuéntale a Dina tu razón."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina te pone un dilema: ¿qué escoges para Liruf?", "difficulty": 2, "explanation_md": "Dina sonríe: ''Ambas opciones tienen su razón. Lo importante es que pienses antes de decidir.''", "audio_segment_id": "s1-wyr.prompt"}], "schema_version": 1}', '{"s1-wyr": {"qualities": {"a": 50, "b": 50}, "reveal_md": "Dina asiente: ''Ambos caminos tienen sentido. Lo importante es que sepas por qué eliges.''"}}', '{"units": {"s1-wyr.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3499304b12f61fa2c30fdc0e33f8a782f6637454bd8bb9d0874691af846dec16.mp3", "hash": "f1bb37efbb6d4b181b35602d0494d19709b2baf216e8ca0543700bf3db23d711", "bytes": 28224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3499304b12f61fa2c30fdc0e33f8a782f6637454bd8bb9d0874691af846dec16.mp3", "duration_ms": 4640}, "s1-wyr.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f7676fbb27f9a5397cab7a0c9c71f2696cc128915a4cff36589f81f346520c98.mp3", "hash": "6286ab083bb99d14122eb7178181c8fa42dfe20c64a7bd89081f1d6418f0c087", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f7676fbb27f9a5397cab7a0c9c71f2696cc128915a4cff36589f81f346520c98.mp3", "duration_ms": 4000}, "s1-wyr.prompt": {"url": "http://localhost:4006/files/lesson-audio/46a662190afccb41d363abe353b5cbdb61ad3c05b4016d08b6181605de0e40f4.mp3", "hash": "32d76b8b657726ffe11c6d868fcd60f70999a6adeb5a914f0901c1c3a961d53c", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/46a662190afccb41d363abe353b5cbdb61ad3c05b4016d08b6181605de0e40f4.mp3", "duration_ms": 3520}, "s1-wyr.choices": {"url": "http://localhost:4006/files/lesson-audio/1ba52a5646f320f89a49ce67b4ba75ab5ea709f45aa6d4f491301d04d413c154.mp3", "hash": "02aecf043d42c6992637c0c85f013d115d10cab54f643438ce30c6a6079afe11", "bytes": 62784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1ba52a5646f320f89a49ce67b4ba75ab5ea709f45aa6d4f491301d04d413c154.mp3", "duration_ms": 10400}, "s1-wyr.explanation": {"url": "http://localhost:4006/files/lesson-audio/5500f3278e759bb5b1c5ec2e42d6808b358eb8ea1cfe90c1a4a688daff01d762.mp3", "hash": "d1e93dec9c52d4a0fee1aa5a125af3bb5ff60da10e855e75e06db6c6860ae9d4", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5500f3278e759bb5b1c5ec2e42d6808b358eb8ea1cfe90c1a4a688daff01d762.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar vasos de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Estimar cantidades usando una barra deslizante", "Desarrollar sentido numérico al estimar antes de contar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jarra", "xp": 10, "type": "estimate_slider", "hints": ["Piensa en el tamaño de la jarra comparado con un vaso.", "No es 1 ni 100, está entre esos dos números."], "title": "¿Cuántos vasos salen?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/8998a07097aa0518f2097288fbb0780a117dd475192710bc23058ebb03fbbe5e.png", "prompt_md": "Sin contar, desliza para estimar: ¿cuántos vasos de limonada salen de esta jarra?", "difficulty": 1, "explanation_md": "La jarra grande llena aproximadamente 8 vasos. ¡Buen ojo para estimar!", "audio_segment_id": "s1-estimate-jarra.prompt"}], "schema_version": 1}', '{"s1-estimate-jarra": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0c86bed091ece7ad203723db573aadda031a324c37b575109ed3ad1f39dc31a0.mp3", "hash": "4f74a3a50530a08088c5eb908140ecbf3caa61e58101c967504d20c5b3b063f7", "bytes": 20448, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/0c86bed091ece7ad203723db573aadda031a324c37b575109ed3ad1f39dc31a0.mp3", "duration_ms": 3360}, "s1-estimate-jarra.hint.1": {"url": "http://localhost:4006/files/lesson-audio/af7bb0c4e51edc1d4a8235c43f06e15e0b4be83798edfdd95f89c34f5291537e.mp3", "hash": "30062c39da51a6922d0b1b819a6168cd58dff05d4c917c5c01b6a1763d639957", "bytes": 19008, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/af7bb0c4e51edc1d4a8235c43f06e15e0b4be83798edfdd95f89c34f5291537e.mp3", "duration_ms": 3120}, "s1-estimate-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/20d8a095f36d84e66c75b3037fb0b38927ef569bb4b584bf68422373698d2b9a.mp3", "hash": "fa6ad1e3b5c72ea9d1ce38e3a173e035eea4c6c6acb27312fe290859aae5b934", "bytes": 33984, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/20d8a095f36d84e66c75b3037fb0b38927ef569bb4b584bf68422373698d2b9a.mp3", "duration_ms": 5600}, "s1-estimate-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/8df8784d5ecf5c7cc6b55eb88c34fdb0a0a91f5945de75f3097a43e062ee5e1b.mp3", "hash": "20b0fe2e1ad9536b0cc277aaae8e0d77beefc73eca39e14fa96e72c1589d52d7", "bytes": 31536, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/8df8784d5ecf5c7cc6b55eb88c34fdb0a0a91f5945de75f3097a43e062ee5e1b.mp3", "duration_ms": 5200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "O plano de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro se ganha oferecendo algo que outros querem", "Ver o plano completo: vender copos de limonada a 5 reais até juntar 80 para o violão"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "title": "O plano de Liruf", "payload": {"art": {"icon": "local_cafe", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/a985c4aaf45441c16cffa2b7f697c45e81d21b8f4ce9c3a05ea6afd5d6b721bd.png"}, "action": "idle", "body_md": "Liruf desenha em um cartaz: um copo de limonada custa 5 reais. Muitos copos juntam os 80 reais do violão. É o seu plano para ganhar o dinheiro! Quantos copos ele precisará vender?", "emotion": "excited", "backdrop": "base", "character": "liruf"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf desenha seu plano para o violão.", "difficulty": 1, "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/0c4dd9f523ef72af9e74df2e96ce046ad3d5e468ba6988bbe366af692d3de7f2.mp3", "hash": "1abce2bc6400d5b4a228464ec5dc906f6a429dc111bf10264cd608c365ae3eea", "bytes": 88704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/0c4dd9f523ef72af9e74df2e96ce046ad3d5e468ba6988bbe366af692d3de7f2.mp3", "duration_ms": 14720}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/43b852fb38b62e527234af4026aa35667697d1c26c512cb7534c8824ec201bdb.mp3", "hash": "bf99df3096c8f5c97c625f8f9483ff63d298c53ce3639b6162bdac52719737e5", "bytes": 17136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/43b852fb38b62e527234af4026aa35667697d1c26c512cb7534c8824ec201bdb.mp3", "duration_ms": 2800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "La registradora de cartón", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar las instrucciones de la registradora casera: recibir pago → verificar monto → dar cambio → anotar la venta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-registradora", "xp": 15, "type": "code_order", "hints": ["Primero recibe el pago del cliente.", "Después de dar cambio, anota la venta."], "title": "Ordena los pasos", "payload": {"blocks": [{"id": "recibir", "text_md": "Recibir pago"}, {"id": "verificar", "text_md": "Verificar monto"}, {"id": "dar_cambio", "text_md": "Dar cambio"}, {"id": "anotar", "text_md": "Anotar la venta"}], "language_hint": "Paso a paso"}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Rho vende limonada a 5 pesos. Un cliente paga con 10. ¿Qué hace Rho primero?", "difficulty": 2, "explanation_md": "Rho recibe los 10 pesos, ve que son más de 5, da 5 de cambio y anota la venta. ¡Así funciona la registradora!", "audio_segment_id": "s1-ordenar-registradora.prompt"}], "schema_version": 1}', '{"s1-ordenar-registradora": {"order": ["recibir", "verificar", "dar_cambio", "anotar"]}}', '{"units": {"s1-ordenar-registradora.hint.0": {"url": "http://localhost:4006/files/lesson-audio/517074fc90c2516d04461bc2c6db0a1f842a10bc6a57bfa212d76d2b94a690bf.mp3", "hash": "71d6523dc477e30b8c43412c3bf705f8cb3d736ecfe12134c0d74b25bec2dc1c", "bytes": 14688, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/517074fc90c2516d04461bc2c6db0a1f842a10bc6a57bfa212d76d2b94a690bf.mp3", "duration_ms": 2400}, "s1-ordenar-registradora.hint.1": {"url": "http://localhost:4006/files/lesson-audio/585ef83c955f085115562ba73f72428d87f61f602bb24a967bcc04b4a4aacae1.mp3", "hash": "55f974214597e0ffa4d28efd4ece5d2996cede330407beb1e6b5cceeb7ea3e2d", "bytes": 20016, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/585ef83c955f085115562ba73f72428d87f61f602bb24a967bcc04b4a4aacae1.mp3", "duration_ms": 3280}, "s1-ordenar-registradora.prompt": {"url": "http://localhost:4006/files/lesson-audio/1cf5c82a7fd771df48c79fb0a729446c71b615c6dc32c0f261402376b2556df7.mp3", "hash": "4ec688901a2bc53974ed580bd7eead8752e361fc17c5f104871aa82bc43cd362", "bytes": 41184, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/1cf5c82a7fd771df48c79fb0a729446c71b615c6dc32c0f261402376b2556df7.mp3", "duration_ms": 6800}, "s1-ordenar-registradora.explanation": {"url": "http://localhost:4006/files/lesson-audio/02583c86bae0313fc35e513bd4cb0c710191035a0b3b12819093eaa1c29077d5.mp3", "hash": "d929aeafe9a97511f401e9ba38e143014525bcf3f6a5c0b12f9992ab05910f9a", "bytes": 57456, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/02583c86bae0313fc35e513bd4cb0c710191035a0b3b12819093eaa1c29077d5.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "repaso-true-false", "title": "Repaso: ¿Verdadero o Falso?", "locale": "es-MX", "subject": "money", "objectives": ["Distinguir entre ingreso total y ganancia en un puesto de limonada", "Recordar que cada vaso cuesta 2 pesos de insumos, por lo que la ganancia por vaso es 3 pesos"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-verdadero-falso", "xp": 10, "type": "true_false", "hints": ["Recuerda: cada vaso cuesta 2 pesos de limón y azúcar. ¿Cuánto te queda de verdad por vaso?", "Si vendes 10 vasos a 5 pesos, entran 50 pesos. Pero de eso hay que restar lo que costó hacerlos."], "title": "¿Verdadero o Falso?", "payload": {"statement_md": "Liruf vendió 10 vasos a 5 pesos cada uno, entonces ganó 50 pesos.", "justifications": [{"id": "j-verdadero", "text_md": "Verdadero: 10 vasos × 5 pesos = 50 pesos, esa es la ganancia."}, {"id": "j-falso", "text_md": "Falso: 10 vasos × 5 pesos = 50 pesos de ingreso, pero cada vaso costó 2 pesos hacerlo, así que la ganancia es 30 pesos."}]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Rho dice: ''Vendiste 10 vasos a 5 pesos cada uno, ¡entonces ganaste 50 pesos!'' ¿Es verdad o es un truco?", "difficulty": 1, "explanation_md": "Es **falso**. Entraron 50 pesos, pero cada vaso costó 2 pesos hacerlo (limón y azúcar). La ganancia por vaso es 5 - 2 = 3 pesos. Por 10 vasos, la ganancia real es 10 × 3 = 30 pesos, no 50. ¡Lo que entra no es lo que te ganas!", "audio_segment_id": "s1-verdadero-falso.prompt"}], "schema_version": 1}', '{"s1-verdadero-falso": {"is_true": false, "correct_justification_id": "j-falso"}}', '{"units": {"s1-verdadero-falso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f29c6c2a1d61aa777ab429e7d1ca8e98c9df5c79b69c63dff58cba5f1d49641c.mp3", "hash": "e33b1bde4755768b1f38cfd9d0710b835755136dbfe821298c2bfd29ba35e8db", "bytes": 43056, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f29c6c2a1d61aa777ab429e7d1ca8e98c9df5c79b69c63dff58cba5f1d49641c.mp3", "duration_ms": 7120}, "s1-verdadero-falso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/36887649b8504997d12386b48568cae6ac20fb56f7da4a49f730a4bbd1c5c115.mp3", "hash": "85497dd5edf646944e6b5dfaa0b305ca76542e0c3164552465adf21388fe5e1b", "bytes": 48384, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/36887649b8504997d12386b48568cae6ac20fb56f7da4a49f730a4bbd1c5c115.mp3", "duration_ms": 8000}, "s1-verdadero-falso.prompt": {"url": "http://localhost:4006/files/lesson-audio/71281f4be5c88492c692afe855048e833a5bd98c8d2ed0a7b05256478c9f3ea2.mp3", "hash": "26eb7f6062daf43a06dfaa183ea296bd58c4a7add7bb7fbfde50fdce6f18b2a8", "bytes": 51696, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/71281f4be5c88492c692afe855048e833a5bd98c8d2ed0a7b05256478c9f3ea2.mp3", "duration_ms": 8560}, "s1-verdadero-falso.explanation": {"url": "http://localhost:4006/files/lesson-audio/e85ed4de6210438b2308365fecd47371b8253b15b97d954cf3814726d2b381a3.mp3", "hash": "53bb3846b45756466c68debef48f7d1ee1310a46252784ddc98b7b563582431c", "bytes": 124704, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/e85ed4de6210438b2308365fecd47371b8253b15b97d954cf3814726d2b381a3.mp3", "duration_ms": 20720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encuentra el error en la cuenta", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas", "Leer una gráfica simple de vasos vendidos por día", "Reconocer señales de un mal trato"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 10, "type": "spot_error", "hints": ["Cuenta cuántos 5 hay en la suma.", "¿Cuánto suman tres veces 5?"], "title": "La cuenta de Liruf", "payload": {"steps": [{"id": "step1", "text_md": "5 + 5 = 10"}, {"id": "step2", "text_md": "10 + 5 = 15"}, {"id": "step3", "text_md": "El resultado es 20"}], "context_md": "Liruf vendió 3 vasos de limonada a 5 pesos cada uno. Anotó en su cuaderno: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/285d6d30b5cefed4cc61a81ca66cf18be16fd32df112069b2d72d28e69f64169.png", "prompt_md": "Liruf anotó: 5 + 5 + 5 = 20. ¿Qué paso está mal?", "difficulty": 1, "explanation_md": "Liruf sumó 5 + 5 + 5, que da 15, no 20. El error está en el resultado.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step3"], "correction_md": "El resultado correcto es 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bcb42b4d87293720bf22300b47fcd4becd29610690ed370f56dfe3ed8b85c84c.mp3", "hash": "1f3ae6b0dcf4a0595b6e1eca170c80dc7a98990ee19eab0f4d20d8ae5d8f92bf", "bytes": 19008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/bcb42b4d87293720bf22300b47fcd4becd29610690ed370f56dfe3ed8b85c84c.mp3", "duration_ms": 3120}, "s1-spot-error.hint.1": {"url": "http://localhost:4006/files/lesson-audio/280a85a89443e3a9b60c95d5ccacc740ad40a57c75e905ae116ccbd324481dcb.mp3", "hash": "6dbf5b43bf4f8e99bf329a0d262a305191b87dde597943a17b908e0b4e4ad40f", "bytes": 13824, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/280a85a89443e3a9b60c95d5ccacc740ad40a57c75e905ae116ccbd324481dcb.mp3", "duration_ms": 2240}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/fe0f28e4928b70f2227f8912ff0b4a7da399bb77bb9df0ae7ac4698fdd8901aa.mp3", "hash": "cec84bc708457b5e8018dbef7e88941df287c9b66686bf122cf1efee74a7f910", "bytes": 38304, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fe0f28e4928b70f2227f8912ff0b4a7da399bb77bb9df0ae7ac4698fdd8901aa.mp3", "duration_ms": 6320}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/28c79c2033709a867725ac81fe79e239cebd8038092d1fb810450ca76cb82f60.mp3", "hash": "3f7583e19a37e0bbe4a56f55975dded1d2bf7fc96ce77b7340a91e88907b60d7", "bytes": 44928, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/28c79c2033709a867725ac81fe79e239cebd8038092d1fb810450ca76cb82f60.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "A pista do recibo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Procurar no recibo do mercado a evidência exata de quanto custaram os limões."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Procure no recibo a linha que diz ''limões''.", "Observe o número ao lado de ''limões''."], "title": "O recibo amassado", "payload": {"claim_md": "Liruf afirma: ''Gastei 20 reais em limões.''", "sentences": [{"id": "s1", "text_md": "Limões: 15 reais"}, {"id": "s2", "text_md": "Açúcar: 5 reais"}, {"id": "s3", "text_md": "Copos: 10 reais"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/e8ae1d5388884215d6c42b1d067f3db6ea3047415d3902a1a71fc13981b20a4c.png", "prompt_md": "Liruf diz: ''Gastei 20 reais em limões.'' O recibo diz outra coisa. Que evidência o recibo mostra?", "difficulty": 1, "explanation_md": "O recibo mostra que os limões custaram 15 reais, não 20. Liruf errou ao somar.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ced9837183c436c66d099f764bd328b84c29df75adfb765cfacdc05351781365.mp3", "hash": "2903141d6ed86e8df4f2598e8a414a703b1dd1dc093844d410dea5f3dd078b82", "bytes": 20016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ced9837183c436c66d099f764bd328b84c29df75adfb765cfacdc05351781365.mp3", "duration_ms": 3280}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/25888286ee57d56176aabdbb546d1f84eea0688805f8884639fcb09bac47d07e.mp3", "hash": "78fa77f3ceee769ff28462f7d71526e927dd409807c743d321ad99ad758d9fed", "bytes": 18576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/25888286ee57d56176aabdbb546d1f84eea0688805f8884639fcb09bac47d07e.mp3", "duration_ms": 3040}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/400cf554f9450642c65b5e8fa2877dfe090b5378d21053aab561d711fbab5259.mp3", "hash": "855c539134199f08585a01f72da08e9ce19eea2175352cc060777559f834ba2b", "bytes": 48816, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/400cf554f9450642c65b5e8fa2877dfe090b5378d21053aab561d711fbab5259.mp3", "duration_ms": 8080}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/2e95387448248649f5f67e5b868eb016a06e8bac86605b2980001a1f1454cf8d.mp3", "hash": "713db86e2d4959724ff06690947ce810ab1efb9c02a6d87d91bc118107ce8e60", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2e95387448248649f5f67e5b868eb016a06e8bac86605b2980001a1f1454cf8d.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Fill in the numbers of the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Counting money to buy a lemonade"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 10, "type": "fill_blank", "hints": ["Count the coins left after paying."], "title": "Day''s profit", "payload": {"bank": [{"id": "b1", "text_md": "2"}, {"id": "b2", "text_md": "5"}, {"id": "b3", "text_md": "8"}], "mode": "typed", "text_md": "Liruf has {{1}} $1 coins left."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf has 5 $1 coins. The lemonade costs $3. How many coins are left?", "difficulty": 1, "explanation_md": "Liruf paid $3 and had 2 $1 coins left. He still has money for another treat!", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["2"], "bank_id": "b1"}]}}', '{"units": {"s1-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3582dd17e5e2a40fd6e024920659c83e072ff4415fa16ffeb3e9d6a7fa2832ba.mp3", "hash": "3b0de497d4315cbca3535aad59a1b47c3f78f039a1fd9f4d6397edf65c380462", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3582dd17e5e2a40fd6e024920659c83e072ff4415fa16ffeb3e9d6a7fa2832ba.mp3", "duration_ms": 1920}, "s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/0c44ca86297801a5ecf14afca3b30d81eb5ab3aae4071187ec4528b5e1026f51.mp3", "hash": "38e6efdd1beb0de658657d4e609987324df9433ae5a41c535f9abb01822b46c7", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0c44ca86297801a5ecf14afca3b30d81eb5ab3aae4071187ec4528b5e1026f51.mp3", "duration_ms": 5760}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/feb1e3d4cc2cb1da5b9d22e38d64b27eccc4aaf965df26081ac7dd4936c0ce26.mp3", "hash": "4d00401bca101bc8c6f4896805d6b7c930bf6f7a1d053e2206069ac2012aed48", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/feb1e3d4cc2cb1da5b9d22e38d64b27eccc4aaf965df26081ac7dd4936c0ce26.mp3", "duration_ms": 5440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confidence in your accounts", "locale": "en-US", "subject": "mixed", "objectives": ["Add 5 + 5 to calculate the total of two glasses sold", "Evaluate the level of confidence in the result of a simple sum"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 10, "type": "confidence_quiz", "hints": ["Think: one glass is 5 dollars, two glasses are 5 plus 5.", "You can count on your fingers: 5 and then 5 more."], "title": "Liruf''s Sales", "payload": {"options": [{"id": "opt-10", "text_md": "10 dollars", "rationale_md": "Correct! 5 + 5 = 10."}, {"id": "opt-5", "text_md": "5 dollars", "rationale_md": "5 dollars is the price of a single glass, but Liruf sold two glasses."}, {"id": "opt-15", "text_md": "15 dollars", "rationale_md": "15 would be if each glass cost 7.50, but each glass costs 5 dollars."}, {"id": "opt-8", "text_md": "8 dollars", "rationale_md": "8 would be if one glass cost 3 and the other 5, but both cost 5."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sold two glasses of lemonade. Each glass costs 5 dollars. How much money did he collect?", "difficulty": 1, "explanation_md": "Two glasses of 5 dollars each add up to 10 dollars. Liruf collected 10 dollars for the two sales.", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confidence-quiz.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7967ac1f7575bd92008dfd70fc9fc273ac6eb1566eb2d619f9b4adc50fde316c.mp3", "hash": "5719521a9f0927f486bef41338f043ffc07d2a3685c5daea5a1a448d9ed83410", "bytes": 25344, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7967ac1f7575bd92008dfd70fc9fc273ac6eb1566eb2d619f9b4adc50fde316c.mp3", "duration_ms": 4160}, "s1-confidence-quiz.hint.1": {"url": "http://localhost:4006/files/lesson-audio/46369ea46dfac76d5cfebed4597b243b2303d08c8caca194a29cec17e0dd5133.mp3", "hash": "b60989d16dc39338ebbd0a8d1cdc2986f4d1476c8cf4d05d956beec83005b1b6", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/46369ea46dfac76d5cfebed4597b243b2303d08c8caca194a29cec17e0dd5133.mp3", "duration_ms": 3120}, "s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/3621b7553479eb338f5e7060a85d87819e303c388ac2190b5778e113c862b2c2.mp3", "hash": "5cd6f1d310e13b096adfe293f311cde00deca5e3e62dbaab584d9c52972b6616", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3621b7553479eb338f5e7060a85d87819e303c388ac2190b5778e113c862b2c2.mp3", "duration_ms": 5760}, "s1-confidence-quiz.choices": {"url": "http://localhost:4006/files/lesson-audio/2d3fd4aaa6a2e1e1e7d19ed1d8fa4cbace2dabddb7aad08ad3ac9c81c0e3681d.mp3", "hash": "d88b9243b67e11025d967a0c8d6f9e0761fe0f5c8f44d757997597ece1afc9b6", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2d3fd4aaa6a2e1e1e7d19ed1d8fa4cbace2dabddb7aad08ad3ac9c81c0e3681d.mp3", "duration_ms": 4080}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/bb4e1834b5f6d6935eb7f5a1ad1dc53802a877759ed6e6f6dac6024b91d8095a.mp3", "hash": "422bb82d397cceb6c64c030958a84eb03fc4cdadbb841995b50b98c3faf99a08", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bb4e1834b5f6d6935eb7f5a1ad1dc53802a877759ed6e6f6dac6024b91d8095a.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "read-chart", "title": "Leer la gráfica de ventas", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer una gráfica de barras de vasos vendidos por día y determinar el mejor día de la semana"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 15, "type": "read_chart", "hints": ["Busca la barra más alta en la gráfica.", "Cada barra representa un día. La más alta es la que más vasos vendió."], "title": "¿Cuál fue el mejor día?", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Vasos vendidos", "points": [{"x": "lunes", "y": 3}, {"x": "martes", "y": 5}, {"x": "miércoles", "y": 4}, {"x": "jueves", "y": 6}, {"x": "viernes", "y": 8}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Lunes"}, {"id": "martes", "text_md": "Martes"}, {"id": "jueves", "text_md": "Jueves"}, {"id": "viernes", "text_md": "Viernes"}], "prompt_md": "¿Cuál día se vendieron más vasos?"}]}, "narrator": {"emotion": "happy", "character": "zara"}, "prompt_md": "Zara quiere comprar una patineta de $10. Lleva 7 días vendiendo limonada. ¿Cuál día vendió más vasos?", "difficulty": 2, "explanation_md": "El viernes vendió 8 vasos, más que cualquier otro día. ¡Ese fue su mejor día! Con eso ya tiene $8, solo le faltan $2 para la patineta.", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c745feb2fa30a8c2a99ecb777fbfb8ab9e70f55d4663b31ad5a83d350a3c7956.mp3", "hash": "ee14e778bc299189f3dc560d1cfc9b6caeddfbde231e2ba583886cd2b45bec32", "bytes": 15264, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/c745feb2fa30a8c2a99ecb777fbfb8ab9e70f55d4663b31ad5a83d350a3c7956.mp3", "duration_ms": 2480}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/98cfd5c455296e63e9ada6592cb902781a551aa3f3e7a54f88f8e90e5b45e39a.mp3", "hash": "e883d6a65a5a6db29b69cc31b87df5fceca53d02269d93cc5874901d6b95d43f", "bytes": 27216, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/98cfd5c455296e63e9ada6592cb902781a551aa3f3e7a54f88f8e90e5b45e39a.mp3", "duration_ms": 4480}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/b6f0d325cb8c5c1567b54cfbcc29c69d037e9dda13768f871e073663c18586a3.mp3", "hash": "a7a65cdba8af7109b3a8c75e6ccb6cd64711dc07101bfa853c390d2ff657a0ab", "bytes": 43488, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b6f0d325cb8c5c1567b54cfbcc29c69d037e9dda13768f871e073663c18586a3.mp3", "duration_ms": 7200}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/43400cef8d805b5650f087637d0128d72864f71272c5395ddaf70b5f66fd80a6.mp3", "hash": "6b5a9f23b819150d6e55a8131c9010da70b908fadd86bfba9827da18078f2c87", "bytes": 59328, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/43400cef8d805b5650f087637d0128d72864f71272c5395ddaf70b5f66fd80a6.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Ronda relámpago en la hora pico", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el cambio correcto para clientes que piden 1-3 vasos de limonada a 5 pesos y pagan con 10 o 20 pesos.", "Aplicar la estrategia: primero suma el costo total, luego resta del pago."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning-round", "xp": 15, "type": "lightning_round", "hints": ["Primero suma cuánto cuestan los vasos: 2 vasos × 5 pesos cada uno.", "Luego resta ese total del pago de 20 pesos."], "title": "Ronda relámpago", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Doña Rosa: 2 vasos, paga con 20. ¿Cuánto cambio le das?"}, {"id": "q2", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "0 pesos"}], "prompt_md": "Don José: 3 vasos, paga con 20. ¿Cuánto cambio le das?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "0 pesos"}, {"id": "d", "text_md": "4 pesos"}], "prompt_md": "Mamá Lila: 1 vaso, paga con 10. ¿Cuánto cambio le das?"}, {"id": "q4", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}, {"id": "d", "text_md": "2 pesos"}], "prompt_md": "Tío Toño: 2 vasos, paga con 10. ¿Cuánto cambio le das?"}, {"id": "q5", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Abuela Nena: 3 vasos, paga con 20. ¿Cuánto cambio le das?"}, {"id": "q6", "options": [{"id": "a", "text_md": "15 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "5 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Don Chuy: 1 vaso, paga con 20. ¿Cuánto cambio le das?"}], "seconds_per_q": 15}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Doña Rosa: 2 vasos, paga con 20. ¿Cuánto cambio le das?", "difficulty": 2, "explanation_md": "2 vasos cuestan 10 pesos (2×5). 20 menos 10 son 10 pesos de cambio.", "audio_segment_id": "s1-lightning-round.prompt"}], "schema_version": 1}', '{"s1-lightning-round": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a", "q5": "a", "q6": "a"}}}', '{"units": {"s1-lightning-round.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f5597d72fd111da1809bdecd4f773cee2a8e5770419855e1c672fe0a313278b6.mp3", "hash": "c6aeb2b75b4808053aa333063ce04095a08aa368afbdc67e9d4a892aee98c4ad", "bytes": 31968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f5597d72fd111da1809bdecd4f773cee2a8e5770419855e1c672fe0a313278b6.mp3", "duration_ms": 5280}, "s1-lightning-round.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7fd863e27d7e42f70eebdcc77318cf85b02a89e995a63693bc98234357ea151c.mp3", "hash": "10dc9be2b3a6e11feff521f8ea3c4d6a14ccd48c8f16a7a3e890fb49c2bf924b", "bytes": 20448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7fd863e27d7e42f70eebdcc77318cf85b02a89e995a63693bc98234357ea151c.mp3", "duration_ms": 3360}, "s1-lightning-round.prompt": {"url": "http://localhost:4006/files/lesson-audio/b92d7a61d528c576774b3e9fd1feedbd89c0bc2fd088f99b2d8fdcb6d0243938.mp3", "hash": "71472866bb5e71d2dae2d51ce30472137b0a527426932686433aaa6a13c3c0fa", "bytes": 29664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b92d7a61d528c576774b3e9fd1feedbd89c0bc2fd088f99b2d8fdcb6d0243938.mp3", "duration_ms": 4880}, "s1-lightning-round.explanation": {"url": "http://localhost:4006/files/lesson-audio/56e4b5d636a9f896fca3a9712fcf65c0458940ae3a015de357b97336501afb3d.mp3", "hash": "2463982d02556cafb1e8c41b1b82c9a2c3db9f65fdea2f9efeb0226b8a893fd4", "bytes": 44928, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56e4b5d636a9f896fca3a9712fcf65c0458940ae3a015de357b97336501afb3d.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "The piggy bank that rewards patience", "locale": "en-US", "subject": "money", "objectives": ["Deciding whether leaving money in a piggy bank that gives extra coins each week is better than spending it now.", "Predicting the total after waiting, understanding that it grows a little but doesn''t double."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Each week the piggy bank gives 2 coins of 1 peso. How many extra coins does it give in 2 weeks?", "Start with 20. Add the extra coins."], "title": "Leave the 20 or take them out now?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Stays at 20"}, {"id": "opt2", "text_md": "24 dollars"}, {"id": "opt3", "text_md": "Almost 40 dollars"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf has 20 dollars saved for a guitar that costs 80. Rho tells him: ''If you keep your money in this special piggy bank, it gives you 2 extra 1-dollar coins each week for leaving it there.'' Liruf puts in his 20 dollars. He thinks: ''If I wait 2 weeks, will I have more or less than if I spend everything now?'' How much will Liruf have after 2 weeks?", "difficulty": 1, "explanation_md": "The piggy bank gives 2 coins of 1 dollar each week, so in 2 weeks it gives 4 extra dollars. 20 + 4 = 24. The money grows little by little toward the guitar! If he had spent everything now, he wouldn''t have those 4 extra dollars.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4dd1d6ccf798aa5c97f749d1bbca0f429554a0e4ddb1067c914ccb754dd04ba7.mp3", "hash": "e3ea14dc8606d826d144eb6363d4368856117ed4d8f67dadc689bfe55e4c73ae", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4dd1d6ccf798aa5c97f749d1bbca0f429554a0e4ddb1067c914ccb754dd04ba7.mp3", "duration_ms": 5840}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7825f2189c180a4b293003f1af92126daa5268cd9d392ca5974129c790076a30.mp3", "hash": "f8bc08ef72f497b9b77b2307f928554ffa4b3b6cc12fc571460ffce20f85865a", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7825f2189c180a4b293003f1af92126daa5268cd9d392ca5974129c790076a30.mp3", "duration_ms": 2400}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/9f9c00569734ab927d477105d91b7fa638b29349b9e21f4b0475d98437fb6fe0.mp3", "hash": "8a9e8790bd658b56a8d71361c7e2330bd79a78bdf563043221ad4f46689b2c85", "bytes": 115488, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9f9c00569734ab927d477105d91b7fa638b29349b9e21f4b0475d98437fb6fe0.mp3", "duration_ms": 19200}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/005c0228752fe743fe4aeac48b6ee8693d17a447c7266e1f24543a7bbecc407a.mp3", "hash": "daa97b2ded3a7663e072dc5c7e9c8d3543d55e7c0f139e1eee9f8808883280b7", "bytes": 86688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/005c0228752fe743fe4aeac48b6ee8693d17a447c7266e1f24543a7bbecc407a.mp3", "duration_ms": 14400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "La noche antes de abrir", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar la meta de la guitarra de 80 pesos, el precio de la limonada a 5 pesos el vaso, y que la ganancia es lo que sobra tras pagar el costo y va al frasco de la guitarra."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "La noche antes de abrir", "payload": {"recap_md": "Es la noche antes de abrir. Dina se sienta junto a Liruf y su frasco vacío de la guitarra. En vez de un examen, señalan las tres cosas que ya tienen listas: la meta pegada en la pared (guitarra, 80 pesos), el cartel de la limonada (5 pesos el vaso) y el secreto que aprendieron — que de cada vaso, lo que sobra después del costo es la ganancia que empuja el frasco hacia los 80. Liruf respira: la idea ya no es solo un sueño, mañana se prueba de verdad. Dina sonríe y le pregunta qué tan cerca siente ya esa guitarra.", "mood_prompt_md": "Liruf mira el frasco vacío pero sonríe. Mañana empieza a llenarlo."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina y Liruf repasan lo que han preparado.", "difficulty": 1, "explanation_md": "Liruf tiene su meta de 80 pesos, su limonada a 5 pesos el vaso, y sabe que la ganancia es lo que sobra después del costo. Mañana lo pone a prueba.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/13fb07ec59f33e84b1f7900aa1a444cc32e10b6caaa33971806ed14a11576230.mp3", "hash": "6e23b7a3d86450478e900bb96fcf67db55a441a1b2ed5347aae4725e9bb08527", "bytes": 192816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/13fb07ec59f33e84b1f7900aa1a444cc32e10b6caaa33971806ed14a11576230.mp3", "duration_ms": 32080}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/993f40fd709c7dddada5c542b444b1d7726c641c7d6345d389cebfd39c64dbd4.mp3", "hash": "3f39d204ee3dfbc7b3c0151c81cbd2129ac45eb8793a91105fe78c8419cabf9d", "bytes": 20016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/993f40fd709c7dddada5c542b444b1d7726c641c7d6345d389cebfd39c64dbd4.mp3", "duration_ms": 3280}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/d58cea1959c2416ca70e48bb75705b09d64344cc0dc12336b28ca286a5da48d3.mp3", "hash": "351e27587681e8a07f9c3b97d9e067c46217534a11601300b0f3dfe88d13ac2e", "bytes": 64656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d58cea1959c2416ca70e48bb75705b09d64344cc0dc12336b28ca286a5da48d3.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "machine-io", "title": "The tipping machine", "locale": "en-US", "subject": "mixed", "objectives": ["Discovering that the machine doubles what goes in", "Predicting the machine''s output with a new number"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 15, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. What operation does the machine do?", "Each coin that goes in becomes double."], "title": "Discover the rule", "payload": {"options": [{"id": "opt-7", "text_md": "7"}, {"id": "opt-8", "text_md": "8"}, {"id": "opt-10", "text_md": "10"}, {"id": "opt-15", "text_md": "15"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Grandma puts in 1 coin and 2 come out. She puts in 3 and 6 come out. How many come out if she puts in 5?", "difficulty": 2, "explanation_md": "The machine doubles: 1 becomes 2, 3 becomes 6, so 5 becomes 10.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt-10"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/270222d239a72063914b8844e0e5dc62563834e943a4c9df321b5b0fb0101111.mp3", "hash": "4bfb436d39b91c87520c8ad3f9ec52e38885862713fc08eed6a71c880d3adc16", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/270222d239a72063914b8844e0e5dc62563834e943a4c9df321b5b0fb0101111.mp3", "duration_ms": 4880}, "s1-machine-io.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1b730ac51b07827957c78d0b356fec72dd8d2c0ab2f3a2d3250c195a1c08ae8a.mp3", "hash": "d7b9f9bc0e212051419a6c5234ea6a762c579b391ae9d80d14c6a090db5d37cb", "bytes": 11376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1b730ac51b07827957c78d0b356fec72dd8d2c0ab2f3a2d3250c195a1c08ae8a.mp3", "duration_ms": 1840}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/a381efaba51345e3bed31704a46a65324092f46f9213b13e6c8ac0617d623340.mp3", "hash": "278990baadf03e597e9c3f0ef4d78879ab80a17de1b32a1bc2a3b714907d5b43", "bytes": 39168, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a381efaba51345e3bed31704a46a65324092f46f9213b13e6c8ac0617d623340.mp3", "duration_ms": 6480}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/185dec5169758d36b66b926b55ea12db304a94621b55f9103525f7ced7c392e2.mp3", "hash": "ca60dbdaa3342491b14a25ae57d4d8678fca58528471d8eaa101859a01696853", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/185dec5169758d36b66b926b55ea12db304a94621b55f9103525f7ced7c392e2.mp3", "duration_ms": 4960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Repasso rápido: lucro por copo", "locale": "pt-BR", "subject": "money", "objectives": ["Calcular o lucro por copo de limonada (preço - custo dos ingredientes)"], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-por-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["O lucro é o que sobra depois de pagar os ingredientes.", "Subtraia o custo dos ingredientes do preço do copo."], "title": "Lucro por copo", "payload": {"options": [{"id": "a", "text_md": "2 reais", "rationale_md": "Esse é o custo dos ingredientes, não o lucro."}, {"id": "b", "text_md": "3 reais"}, {"id": "c", "text_md": "5 reais", "rationale_md": "Esse é o preço do copo, mas é preciso subtrair o que custa fazê-lo."}, {"id": "d", "text_md": "7 reais", "rationale_md": "Você somou o preço e o custo, mas o lucro é a subtração."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina te desafia: sem ver o caderno, quanto Liruf ganha por cada copo que vende? O copo custa 5 reais e os ingredientes custam 2 reais.", "difficulty": 1, "explanation_md": "Liruf ganha 3 reais por copo: 5 reais do preço menos 2 reais de ingredientes. Esse é o lucro!", "audio_segment_id": "s1-ganancia-por-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-por-vaso": {"correct_option_id": "b"}}', '{"units": {"s1-ganancia-por-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/95eddb0230412112aece402bb5a3384baff9376480775bda941c59676caee83d.mp3", "hash": "5b7f08172d1c0d3a7ce917de41382043c93572afae2e55c79e2f7773b0fb29c5", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/95eddb0230412112aece402bb5a3384baff9376480775bda941c59676caee83d.mp3", "duration_ms": 4080}, "s1-ganancia-por-vaso.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0f0bdb62911352344ab51741db2b4de895e37a2d395163224f3df3a43899b9ed.mp3", "hash": "eb721f5d0b09a7e1ebf920065cc4ae74d9decc24db64580abe35ed9eec2e94ef", "bytes": 21456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0f0bdb62911352344ab51741db2b4de895e37a2d395163224f3df3a43899b9ed.mp3", "duration_ms": 3520}, "s1-ganancia-por-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/7c9f6b92137ea5942dee013b22f7b997ce5ff481491cdaf210c66a0fac6102d3.mp3", "hash": "a0aeb30f28c91bfe23205479ea06983dab6d0736751fe2a4075bbde5e7de408b", "bytes": 66096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7c9f6b92137ea5942dee013b22f7b997ce5ff481491cdaf210c66a0fac6102d3.mp3", "duration_ms": 10960}, "s1-ganancia-por-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/4e1657005ed203b7f25f92d10197cd27079c6291d3af4dd527c4c775e5da8ed5.mp3", "hash": "c5a43813ef524c6953d1290e70204089e7c252f8b19846de2613dccefaf14789", "bytes": 33408, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4e1657005ed203b7f25f92d10197cd27079c6291d3af4dd527c4c775e5da8ed5.mp3", "duration_ms": 5520}, "s1-ganancia-por-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/091b871cbde8a0c83e697ce2e11d2a3df9b0335b7511c13a28a3d9afcacf8222.mp3", "hash": "732a9854fb53fa5351176ae413118957290775b60c8a5786fd61d44d731ef978", "bytes": 49824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/091b871cbde8a0c83e697ce2e11d2a3df9b0335b7511c13a28a3d9afcacf8222.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'en-US', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "flash-match", "title": "Flash Match: Stand Concepts", "locale": "en-US", "subject": "mixed", "objectives": ["Match each stand word with its concrete example (saving→piggy bank, cost→lemons, profit→what''s left over)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "hints": ["Think about what each word means at the lemonade stand.", "Saving is what you keep, cost is what you pay, profit is what''s left over."], "title": "Connect the concepts!", "payload": {"left": [{"id": "ahorro", "text_md": "Saving", "image_url": "http://localhost:4006/files/lesson-images/090415ebca9189f3fb0dceccf1b6358ec4a877c10a88207e406af0aea88b061f.png"}, {"id": "costo", "text_md": "Cost", "image_url": "http://localhost:4006/files/lesson-images/ddcaa401cb87185f2718603c9ef8c2eed281b1e6927f05e6f8b2f1622cf581c0.png"}, {"id": "ganancia", "text_md": "Profit", "image_url": "http://localhost:4006/files/lesson-images/a21762522b599ee3f69c8b0d381c64bd33a70ceb009ea48e62093bf4722b8eac.png"}], "right": [{"id": "alcancia", "text_md": "Piggy Bank"}, {"id": "limones", "text_md": "Lemons"}, {"id": "lo-que-sobra", "text_md": "What''s left over"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Tap each word on the left and then its example on the right. Quick!", "difficulty": 1, "explanation_md": "Saving is putting money in the piggy bank, cost is the lemons you buy, profit is what''s left after selling.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "lo-que-sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a3633259d30f827a9ac2c068f4cfda0510b31a3333dca93ae69240f7e6487937.mp3", "hash": "04fbef61fd0bd8e244351e766fe2974498058e48b85e7d8aeec5389e7a0e9023", "bytes": 20016, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/a3633259d30f827a9ac2c068f4cfda0510b31a3333dca93ae69240f7e6487937.mp3", "duration_ms": 3280}, "s1-flash-match.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c4442831f85d348e810af84f9de48e7be28d42e4c81ee3e87017d21ced32ee6a.mp3", "hash": "2e6749a3f7c1347b88b37be77da399ead04094e7197d48776bfaa453164e27ec", "bytes": 32976, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c4442831f85d348e810af84f9de48e7be28d42e4c81ee3e87017d21ced32ee6a.mp3", "duration_ms": 5440}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/9d3db011d21c0b57b6fe8ffa92fc768d5bca8f867291673005b7368662f582f9.mp3", "hash": "30ffa6a6e34e3fb9029adda978a8a1d9e210059923783d1fbf7446d8cba88ce6", "bytes": 25776, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/9d3db011d21c0b57b6fe8ffa92fc768d5bca8f867291673005b7368662f582f9.mp3", "duration_ms": 4240}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/7246d9d4b9e0ee83d3ec334829680e05c8b60c5dce67ef8cbeb2feadb57bbc13.mp3", "hash": "3e212dacc0fd80d579b4e0c0b6eb12c96e59e6739730d0de75d2058111562f81", "bytes": 40608, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7246d9d4b9e0ee83d3ec334829680e05c8b60c5dce67ef8cbeb2feadb57bbc13.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'es-MX', '1', '{"meta": {"cast": ["zara", "liruf"], "slug": "flash-match", "title": "Flash Match: Conceptos del Puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Relacionar cada palabra del puesto con su ejemplo concreto (ahorro→alcancía, costo→limones, ganancia→lo que sobra)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "hints": ["Piensa en lo que cada palabra significa en el puesto de limonada.", "El ahorro es lo que guardas, el costo es lo que pagas, la ganancia es lo que te sobra."], "title": "¡Conecta los conceptos!", "payload": {"left": [{"id": "ahorro", "text_md": "Ahorro", "image_url": "http://localhost:4006/files/lesson-images/ac3f8f6660ebf4e411fe568beb3b2b915c80bb9e9ad9e6d57a261d7910f66bd9.png"}, {"id": "costo", "text_md": "Costo", "image_url": "http://localhost:4006/files/lesson-images/e7cf682207fc4c04567bc6dfd8306b31433c871f0695e8ab08c0b39305016228.png"}, {"id": "ganancia", "text_md": "Ganancia", "image_url": "http://localhost:4006/files/lesson-images/cd3f8eed5ae720ba523682f697ccc5df9a84fcfd52bf9f9f3027d0d6c4f633f9.png"}], "right": [{"id": "alcancia", "text_md": "Alcancía"}, {"id": "limones", "text_md": "Limones"}, {"id": "lo-que-sobra", "text_md": "Lo que sobra"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toca cada palabra de la izquierda y luego su ejemplo en la derecha. ¡Rápido!", "difficulty": 1, "explanation_md": "Ahorro es guardar dinero en la alcancía, costo son los limones que compras, ganancia es lo que sobra después de vender.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "lo-que-sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/48711b34c67f74d9eedd8e9dff88690e53ca6e0e3d641466d268b43704850d0d.mp3", "hash": "e9a376a3f3db8b869f3d350e120b0a559179aec837d73122d770f45a2ce30d5b", "bytes": 23328, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/48711b34c67f74d9eedd8e9dff88690e53ca6e0e3d641466d268b43704850d0d.mp3", "duration_ms": 3840}, "s1-flash-match.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d1be15223e63d0a952b96a15e9f8871143101617c6c543601cc03e7913bd8c41.mp3", "hash": "9ee7828e2a028acc3ccc0025b5bf0fb10b41ef61e65124f8e72c3ac59b1f0e74", "bytes": 32976, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d1be15223e63d0a952b96a15e9f8871143101617c6c543601cc03e7913bd8c41.mp3", "duration_ms": 5440}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/6add5b5133b30d4f5345a65ef1a06b617db2ca744539d58c96ad8eb6eab3f0f4.mp3", "hash": "f87a38061fefd6dc57b4b4f459b58af699e1bf6b0b1683c2466367c9a9a80c8b", "bytes": 32544, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/6add5b5133b30d4f5345a65ef1a06b617db2ca744539d58c96ad8eb6eab3f0f4.mp3", "duration_ms": 5360}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/d4e41410f470283f8adcb7a91319bb78693c5c4f5998c136db3e7cf3c4b3dcee.mp3", "hash": "9ea3e62bf5d067eb460c4f2d7f888ba5792e4b44719d2507543215ecc868c4d2", "bytes": 42048, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d4e41410f470283f8adcb7a91319bb78693c5c4f5998c136db3e7cf3c4b3dcee.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "pattern-complete", "title": "A escada de preços", "locale": "pt-BR", "subject": "money", "objectives": ["Ordenar passos, combinar produtos com preços e classificar compras entre necessidades da barraca e desejos que podem esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Observe o padrão: pequeno, médio, grande, pequeno, médio... qual tamanho vem depois do médio?", "Cada tamanho custa mais que o anterior. O próximo deve custar mais que R$10."], "title": "Qual copo vem a seguir?", "payload": {"options": [{"id": "chico", "icon": "local_drink", "tint": "primary"}, {"id": "mediano", "icon": "local_drink", "tint": "accent"}, {"id": "grande", "icon": "local_drink", "tint": "success"}, {"id": "limon", "icon": "nutrition", "tint": "primary"}], "sequence": [{"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}, {"icon": "local_drink", "tint": "success"}, {"icon": "local_drink", "tint": "primary"}, {"icon": "local_drink", "tint": "accent"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Os preços: pequeno R$5, médio R$10, grande R$15. Qual copo vai no espaço?", "difficulty": 2, "explanation_md": "O padrão sobe de preço: pequeno R$5, médio R$10, grande R$15, e recomeça. Depois do médio (R$10) vem o grande (R$15).", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"0": "grande"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1d3a31b0458850a69cae6c8cc58b4259083a8299df156be45f054cc0652af9a8.mp3", "hash": "41fb24b38786dffc33d6e0ba6bb090518de6f86a293f9fe6df33b50eac40139e", "bytes": 42624, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/1d3a31b0458850a69cae6c8cc58b4259083a8299df156be45f054cc0652af9a8.mp3", "duration_ms": 7040}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9568dbe4c8e1df6c86f18caef9061051555d24f57cf11be2f4955d49757ad3d8.mp3", "hash": "f2c493430c89145253059ced5343f81985d709909f0cbc0f2d00f0a61207b050", "bytes": 32976, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/9568dbe4c8e1df6c86f18caef9061051555d24f57cf11be2f4955d49757ad3d8.mp3", "duration_ms": 5440}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/47aef17b0dba07cd2628bad3f730f8932192a54408df316e31737a8c0218d462.mp3", "hash": "6ff23858ffcb2a63e2356263d5eea865ef70e8fd2da641e374318596fe8ee882", "bytes": 45936, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/47aef17b0dba07cd2628bad3f730f8932192a54408df316e31737a8c0218d462.mp3", "duration_ms": 7600}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/1a994aec6d7321e949ae28850bfb61a8d0f984058e9fbbed47ee48e87932b33f.mp3", "hash": "14acb0c414a3c14b610908c8552694ba658cf5cf68b1bdf253ec6cc982cc0019", "bytes": 77184, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/1a994aec6d7321e949ae28850bfb61a8d0f984058e9fbbed47ee48e87932b33f.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
